def _d01_witness_receipt(case_type, name, sites):
    """Run one shipped witness and bind durable decisions to reached sites.

    The adapter call's source frame is still an ancestor when its ledger
    decision becomes durable. The two raw metadata calls occur *after* that
    decision, so their confined transport call is paired with the exact
    logical/attempt IDs from the same active request. No production hook or
    source-text name match is credited as execution evidence.
    """
    location = {}
    root = Path(__file__).resolve().parent.parent
    for row in sites:
        source = (root / (row["module"].replace(".", "/") + ".py")).resolve()
        location.setdefault((str(source).lower(), row["line"]), []).append(row)
    code_paths = {}

    def path_for(code):
        if code not in code_paths:
            code_paths[code] = str(Path(code.co_filename).resolve()).lower()
        return code_paths[code]

    receipts, durable = set(), set()
    lock = threading.Lock()
    original_decision = FetchLedger.decision

    def witnessed_decision(ledger, ids, payload):
        value = original_decision(ledger, ids, payload)
        token = (threading.get_ident(), ids["logical_id"], ids["attempt_id"])
        with lock:
            durable.add(token)
        if tp._ACTIVE is None:
            return value
        frame = inspect.currentframe().f_back
        while frame is not None:
            for row in location.get((path_for(frame.f_code), frame.f_lineno), ()):
                if row["primitive"] in {"adapter_fetch", "adapter_head"} \
                        and row["producer_id"] == ids["producer_id"]:
                    with lock:
                        receipts.add((ids["producer_id"], row["site_key"]))
            frame = frame.f_back
        return value

    raw_callees = {"details", "search", "reqContractDetailsAsync",
                   "reqMatchingSymbols"}

    def observe(frame, event, _arg):
        if event != "call" or tp._ACTIVE is None or frame.f_back is None:
            return
        caller = frame.f_back
        candidates = location.get((path_for(caller.f_code), caller.f_lineno), ())
        if frame.f_code.co_name not in raw_callees:
            return
        for row in candidates:
            if row["primitive"] != "ibkr_raw_request":
                continue
            active = frame.f_back
            while active is not None:
                if active.f_code.co_name == "_execute" and \
                        path_for(active.f_code).endswith("fetch_run_context.py"):
                    request = active.f_locals.get("self")
                    ids = active.f_locals.get("ids", {})
                    token = (threading.get_ident(), ids.get("logical_id"),
                             ids.get("attempt_id"))
                    with lock:
                        if getattr(request, "producer_id", None) == row["producer_id"] \
                                and token in durable:
                            receipts.add((row["producer_id"], row["site_key"]))
                    break
                active = active.f_back

    previous_sys, previous_threads = sys.getprofile(), threading.getprofile()
    result = unittest.TestResult()
    output = io.StringIO()
    with patch.object(FetchLedger, "decision", new=witnessed_decision):
        sys.setprofile(observe)
        threading.setprofile(observe)
        try:
            with redirect_stdout(output):
                case_type(name).run(result)
        finally:
            sys.setprofile(previous_sys)
            threading.setprofile(previous_threads)
    if result.testsRun != 1 or not result.wasSuccessful():
        detail = (result.errors + result.failures)[0][1][-2000:] \
            if result.errors or result.failures else "test did not run once"
        raise AssertionError(f"D01 witness {name} failed: {detail}")
    if tp._ACTIVE is not None:
        raise AssertionError(f"D01 witness {name} leaked its offline guard")
    return frozenset(receipts)


def _d01_verify(rows, bindings, receipts, catalog):
    """Exact structural allocation plus reached-site evidence for every row."""
    assert len(bindings) == 22 and len({row[0] for row in bindings}) == 21
    expected = Counter((producer, site) for producer, site, _, _ in bindings)
    assert all(count == 1 for count in expected.values())
    actual = Counter((row["producer_id"], row["site_key"]) for row in rows)
    assert actual == expected, ("D01 site denominator", actual - expected,
                                expected - actual)
    by_pair = {(producer, site): (witness, transport)
               for producer, site, witness, transport in bindings}
    for row in rows:
        producer, site = row["producer_id"], row["site_key"]
        witness, transport = by_pair[(producer, site)]
        owner, qualname, primitive, ordinal = site.split(":")
        assert row["module"] == owner and row["qualname"] == qualname
        assert row["primitive"] == primitive and ordinal.isdigit()
        assert row["disposition"] == "a2_refused" and row["transport"] == transport
        assert witness in catalog and (producer, site) in receipts.get(witness, ()), \
            ("D01 unreached physical site", witness, producer, site)
    d_prefixes = ("ibkr.live_combined_flags.", "ibkr.live_internal_daily_check.",
                  "ibkr.live_internal_revalidate.", "ibkr.live_kind_smoke.",
                  "ibkr.two_account_pacing_probe.")
    c_prefixes = ("ibkr.live_spot_probe.", "ibkr.vol_value_bank.",
                  "ibkr.stock_ibkr.retired_spot_check")
    d = [row for row in rows if row["producer_id"].startswith(d_prefixes)]
    c = [row for row in rows if row["producer_id"].startswith(c_prefixes)]
    b = [row for row in rows if row not in d and row not in c]
    assert (len({row["producer_id"] for row in b}), len(b)) == (5, 6)
    assert (len({row["producer_id"] for row in c}), len(c)) == (4, 4)
    assert (len({row["producer_id"] for row in d}), len(d)) == (12, 12)


