def _d14_release_verify(roots, holds, nightly, receipts, rights, catalog):
    """Exact production surface, A1-only rights, and executed default gate."""
    expected = Counter((path, owner, purpose, "begin_operation")
                       for path, owner, purpose, _ in (*holds, *nightly))
    actual = Counter((row["path"], row["owner"], row["purpose"], row["api"])
                     for row in roots)
    assert len(holds) == 26 and len(nightly) == 4
    assert len(expected) == 30 and all(n == 1 for n in expected.values())
    assert actual == expected, ("D14 registered root drift", actual - expected,
                                expected - actual)
    assert Counter((path, owner, purpose, "begin_operation")
                   for (path, owner), purpose in op.PRODUCTION_ROOTS.items()) == expected, \
        "D14 mint registry drift"
    a2_producers = {producer for producer, *_ in _D01_BINDINGS}
    assert len(a2_producers) == 21
    assert not a2_producers & set(rights["nightly"]), "D14 A2 producer live-enabled"
    assert a2_producers <= set().union(*(set(rights[purpose]) for purpose in
        ("add_stocks", "identity", "repair", "diagnostic"))), \
        "D14 missing A2 held-rights owner"
    assert set(rights) == {"nightly", "add_stocks", "identity", "repair",
                           "diagnostic", "validation", "external_sweep"}
    http = {"http.stockanalysis.validation", "http.stockanalysis.external_sweep"}
    assert not any(producer.startswith("http.") for producer in rights["nightly"])
    assert not any(producer.startswith("http.") for producer in op._SHARED)
    assert rights["validation"] == {"http.stockanalysis.validation"}
    assert rights["external_sweep"] == {"http.stockanalysis.external_sweep"}
    assert {value for value in rights["diagnostic"] if value.startswith("http.")} == {
        "http.stockanalysis.validation"}, "D14 diagnostic HTTP rights drift"
    assert {value for value in rights["repair"] if value.startswith("http.")} == {
        "http.stockanalysis.validation"}, "D14 repair HTTP rights drift"
    assert not any(value.startswith("http.") for purpose in ("add_stocks", "identity")
                   for value in rights[purpose]), "D14 unreviewed embedded HTTP right"
    assert http <= set().union(*(set(rights[purpose]) for purpose in
        ("validation", "external_sweep"))), "D14 missing held HTTP right"
    for path, owner, purpose, method in holds:
        assert method in catalog, ("D14 missing held witness", method)
        turns = [turn for turn in receipts[method]["operations"].values()
                 if turn["key"] == (path, owner) and turn["purpose"] == purpose]
        defaults = [turn for turn in turns if not turn["capability"]]
        assert defaults and all(turn["held"] and not turn["admitted"]
            and not turn["decisions"] and not turn["results"]
            for turn in defaults), \
            ("D14 default root not held before decision", path, owner, turns)
        if purpose in {"validation", "external_sweep"}:
            assert all(turn.get("precontext") is True for turn in defaults), \
                ("D14 HTTP root did not hold before context", path, owner, turns)
    for path, owner, purpose, method in nightly:
        assert method in catalog
        turns = [turn for turn in receipts[method]["operations"].values()
                 if turn["key"] == (path, owner) and turn["purpose"] == purpose]
        assert turns and all(turn["admitted"] and not turn["held"]
            and not turn["capability"] for turn in turns), \
            ("D14 nightly root not admitted by default", path, owner, turns)
    positive = [turn for turn in receipts["test_actual_nightly_preflight_and_fill_share_parent"]
                ["operations"].values() if turn["key"] ==
                ("engine/stock_ibkr.py", "nightly_update")]
    assert positive and all(turn["admitted"] and not turn["held"]
        and not turn["capability"] and turn["decisions"] and turn["results"]
        for turn in positive), "D14 A1 shared send no longer admitted"


