def _d07_audit_witness(case_type, name):
    """Run a shipped offline witness and capture classifier, ledger and file receipts."""
    import stock_validate as sv
    lock = threading.Lock()
    receipt = {"decision": Counter(), "result_attempt": Counter(),
               "result_durable": Counter(), "classifier": Counter(), "sidecars": []}
    original_decision, original_result = FetchLedger.decision, FetchLedger.result
    original_internal = sv.internal_daily_audit
    original_combined = sv.combined_crosscheck
    original_internal_save = sv.record_internal_validation
    original_combined_save = sv.record_combined_flags

    def decision(ledger, ids, payload):
        value = original_decision(ledger, ids, payload)
        with lock:
            receipt["decision"][ids["producer_id"]] += 1
        return value

    def result_event(ledger, ids, payload):
        with lock:
            receipt["result_attempt"][ids["producer_id"]] += 1
        value = original_result(ledger, ids, payload)
        with lock:
            receipt["result_durable"][ids["producer_id"]] += 1
        return value

    def classifier(label, original):
        def tracked(*args, **kwargs):
            with lock:
                receipt["classifier"][label] += 1
            return original(*args, **kwargs)
        return tracked

    def save(label, original):
        def tracked(root, entry):
            value = original(root, entry)
            path = Path(root) / label
            if path.exists():
                data = path.read_bytes()
                saved = json.loads(data)
                key = (entry["ticker"] if label == "_internal_validation.json"
                       else entry["ticker"] + " " + entry["interval"])
                actual = saved[key]
                assert actual["status"] == entry.get("status"), (
                    "D07 persisted status diverged", label, key)
                assert actual.get("_verification_current") == entry.get(
                    "_verification_current"), ("D07 persisted currentness diverged", label, key)
                with lock:
                    receipt["sidecars"].append({"path": label,
                        "status": actual["status"],
                        "current": actual.get("_verification_current"),
                        "sha256": hashlib.sha256(data).hexdigest()})
            return value
        return tracked

    result = unittest.TestResult()
    output = io.StringIO()
    with patch.object(FetchLedger, "decision", new=decision), \
            patch.object(FetchLedger, "result", new=result_event), \
            patch.object(sv, "internal_daily_audit", new=classifier(
                "internal_daily_audit", original_internal)), \
            patch.object(sv, "combined_crosscheck", new=classifier(
                "combined_crosscheck", original_combined)), \
            patch.object(sv, "record_internal_validation", new=save(
                "_internal_validation.json", original_internal_save)), \
            patch.object(sv, "record_combined_flags", new=save(
                "_combined_flags.json", original_combined_save)), \
            redirect_stdout(output):
        case_type(name).run(result)
    if result.testsRun != 1 or not result.wasSuccessful():
        detail = (result.errors + result.failures)[0][1][-2500:] \
            if result.errors or result.failures else "test did not run once"
        raise AssertionError(f"D07 witness {name} failed: {detail}")
    if tp._ACTIVE is not None:
        raise AssertionError(f"D07 witness {name} leaked its offline guard")
    return receipt


def _d07_audit_verify(rows):
    expected = Counter((path, scenario) for path, scenario, *_ in _D07_AUDITS)
    actual = Counter((row["path"], row["scenario"]) for row in rows)
    assert len(_D07_AUDITS) == 7 and all(value == 1 for value in expected.values())
    assert set(_D07_COUNTS) == set(expected)
    assert actual == expected, ("D07 audit denominator", actual - expected,
                                expected - actual)
    by_key = {(row["path"], row["scenario"]): row for row in rows}
    for path, scenario, name, classifier, sidecar, producers, statuses in _D07_AUDITS:
        row = by_key[path, scenario]
        receipt = row["receipt"]
        assert row["method"] == name, ("D07 witness identity", path, scenario)
        counts = Counter(_D07_COUNTS[path, scenario])
        assert set(counts) == producers
        assert receipt["decision"] == counts, ("D07 decision IDs", path, scenario)
        assert receipt["result_attempt"] == counts, ("D07 result IDs", path, scenario)
        assert receipt["result_durable"] == (
            Counter() if scenario == "result-fault-debt" else counts), (
            "D07 result durability", path, scenario)
        if classifier is None:
            assert not receipt["classifier"], ("D07 fault reached classifier", path, scenario)
        else:
            assert receipt["classifier"][classifier] > 0, (
                "D07 classifier not reached", path, scenario)
        saved = [entry for entry in receipt["sidecars"] if entry["path"] == sidecar]
        assert statuses <= {entry["status"] for entry in saved}, (
            "D07 sidecar status", path, scenario, saved)
        assert all(len(entry["sha256"]) == 64 for entry in saved)
        if scenario in {"incomplete-month", "unavailable-http", "held-http-debt",
                        "result-fault-debt"}:
            assert any(entry["current"] is False for entry in saved), (
                "D07 noncurrent verdict", path, scenario)
    return by_key


