def _d13_regression_verify(rows):
    expected = {(family, scenario): (method, Counter(decisions), label_count, labels)
                for family, scenario, method, decisions, label_count, labels
                in _D13_REGRESSION_CASES}
    assert len(expected) == len(_D13_REGRESSION_CASES) == 14, "D13 table identity collision"
    observed = {}
    for row in rows:
        key = row["family"], row["scenario"]
        assert key not in observed, ("D13 duplicate identity", key)
        observed[key] = row
    assert set(observed) == set(expected), ("D13 identity coverage",
        set(expected) - set(observed), set(observed) - set(expected))
    for key, (method, decisions, label_count, required) in expected.items():
        row = observed[key]
        assert row["method"] == method, ("D13 witness identity", key)
        assert row["decisions"] == decisions, ("D13 ledger decisions", key)
        assert sum(row["labels"].values()) == label_count, ("D13 rendered labels", key)
        assert all(row["labels"][label] == 1 for label in required), (
            "D13 required diagnostic label", key)


def _d13_label_inventory(sources):
    """Retain owner, duplicate branch labels and dynamic expression templates."""
    rows = Counter()
    for path, source in sources.items():
        tree = ast.parse(source, filename=path)
        def visit(node, owners):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                owners = (*owners, node.name)
            if isinstance(node, ast.Call):
                fun = node.func
                if isinstance(fun, ast.Name) and fun.id in {"check", "check_local"} and node.args:
                    index = 0
                elif isinstance(fun, ast.Attribute) and fun.attr == "check" and len(node.args) > 1:
                    index = 1
                else:
                    index = None
                if index is not None:
                    rows[path, ".".join(owners), ast.unparse(node.args[index])] += 1
            for child in ast.iter_child_nodes(node):
                visit(child, owners)
        visit(tree, ())
    return rows


def _d13_label_verify(baseline, observed):
    assert sum(baseline.values()) == 75, "D13 original label denominator"
    normalized = Counter()
    observer_safe = 0
    for (path, owner, label), count in baseline.items():
        owner = _D13_LABEL_OWNER_MOVES.get((path, owner), owner)
        label = _D13_LABEL_RENAMES.get(label, label)
        if path == "engine/live_kind_smoke.py" and "{exc}" in label:
            label = label.replace("{exc}", "{_observer_text(exc)}")
            observer_safe += count
        normalized[path, owner, label] += count
    assert observer_safe == 8, "D13 observer-safe diagnostic labels"
    assert normalized + _D13_ADDED_LABELS == observed, (
        "D13 original diagnostic label reconciliation",
        normalized + _D13_ADDED_LABELS - observed,
        observed - (normalized + _D13_ADDED_LABELS))
    assert sum(observed.values()) == 77, "D13 current label denominator"
    return normalized


def _d13_case_witness(case_type, name):
    """Rerun a shipped offline case and capture real durable sends/check output."""
    lock = threading.Lock()
    decisions, labels, failures = Counter(), Counter(), Counter()
    original_decision, original_print = FetchLedger.decision, builtins.print
    def decision(ledger, ids, payload):
        value = original_decision(ledger, ids, payload)
        with lock:
            decisions[ids["producer_id"]] += 1
        return value
    def printed(*args, **kwargs):
        if args and isinstance(args[0], str):
            line = args[0]
            if line.startswith(("[PASS] ", "[FAIL] ")):
                label = line.split("] ", 1)[1].split("  -- ", 1)[0]
                failed = line.startswith("[FAIL] ")
            elif line.startswith(("  PASS  ", "  FAIL  ")):
                label = line[8:]
                failed = line.startswith("  FAIL  ")
            else:
                label = None
            if label is not None:
                with lock:
                    labels[label] += 1
                    if failed:
                        failures[label] += 1
        return original_print(*args, **kwargs)
    result = unittest.TestResult()
    with patch.object(FetchLedger, "decision", new=decision), \
            patch.object(builtins, "print", new=printed), redirect_stdout(io.StringIO()):
        case_type(name).run(result)
    if result.testsRun != 1 or not result.wasSuccessful():
        detail = (result.errors + result.failures)[0][1][-2500:] \
            if result.errors or result.failures else "test did not run once"
        raise AssertionError(f"D13 witness {name} failed: {detail}")
    assert not failures, ("D13 diagnostic FAIL label", name, failures)
    assert tp._ACTIVE is None, ("D13 leaked offline guard", name)
    return decisions, labels


def _d10_terminal_witness(case_type, name):
    """Rerun a shipped fault case and observe the real ledger failure site."""
    lock = threading.Lock()
    faults = Counter()
    original_append, original_seal = FetchLedger._append, FetchLedger.seal

    def append(ledger, kind, ids, payload):
        prior = ledger._fault
        producer = ids.get("producer_id", "__run__")
        def observed(event, phase):
            try:
                return prior(event, phase)
            except BaseException:
                if kind != "seal":
                    with lock:
                        faults[producer, event, phase] += 1
                raise
        ledger._fault = observed
        try:
            return original_append(ledger, kind, ids, payload)
        finally:
            ledger._fault = prior

    def seal(ledger):
        prior = ledger._fault
        def observed(event, phase):
            try:
                return prior(event, phase)
            except BaseException:
                with lock:
                    faults["__run__", event, phase] += 1
                raise
        ledger._fault = observed
        try:
            return original_seal(ledger)
        finally:
            ledger._fault = prior

    result = unittest.TestResult()
    output = io.StringIO()
    with patch.object(FetchLedger, "_append", new=append), \
            patch.object(FetchLedger, "seal", new=seal), redirect_stdout(output):
        case_type(name).run(result)
    if result.testsRun != 1 or not result.wasSuccessful():
        detail = (result.errors + result.failures)[0][1][-2500:] \
            if result.errors or result.failures else "test did not run once"
        raise AssertionError(f"D10 witness {name} failed: {detail}")
    if tp._ACTIVE is not None:
        raise AssertionError(f"D10 witness {name} leaked its offline guard")
    return faults


