    actual = Counter((row["path"], row["property"]) for row in rows)
    assert len(_D10_TERMINAL_CASES) == 16 and all(n == 1 for n in expected.values())
    assert set(_D10_EXPECTED_FAULTS) == set(expected), "D10 expected fault inventory"
    assert actual == expected, ("D10 terminal denominator", actual - expected,
                                expected - actual)
    by_key = {(row["path"], row["property"]): row for row in rows}
    for path, prop, name, count in _D10_TERMINAL_CASES:
        row = by_key[path, prop]
