def _d06_calendar_verify(receipts):
    """Reconcile real targeted sends and publication against an independent grid."""
    from fetch_authority import TOKENS, parse_token

    expected = {
        base + ("-" + kind if kind else "") + ("-" + session if session != "rth" else "")
        for base in _D06_CALENDAR_BASES for kind in _D06_CALENDAR_KINDS
        for session in _D06_CALENDAR_SESSIONS
        if base != "1d" or session == "rth"
    }
    refused = {
        "1d" + ("-" + kind if kind else "") + "-" + session
        for kind in _D06_CALENDAR_KINDS for session in ("pre", "post")
    }
    assert len(expected) == 124 and len(refused) == 8, "D06 calendar denominator"
    assert set(TOKENS) == expected | refused and not expected & refused, \
        "D06 calendar shipped token drift"
    actual = Counter(row["token"] for row in receipts)
    assert actual == Counter({token: 1 for token in expected}), \
        ("D06 calendar missing/extra/duplicate receipt", actual)
    for row in receipts:
        base, kind, session = parse_token(row["token"])
        assert (base, kind, session) == tuple(row["identity"]), \
            ("D06 calendar wrong identity", row)
        assert row["sends"] == row["decisions"] == row["results"] > 0, \
            ("D06 calendar unbound send", row)
        assert row["accepted"] == row["stored"] > 0 and row["dropped"] > 0, \
            ("D06 calendar publication mismatch", row)
    return expected, refused


def _d04_verify_source_sites():
    """Each role has one exact production boundary in its owning source."""
    import importlib
    assert Counter(row[0] for row in _D04_SOURCE) == \
           Counter(row[0] for row in _D04_ROLES), "D04 source role denominator"
    for role, module_name, owner, needle in _D04_SOURCE:
        module = importlib.import_module(module_name)
        assert inspect.getsource(getattr(module, owner)).count(needle) == 1, \
            ("D04 source boundary missing or multiplied", role, module_name, owner)


def _d04_run_witness(case_type, name):
    """Profile direct real observer entries while one existing guarded case runs."""
    project = Path(__file__).resolve().parent.parent
    observe_code = bridge.without_authority(lambda: None).__code__
    lock = threading.RLock()
    entries = Counter()
    borrow_denials = Counter()
    violations = []

    def profile(frame, event, _value):
        if event != "call" or frame.f_back is None or \
                frame.f_back.f_code is not observe_code:
            return
        callback = frame.f_back.f_locals.get("callback")
        callback_code = getattr(callback, "__code__", None)
        if callback_code is None and callback is not None:
            callback_code = getattr(type(callback).__call__, "__code__", None)
        if frame.f_code is not callback_code:
            return
        caller = frame.f_back.f_back
        while caller is not None:
            try:
                path = Path(caller.f_code.co_filename).resolve().relative_to(project).as_posix()
            except ValueError:
                path = "outside-project"
            if path.startswith("engine/") and path not in {
                    "engine/fetch_ibkr_bridge.py", "engine/fetch_operations.py",
                    "engine/fetch_a2_ibkr_workflows_selftest.py"}:
                break
            caller = caller.f_back
        if caller is None:
            return
        key = (path, caller.f_code.co_qualname, frame.f_code.co_qualname)
        worker_none = bridge.current_worker() is None
        operation_none = op._CURRENT.get() is None
        try:
            op._not_observer()  # The same guard used by mint/child/borrow.
        except AuthorityError:
            mint_denied = True
        else:
            mint_denied = False
        active_parent = next(iter(op._OPERATIONS), None)
        if active_parent is not None:
            try:
                op._run(active_parent)  # A real open handle must remain unusable.
            except AuthorityError:
                borrow_denied = True
            else:
                borrow_denied = False
        else:
            borrow_denied = None
        with lock:
            entries[key] += 1
            if borrow_denied:
                borrow_denials[key] += 1
            if not (op._OBSERVER.get() and worker_none and operation_none
                    and mint_denied and borrow_denied is not False):
                violations.append((key, bool(op._OBSERVER.get()), worker_none,
                                   operation_none, mint_denied, borrow_denied))

    result, output = unittest.TestResult(), io.StringIO()
    prior_sys, prior_thread = sys.getprofile(), threading.getprofile()
    sys.setprofile(profile)
    threading.setprofile(profile)
    try:
        with redirect_stdout(output):
            case_type(name).run(result)
    finally:
        sys.setprofile(prior_sys)
        threading.setprofile(prior_thread)
    if result.testsRun != 1 or not result.wasSuccessful():
        detail = (result.errors + result.failures)[0][1][-2000:]
        raise AssertionError(f"D04 witness {name} failed: {detail}")
    if tp._ACTIVE is not None or op._OPERATIONS or op._CHILDREN:
        raise AssertionError(f"D04 witness {name} leaked offline authority")
    return {"entries": entries, "borrow_denials": borrow_denials,
            "violations": violations}


def _d04_verify(bindings, roles, receipts, catalog):
    """All ten families and exact role/site owners must execute in isolation."""
    positives = {row[3]: row[0] for row in bindings}
    required = set(positives) | set(_D04_HOSTILE)
    assert len(bindings) == len(positives) == 10, "D04 root denominator"
    assert required <= catalog and receipts.keys() == required, "D04 witness denominator"
    assert len(roles) == len(_D04_ROLES) and \
           len({row[0] for row in roles}) == len(roles), "D04 role denominator"
    assert Counter(roles) == Counter(_D04_ROLES), "D04 missing/extra role site"
    for method, receipt in receipts.items():
        assert receipt["entries"] and not receipt["violations"], \
            ("D04 observer authority leak", method, receipt["violations"])
    for method, path in positives.items():
        assert any(site[0] == path for site in receipts[method]["entries"]), \
            ("D04 unreached root callback", method, path)
    assert any(site[:2] == ("engine/stock_ibkr.py", "ReusableAdapter._live")
               for site in receipts[_D04_HOSTILE[-1]]["entries"]), \
        "D04 inherited stock factory not executed"
    for role, method, path, owner, callback in roles:
        matches = [(site, count) for site, count in receipts[method]["entries"].items()
                   if site[0] == path and site[1] == owner and
                   site[2].endswith(callback)]
        assert len(matches) == 1 and matches[0][1] >= 1 and \
               receipts[method]["borrow_denials"][matches[0][0]] >= 1, \
            ("D04 unreached or duplicated role site", role, method, matches)


def _d05_verify(rows, bindings, receipts):
    """Bind the six daily identities to real reached inventory sites."""
    assert len(bindings) == 6 and len({row[0] for row in bindings}) == 6, \
        "D05 daily producer denominator"
    assert len({row[1] for row in bindings}) == 6, "D05 daily site denominator"
    assert all(row[2].startswith("1d") for row in bindings), "D05 wrong token"
    expected = Counter((producer, site) for producer, site, _ in bindings)
    actual = Counter((row["producer_id"], row["site_key"]) for row in rows)
    assert actual == expected and all(n == 1 for n in actual.values()), \
        ("D05 daily inventory drift", actual - expected, expected - actual)
    assert set(receipts) == set(expected), "D05 daily physical site not reached"
    for row in rows:
        owner, qualname, primitive, ordinal = row["site_key"].split(":")
        assert row["module"] == owner and row["qualname"] == qualname and \
               row["primitive"] == primitive == "adapter_fetch" and \
               ordinal == "1" and row["transport"] == "ibkr-bars", \
               ("D05 wrong daily source owner", row["site_key"])


def _d06_verify(rows, bindings, receipts):
    """Bind every d minute/second physical site to a real reached send."""
    assert len(bindings) == 6 and len({row[0] for row in bindings}) == 6, \
        "D06 subdaily producer denominator"
    assert len({row[1] for row in bindings}) == 6, "D06 subdaily site denominator"
    assert Counter((row[2], row[3]) for row in bindings) == Counter({
        ("1m", "ibkr-bars"): 2,
        ("1m-hvol", "ibkr-bars"): 1,
        ("1m-iv", "ibkr-bars-unfiltered"): 1,
        ("1m-iv", "ibkr-bars"): 1,
        ("1s", "ibkr-bars"): 1,
    }), "D06 token/transport denominator"
    expected = Counter((producer, site) for producer, site, _, _ in bindings)
    actual = Counter((row["producer_id"], row["site_key"]) for row in rows)
    assert actual == expected and all(n == 1 for n in actual.values()), \
        ("D06 subdaily inventory drift", actual - expected, expected - actual)
    assert set(receipts) == set(expected), "D06 subdaily physical site not reached"
    for row in rows:
        owner, qualname, primitive, ordinal = row["site_key"].split(":")
        assert row["module"] == owner and row["qualname"] == qualname and \
               row["primitive"] == primitive == "adapter_fetch" and \
               ordinal in {"1", "2"} and row["transport"] == next(
                   binding[3] for binding in bindings if binding[0] == row["producer_id"]), \
            ("D06 wrong subdaily source owner", row["site_key"])


class Operations(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.authority = ScheduleAuthority.load()

    def setUp(self):
        if self._testMethodName in {
                "test_zz_d01_execution_bound_site_reconciliation",
                "test_zz_d02_execution_bound_root_reconciliation",
                "test_zz_d03_execution_bound_lifecycle_reconciliation",
                "test_zz_d04_execution_bound_observer_reconciliation",
                "test_zz_d05_execution_bound_daily_reconciliation",
                "test_zz_d06_execution_bound_subdaily_reconciliation",
                "test_zz_d06_calendar_physical_reconciliation",
                "test_zz_d07_audit_reconciliation",
                "test_zz_d10_terminal_fault_reconciliation",
                "test_zz_d13_regression_reconciliation",
                "test_zz_d14_default_release_reconciliation"}:
            # This oracle runs named witness cases below, each with its own
            # intact offline guard; do not nest another guard around them.
            self.assertIsNone(tp._ACTIVE)
            return
        if self._testMethodName == "diagnose_injected_fixdata_reference":
            import socket
            self._s5_socket = socket.socket
            self._s5_targets = tuple(tp._guard_targets())
            self._s5_originals = tuple(getattr(owner, name)
                                       for owner, name in self._s5_targets)
            # Registered first, therefore checked after policy/guard teardown.
            self.addCleanup(self.verify_injected_guard_restoration)
        if self._testMethodName == "legacy_ratio_hard_exit_contracts":
            # Static parent orchestration only. It owns no policy or request;
            # each fixed child/retry case creates its own intact guard below.
            self.assertIsNone(tp._ACTIVE)
            self._setup_local_fixture()
            return
        self.guard = tp.offline_transports()
        self.guard.__enter__()
        self.addCleanup(self.guard.__exit__, None, None, None)
        self.policy_scope = tp.offline_policy()
        self.capability = self.policy_scope.__enter__()
        self.addCleanup(self.policy_scope.__exit__, None, None, None)
        self._setup_local_fixture()

    def _setup_local_fixture(self):
        # Separate resources from guard ownership for the single static legacy
        # targeted-fill case below. This does not mint or extend policy lifetime.
        if self._testMethodName == "legacy_ratio_crash_worker":
            bank = self.legacy_crash_custody(self.crash_root)
            self.root = (bank.parent / "fetch-evidence").resolve()
            self.assertTrue(self.root.is_relative_to(bank.parents[1]))
