    def scheduler_driver_fixture(self, driver):
        """Original scheduler cases through shipped roots and raw-only fakes."""
        import platform
        import time as wall_time
        from fetch_ibkr_integration_selftest import ib_contract
        self.patch(platform, "machine", return_value="AMD64")
        created = self.root_fixture()
        self.fixture_now = datetime(2024, 6, 28, 17, tzinfo=NY)
        virtual, clock_lock = [0.0], threading.Lock()
        def clock():
            with clock_lock:
                return virtual[0]
        def sleep(seconds, cancel=None):
            if cancel is not None and cancel.is_set():
                raise ib.Cancelled()
            with clock_lock:
                virtual[0] += seconds
            wall_time.sleep(0)  # Yield only; controller timings remain real.
        self.patch(governors, "_REGISTRY", new=governors.GovernorRegistry(
            time_fn=clock, sleep_fn=sleep))
        modules = patch.dict("sys.modules", {"ib_async": SimpleNamespace(
            Stock=lambda symbol, exchange, currency: contract(symbol, 0),
            Contract=ib_contract)})
        modules.start()
        self.addCleanup(modules.stop)
        adapters, raw_calls = [], []
        class SchedulerRaw(RawIB):
            def __init__(raw, source):
                super().__init__()
                raw.source = source
                raw.head = getattr(source, "HEAD", driver.HEAD if hasattr(driver, "HEAD") else None)
            def managedAccounts(raw):
                return [raw.source.account()]
            def reqHistoricalDataAsync(raw, pinned, **kwargs):
                end = kwargs["endDateTime"]
                if isinstance(end, str):
                    end = datetime.fromisoformat(end)
                raw_calls.append((raw.source.port, pinned.symbol, kwargs))
                return raw.source.fetch(pinned, end, kwargs["durationStr"], kwargs["barSizeSetting"])
            def disconnect(raw):
                raw.source.disconnect()
        def wrap(source):
            adapter = ib.LiveIB()
            adapter.port = source.port
            adapter.ib = SchedulerRaw(source)
            adapter._await = lambda value, timeout, what: value
            adapter.reconnect = source.reconnect
            adapters.append(adapter)
            return adapter
        factory_name = "speed_factory" if hasattr(driver, "speed_factory") else "choke_factory"
        original_factory = getattr(driver, factory_name)
        def factory(*args, **kwargs):
            legacy_factory = original_factory(*args, **kwargs)
            def per_port(host, ports):
                make = legacy_factory(host, ports)
                return lambda: wrap(make())
            return per_port
        self.patch(driver, factory_name, new=factory)
        return created, raw_calls

    def _scheduler_driver_contracts(self, driver, expected):
        created, raw_calls = self.scheduler_driver_fixture(driver)
        result = driver._run_cases(temp_root=self.root / "scheduler", authority=self.authority)
        self.assertEqual(driver.N[0], expected, "original scheduler assertions were skipped")
        self.assertEqual(result, 0, driver.FAILS)
        self.assertEqual(driver.FAILS, [])
        self.assertTrue(raw_calls, "scheduler never reached the shipped raw choke")
        self.assertTrue(created)
        self.assertTrue(self.fixture_leases)
        self.assertTrue(all(lease.released for lease in self.fixture_leases))
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})
        for context in created:
            self.assertTrue(context.ledger.path.resolve().is_relative_to(self.root))
            self.assertTrue(inspect_ledger(context.ledger.path)["events"])

