    def test_callbacks_and_event_methods_cannot_borrow_or_mint(self):
        import ast
        import inspect
        self.root_fixture()
        plain_names = {"progress", "port_status", "on_series", "on_series_start", "on_recover",
                       "port_up", "restart_port", "restart_ports", "adapter_factory",
                       "preflight_factory", "watchdog_factory", "probe_fn", "import_fn"}
        object_names = {"cancel", "pause", "post_pipeline"}
        source = inspect.getsource(bridge.guard_callbacks)
        loops = [node for node in ast.parse(source).body[0].body if isinstance(node, ast.For)]
        self.assertEqual([set(ast.literal_eval(node.iter)) for node in loops],
                         [plain_names, object_names])
        mutations = {
            "plain": ("arguments[name] = without_authority(arguments[name])",
                      "arguments[name] = arguments[name]"),
            "objects": ("arguments[name] = _observer_object(arguments[name])",
                        "arguments[name] = arguments[name]"),
        }
        mutants = {}
        for label, (needle, replacement) in mutations.items():
            self.assertEqual(source.count(needle), 1)
            namespace = dict(vars(bridge))
            exec(compile(source.replace(needle, replacement), bridge.__file__, "exec"), namespace)
            mutants[label] = namespace["guard_callbacks"]
        for removed in ("none", "plain", "objects"):
            with self.subTest(removed=removed):
                registry, adapter, _ = self.metadata_fixture()
                adapter.ib.rows = [bar(datetime(2026, 7, 1, 9, 30, tzinfo=NY))]
                run = self.open(governors=registry)
                child = self.child(run)
                seen, leaks = [], []
                def observer(name):
                    def invoke(*args, **kwargs):
                        seen.append(name)
                        try:
                            minted = self.open()
                        except AuthorityError:
                            pass
                        else:
                            leaks.append((name, "mint"))
                            minted.seal()
                            minted.close()
                        try:
                            child.worker()
                        except AuthorityError:
                            pass
                        else:
                            leaks.append((name, "child"))
                        try:
                            ib.nightly_gap_fill(self.root, [],
                                adapter_factory=lambda: self.metadata_fixture()[1])
                        except AuthorityError:
                            pass
                        else:
                            leaks.append((name, "workflow-root"))
                        before = len(adapter.ib.calls)
                        try:
                            result = {"requests": 0, "counters": {
                                "invalid": 0, "outside_day": 0, "non_rth": 0}}
                            list(ib._fetch_sessions([date(2026, 7, 1)], "1m", adapter,
                                contract(), InstantPacer(), None, lambda _: None,
                                lambda: None, "TEST", result))
                        except AuthorityError:
                            pass
                        if len(adapter.ib.calls) > before:
                            self.assertEqual(len(adapter.ib.calls), before + 1)
                            leaks.append((name, "helper-send"))
                        return False
                    return invoke
                arguments = {name: observer(name) for name in plain_names}
                arguments.update({name: SimpleNamespace(is_set=observer(name + ".is_set"),
                    set=observer(name + ".set")) for name in ("cancel", "pause")})
                arguments["post_pipeline"] = SimpleNamespace(
                    **{name: observer("post_pipeline." + name)
                       for name in ("record_series", "claim", "has_pending")})
                mutants.get(removed, bridge.guard_callbacks)(arguments)
                watchdog = bridge.observer_object(SimpleNamespace(
                    snapshot=observer("watchdog.snapshot"),
                    interrupt_event=lambda port: SimpleNamespace(
                        is_set=observer("watchdog.interrupt.is_set"))))
                @bridge.worker_scope
                def dispatch():
                    for name, value in arguments.items():
                        if name in {"cancel", "pause"}:
                            value.is_set()
                            value.set()
                        elif name == "post_pipeline":
                            value.record_series([])
                            value.claim()
                            value.has_pending()
                        else:
                            value()
                    watchdog.snapshot()
                    watchdog.interrupt_event(1001).is_set()
                dispatch(_fetch_child=child)
                expected = (plain_names | {"cancel.is_set", "cancel.set", "pause.is_set", "pause.set",
                    "post_pipeline.record_series", "post_pipeline.claim", "post_pipeline.has_pending",
                    "watchdog.snapshot", "watchdog.interrupt.is_set"})
                self.assertEqual(set(seen), expected)
                self.assertEqual(len(seen), 22)
                def no_authority():
                    self.assertEqual(leaks, [])
                    self.assertEqual(adapter.ib.calls, [])
                if removed == "none":
                    no_authority()
                else:
                    with self.assertRaises(AssertionError):
                        no_authority()
                    affected = plain_names if removed == "plain" else {
                        "cancel.is_set", "cancel.set", "pause.is_set", "pause.set",
                        "post_pipeline.record_series", "post_pipeline.claim", "post_pipeline.has_pending"}
                    self.assertEqual(set(leaks), {(name, action) for name in affected
                        for action in ("mint", "child", "workflow-root", "helper-send")})
                    self.assertEqual(len(adapter.ib.calls), len(affected))
                self.assertEqual(op._CHILDREN, {})
                run.seal()
                run.close()
                self.assertEqual(op._OPERATIONS, {})

