    def session_property_adapter(self, adapter, worker, *, method_hook=False):
        """A real LiveIB with hostile session hooks, not a substitute fetch body."""
        case, observations = self, []
        thief = ib.LiveIB()
        thief.ib = RawIB()
        thief._await = lambda value, timeout, description: value
        def witness(label):
            case.assertTrue(bridge.current_worker() is None, label + " borrowed worker")
            case.assertTrue(bridge._SEND.get() is None, label + " borrowed send")
            captured = worker()
            case.assertIsNotNone(captured)
            with case.assertRaises(AuthorityError):
                thief.fetch(contract(), datetime(2026, 7, 31, 23, 59), "2 M", "1 day")
            with case.assertRaises(AuthorityError):
                thief.head_timestamp(contract())
            with case.assertRaises(AuthorityError):
                case.request(captured)
            with case.assertRaises(AuthorityError):
                op.narrow_worker_child(captured, "property-borrower")
            with case.assertRaises(AuthorityError):
                case.open()
            case.assertEqual(thief.ib.calls, [])
            observations.append(label)
        class SessionHooks(ib.LiveIB):
            @property
            def use_rth(self):
                witness("get")
                return self._session_value
            @use_rth.setter
            def use_rth(self, value):
                witness("set")
                self._session_value = value
        class MethodHook(SessionHooks):
            @property
            def fetch(self):
                witness("fetch")
                return ib.LiveIB.fetch.__get__(self)
            @property
            def reconnect(self):
                witness("reconnect-get")
                def reconnect():
                    witness("reconnect-call")
                    self._session_value = False  # Retry must reapply RTH.
                return reconnect
        adapter._session_value = False
        adapter.__dict__.pop("use_rth")
        adapter.__class__ = MethodHook if method_hook else SessionHooks
        return observations

    def test_targeted_session_properties_are_observers_at_actual_choke(self):
        import platform
        self.patch(platform, "machine", return_value="offline")
        self.root_fixture()
        original = ib._fetch_month_bars
        active = {}
        def capture(*args, **kwargs):
            active["worker"] = bridge.current_worker()
            return original(*args, **kwargs)
        self.patch(ib, "_fetch_month_bars", side_effect=capture)
        cases = [("1d", reused, "none") for reused in (False, True)] + [
            (token, reused, retry) for token in ("1m", "1m-pre")
            for reused in (False, True) for retry in ("pacing", "disconnect")]
        for token, reused, retry in cases:
            with self.subTest(token=token, reused=reused, retry=retry):
                registry, adapter, _ = self.metadata_fixture()
                observed = self.session_property_adapter(adapter, lambda: active.get("worker"), method_hook=True)
                opening = self.authority.window(token, date(2026, 7, 1))[0]
                adapter.ib.rows = [bar(date(2026, 7, 1) if token == "1d" else opening)]
                if retry == "pacing":
                    adapter.ib.failures = [ib.PacingViolation("session retry witness")]
                elif retry == "disconnect":
                    adapter.ib.failures = [ConnectionError("session reconnect witness")]
                with patch.object(governors, "_REGISTRY", registry):
                    borrowed = ib.ReusableAdapter(lambda: adapter) if reused else adapter
                    result = ib.fill_missing_days(borrowed, self.root / f"{token}-{reused}-{retry}", "TEST", token,
                        ["2026-07-01"], contract=contract(), _test_capability=self.capability)
                self.assertTrue(result["fetch_ledger"]["verified"], result)
                self.assertEqual(result["added"], 1)
                self.assertEqual(result["unfilled"], [])
                self.assertFalse(adapter._session_value)
                self.assertEqual(observed[0], "get")
                self.assertEqual(observed[-1], "set")
                calls = [c for c in adapter.ib.calls if c[0] == "bars"]
                self.assertTrue(calls)
                self.assertTrue(all(c[2]["useRTH"] == (token != "1m-pre") for c in calls))
                self.assertEqual(observed.count("get"), len(calls) + 1)
                self.assertEqual(observed.count("fetch"), len(calls))
                self.assertEqual(observed.count("reconnect-get"), int(retry == "disconnect"))
                self.assertEqual(observed.count("reconnect-call"), int(retry == "disconnect"))
                self.assertEqual(observed.count("set"), 2 if token == "1d" else len(calls) + 2)
                self.assertEqual(op._OPERATIONS, {})
                self.assertEqual(op._CHILDREN, {})

