    def calendar_boundary_rows(self, token, day):
        """Independent labels at both ends; never use the production acceptor as oracle."""
        from fetch_authority import BAR_SIZES, parse_token
        base, kind, _ = parse_token(token)
        opening, closing = self.authority.window(token, day)
        if base == "1d":
            positives = [day]
            closed = day + timedelta(days=(5 - day.weekday()) % 7)
            self.assertIsNone(self.authority.window(token, closed))
            negatives = [closed]
        else:
            step = BAR_SIZES[base][1]
            periods = (int((closing - opening).total_seconds()) - 1) // step
            positives = [opening, opening + timedelta(seconds=periods * step)]
            negatives = [opening - timedelta(seconds=1), closing, closing + timedelta(seconds=1)]
            if step > 1:
                negatives.append(opening + timedelta(seconds=1))
        def rows(labels):
            values = [bar(stamp) for stamp in labels]
            if kind in ib.ss.RATIO_KINDS:
                for value in values:
                    value.open, value.high, value.low, value.close = 0.25, 0.3, 0.2, 0.25
            return values
        expected = [datetime.combine(stamp, time.min) if type(stamp) is date
                    else stamp.replace(tzinfo=None) for stamp in positives]
        return rows(positives), rows(negatives), expected

    def targeted_calendar_case(self, token, days, bank_name):
        from fetch_authority import BAR_SIZES, KINDS, parse_token
        from fetch_envelopes import carrier_start
        base, kind, session = parse_token(token)
        registry, adapter, _ = self.metadata_fixture()
        raw, expected = [], []
        for day in days:
            positive, negative, stamps = self.calendar_boundary_rows(token, day)
            raw.extend(positive + negative)
            expected.extend(stamps)
        adapter.ib.rows = raw
        adapter.use_rth = False
        bank = self.root / bank_name / token
        with patch.object(governors, "_REGISTRY", registry):
            result = ib.fill_missing_days(adapter, bank, "TEST", token,
                [day.isoformat() for day in days], contract=contract(),
                _test_capability=self.capability)
        self.assertTrue(result["fetch_ledger"]["verified"], result)
        self.assertEqual(result["added"], len(expected), result)
        self.assertEqual(result["unfilled"], [])
        self.assertEqual(result["source_absent"], [])
        self.assertFalse(adapter.use_rth)
        sends = [call[2] for call in adapter.ib.calls if call[0] == "bars"]
        self.assertTrue(sends)
        self.assertTrue(all(send["barSizeSetting"] == BAR_SIZES[base][0] for send in sends))
        self.assertTrue(all(send["whatToShow"] == KINDS[kind] for send in sends))
        self.assertTrue(all(send["useRTH"] == (session == "rth") for send in sends))
        events = inspect_ledger(result["fetch_ledger"]["path"])["events"]
        decisions = [event for event in events if event["event"] == "decision"]
        results = [event for event in events if event["event"] == "result"]
        producer = "ibkr.gap_fill.month_daily" if base == "1d" else "ibkr.gap_fill.month_intraday"
        self.assertEqual({event["producer_id"] for event in decisions}, {producer})
        self.assertEqual(len(decisions), len(sends))
        self.assertEqual(len(results), len(sends))
        self.assertEqual(sum(event["payload"]["accepted"]["count"] for event in results), len(expected))
        self.assertEqual(sum(event["payload"]["observed"]["count"] for event in results), len(raw) * len(sends))
        self.assertGreater(sum(event["payload"]["dropped"] for event in results), 0)
        for event in decisions:
            for field in ("requested", "effective"):
                request = event["payload"][field]
                self.assertEqual(request["token"], token)
                self.assertEqual(request["what_to_show"], KINDS[kind])
                self.assertEqual(request["use_rth"], session == "rth")
                self.assertGreaterEqual(carrier_start(datetime.fromisoformat(request["raw_end"]),
                    request["duration"]).date(), self.authority.first_date)
                first = datetime.fromisoformat(request["intended_start"]).date()
                last = datetime.fromisoformat(request["intended_end"]).date()
                for offset in range((last - first).days + 1):
                    # Closed dates are representable; unsupported windows
                    # must have been split out before any request was made.
                    self.authority.window(token, first + timedelta(days=offset))
        stored = []
        manifest = ib.ss.load_manifest(bank / "TEST")
        for year, month in sorted({(day.year, day.month) for day in days}):
            path = ib.ss.find_month_file(bank, "TEST", year, month, token)
            rows, stats = ib.ss.read_month_file(path)
            stored.extend(row[0] for row in rows)
            entry = manifest["intervals"][token]["months"][ib.ss.month_key(year, month)]
            self.assertEqual(entry["sha256"], stats["sha256"])
        self.assertEqual(stored, sorted(expected))
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})
        return {"token": token, "identity": (base, kind, session),
                "sends": len(sends), "decisions": len(decisions),
                "results": len(results), "accepted": sum(
                    event["payload"]["accepted"]["count"] for event in results),
                "stored": len(stored), "dropped": sum(
                    event["payload"]["dropped"] for event in results)}

