    def legacy_integration_contracts_through_confined_transport(self):
        # Dedicated legacy CLI owner, not a second discovered copy of its78
        # cases inside the default Operations suite. run_gates runs both entries.
        import platform
        from fetch_ibkr_integration_selftest import Integration
        # Pandas' first Arrow conversion asks platform.machine(), which on
        # Windows queries the hostname. Keep that machine fact fixture-local.
        self.patch(platform, "machine", return_value="offline")
        guard = tp._ACTIVE
        guard.verify()
        capability = self.capability
        auxiliary = ib._auxiliary_directory
        registry = governors._REGISTRY
        # Deliberately use a started enclosing patch: global stopall in a nested
        # legacy cleanup must be detected, not merely hidden by context patches.
        sentinel = self.patch(ib, "_connection_diag_path", return_value=self.root / "outer.log")
        nested_cases = []

        def targeted_case(legacy_case):
            self.assertIs(tp._ACTIVE, guard)
            guard.verify()
            case = Operations("test_targeted_empty_pre_month_legacy_contract")
            case.capability = capability
            case.setUp = case._setup_local_fixture
            nested_cases.append(case)
            return case

        owner = self
        class GuardedResult(unittest.TestResult):
            def stopTest(result, case):
                super().stopTest(case)
                owner.assertIs(tp._ACTIVE, guard)
                guard.verify()
                owner.assertTrue(tp.capability_allows(capability,
                    "ibkr.gap_fill.month_intraday", "ibkr-bars", None))
                owner.assertIs(ib._connection_diag_path, sentinel,
                               "legacy cleanup removed enclosing patch")
                owner.assertIs(ib._auxiliary_directory, auxiliary,
                               "legacy cleanup removed enclosing patch")
                owner.assertIs(governors._REGISTRY, registry)
                owner.assertEqual(op._CHILDREN, {})
                owner.assertEqual(op._OPERATIONS, {})

        with patch.object(Integration, "_targeted_empty_pre_month_case", targeted_case):
            suite = unittest.defaultTestLoader.loadTestsFromTestCase(Integration)
            self.assertEqual(suite.countTestCases(), 78)
            result = GuardedResult()
            suite.run(result)
        print(f"{result.testsRun} checks, {len(result.errors) + len(result.failures)} failed")
        self.assertEqual(result.testsRun, 78)
        self.assertEqual(result.skipped, [])
        self.assertEqual(result.expectedFailures, [])
        self.assertTrue(result.wasSuccessful(), result.errors + result.failures)
        # The positive and the original inverse both ran the same real oracle.
        self.assertEqual(len(nested_cases), 2)
        self.assertTrue(all(not case.root.exists() for case in nested_cases))
        print("legacy Integration 78/78; enclosing guard/policy/patches intact")

