    def test_targeted_concurrent_manifest_merge_legacy_contract(self):
        import platform
        self.patch(platform, "machine", return_value="offline")
        bank = self.root / "merge-bank"
        barrier = threading.Barrier(2)
        manifest_lock = threading.Lock()
        run = self.open("repair")
        children = {token: self.child(run, token) for token in ("1m", "1h")}
        seen, errors, results = [], [], []
        def month(adapter, pinned, year, month, token, cancel=None):
            worker = bridge.current_worker()
            seen.append((worker.context, worker.worker_id))
            barrier.wait(timeout=5)
            return ([(datetime(year, month, 2, 9, 30), 1.0, 1.0, 1.0, 1.0, 100)], set())
        self.patch(ib, "_fetch_month_bars", side_effect=month)
        def fill(token):
            try:
                results.append(ib.fill_missing_days(SimpleNamespace(), bank, "MLK",
                    token, ["2025-07-02"], contract=contract("MLK"),
                    manifest_lock=manifest_lock, _fetch_child=children[token]))
            except BaseException as exc:
                errors.append(exc)
        threads = [threading.Thread(target=fill, args=(token,)) for token in children]
        for thread in threads:
            thread.start()
        for thread in threads:
            thread.join()
        self.assertFalse(errors, repr(errors))
        manifest = ib.ss.load_manifest(bank / "MLK") or {}
        self.assertTrue({"1m", "1h"} <= set(manifest.get("intervals", {})), manifest)
        self.assertEqual(len(results), 2)
        self.assertEqual(len(seen), 2)
        self.assertTrue(all(context is run.context for context, _ in seen))
        self.assertEqual(len({worker for _, worker in seen}), 2)
        for token in children:
            path = ib.ss.find_month_file(bank, "MLK", 2025, 7, token)
            self.assertEqual(len(ib.ss.read_month_file(path)[0]), 1)
        self.assertEqual(op._CHILDREN, {})
        run.seal()
        run.close()

    def test_targeted_cancel_partial_month_legacy_contract(self):
        import platform
        import stock_validate
        self.patch(platform, "machine", return_value="offline")
        self.root_fixture()
        registry, adapter, _ = self.metadata_fixture()
        self.patch(governors, "_REGISTRY", new=registry)
        cancelled = threading.Event()
        day = date(2025, 6, 24)
        adapter.ib.rows = [bar(datetime(2025, 6, 24, 9, 30, tzinfo=NY)
            + timedelta(minutes=index)) for index in range(60)]
        original = adapter.ib.reqHistoricalDataAsync
        def partial_then_cancel(pinned, **kwargs):
            rows = original(pinned, **kwargs)
            cancelled.set()
            return rows
        adapter.ib.reqHistoricalDataAsync = partial_then_cancel
        requested = ["2025-06-10", "2025-06-17", day.isoformat()]
        bank = self.root / "cancel-bank"
        # The connected-gap scanner intentionally ignores dates before its
        # first stored bar. Seed a prior month so both unvisited dates are
        # interior, while June still has no pre-existing manifest entry.
        prior_path = ib.ss.month_file_path(bank, "CXL", 2025, 5, "1m")
        stats = ib.ss.write_month_file(prior_path, [
            (datetime(2025, 5, 30, 9, 30), 10.0, 11.0, 9.0, 10.0, 100)])
        manifest = ib.ss.new_manifest("CXL", "CXL")
        manifest["conid"] = 123
        ib.ss.manifest_months(manifest, "1m")["2025-05"] = dict(stats, status="present")
        ib.ss.save_manifest(bank / "CXL", manifest)
        with self.assertRaises(ib.Cancelled) as caught:
            ib.fill_missing_days(adapter, bank, "CXL", "1m", requested,
                contract=contract("CXL"), cancel=cancelled.is_set,
                _test_capability=self.capability)
        evidence = caught.exception.fetch_ledger
        self.assertFalse(evidence["verified"])
        completion = evidence["targeted_fill"]
        self.assertEqual(completion["published_months"], ["2025-06"])
        self.assertEqual(completion["months"]["2025-06"]["stage"], "published")
        self.assertEqual(completion["unresolved_days"], requested[:2])
        self.assertEqual(completion["source_absent"], [])
        sends = [call for call in adapter.ib.calls if call[0] == "bars"]
        self.assertEqual(len(sends), 1)
        stored_path = ib.ss.find_month_file(bank, "CXL", 2025, 6, "1m")
        self.assertIsNotNone(stored_path, "cancel must retain the completed month write")
        stored = ib.ss.read_month_file(stored_path)[0]
        self.assertEqual(len(stored), 60)
        scan = stock_validate.scan_series_gaps(bank, "CXL", "1m",
            calendar_days=[date.fromisoformat(value) for value in requested])
        self.assertNotIn("error", scan, scan)
        self.assertEqual(scan["bars"], 61)
        self.assertEqual(scan["missing_days"], requested[:2], scan)
        self.assertEqual(scan["source_absent"], [], scan)
        manifest = ib.ss.load_manifest(bank / "CXL") or {}
        absent = manifest.get("intervals", {}).get("1m", {}).get("verified_absent", [])
        self.assertFalse(set(requested[:2]) & set(absent))
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})

