    def test_targeted_completion_survives_seal_and_report_faults(self):
        import platform
        self.patch(platform, "machine", return_value="offline")
        self.root_fixture()
        create, write_report = FetchRunContext.create, reporting.write_report
        for point, stages in (("seal", ("append", "flush", "fsync")),
                              ("report", ("create", "flush", "fsync", "replace"))):
            for stage in stages:
                with self.subTest(point=point, stage=stage):
                    registry, adapter, _ = self.metadata_fixture()
                    adapter.ib.rows = [bar(date(2025, 6, 3))]
                    bank = self.root / f"completion-{point}-{stage}"
                    def fault(kind, phase):
                        if (kind, phase) == (point, stage):
                            raise OSError("completion evidence witness")
                    report_patch = (patch.object(reporting, "write_report",
                        side_effect=lambda value, directory=None:
                        write_report(value, directory, fault=fault))
                        if point == "report" else nullcontext())
                    with patch.object(governors, "_REGISTRY", registry), patch.object(
                            FetchRunContext, "create", side_effect=lambda directory, **kwargs:
                            create(directory, fault=fault, **kwargs)), report_patch:
                        with self.assertRaises(LedgerError) as caught:
                            ib.fill_missing_days(adapter, bank, "TEST", "1d", ["2025-06-03"],
                                contract=contract(), _test_capability=self.capability)
                    report = caught.exception.fetch_ledger
                    self.assertFalse(report["verified"])
                    self.assertEqual(report["targeted_fill"]["published_months"], ["2025-06"])
                    self.assertEqual(report["targeted_fill"]["unresolved_days"], [])
                    self.assertIsNotNone(ib.ss.find_month_file(bank, "TEST", 2025, 6, "1d"))
                    parent = Path(report["path"]).parent
                    companion = parent / (report["operation_id"] + ".operation.json")
                    if point == "report":
                        self.assertFalse(report["report_persisted"])
                        self.assertEqual(report["operation_outcome"], "returned")
                        self.assertEqual(report["outcome"], "report_failed")
                        self.assertFalse(companion.exists())
                        self.assertEqual(list(parent.glob(".operation-*.tmp")), [])
                    else:
                        saved = json.loads(companion.read_text(encoding="utf-8"))
                        self.assertEqual(saved["targeted_fill"], report["targeted_fill"])
                    self.assertEqual(op._OPERATIONS, {})
                    self.assertEqual(op._CHILDREN, {})

