    @classmethod
    def run_fixdata_reference_cli(cls, module_name):
        """Fixed canonical entries; return the reference's own 0/1/3 result."""
        methods = {
            "fixdata_health_relocation_reference": "diagnose_unchanged_health_relocation_reference",
            "fixdata_port_death_reference": "diagnose_unchanged_port_death_reference",
            "fixdata_port_recovery_reference": "diagnose_unchanged_port_recovery_reference",
            "probe_wait_status_reference": "diagnose_unchanged_probe_wait_reference",
            "fixdata_pause_reference": "diagnose_unchanged_pause_reference",
            "fixdata_injected_fence_reference": "diagnose_injected_fixdata_reference",
        }
        case = cls(methods[module_name])
        case._reference_cli = True
        result = unittest.TextTestRunner(verbosity=2).run(unittest.TestSuite([case]))
        if not result.wasSuccessful():
            return 1  # Setup/containment/cleanup errors remain visible failures.
        return case._reference_exit

    def assert_injected_guard_owners(self, targets):
        self.assertEqual(len(targets), len(self._s5_targets))
        for (owner, name), (expected, expected_name) in zip(targets, self._s5_targets):
            self.assertIs(owner, expected)
            self.assertEqual(name, expected_name)
        self.assertEqual([name for owner, name in targets if owner is self._s5_socket],
                         ["connect", "connect_ex", "sendto"])
        self.assertFalse(any(isinstance(owner, type) and owner is not self._s5_socket
                             and issubclass(owner, self._s5_socket)
                             for owner, _ in targets))

    def verify_injected_guard_restoration(self):
        import socket
        self.assertIsNone(tp._ACTIVE)
        self.assertIs(socket.socket, self._s5_socket)
        for (owner, name), original in zip(self._s5_targets, self._s5_originals):
            self.assertIs(getattr(owner, name), original)
        self.assertFalse(getattr(self.capability, "_live", True))
        print("S5 OWNER CONTROL: production hooks and expired capability restored", flush=True)

    def compose_injected_guard(self):
        import os
        import socket
        import subprocess
        guard = tp._ACTIVE
        self.assert_injected_guard_owners(guard.targets)
        self.assertIsNot(socket.socket, self._s5_socket)
        self.assertTrue(issubclass(socket.socket, self._s5_socket))
        overlap = ((socket, "create_connection"), (socket, "getaddrinfo"),
                   (subprocess, "Popen"), (os, "system"))
        for owner, name in guard.targets:
            if (owner, name) not in overlap:
                self.assertIs(getattr(owner, name), tp._deny)
        # EarlyTripwire saved the existing policy denial as its original.
        # It restores that denial first; the outer guard restores production last.
        for owner, name in overlap:
            setattr(owner, name, tp._deny)
        guard.verify()
        return overlap

    def injected_composition_controls(self, reference):
        import socket
        guard = tp._ACTIVE
        self.assert_injected_guard_owners(guard.targets)
        before = {(owner, name): getattr(owner, name)
                  for owner, name in guard.targets}
        spawn_before = {name: getattr(reference.os, name) for name in dir(reference.os)
                        if name.startswith("spawn") and callable(getattr(reference.os, name))}
        for exceptional in (False, True):
            class CleanupSentinel(Exception):
                pass
            try:
                with reference.EarlyTripwire() as tripwire:
                    # The rejected order would capture this substitute class.
                    with self.assertRaises(AssertionError):
                        self.assert_injected_guard_owners(tuple(tp._guard_targets()))
                    with self.assertRaises(AuthorityError):
                        guard.verify()
                    overlap = self.compose_injected_guard()
                    for owner, name in overlap:
                        with self.assertRaises(AuthorityError):
                            getattr(owner, name)()
                    self.assertEqual(dict(tripwire.denials), {})
                    with self.assertRaises(reference.HarnessError):
                        socket.socket()
                    self.assertEqual(dict(tripwire.denials), {"socket.socket": 1})
                    for owner, name, original in tripwire._patches:
                        if (owner, name) in before:
                            self.assertIs(original, before[(owner, name)])
                    if exceptional:
                        raise CleanupSentinel()
            except CleanupSentinel:
                self.assertTrue(exceptional)
            self.assertIs(socket.socket, self._s5_socket)
            for (owner, name), value in before.items():
                self.assertIs(getattr(owner, name), value)
            for name, value in spawn_before.items():
                self.assertIs(getattr(reference.os, name), value)
            self.assertIs(tp._ACTIVE, guard)
            guard.verify()
        print("S5 OWNER CONTROLS: real owners, decoy inverse, four-hook denial cost, "
              "normal/exception reverse cleanup PASS", flush=True)

    def diagnose_injected_fixdata_reference(self):
        """S5 keeps its own probes, temporary roots, tripwires and exit code."""
        import hashlib
        import importlib
        self.fixdata_fixture()
        reference = importlib.import_module("fixdata_injected_fence_reference")
        source = Path(reference.__file__)
        before = hashlib.sha256(source.read_bytes()).hexdigest()
        guard = tp._ACTIVE
        guard.verify()
        existing_threads = set(threading.enumerate())
        self.injected_composition_controls(reference)
        load_subjects = reference.load_subjects
        loads = []

        def guarded_load_subjects(sources):
            self.compose_injected_guard()
            subjects = load_subjects(sources)
            guard.verify()
            loads.append(1)
            return subjects

        with tempfile.TemporaryDirectory(dir=self.root, prefix="reference-s5-") as temporary:
            reference_root = Path(temporary).resolve()
            with patch.object(tempfile, "tempdir", str(reference_root)), \
                    patch.object(reference, "_TEST_CAPABILITY", self.capability), \
                    patch.object(reference, "_REFERENCE_ROOT", reference_root), \
                    patch.object(reference, "load_subjects", guarded_load_subjects):
                try:
                    result = reference.run()
                finally:
                    self.assertIs(tp._ACTIVE, guard)
                    guard.verify()
                    self.assertEqual(op._OPERATIONS, {})
                    self.assertEqual(op._CHILDREN, {})
                    self.assertEqual([t.name for t in threading.enumerate()
                                      if t not in existing_threads and t.is_alive()], [])
                    self.assertEqual(list(reference_root.iterdir()), [])
                    self.assertEqual(hashlib.sha256(source.read_bytes()).hexdigest(), before)
        self.assertFalse(reference_root.exists())
        self.assertIs(reference.load_subjects, load_subjects)
        self.assertTrue(loads)
        print(f"S5 OWNER CONTROL: {len(loads)} guarded subject loads; no leaked threads/roots", flush=True)
        self.assertIn(result, (0, 1, 3))
        self._reference_exit = result

    def diagnose_unchanged_fixdata_reference(self, module_name):
        """Original reference body under the existing confined owner."""
        import hashlib
        import importlib
        from functools import wraps
        from check_kit import CheckKit
        self.assertIn(module_name, (
            "fixdata_health_relocation_reference", "fixdata_port_death_reference",
            "fixdata_port_recovery_reference", "gap_ignore_removal_reference",
            "probe_wait_status_reference", "fixdata_pause_reference"))
        pipeline = self.fixdata_fixture()
        reference = importlib.import_module(module_name)
        source_path = Path(reference.__file__)
        before = hashlib.sha256(source_path.read_bytes()).hexdigest()
        kit = CheckKit() if hasattr(reference, "KIT") else None
        if kit is not None:
            self.patch(reference, "KIT", new=kit)
            self.patch(reference, "check", new=kit.check)
            self.patch(reference, "section", new=kit.section)
        else:
            self.patch(reference, "COUNT", new=[0])
            self.patch(reference, "FAILURES", new=[])
        scanner_roots = []
        if module_name == "gap_ignore_removal_reference":
            self.patch(reference, "_TMP", new=scanner_roots)
        guard = tp._ACTIVE
        guard.verify()
        sentinel = ib._connection_diag_path
        auxiliary = ib._auxiliary_directory
        acquire = pipeline.operation_gate.acquire
        lock_path = pipeline.operation_gate.LOCK_PATH
        existing_threads = set(threading.enumerate())
        roots = []
        shipped = pipeline.run

        @wraps(shipped)
        def run(*args, **kwargs):
            # Keep each reference's temporary root and original callbacks.
            root = Path(kwargs["root"]).resolve()
            self.assertTrue(root.is_relative_to(reference_root))
            roots.append(root)
            self.assertNotIn("_test_capability", kwargs)
            self.assertNotIn("evidence_dir", kwargs)
            result = shipped(*args, **kwargs, _test_capability=self.capability,
                evidence_dir=self.root / f"reference-ledgers-{len(roots)}")
            if module_name == "fixdata_pause_reference":
                print("pause diagnostic " + json.dumps({
                    "scenario": root.name,
                    **{key: result.get(key) for key in (
                        "cancelled", "error", "port_errors", "unprocessed",
                        "fill_series", "acc_series", "checked")}}, sort_keys=True))
            return result

        # Own even the pause reference's mkdtemp, whose original main does not
        # remove it. Keep original cleanup for references which implement it.
        with tempfile.TemporaryDirectory(dir=self.root, prefix="reference-") as temporary:
            reference_root = Path(temporary).resolve()
            if module_name == "probe_wait_status_reference":
                self.patch(reference, "_fixture_root", new=reference_root / "probe-bank")
            with patch.object(tempfile, "tempdir", str(reference_root)), \
                    patch.object(pipeline, "run", run):
                try:
                    result = (reference.cli_main() if module_name == "fixdata_pause_reference"
                              else reference.main())
                finally:
                    self.assertIs(tp._ACTIVE, guard)
                    guard.verify()
                    self.assertTrue(tp.capability_allows(self.capability,
                        "ibkr.gap_fill.month_intraday", "ibkr-bars", None))
                    self.assertIs(ib._connection_diag_path, sentinel)
                    self.assertIs(ib._auxiliary_directory, auxiliary)
                    self.assertIs(pipeline.operation_gate.acquire, acquire)
                    self.assertEqual(pipeline.operation_gate.LOCK_PATH, lock_path)
                    self.assertEqual(op._OPERATIONS, {})
                    self.assertEqual(op._CHILDREN, {})
                    self.assertEqual([t.name for t in threading.enumerate()
                                      if t not in existing_threads and t.is_alive()], [])
                    if module_name == "gap_ignore_removal_reference":
                        self.assertEqual(roots, [])
                        self.assertTrue(scanner_roots)
                        self.assertTrue(all(root.is_relative_to(reference_root)
                                            and not root.exists() for root in scanner_roots))
                    else:
                        self.assertTrue(roots, "reference did not enter the real root")
                        if module_name not in ("probe_wait_status_reference",
                                               "fixdata_pause_reference"):
                            self.assertTrue(all(not root.exists() for root in roots))
                    self.assertEqual(hashlib.sha256(source_path.read_bytes()).hexdigest(), before)
        self.assertFalse(reference_root.exists())
        self.assertTrue(all(not root.exists() for root in roots))
        if kit is not None:
            self.assertTrue(kit.finished)
            total, failures = kit.total, kit.failures
        else:
            total, failures = reference.COUNT[0], reference.FAILURES
        self.assertGreater(total, 0)
        self.assertIn(result, (0, 1, 3))
        if getattr(self, "_reference_cli", False):
            self._reference_exit = result
        else:
            print(f"unchanged reference {module_name}: {total} checks; exit={result}")
            self.assertEqual(result, 0, failures)

