    def run_empty_month_reference(self):
        import hashlib
        import platform
        import empty_month_absence_reference as reference
        from check_kit import CheckKit
        reference_path = Path(reference.__file__)
        before = hashlib.sha256(reference_path.read_bytes()).hexdigest()
        self.patch(platform, "machine", return_value="offline")
        self.root_fixture()
        kit = CheckKit()
        self.patch(reference, "KIT", new=kit)
        self.patch(reference, "check", new=kit.check)
        self.patch(reference, "section", new=kit.section)
        roots = []
        self.patch(reference, "_TMPDIRS", new=roots)
        def fresh_root():
            parent = self.root / f"empty-reference-{len(roots)}"
            roots.append(parent)
            bank = parent / ib.ss.STORAGE_DIR_NAME
            bank.mkdir(parents=True)
            return bank
        self.patch(reference, "fresh_root", new=fresh_root)
        shipped = ib.fill_missing_days
        calls = []
        def fill(adapter, root, *args, **kwargs):
            self.assertTrue(Path(root).resolve().is_relative_to(self.root))
            calls.append((args[0], args[1]))
            # Preserve the reference's explicit scripted month-fetch seam.
            # This is a publication/control regression, not physical-ledger
            # evidence; separate actual-transport tests prove that boundary.
            return shipped(adapter, root, *args, **kwargs,
                evidence_dir=self.root / "reference-ledgers", _test_capability=self.capability)
        self.patch(ib, "fill_missing_days", side_effect=fill)
        result = reference.main()
        # The unchanged reference has a distinct pre-feature baseline:16 checks
        # and exit3 when green. Do not replace that exit with a wrapper failure.
        self.assertEqual(kit.total, 59 if reference.FEATURE else 16,
                         "reference assertion denominator changed")
        self.assertTrue(calls)
        self.assertTrue(roots)
        self.assertTrue(all(not root.exists() for root in roots))
        self.assertTrue(all(lease.released for lease in self.fixture_leases))
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})
        self.assertEqual(hashlib.sha256(reference_path.read_bytes()).hexdigest(), before)
        return result

    def test_unchanged_empty_month_reference_under_confined_owner(self):
        import empty_month_absence_reference as reference
        with patch.object(reference, "main", wraps=reference.main) as main:
            self.assertEqual(self.run_empty_month_reference(), 0)
        self.assertEqual(main.call_count, 1)

    def reference_baseline_exit_pin(self, *, inverse=False):
        import ast
        import io
        import empty_month_absence_reference as reference
        # Model the pre-feature engine/display seams, never change any original
        # reference assertion, main, reporting or cleanup implementation.
        self.patch(reference, "FEATURE", new=False)
        self.patch(ib, "_positive_empty_month_control", return_value=None)
        self.patch(reference, "DISPLAY_SOURCE", new=SimpleNamespace(
            exists=lambda: True, read_text=lambda **kwargs: "class DataViewerApp: pass"))
        execute = self.run_empty_month_reference
        if inverse:
            tree = ast.parse(Path(__file__).read_text(encoding="utf-8"))
            cls = next(n for n in tree.body if isinstance(n, ast.ClassDef) and n.name == "Operations")
            fn = next(n for n in cls.body if isinstance(n, ast.FunctionDef) and n.name == "run_empty_month_reference")
            choices = [n for n in ast.walk(fn) if isinstance(n, ast.IfExp)
                       and ast.unparse(n.test) == "reference.FEATURE"]
            self.assertEqual(len(choices), 1)
            choices[0].orelse = ast.Constant(value=59)
            namespace = dict(globals())
            exec(compile(ast.fix_missing_locations(ast.Module(body=[fn], type_ignores=[])), __file__, "exec"), namespace)
            execute = lambda: namespace[fn.name](self)
        output = io.StringIO()
        with patch("sys.stdout", output), patch.object(reference, "main", wraps=reference.main) as main:
            self.assertEqual(execute(), 3)
        self.assertEqual(main.call_count, 1)
        self.assertEqual(output.getvalue().count("16 checks, 0 failed"), 1)
        self.assertIn("harness exit=3", output.getvalue())

    def test_empty_month_reference_preserves_original_baseline_exit(self):
        self.reference_baseline_exit_pin()

    def test_inverse_fixed59_wrapper_breaks_original_baseline_exit(self):
        with self.assertRaisesRegex(AssertionError, "16 != 59"):
            self.reference_baseline_exit_pin(inverse=True)

    def nightly_calendar_resume(self, token, *, mixed=False):
        """Real stored-day discovery, nested target and forward dispatch; no GUI/network."""
        from contextlib import ExitStack
        import platform
        self.patch(platform, "machine", return_value="offline")
        bank = self.root / f"resume-{token}-{mixed}-{len(self.runs)}"
        folder = bank / "TEST"
        folder.mkdir(parents=True)
        manifest = ib.ss.new_manifest("TEST", "TEST")
        manifest["conid"] = 123
        calendar = [date(2024, 11, 26), date(2024, 11, 27),
                    date(2024, 11, 29), date(2024, 12, 2)]
        for iv in ("1d", token):
            months = {}
            for day in calendar:
                if iv != "1d" and (day.day == 29 or (mixed and day.day == 27)):
                    continue
                stamp = datetime.combine(day, time(4 if iv.endswith("pre") else 16))
                if iv == "1d":
                    stamp = datetime.combine(day, time.min)
                months.setdefault((day.year, day.month), []).append((stamp, 10., 10., 10., 10., 100))
            for (year, month), rows in months.items():
                path = ib.ss.month_file_path(bank, "TEST", year, month, iv)
                stats = ib.ss.write_month_file(path, rows)
                ib.ss.manifest_months(manifest, iv)[ib.ss.month_key(year, month)] = {**stats, "status": "present"}
        sec = manifest["intervals"][token]
        ib._backfill_marker(manifest, token, set_to=True)
        sec["backfill_incomplete_reason"] = "interrupted"
        ib.ss.save_manifest(folder, manifest)
        registry, adapter, _ = self.metadata_fixture()
        recovered_stamp = datetime(2024, 11, 27, 4 if token.endswith("pre") else 16)
        adapter.ib.rows = [bar(recovered_stamp.replace(tzinfo=NY))] if mixed else []
        run = self.open("nightly", governors=registry)
        child = self.child(run, "resume")
        forward = []
        last = ib.series_last_dt(manifest, token)
        plan = {"empty_series": False, "days": [date(2024, 12, 3)],
                "clipped_1s": False, "last_stored": last}
        @bridge.worker_scope
        def execute():
            return ib._fill_series(bank, adapter, SimpleNamespace(_pause=None), "TEST", token,
                "resume-proof", None, None, None, date(2024, 12, 3), since=date(2024, 11, 26))
        with ExitStack() as stack:
            stack.enter_context(patch.object(ib, "plan_gap", return_value=plan))
            stack.enter_context(patch.object(ib, "_run_days", side_effect=lambda *a, **k: forward.append(a[1])))
            sealed = stack.enter_context(patch.object(ib, "_backfill_try_seal", wraps=ib._backfill_try_seal))
            result = execute(_fetch_child=child)
        self.assertIsNone(result["halt"], result)
        self.assertEqual(sealed.call_count, 1, result)
        self.assertEqual(forward, [[date(2024, 12, 3)]])
        self.assertIsNone(result["halt"])
        self.assertFalse(ib._backfill_marker(ib.ss.load_manifest(folder), token))
        if mixed:
            self.assertTrue(adapter.ib.calls, "eligible mixed holes must still reach transport")
            self.assertEqual(result["added"], 1)
            rows, _ = ib.ss.read_month_file(ib.ss.find_month_file(bank, "TEST", 2024, 11, token))
            self.assertIn(recovered_stamp, [row[0] for row in rows])
        else:
            self.assertEqual(adapter.ib.calls, [])
            self.assertTrue(any("no supported settled request day" in note for note in result["notes"]))
            self.assertEqual(inspect_ledger(run.context.ledger.path, require_seal=False)["events"], [])
        self.assertEqual(op._CHILDREN, {})
        run.seal(); run.close()

