    def gui_targeted_loop(self, method, category, *, failure=None, inverse_terminal=False):
        """Execute each entire shipped GUI method, never import Tk or launch a thread."""
        import ast
        from contextlib import ExitStack
        source = Path(ib.__file__).parents[1] / "display_data.py"
        tree = ast.parse(source.read_text(encoding="utf-8"), filename=str(source))
        cls = next(n for n in tree.body if isinstance(n, ast.ClassDef) and n.name == "DataViewerApp")
        function = next(n for n in cls.body if isinstance(n, ast.FunctionDef) and n.name == method)
        if inverse_terminal:
            guards = [n for n in ast.walk(function) if isinstance(n, ast.ExceptHandler)
                      and isinstance(n.type, ast.Tuple)
                      and any(isinstance(t, ast.Attribute) and t.attr == "AuthorityError" for t in n.type.elts)]
            self.assertEqual(len(guards), 1)
            guards[0].body = [ast.Pass()]
        token, days = {
            "unsupported": ("1m-pre", ["2024-11-29"]),
            "closed": ("1m", ["2026-07-03"]),
            "unsettled": ("1m", ["2026-08-05"]),
        }[category]
        pairs = [("FIRST", token), ("LATER", "1m")]
        calls, messages, scheduled, outcomes = [], [], [], []
        validator = SimpleNamespace(
            consensus_calendar=lambda root: [date(2024, 11, 29)],
            scan_series_gaps=lambda *a, **k: {"missing_days": days},
            scan_all_gaps=lambda *a, **k: {"summary": {
                f"{t} {iv}": {"missing_day_list": days} for t, iv in pairs}},
            update_gap_report=lambda *a, **k: {"missing_days_run": 1})
        app = SimpleNamespace(_storage_root=self.root / "gui-bank", _gap_cal_cache=[1],
            _xval_finish=lambda: None, _seal_aborted=lambda: False,
            _tws_ports=lambda: [1001], _storage_ibkr_say=messages.append,
            _storage_ibkr_refresh=lambda: None,
            root=SimpleNamespace(after=lambda delay, callback: scheduled.append(callback)))
        namespace = {"stock_ibkr": ib, "stock_storage": ib.ss, "stock_validate": validator}
        module = ast.fix_missing_locations(ast.Module(body=[function], type_ignores=[]))
        exec(compile(module, str(source), "exec"), namespace)
        shipped = ib.fill_missing_days
        def dispatch(adapter, root, ticker, interval, requested, **kwargs):
            calls.append(ticker)
            if ticker == "LATER":
                return {"added": 7}
            if failure is not None:
                raise failure
            try:
                return shipped(adapter, root, ticker, interval, requested, **kwargs,
                               _test_capability=self.capability)
            except ib.TargetedNoRequest as exc:
                outcomes.append(exc)
                raise
        class InlineThread:
            def __init__(self, *, target, **kwargs):
                self.target = target
            def start(self):
                self.target()
        with ExitStack() as stack:
            stack.enter_context(patch.object(ib, "fill_missing_days", side_effect=dispatch))
            factory = stack.enter_context(patch.object(ib, "live_adapter_factory",
                return_value=lambda: self.fail("calendar-only GUI request connected")))
            report = stack.enter_context(patch.object(validator, "update_gap_report", wraps=validator.update_gap_report))
            stack.enter_context(patch.object(threading, "Thread", new=InlineThread))
            if method == "_finalize_drain_and_seal":
                result = namespace[method](app, pairs, [1001], messages.append)
                self.assertEqual(result, (7, 0) if failure is None else (0, 0))
            else:
                namespace[method](app, None)
                self.assertEqual(len(scheduled), 1)
                scheduled[0]()
            self.assertEqual(factory.call_count, 1)
            self.assertEqual(report.call_count, 1 if failure is None else 0)
        self.assertEqual(calls, ["FIRST", "LATER"] if failure is None else ["FIRST"])
        if failure is None:
            self.assertEqual(len(outcomes), 1, "must exercise the real calendar-only refusal")
            self.assertNotIsInstance(outcomes[0], AuthorityError)
            self.assertEqual(outcomes[0].fetch_ledger["targeted_fill"]["state"], "no_request")
        if method == "_storage_heal_gaps":
            self.assertTrue(any(("+7" if failure is None else "skipped") in line for line in messages), messages)
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})

