    def test_c2_prefetch_durability_never_publishes_partial_cache(self):
        from fetch_ibkr_integration_selftest import ib_contract
        day = date(2026, 7, 8)
        tokens = ("1m", "1m-pre", "1m-post")
        hours = {"1m": 9, "1m-pre": 4, "1m-post": 16}
        scenarios = [(None, None, None)] + [
            (event, stage, nth) for event in ("decision", "result")
            for stage in ("append", "flush", "fsync") for nth in (1, 2)]
        with patch.dict("sys.modules", {"ib_async": SimpleNamespace(Contract=ib_contract)}):
            for combined in (False, True):
                for event, stage, nth in scenarios:
                    label = f"prefetch-{combined}-{event}-{stage}-{nth}"
                    with self.subTest(combined=combined, event=event, stage=stage, nth=nth):
                        bank = self.root / label / "bank"
                        folder = bank / "TEST"
                        folder.mkdir(parents=True)
                        manifest = ib.ss.new_manifest("TEST", "TEST")
                        manifest["conid"] = 123
                        ib.ss.save_manifest(folder, manifest)
                        before = {p.relative_to(bank): p.read_bytes()
                                  for p in bank.rglob("*") if p.is_file()}
                        registry, adapter, _ = self.metadata_fixture()
                        adapter.ib.rows = [bar(datetime(2026, 7, 8, hour, minute, tzinfo=NY))
                                           for hour, minute in ((4, 0), (9, 30), (16, 0))]
                        matched, fired = [], []
                        def fault(kind, phase):
                            if (kind, phase) == (event, stage):
                                matched.append((kind, phase))
                                if len(matched) == nth:
                                    fired.append((kind, phase))
                                    raise OSError("prefetch durability witness")
                        run = self.open("repair", governors=registry, fault=fault,
                                        evidence_dir=self.root / label / "evidence")
                        pacer = InstantPacer()
                        report = {"requests": 0,
                                  "counters": {"invalid": 0, "outside_day": 0, "non_rth": 0}}
                        sentinel = object()
                        published = {"cache": sentinel}
                        @bridge.worker_scope
                        def invoke():
                            if combined:
                                return ib._prefetch_combined(bank, adapter, pacer,
                                    "TEST", "1m", tokens, {"TEST": 123}, day,
                                    None, None, lambda _: None, report)
                            return ib._prefetch_unfiltered(adapter, pacer, contract(),
                                "TEST", "1m", tokens, [day], None, lambda _: None, report)
                        plan = {"days": [day], "empty_series": False}
                        with patch.object(ib, "plan_gap", return_value=plan), patch.object(
                                ib, "split_session_bars", wraps=ib.split_session_bars) as split:
                            if event is None:
                                published["cache"] = invoke(_fetch_child=self.child(run))
                                self.assertEqual(set(published["cache"]), set(tokens))
                                for token in tokens:
                                    self.assertEqual(set(published["cache"][token]), {day})
                                    rows = published["cache"][token][day]
                                    self.assertEqual(len(rows), 1)
                                    self.assertEqual(rows[0][0].hour, hours[token])
                                self.assertEqual(split.call_count, 3)
                                self.assertEqual(fired, [])
                                expected_sends = 3
                                run.seal()
                                self.assertTrue(run.context.ledger.verified)
                            else:
                                with self.assertRaisesRegex(LedgerError, "prefetch durability witness"):
                                    published["cache"] = invoke(_fetch_child=self.child(run))
                                self.assertIs(published["cache"], sentinel)
                                self.assertEqual(fired, [(event, stage)])
                                self.assertEqual(len(matched), nth)
                                self.assertEqual(split.call_count, nth - 1)
                                expected_sends = nth - int(event == "decision")
                                self.assertFalse(run.context.ledger.verified)
                        self.assertEqual([call[0] for call in adapter.ib.calls],
                                         ["bars"] * expected_sends)
                        self.assertEqual(pacer.turns, 0)
                        self.assertEqual({p.relative_to(bank): p.read_bytes()
                                          for p in bank.rglob("*") if p.is_file()}, before)
                        self.assertEqual(op._CHILDREN, {})
                        run.close()
                        self.assertEqual(op._OPERATIONS, {})

