    def test_nested_targeted_child_inherits_parent_and_cannot_widen(self):
        run = self.open("nightly")
        parent = self.child(run, rights={QUALIFY})
        @bridge.worker_scope
        def nested():
            worker = bridge.current_worker()
            child = op.narrow_worker_child(worker, "targeted")
            with op.scoped_worker(child, close=True) as inner:
                self.assertIs(inner.context, run.context)
                self.assertEqual(op.operation_purpose(inner.context), "nightly")
                with self.assertRaisesRegex(AuthorityError, "outside"):
                    self.request(inner, SEARCH)
            with self.assertRaisesRegex(AuthorityError, "widen"):
                op.narrow_worker_child(worker, "widen", rights={SEARCH})
            with self.assertRaises(AuthorityError):
                bridge.without_authority(op.narrow_worker_child)(worker, "observer")
        nested(_fetch_child=parent)
        for forged in (None, SimpleNamespace(context=run.context, worker_id="worker")):
            with self.assertRaisesRegex(AuthorityError, "explicit operation child"):
                op.narrow_worker_child(forged, "forged")
        self.assertEqual(op._CHILDREN, {})
        run.seal()

    def unbound_worker_narrowing_pin(self, *, inverse=False):
        import ast
        old = FetchRunContext.create(self.root / "unbound", authority=self.authority,
            clock=lambda: datetime(2026, 8, 4, 17, tzinfo=NY))
        self.addCleanup(old.ledger.close)
        worker = old.worker("unbound")
        run = self.open()
        child = self.child(run, "bound")
        narrow = op.narrow_worker_child
        if inverse:
            tree = ast.parse(Path(op.__file__).read_text(encoding="utf-8"))
            fn = next(n for n in tree.body if isinstance(n, ast.FunctionDef) and n.name == "narrow_worker_child")
            block = next(n for n in ast.walk(fn) if isinstance(n, ast.If)
                         and ast.unparse(n.test) == "value is None")
            block.body = [ast.Pass()]
            namespace = dict(vars(op))
            exec(compile(ast.fix_missing_locations(ast.Module(body=[fn], type_ignores=[])), op.__file__, "exec"), namespace)
            narrow = namespace[fn.name]
        with child.scope():
            self.assertIsNone(op._active_child(old, "unbound"))
            with self.assertRaisesRegex(AuthorityError, "nested task requires an explicit operation child"):
                borrowed = narrow(worker, "must-refuse")
                self.children.append(borrowed)  # inverse cleanup; no leaked child

    def test_unbound_worker_nested_narrowing_is_named_refusal(self):
        self.unbound_worker_narrowing_pin()

    def test_inverse_unbound_worker_guard_removal_breaks_named_refusal(self):
        with self.assertRaises(AssertionError):
            self.unbound_worker_narrowing_pin(inverse=True)

    def test_retired_provider_exception_hooks_are_observers(self):
        from contextlib import ExitStack
        for token in ("1m", "1d", "1d-iv", "1d-hvol"):
            for base in (ConnectionError, RuntimeError, ib.PacingViolation, ib.SeriesHalt):
                for reject in (None, "str", "format"):
                    with self.subTest(token=token, error=base.__name__, reject=reject), ExitStack() as cleanup:
                        cleanup.callback(self.cleanup_handles)
                        registry, adapter, _ = self.metadata_fixture()
                        run = self.open("diagnostic", governors=registry)
                        child = self.child(run)
                        with child.scope():
                            worker = child.worker()
                        observed, leaks = [], []
                        thief = ib.LiveIB()
                        thief.ib = RawIB()
                        thief._await = lambda value, timeout, what: value

                        def witness(hook):
                            observed.append(hook)
                            if bridge.current_worker() is not None:
                                leaks.append((hook, "worker"))
                            if bridge._SEND.get() is not None:
                                leaks.append((hook, "send"))
                            for label, action in (
                                    ("bars", lambda: thief.fetch(contract(), datetime(2026, 7, 1, 16), "1 D", "1 day")),
                                    ("head", lambda: thief.head_timestamp(contract())),
                                    ("request", lambda: self.request(worker)),
                                    ("child", lambda: op.narrow_worker_child(worker, "exception-hook")),
                                    ("root", lambda: self.open("diagnostic"))):
                                try:
                                    value = action()
                                except AuthorityError:
                                    continue
                                leaks.append((hook, label))
                                if label in {"root", "child"}:
                                    value.close()

                        class FormatFailure(RuntimeError):
                            pass

                        class ProviderFailure(base):
                            def __str__(error):
                                witness("str")
                                if reject == "str":
                                    raise FormatFailure("offline string failure")
                                return "offline provider failure"

                            def __format__(error, spec):
                                witness("format")
                                if reject == "format":
                                    raise FormatFailure("offline format failure")
                                return format(str(error), spec)

                        failure = ProviderFailure("offline")
                        adapter.ib.failures.append(failure)
                        adapter.use_rth = False
                        private = InstantPacer()
                        if reject is None:
                            result = ib._retired_spot_check_day(adapter, contract(), token,
                                date(2026, 7, 1), [], private, None, _fetch_child=child)
                            self.assertEqual(result["result"], "skipped")
                            self.assertIn("offline provider failure", result["detail"])
                        else:
                            with self.assertRaises(FormatFailure):
                                ib._retired_spot_check_day(adapter, contract(), token,
                                    date(2026, 7, 1), [], private, None, _fetch_child=child)
                        # Assertions outside the hostile hook cannot be swallowed
                        # by provider wrapping, ledger formatting, or skip handling.
                        self.assertEqual(leaks, [], "provider exception observer borrowed authority")
                        self.assertTrue(observed)
                        self.assertFalse(adapter.use_rth)
                        self.assertEqual(thief.ib.calls, [])
                        self.assertEqual(len(adapter.ib.calls), 1)
                        self.assertEqual(private.turns, 0)
                        self.assertFalse(child in op._CHILDREN)
                        events = inspect_ledger(run.context.ledger.path, require_seal=False)["events"]
                        self.assertEqual(sum(e["event"] == "decision" for e in events), 1)
                        # C2 preserves a physical error receipt even if __str__ fails.
                        results = [e["payload"] for e in events if e["event"] == "result"]
                        self.assertEqual(len(results), 1)
                        if base is ib.PacingViolation and reject == "str":
                            self.assertEqual(results[0]["outcome"], "error")
                            self.assertEqual(results[0]["error_type"], "ProviderFailure")
                            self.assertEqual(results[0]["error"], "exception details unavailable")
                        governor = registry.ibkr(["TEST-ACCOUNT"])
                        self.assertEqual(governor._pacer._forced, base is ib.PacingViolation)
                        run.seal()
                        run.close()
                        self.assertEqual(len(op._CHILDREN), 0)
                        self.assertEqual(len(op._OPERATIONS), 0)

    def test_retired_diagnostic_receipt_fallback_removal_inverse(self):
        import inspect
        import textwrap
        import fetch_run_context as frc
        source = textwrap.dedent(inspect.getsource(frc.LogicalRequest._execute))
        seam = 'message = "exception details unavailable"'
        self.assertEqual(source.count(seam), 1)
        namespace = dict(vars(frc))
        exec(compile(source.replace(seam, "raise formatting"), frc.__file__, "exec"), namespace)
        class FormattingFailure(RuntimeError):
            pass
        class ProviderFailure(ib.PacingViolation):
            def __str__(error):
                self.assertIsNone(bridge.current_worker())
                raise FormattingFailure("ordinary diagnostic failure")
        def receipt(events):
            results = [e["payload"] for e in events if e["event"] == "result"]
            self.assertEqual(len(results), 1, "physical error receipt was lost")
            self.assertEqual(results[0]["outcome"], "error")
            self.assertEqual(results[0]["error_type"], "ProviderFailure")
            self.assertEqual(results[0]["error"], "exception details unavailable")
        for broken in (False, True):
            with self.subTest(broken=broken):
                registry, adapter, _ = self.metadata_fixture()
                run = self.open("diagnostic", governors=registry)
                adapter.ib.failures.append(ProviderFailure("original"))
                scope = (patch.object(frc.LogicalRequest, "_execute", namespace["_execute"])
                         if broken else nullcontext())
                with scope, self.assertRaises(FormattingFailure):
                    ib._retired_spot_check_day(adapter, contract(), "1m", date(2026, 7, 1),
                        [], InstantPacer(), None, _fetch_child=self.child(run))
                self.assertEqual(len(adapter.ib.calls), 1)
                events = inspect_ledger(run.context.ledger.path, require_seal=False)["events"]
                self.assertEqual(sum(e["event"] == "decision" for e in events), 1)
                if broken:
                    with self.assertRaisesRegex(AssertionError, "physical error receipt was lost"):
                        receipt(events)
                    with self.assertRaises(LedgerError):
                        run.seal()
                else:
                    receipt(events)
                    run.seal()
                self.assertEqual(registry.ibkr(["TEST-ACCOUNT"])._pacer._forced, not broken)
                run.close()
                self.assertEqual(op._CHILDREN, {})
                self.assertEqual(op._OPERATIONS, {})


    def test_retired_adapter_descriptors_are_observers(self):
        from contextlib import ExitStack
        for token in ("1m", "1m-pre", "1d", "1d-iv", "1d-hvol"):
            for reused in (False, True):
                with self.subTest(token=token, reused=reused), ExitStack() as cleanup:
                    cleanup.callback(self.cleanup_handles)
                    registry, adapter, _ = self.metadata_fixture()
                    run = self.open("diagnostic", governors=registry)
                    child = self.child(run)
                    with child.scope():
                        worker = child.worker()
                    day = date(2026, 7, 1)
                    opening, _ = self.authority.window(token, day)
                    raw = ([bar(day)] if token.startswith("1d") else
                           [bar(opening), bar(opening + timedelta(minutes=1))])
                    if token in ("1d-iv", "1d-hvol"):
                        for row in raw:
                            row.open, row.high, row.low, row.close = 0.25, 0.3, 0.2, 0.25
                    adapter.ib.rows = raw
