    def test_retired_helper_all_bases_kinds_sessions_use_canonical_turns(self):
        from fetch_authority import BAR_SIZES, KINDS, SESSION_WINDOWS
        from datetime import timedelta
        day = date(2026, 7, 1)
        cases = 0
        for base in BAR_SIZES:
            for kind, what in KINDS.items():
                for session in SESSION_WINDOWS:
                    token = base + ("-" + kind if kind else "") + ("-" + session if session != "rth" else "")
                    if base == "1d" and session != "rth":
                        continue  # Daily extended sessions have no calendar authority.
                    with self.subTest(token=token):
                        registry, adapter, _ = self.metadata_fixture()
                        run = self.open("diagnostic", governors=registry)
                        window = self.authority.window(token, day)
                        if base == "1d":
                            raw = [bar(day)]
                        else:
                            step = timedelta(seconds=BAR_SIZES[base][1])
                            raw = [bar(window[0]), bar(window[0] + step)]
                        if kind in ib.ss.RATIO_KINDS:
                            for row in raw:
                                row.open, row.high, row.low, row.close = 0.25, 0.3, 0.2, 0.25
                        adapter.ib.rows = raw
                        stored = ib.convert_bars(raw, day,
                            {"invalid": 0, "outside_day": 0, "non_rth": 0}, token)
                        pacer = InstantPacer()
                        adapter.use_rth = False
                        result = ib._retired_spot_check_day(adapter, contract(), token, day,
                            stored, pacer, None, _fetch_child=self.child(run))
                        self.assertEqual(result["result"], "ok")
                        self.assertEqual(result["compared"], max(0, len(stored) - 1))
                        self.assertFalse(adapter.use_rth)
                        self.assertEqual(pacer.turns, 0)  # No second private turn.
                        sends = [call[2] for call in adapter.ib.calls if call[0] == "bars"]
                        self.assertEqual(len(sends), len(ib.day_requests(token, day)))
                        self.assertTrue(all(send["whatToShow"] == what for send in sends))
                        self.assertTrue(all(send["useRTH"] == (session == "rth") for send in sends))
                        run.seal()
                        events = inspect_ledger(run.context.ledger.path)["events"]
                        self.assertEqual(sum(event["event"] == "decision" for event in events), len(sends))
                        self.assertEqual(sum(event["event"] == "result" for event in events), len(sends))
                        cases += 1
        self.assertEqual(cases, 124)

    def test_retired_helper_calendar_and_closing_grid(self):
        from fetch_authority import TOKENS, parse_token
        days = [date(1980, 1, 2), date(1980, 2, 1), date(2024, 2, 29), date(2024, 3, 8),
                date(2024, 3, 11), date(2024, 11, 1), date(2024, 11, 4), date(2024, 11, 29)]
        cases = 0
        for day in days:
            for token in TOKENS:
                base, _, session = parse_token(token)
                if (base == "1d" or day == date(2024, 11, 29)) and session != "rth":
                    continue
                with self.subTest(day=day, token=token):
                    registry, adapter, _ = self.metadata_fixture()
                    # Independent calendar cases do not share an ever-growing
                    # filename-allocation directory; real ledger I/O is retained.
                    evidence_dir = self.root / f"calendar-{cases:04d}"
                    run = self.open("diagnostic", governors=registry, evidence_dir=evidence_dir)
                    self.assertEqual(run.context.ledger.path.parent, evidence_dir)
                    positive, negative, _ = self.calendar_boundary_rows(token, day)
                    adapter.ib.rows = positive + negative
                    stored = ib.convert_bars(positive, day,
                        {"invalid": 0, "outside_day": 0, "non_rth": 0}, token)
                    pacer = InstantPacer()
                    adapter.use_rth = False
                    result = ib._retired_spot_check_day(adapter, contract(), token, day,
                        stored, pacer, None, _fetch_child=self.child(run))
                    self.assertEqual(result["result"], "ok")
                    self.assertEqual(result["compared"], max(0, len(positive) - 1))
                    self.assertEqual(pacer.turns, 0)
                    self.assertFalse(adapter.use_rth)
                    run.seal()
                    events = inspect_ledger(run.context.ledger.path)["events"]
                    decisions = [event["payload"] for event in events if event["event"] == "decision"]
                    opening, closing = self.authority.window(token, day)
                    for field in ("requested", "effective"):
                        spans = [(datetime.fromisoformat(event[field]["intended_start"]),
                                  datetime.fromisoformat(event[field]["intended_end"])) for event in decisions]
                        self.assertEqual(spans[0][0], opening)
                        self.assertEqual(spans[-1][1], closing)
                        self.assertTrue(all(start >= opening and end <= closing for start, end in spans))
                        self.assertTrue(all(left[1] == right[0] for left, right in zip(spans, spans[1:])))
                    results = [event["payload"] for event in events if event["event"] == "result"]
                    self.assertEqual(sum(event["accepted"]["count"] for event in results), len(positive))
                    self.assertGreater(sum(event["dropped"] for event in results), 0)
                    self.assertEqual(len(results), len(adapter.ib.calls))
                    self.assertEqual(op._CHILDREN, {})
                    run.close()
                    cases += 1
        self.assertEqual(cases, 912)

    def test_retired_calendar_refusals_precede_adapter_access(self):
        from fetch_authority import TOKENS, CalendarUnsupported, parse_token
        run = self.open("diagnostic")
        cases = [(token, date(2026, 7, 3), ib.RequestRefused, "closed session") for token in TOKENS]
        cases += [(token, date(1979, 12, 31), CalendarUnsupported, "outside schedule coverage") for token in TOKENS]
        cases += [(token, date(2024, 11, 29), CalendarUnsupported, "no proven provenance")
                  for token in TOKENS if parse_token(token)[2] != "rth"]
        cases += [(token, date(2026, 7, 1), CalendarUnsupported, "no proven provenance")
                  for token in TOKENS if parse_token(token)[0] == "1d" and parse_token(token)[2] != "rth"]
        for index, (token, day, failure, reason) in enumerate(cases):
            with self.subTest(token=token, day=day), self.assertRaisesRegex(failure, reason):
                ib._retired_spot_check_day(object(), contract(), token, day, [], InstantPacer(), None,
                    _fetch_child=self.child(run, f"calendar-refusal-{index}"))
            self.assertEqual(op._CHILDREN, {})
        self.assertEqual(len(cases), 360)
        run.seal()
        self.assertEqual([event["event"] for event in inspect_ledger(run.context.ledger.path)["events"]], ["seal"])

    def test_retired_short_final_period_settlement_edge(self):
        cases = 0
        for day, session in ((date(2026, 7, 1), "rth"), (date(2026, 7, 1), "pre"),
                             (date(2024, 11, 29), "rth")):
            for kind in ("", "iv", "hvol", "bidask"):
                token = "1h" + ("-" + kind if kind else "") + ("-pre" if session == "pre" else "")
                opening, closing = self.authority.window(token, day)
                self.assertNotEqual(int((closing - opening).total_seconds()) % 3600, 0)
                for seconds in (59, 60):
                    with self.subTest(day=day, token=token, seconds=seconds):
                        registry, adapter, _ = self.metadata_fixture()
                        run = self.open("diagnostic", governors=registry,
                            clock=lambda: closing + timedelta(seconds=seconds))
                        positive, _, _ = self.calendar_boundary_rows(token, day)
                        adapter.ib.rows = positive
                        stored = ib.convert_bars(positive, day,
                            {"invalid": 0, "outside_day": 0, "non_rth": 0}, token)
                        child = self.child(run)
                        pacer = InstantPacer()
                        if seconds == 59:
                            with self.assertRaisesRegex(AuthorityError, "fully settled session"):
                                ib._retired_spot_check_day(adapter, contract(), token, day, stored, pacer, None,
                                    _fetch_child=child)
                        else:
                            result = ib._retired_spot_check_day(adapter, contract(), token, day, stored, pacer, None,
                                _fetch_child=child)
                            self.assertEqual(result["result"], "ok")
                            self.assertEqual(result["compared"], 1)
                        self.assertEqual(len(adapter.ib.calls), int(seconds == 60))
                        self.assertEqual(pacer.turns, 0)
                        self.assertEqual(op._CHILDREN, {})
                        run.seal()
                        events = inspect_ledger(run.context.ledger.path)["events"]
                        results = [event["payload"] for event in events if event["event"] == "result"]
                        self.assertEqual(len(results), int(seconds == 60))
                        if results:
                            self.assertEqual(results[0]["accepted"]["count"], 2)
                        run.close()
                        cases += 1
        self.assertEqual(cases, 24)

