    def test_standalone_probe_calendar_and_closing_grid(self):
        from fetch_ibkr_integration_selftest import ib_contract
        self.root_fixture()
        anchors = [date(1980, 1, 2), date(1980, 2, 1), date(1981, 1, 2),
                   date(2024, 2, 29), date(2024, 3, 8), date(2024, 3, 11),
                   date(2024, 11, 1), date(2024, 11, 4), date(2024, 11, 29)]
        positives = refusals = 0
        with patch.dict("sys.modules", {"ib_async": SimpleNamespace(Contract=ib_contract)}):
            for anchor in anchors:
                self.fixture_now = datetime.combine(anchor, time(17), NY)
                for token in probe._PROBE_INTERVALS:
                    with self.subTest(anchor=anchor, token=token):
                        days = [anchor]
                        cursor = anchor - timedelta(days=1)
                        while token != "1m" and len(days) < 3 and cursor >= self.authority.first_date:
                            if self.authority.window(token, cursor) is not None:
                                days.append(cursor)
                            cursor -= timedelta(days=1)
                        registry, adapter, _ = self.metadata_fixture()
                        bank, raw = self.probe_bank_fixture(token, sorted(days),
                            name=f"calendar-probe-{token}-{anchor}", boundary=True)
                        transport = adapter.ib
                        transport.rows = raw
                        before = probe.bank_tree_metadata(bank)
                        cls = probe.IBKRMinuteDayFetcher if token == "1m" else probe.IBKRDailySpanFetcher
                        fetcher = cls(adapter_factory=lambda: adapter)
                        reports = self.root / f"reports-{token}-{anchor}"
                        unsupported = token != "1m" and anchor.year == 1980
                        with patch.object(governors, "_REGISTRY", registry):
                            if unsupported:
                                with self.assertRaisesRegex(AuthorityError, "calendar_unsupported") as caught:
                                    probe.run_live_probe(bank, ticker="TEST", day=anchor.isoformat(), interval=token,
                                        live_fetcher=fetcher, run_logs_root=reports, _test_capability=self.capability)
                                self.assertEqual(transport.calls, [])
                                self.assertFalse(caught.exception.fetch_ledger["verified"])
                                self.assertFalse(reports.exists())
                                refusals += 1
                            else:
                                result = probe.run_live_probe(bank, ticker="TEST", day=anchor.isoformat(), interval=token,
                                    live_fetcher=fetcher, run_logs_root=reports, _test_capability=self.capability)
                                self.assertEqual(result["probe_error_count"], 0, result)
                                self.assertTrue(result["fetch_ledger"]["verified"], result)
                                row = result["probes"][0]
                                self.assertTrue(row["pass_equivalent"], row)
                                evidence = row["fetch_provenance"]
                                self.assertTrue(evidence["coverage_complete"])
                                self.assertEqual(evidence["effective"]["token"], token)
                                self.assertEqual(evidence["effective"]["con_id"], 123)
                                if token == "1m":
                                    opening, closing = self.authority.window(token, anchor)
                                    for field in ("requested", "effective"):
                                        self.assertEqual(datetime.fromisoformat(evidence[field]["intended_start"]), opening)
                                        self.assertEqual(datetime.fromisoformat(evidence[field]["intended_end"]), closing)
                                events = inspect_ledger(evidence["ledger_path"])["events"]
                                results = [event["payload"] for event in events if event["event"] == "result"]
                                self.assertEqual(len(results), 1)
                                self.assertEqual(results[0]["accepted"]["count"], 13 if token == "1m" else 3)
                                self.assertGreater(results[0]["dropped"], 0)
                                self.assertEqual(len(transport.calls), 1)
                                self.assert_probe_delivery(result)
                                positives += 1
                        self.assertEqual(probe.bank_tree_metadata(bank), before)
                        self.assertEqual(op._OPERATIONS, {})
                        self.assertEqual(op._CHILDREN, {})
        self.assertEqual((positives, refusals), (30, 6))

    def test_daily_probe_settlement_and_holiday_selection(self):
        from fetch_ibkr_integration_selftest import ib_contract
        self.root_fixture()
        scenarios = [(date(2026, 7, 2), time(hour, minute), date(2026, 7, 1) if hour == 13 else date(2026, 7, 2))
                     for hour, minute in ((13, 0), (13, 20), (16, 20))]
        scenarios += [(date(2024, 11, 29), time(hour, minute), date(2024, 11, 27) if hour == 13 else date(2024, 11, 29))
                      for hour, minute in ((13, 0), (13, 20), (16, 20))]
        scenarios.append((date(2024, 11, 28), time(17), date(2024, 11, 27)))
        cases = 0
        with patch.dict("sys.modules", {"ib_async": SimpleNamespace(Contract=ib_contract)}):
            for requested, clock, selected in scenarios:
                self.fixture_now = datetime.combine(requested, clock, NY)
                days = []
                cursor = requested - timedelta(days=1)
                while len(days) < 3:
                    if self.authority.row(cursor).is_open:
                        days.append(cursor)
                    cursor -= timedelta(days=1)
                stored_days = sorted(days + ([requested] if self.authority.row(requested).is_open else []))
                for token in probe._PROBE_INTERVALS[1:]:
                    with self.subTest(token=token, requested=requested, clock=clock):
                        registry, adapter, _ = self.metadata_fixture()
                        bank, raw = self.probe_bank_fixture(token, stored_days,
                            name=f"settlement-{token}-{requested}-{clock.hour}-{clock.minute}")
                        if not self.authority.row(requested).is_open:
                            value = bar(requested)
                            if ib.ss.kind_of(token) in ib.ss.RATIO_KINDS:
                                value.open, value.high, value.low, value.close = 0.25, 0.3, 0.2, 0.25
                            raw.append(value)
                        transport = adapter.ib
                        transport.rows = raw
                        before = probe.bank_tree_metadata(bank)
                        pacer = InstantPacer()
                        fetcher = probe.IBKRDailySpanFetcher(adapter_factory=lambda: adapter, pacer=pacer)
                        with patch.object(governors, "_REGISTRY", registry):
                            result = probe.run_live_probe(bank, ticker="TEST", day=requested.isoformat(), interval=token,
                                live_fetcher=fetcher, run_logs_root=self.root / f"settlement-reports-{cases}",
                                _test_capability=self.capability)
                        self.assertTrue(result["fetch_ledger"]["verified"], result)
                        self.assertEqual(result["probe_error_count"], 0)
                        self.assertEqual(result["request_count"], 1)
                        self.assertEqual(len(transport.calls), 1)
                        self.assertEqual(pacer.turns, 0)
                        row = result["probes"][0]
                        self.assertTrue(row["pass_equivalent"], row)
                        self.assertEqual(row["span_end"], selected.isoformat())
                        provenance = row["fetch_provenance"]
                        self.assertEqual(datetime.fromisoformat(provenance["effective"]["intended_end"]).date(), selected)
                        self.assertTrue(provenance["coverage_complete"])
                        events = inspect_ledger(provenance["ledger_path"])["events"]
                        payloads = [event["payload"] for event in events if event["event"] == "result"]
                        self.assertEqual(payloads[0]["observed"]["count"], 4)
                        self.assertEqual(payloads[0]["accepted"]["count"], 4 if selected == requested else 3)
                        self.assertEqual(payloads[0]["dropped"], 0 if selected == requested else 1)
                        self.assertEqual(len(result["selection_adjustments"]), int(selected != requested))
                        if selected != requested:
                            self.assertEqual(result["selection_adjustments"][0]["requested_day"], requested.isoformat())
                        self.assertEqual(probe.bank_tree_metadata(bank), before)
                        self.assertEqual(op._OPERATIONS, {})
                        self.assertEqual(op._CHILDREN, {})
                        cases += 1
        self.assertEqual(cases, 21)

