    def test_probe_reuse_requires_published_sealed_source(self):
        from copy import deepcopy
        from fetch_ibkr_integration_selftest import ib_contract
        self.root_fixture()
        with patch.dict("sys.modules", {"ib_async": SimpleNamespace(Contract=ib_contract)}):
            for token in ("1m", "1d", "1d-iv", "1d-hvol"):
                with self.subTest(token=token):
                    bank, raw = self.probe_bank_fixture(token,
                        [date(2026, 6, 29), date(2026, 6, 30), date(2026, 7, 1)])
                    before = probe.bank_tree_metadata(bank)
                    registry, adapter, _ = self.metadata_fixture()
                    adapter.ib.rows = raw
                    adapter.port, adapter.client_id = 2017, 842
                    transport = adapter.ib
                    cls = probe.IBKRMinuteDayFetcher if token == "1m" else probe.IBKRDailySpanFetcher
                    name = "fetch_day" if token == "1m" else "fetch_span"
                    original, captured = getattr(cls, name), []
                    def capture(*args, **kwargs):
                        result = original(*args, **kwargs)
                        captured.append(result)
                        return result
                    fetcher = cls(adapter_factory=lambda: adapter, pacer=InstantPacer())
                    with patch.object(governors, "_REGISTRY", registry), patch.object(cls, name, new=capture):
                        source = probe.run_live_probe(bank, ticker="TEST", day="2026-07-01", interval=token,
                            live_fetcher=fetcher, run_logs_root=self.root / "reuse-artifacts",
                            _test_capability=self.capability)
                    self.assert_probe_delivery(source)
                    snapshot = (probe.stored_day_snapshot(bank, "TEST", "2026-07-01") if token == "1m"
                        else probe.stored_daily_span_snapshot(bank, "TEST", day="2026-07-01", interval=token))
                    evidence = dict(probe._public_snapshot(snapshot), read_only=True, used_for_commit=False,
                        fetched_after_boundary=True, live_result=captured[0])
                    def reuse(value):
                        with patch.object(governors.Governor, "wait_turn", side_effect=AssertionError("reuse paced")) as pacing, \
                                patch.object(RawIB, "reqHistoricalDataAsync", side_effect=AssertionError("reuse sent")) as sending:
                            row = probe.run_embedded_probe(bank, ticker="TEST", day="2026-07-01",
                                interval=token, live_evidence=value)
                        pacing.assert_not_called()
                        sending.assert_not_called()
                        return row
                    positive = reuse(evidence)
                    self.assertTrue(positive["pass_equivalent"], positive.get("error"))
                    self.assertEqual(positive["request_count"], 0)
                    self.assertEqual(positive["reused_request_count"], 1)
                    self.assertEqual(positive["fetch_provenance"], source["probes"][0]["fetch_provenance"])
                    producer = evidence["live_result"]["fetch_provenance"]["producer_id"]
                    run = self.open("diagnostic")
                    child = self.child(run, rights={producer})
                    leaks, observed = [], []
                    thief = ib.LiveIB()
                    thief.ib = RawIB()
                    thief._await = lambda value, timeout, what: value
                    with child.scope():
                        worker = child.worker()
                        def observe(label):
                            observed.append(label)
                            if bridge.current_worker() is not None:
                                leaks.append((label, "worker"))
                            for action_name, action in (
                                    ("bars", lambda: ib.LiveIB.fetch(thief, contract(), datetime(2026, 7, 1, 16), "1 D", "1 day")),
                                    ("head", lambda: thief.head_timestamp(contract())),
                                    ("request", lambda: worker.request(producer, evidence["live_result"]["fetch_provenance"]["requested"])),
                                    ("child", lambda: op.narrow_worker_child(worker, "reuse-hook")),
                                    ("root", lambda: self.open("diagnostic"))):
                                try:
                                    value = action()
                                except AuthorityError:
                                    continue
                                leaks.append((label, action_name))
                                if action_name in {"child", "root"}:
                                    value.close()
                        class HostileEvidence(dict):
                            def get(value, *args):
                                observe("input")
                                return dict.get(value, *args)
                        original_open = Path.open
                        directories = {Path(source["artifact"]).parent, Path(source["fetch_ledger"]["path"]).parent}
                        def evidence_open(path, *args, **kwargs):
                            if path.parent in directories:
                                observe("file")
                            return original_open(path, *args, **kwargs)
                        caller_token = bridge._WORKER.set(worker)
                        try:
                            with patch.object(Path, "open", new=evidence_open):
                                guarded = reuse(HostileEvidence(evidence))
                            self.assertTrue(bridge.current_worker() is worker)
                        finally:
                            bridge._WORKER.reset(caller_token)
                    child.close()
                    run.seal()
                    run.close()
                    self.assertEqual(leaks, [], "reuse observer borrowed authority")
                    self.assertIn("input", observed)
                    self.assertIn("file", observed)
                    self.assertEqual(thief.ib.calls, [])
                    self.assertTrue(guarded["pass_equivalent"], guarded.get("error"))
                    cases = []
                    for key, value in (("operation_id", "forged-operation"), ("attempt_id", "forged-attempt"),
                            ("logical_id", "forged-logical"), ("producer_id", "ibkr.live_spot_probe.wrong"),
                            ("accepted", {"count": 0, "sha256": "0" * 64}), ("raw_bar_count", 999),
                            ("ledger_path", "missing.jsonl"), ("coverage_complete", False),
                            ("captured_now", "2020-01-01T00:00:00+00:00")):
                        bad = deepcopy(evidence)
                        bad["live_result"]["fetch_provenance"][key] = value
                        cases.append((key, bad))
                    for envelope in ("requested", "effective"):
                        for key, value in (("token", "1d" if token == "1m" else "1m"), ("con_id", 124),
                                ("intended_start", "2020-01-01T00:00:00-05:00"),
                                ("intended_end", "2026-07-02T16:00:00-04:00")):
                            bad = deepcopy(evidence)
                            bad["live_result"]["fetch_provenance"][envelope][key] = value
                            cases.append((envelope + key, bad))
                    bad = deepcopy(evidence)
                    del bad["live_result"]["fetch_provenance"]
                    cases.append(("legacy", bad))
                    for key in ("volume", "raw_bar_count", "accepted_bar_count", "port", "client_id"):
                        bad = deepcopy(evidence)
                        bad["live_result"][key] += 1
                        cases.append((key, bad))
                    bad = deepcopy(evidence)
                    stamp = next(iter(bad["live_result"]["closes"]))
                    bad["live_result"]["closes"][stamp] *= 2
                    cases.append(("closes", bad))
                    bad = deepcopy(evidence)
                    bad["live_result"]["discarded"]["invalid"] += 1
                    cases.append(("discarded", bad))
                    for label, bad in cases:
                        with self.subTest(token=token, altered=label):
                            result = reuse(bad)
                            self.assertFalse(result["pass_equivalent"])
                            self.assertEqual(result["verdict"], probe.PROBE_ERROR)
                            self.assertEqual(result["request_count"], 0)
                            self.assertEqual(result["reused_request_count"], 0)
                    companion_path = Path(source["fetch_ledger"]["report_path"])
                    companion_bytes = companion_path.read_bytes()
                    for key, value in (("verified", False), ("outcome", "failed"),
                            ("report_persisted", False), ("artifact_sha256", "0" * 64),
                            ("operation_id", "other"), ("artifact_relative_path", "missing.json")):
                        with self.subTest(token=token, companion=key):
                            changed = json.loads(companion_bytes)
                            changed[key] = value
                            try:
                                companion_path.write_text(json.dumps(changed), encoding="utf-8")
                                self.assertFalse(reuse(evidence)["pass_equivalent"])
                            finally:
                                companion_path.write_bytes(companion_bytes)
                    for path in (Path(source["artifact"]), Path(source["fetch_ledger"]["path"]),
                            Path(source["fetch_ledger"]["path"]).with_suffix(".seal.json"), companion_path):
                        saved = path.read_bytes()
                        with self.subTest(token=token, corrupt=path.suffix):
                            try:
                                path.write_bytes(b"{broken")
                                self.assertFalse(reuse(evidence)["pass_equivalent"])
                            finally:
                                path.write_bytes(saved)
                        # Missing-file failures are distinct from malformed JSON.
                        original_open = Path.open
                        def missing(candidate, *args, **kwargs):
                            if candidate.resolve() == path.resolve():
                                raise FileNotFoundError(str(candidate))
                            return original_open(candidate, *args, **kwargs)
                        with patch.object(Path, "open", new=missing):
                            self.assertFalse(reuse(evidence)["pass_equivalent"])
                    # Match altered provenance in both caller and artifact and
                    # rehash the artifact: the real ledger must still reject it.
                    ledger_path = Path(source["fetch_ledger"]["path"])
                    sealed_bytes = ledger_path.read_bytes()
                    try:
                        ledger_path.write_bytes(b"".join(sealed_bytes.splitlines(keepends=True)[:-1]))
                        unsealed = reuse(evidence)
                        self.assertFalse(unsealed["pass_equivalent"])
                        self.assertIn("seal", unsealed["error"]["message"])
                    finally:
                        ledger_path.write_bytes(sealed_bytes)
                    artifact_path = Path(source["artifact"])
                    artifact_bytes = artifact_path.read_bytes()
                    for field, value in (("accepted", {"count": 0, "sha256": "0" * 64}),
                            ("accepted", dict(evidence["live_result"]["fetch_provenance"]["accepted"],
                                count=float(evidence["live_result"]["fetch_provenance"]["accepted"]["count"]))),
                            ("raw_bar_count", float(evidence["live_result"]["fetch_provenance"]["raw_bar_count"])),
                            ("dropped", float(evidence["live_result"]["fetch_provenance"]["dropped"])),
                            ("attempt_id", "different-attempt"), ("logical_id", "different-logical")):
                        with self.subTest(token=token, coherent_tamper=field):
                            bad = deepcopy(evidence)
                            bad["live_result"]["fetch_provenance"][field] = value
                            altered = json.loads(artifact_bytes)
                            altered["probes"][0]["fetch_provenance"][field] = value
                            payload = json.dumps(altered).encode("utf-8")
                            report = json.loads(companion_bytes)
                            report["artifact_sha256"] = probe.hashlib.sha256(payload).hexdigest()
                            try:
                                artifact_path.write_bytes(payload)
                                companion_path.write_text(json.dumps(report), encoding="utf-8")
                                self.assertFalse(reuse(bad)["pass_equivalent"])
                            finally:
                                artifact_path.write_bytes(artifact_bytes)
                                companion_path.write_bytes(companion_bytes)
                    self.assertTrue(reuse(evidence)["pass_equivalent"])
                    # Preserve file bytes/old display paths while relocating
                    # both sibling directories. All reads must use the copy.
                    import shutil
                    copied = self.root / ("copied-" + token)
                    shutil.copytree(companion_path.parent, copied / companion_path.parent.name)
                    shutil.copytree(Path(source["artifact"]).parent, copied / Path(source["artifact"]).parent.name)
                    relocated = deepcopy(evidence)
                    relocated["source_companion_path"] = str(copied / companion_path.parent.name / companion_path.name)
                    original_open = Path.open
                    reads = []
                    def local_open(path, *args, **kwargs):
                        resolved = path.resolve()
                        if path.suffix in {".jsonl", ".json"} and (path.parent == companion_path.parent
                                or path.parent == Path(source["artifact"]).parent):
                            reads.append(str(resolved))
                            raise AssertionError("copied reuse consulted original evidence")
                        return original_open(path, *args, **kwargs)
                    # read_bytes is deliberately routed through the same check
                    # because Python versions differ in its internal open path.
                    def local_read(path):
                        with local_open(path, "rb") as stream:
                            return stream.read()
                    with patch.object(Path, "open", new=local_open), patch.object(Path, "read_bytes", new=local_read):
                        copied_result = reuse(relocated)
                    self.assertEqual(reads, [])
                    self.assertTrue(copied_result["pass_equivalent"], copied_result.get("error"))
                    self.assertEqual(copied_result["fetch_provenance"], positive["fetch_provenance"])
                    # Rewrite a real stored month and its manifest, then give
                    # the caller the new boundary metadata. Only the durable
                    # source snapshot comparison can reject that stale source.
                    manifest_path = bank / "TEST" / "manifest.json"
                    manifest_bytes = manifest_path.read_bytes()
                    month_path = ib.ss.month_file_path(bank, "TEST", 2026, 7, token)
                    month_bytes = month_path.read_bytes()
                    stamps = {path: path.stat() for path in (bank, *bank.rglob("*"))}
                    manifest = json.loads(manifest_bytes)
                    parsed, _ = ib.ss.read_month_file(month_path)
                    changed_rows = [(row[0],) + tuple(value * 1.5 for value in row[1:5]) + tuple(row[5:])
                                    for row in parsed]
                    try:
                        ib.ss.manifest_months(manifest, token)[ib.ss.month_key(2026, 7)] = ib.ss.write_month_file(month_path, changed_rows)
                        ib.ss.save_manifest(bank / "TEST", manifest)
                        current = (probe.stored_day_snapshot(bank, "TEST", "2026-07-01") if token == "1m"
                            else probe.stored_daily_span_snapshot(bank, "TEST", day="2026-07-01", interval=token))
                        updated = dict(evidence, **probe._public_snapshot(current))
                        stale = reuse(updated)
                        self.assertFalse(stale["pass_equivalent"])
                        self.assertEqual(stale["verdict"], probe.PROBE_ERROR)
                        self.assertIn("current stored snapshot", stale["error"]["message"])
                    finally:
                        month_path.write_bytes(month_bytes)
                        manifest_path.write_bytes(manifest_bytes)
                        for path, stat in stamps.items():
                            probe.os.utime(path, ns=(stat.st_atime_ns, stat.st_mtime_ns))
                    self.assertEqual(len(transport.calls), 1)
                    self.assertEqual(probe.bank_tree_metadata(bank), before)
                    self.assertEqual(op._OPERATIONS, {})
                    self.assertEqual(op._CHILDREN, {})

    def test_c1_probe_and_retired_account_pacing_across_operations(self):
        from fetch_ibkr_integration_selftest import ib_contract
        self.root_fixture()
        with patch.dict("sys.modules", {"ib_async": SimpleNamespace(Contract=ib_contract)}):
            for family in ("1m", "1d", "1d-iv", "1d-hvol", "retired"):
                with self.subTest(family=family):
                    token = "1m" if family == "retired" else family
                    bank, raw = self.probe_bank_fixture(token,
                        [date(2026, 6, 29), date(2026, 6, 30), date(2026, 7, 1)], name="pacing-" + family)
                    bank_before = probe.bank_tree_metadata(bank)
                    virtual, cancelling, sends, turns, operations = [0.0], [False], [], [], []
                    saturations = []
                    def sleep(seconds, cancel=None):
                        if cancelling[0]:
                            raise ib.Cancelled("cancelled in canonical account wait")
                        virtual[0] += seconds
                    registry = governors.GovernorRegistry(time_fn=lambda: virtual[0], sleep_fn=sleep)
                    def make(port, account):
                        adapter = ib.LiveIB()
                        adapter.port, adapter.client_id = port, 842
                        adapter.ib = RawIB()
                        adapter.ib.rows = raw
                        adapter.ib.managedAccounts = lambda: [account]
                        adapter._await = lambda value, timeout, what: value
                        original = adapter.ib.reqHistoricalDataAsync
                        def transport(*args, **kwargs):
                            sends.append((account, port, virtual[0]))
                            return original(*args, **kwargs)
                        adapter.ib.reqHistoricalDataAsync = transport
                        return adapter
                    first, second, other = make(2000, "ACCOUNT-A"), make(3000, "ACCOUNT-A"), make(2000, "ACCOUNT-B")
                    pacer = InstantPacer()
                    original_turn = governors.Governor.wait_turn
                    original_saturate = governors.Governor.saturate
                    def saturate(governor):
                        saturations.append(governor.identity)
                        return original_saturate(governor)
                    def turn(governor, *args, **kwargs):
                        turns.append(governor.identity)
                        return original_turn(governor, *args, **kwargs)
                    def invoke(adapter):
                        if family != "retired":
                            cls = probe.IBKRMinuteDayFetcher if token == "1m" else probe.IBKRDailySpanFetcher
                            result = probe.run_live_probe(bank, ticker="TEST", day="2026-07-01", interval=token,
                                live_fetcher=cls.from_borrowed_adapter(adapter, pacer=pacer),
                                run_logs_root=self.root / ("pacing-reports-" + family), _test_capability=self.capability)
                            operations.append(result["fetch_ledger"]["operation_id"])
                            events = inspect_ledger(result["fetch_ledger"]["path"])["events"]
                            self.assertEqual(sum(event["event"] == "decision" for event in events), 1)
                            return result
                        run = self.open("diagnostic", governors=registry)
                        operations.append(run.context.operation_id)
                        try:
                            stored = ib.convert_bars(raw, date(2026, 7, 1),
                                {"invalid": 0, "outside_day": 0, "non_rth": 0}, token)
                            result = ib._retired_spot_check_day(adapter, contract(), token, date(2026, 7, 1),
                                stored, pacer, None, _fetch_child=self.child(run))
                            run.seal()
                            return result
                        finally:
                            run.close()
                    with patch.object(governors, "_REGISTRY", registry), patch.object(governors.Governor, "wait_turn", new=turn), \
                            patch.object(governors.Governor, "saturate", new=saturate):
                        invoke(first)
                        invoke(second)
                        invoke(other)
                        invoke(first)
                        self.assertEqual(len(sends), 4)
                        self.assertGreaterEqual(sends[1][2] - sends[0][2], 0.15 - 1e-8)
                        self.assertEqual(sends[2][2], sends[1][2])
                        self.assertGreaterEqual(sends[3][2] - sends[1][2], 0.15 - 1e-8)
                        self.assertEqual(len(set(operations)), 4)
                        first.ib.failures.append(ib.PacingViolation("canonical saturation witness"))
                        failed = invoke(first)
                        if family == "retired":
                            self.assertEqual(failed["result"], "skipped")
                        else:
                            self.assertEqual(failed["status"], "partial")
                            self.assertFalse(failed["fetch_ledger"]["verified"])
                        limited = registry.ibkr(["ACCOUNT-A"])
                        self.assertTrue(limited._pacer._forced, "pacing rejection did not saturate canonical account")
                        self.assertFalse(registry.ibkr(["ACCOUNT-B"])._pacer._forced)
                        rejection_time = sends[-1][2]
                        invoke(other)
                        self.assertLess(sends[-1][2] - rejection_time, 1)
                        invoke(second)
                        self.assertGreaterEqual(sends[-1][2] - rejection_time,
                            governors.IBKR_POLICY.window_s / governors.IBKR_POLICY.max_requests - 1e-7)
                        reservations = list(limited._pacer._stamps)
                        before_sends = len(sends)
                        cancelling[0] = True
                        with self.assertRaisesRegex(ib.Cancelled, "canonical account wait"):
                            invoke(first)
                        self.assertEqual(len(sends), before_sends)
                        self.assertEqual(list(limited._pacer._stamps), reservations)
                    self.assertEqual(len(turns), len(sends) + 1)
                    self.assertEqual(saturations, [("ibkr", "ACCOUNT-A")])
                    self.assertEqual(pacer.turns, 0)
                    self.assertEqual(probe.bank_tree_metadata(bank), bank_before)
                    self.assertEqual(op._OPERATIONS, {})
                    self.assertEqual(op._CHILDREN, {})

