    def test_probe_adapter_descriptors_are_observers(self):
        self.root_fixture()
        original_get = ib.LiveIB.__getattribute__
        original_request, original_turn = bridge.bar_request, governors.Governor.wait_turn
        from fetch_ibkr_integration_selftest import ib_contract
        with patch.dict("sys.modules", {"ib_async": SimpleNamespace(Contract=ib_contract)}):
            for token in ("1m", "1d", "1d-iv", "1d-hvol"):
                bank, raw = self.probe_bank_fixture(token,
                    [date(2026, 6, 29), date(2026, 6, 30), date(2026, 7, 1)])
                before = probe.bank_tree_metadata(bank)
                for reused in (False, True):
                    for fail_at in (None, "fetch", "port", "client_id"):
                        with self.subTest(token=token, reused=reused, fail_at=fail_at):
                            registry, adapter, _ = self.metadata_fixture()
                            transport = adapter.ib
                            transport.rows = raw
                            adapter.port, adapter.client_id, adapter.use_rth = 2017, 842, False
                            thief = ib.LiveIB()
                            thief.ib = RawIB()
                            thief._await = lambda value, timeout, what: value
                            active, observed, leaks, turns = {}, [], [], []
                            def capture(*args, **kwargs):
                                request = original_request(*args, **kwargs)
                                active["request"] = request
                                return request
                            def turn(governor, *args, **kwargs):
                                turns.append(True)
                                return original_turn(governor, *args, **kwargs)
                            def descriptor(obj, name):
                                if obj is adapter and name in {"fetch", "port", "client_id"}:
                                    observed.append(name)
                                    if bridge.current_worker() is not None:
                                        leaks.append((name, "worker"))
                                    if bridge._SEND.get() is not None:
                                        leaks.append((name, "send"))
                                    request = active["request"]
                                    for label, action in (
                                            ("bars", lambda: ib.LiveIB.fetch(thief, contract(),
                                                datetime(2026, 7, 1, 16), "1 D", "1 day")),
                                            ("head", lambda: thief.head_timestamp(contract())),
                                            ("worker-request", lambda: request.worker.request(
                                                request.producer_id, request.envelope.wire())),
                                            ("child", lambda: op.narrow_worker_child(request.worker, "descriptor-borrower")),
                                            ("root", lambda: self.open("diagnostic"))):
                                        try:
                                            value = action()
                                        except AuthorityError:
                                            continue
                                        leaks.append((name, label))
                                        if label in {"root", "child"}:
                                            value.close()
                                    if name == fail_at:
                                        raise OSError(name + " descriptor witness")
                                return original_get(obj, name)
                            borrowed = ib.ReusableAdapter(lambda: adapter) if reused else adapter
                            cls = probe.IBKRMinuteDayFetcher if token == "1m" else probe.IBKRDailySpanFetcher
                            pacer = InstantPacer()
                            fetcher = cls(adapter_factory=lambda: borrowed, pacer=pacer)
                            problem = None
                            with patch.object(governors, "_REGISTRY", registry), patch.object(
                                    governors.Governor, "wait_turn", new=turn), patch.object(
                                    bridge, "bar_request", side_effect=capture), patch.object(
                                    ib.LiveIB, "__getattribute__", new=descriptor):
                                try:
                                    result = probe.run_live_probe(bank, ticker="TEST", day="2026-07-01", interval=token,
                                        live_fetcher=fetcher, run_logs_root=self.root / f"descriptor-{token}-{reused}-{fail_at}",
                                        _test_capability=self.capability)
                                except BaseException as exc:
                                    problem = exc
                            # Observe outside callbacks so error-row conversion
                            # cannot swallow a failed isolation assertion.
                            self.assertEqual(leaks, [], "probe descriptor borrowed authority")
                            if problem is not None:
                                raise problem
                            self.assertEqual(thief.ib.calls, [])
                            self.assertEqual(observed, ["fetch", "port", "client_id"][:
                                1 if fail_at == "fetch" else 2 if fail_at == "port" else 3])
                            self.assertEqual(len(transport.calls), int(fail_at != "fetch"))
                            self.assertEqual(len(turns), int(fail_at != "fetch"))
                            self.assertEqual(pacer.turns, 0)
                            self.assertFalse(adapter.use_rth)
                            self.assertEqual(result["status"], "complete" if fail_at is None else "partial")
                            self.assertEqual(result["fetch_ledger"]["verified"], fail_at is None)
                            self.assert_probe_delivery(result)
                            row = result["probes"][0]
                            if fail_at is None:
                                self.assertTrue(row["pass_equivalent"])
                                self.assertEqual((row["port"], row["client_id"]), (2017, 842))
                            else:
                                self.assertEqual(row["verdict"], probe.PROBE_ERROR)
                                self.assertFalse(row["pass_equivalent"])
                                self.assertIn(fail_at + " descriptor witness", row["error"]["message"])
                            events = inspect_ledger(result["fetch_ledger"]["path"])["events"]
                            results = [event for event in events if event["event"] == "result"]
                            self.assertEqual(len(results), int(fail_at != "fetch"))
                            if results:
                                self.assertEqual(results[0]["payload"]["accepted"]["count"], 12 if token == "1m" else 3)
                            if reused:
                                self.assertIs(borrowed._a, adapter)
                                borrowed.close()
                            self.assertTrue(fetcher._adapter is None)
                            self.assertEqual(probe.bank_tree_metadata(bank), before)
                            self.assertEqual(op._OPERATIONS, {})
                            self.assertEqual(op._CHILDREN, {})

    def test_probe_companion_publication_order_and_faults(self):
        created = self.root_fixture()
        create, write_report = FetchRunContext.create, reporting.write_report
        from fetch_ibkr_integration_selftest import ib_contract
        with patch.dict("sys.modules", {"ib_async": SimpleNamespace(Contract=ib_contract)}):
            for token in ("1m", "1d", "1d-iv", "1d-hvol"):
                bank, raw = self.probe_bank_fixture(token,
                    [date(2026, 6, 29), date(2026, 6, 30), date(2026, 7, 1)])
                before = probe.bank_tree_metadata(bank)
                for point in ("success", "setup", "terminal", "artifact",
                              "seal_append", "seal_flush", "seal_fsync"):
                    for stage in (None, "create", "flush", "fsync", "replace"):
                        with self.subTest(token=token, point=point, report_stage=stage):
                            registry, adapter, _ = self.metadata_fixture()
                            adapter.ib.rows = raw
                            transport = adapter.ib
                            original_failure = (ib.Cancelled("terminal probe witness") if point == "terminal"
                                                else OSError("probe publication witness"))
                            def fail(*args, **kwargs):
                                raise original_failure
                            def seal_fault(event, phase):
                                if point.startswith("seal_") and (event, phase) == ("seal", point[5:]):
                                    fail()
                            def report_fault(event, phase):
                                if phase == stage:
                                    raise OSError("companion " + stage + " witness")
                            def persist(value, directory=None):
                                # A durable VERIFIED record is forbidden until
                                # its invocation's artifact actually exists.
                                if value["verified"]:
                                    self.assertTrue(value.get("artifact_path") and Path(value["artifact_path"]).is_file())
                                return write_report(value, directory, fault=report_fault)
                            cls = probe.IBKRMinuteDayFetcher if token == "1m" else probe.IBKRDailySpanFetcher
                            fetcher = cls(adapter_factory=fail if point in {"setup", "terminal"} else lambda: adapter)
                            reports = self.root / f"delivery-{token}-{point}-{stage}"
                            artifact_patch = (patch.object(probe, "write_artifact", side_effect=fail)
                                              if point == "artifact" else nullcontext())
                            with patch.object(governors, "_REGISTRY", registry), patch.object(
                                    FetchRunContext, "create", side_effect=lambda directory, **kwargs:
                                    create(directory, fault=seal_fault, **kwargs)), patch.object(
                                    reporting, "write_report", side_effect=persist), artifact_patch:
                                options = dict(ticker="TEST", day="2026-07-01", interval=token,
                                    live_fetcher=fetcher, run_logs_root=reports, _test_capability=self.capability)
                                if stage is not None or point in {"terminal", "artifact"} or point.startswith("seal_"):
                                    expected = (reporting.OperationReportError if stage is not None else
                                                LedgerError if point.startswith("seal_") else type(original_failure))
                                    with self.assertRaises(expected) as caught:
                                        probe.run_live_probe(bank, **options)
                                    evidence = caught.exception.fetch_ledger
                                    if stage is None and point in {"terminal", "artifact"}:
                                        self.assertIs(caught.exception, original_failure)
                                    if stage is not None and point in {"terminal", "artifact"}:
                                        self.assertIs(caught.exception.__cause__, original_failure)
                                else:
                                    result = probe.run_live_probe(bank, **options)
                                    evidence = result["fetch_ledger"]
                                    self.assertEqual(result["status"], "complete" if point == "success" else "partial")
                            self.assertEqual(evidence["verified"], point == "success" and stage is None)
                            operation_outcome = "returned" if point == "success" else "partial" if point == "setup" else "failed"
                            if stage is not None:
                                self.assertEqual(evidence["state"], "UNVERIFIED")
                                self.assertEqual(evidence["outcome"], "report_failed")
                                self.assertEqual(evidence["operation_outcome"], operation_outcome)
                                self.assertFalse(evidence["report_persisted"])
                                self.assertIn(stage, evidence["report_failure"])
                            else:
                                self.assertEqual(evidence["outcome"], operation_outcome)
                                self.assertTrue(evidence["report_persisted"])
                            companion = Path(evidence["report_path"])
                            self.assertEqual(companion.exists(), stage is None)
                            if companion.exists():
                                self.assertEqual(json.loads(companion.read_text()), evidence)
                            artifacts = list(reports.glob("*.json"))
                            self.assertEqual(len(artifacts), int(point in {"success", "setup"}))
                            if artifacts:
                                payload = artifacts[0].read_bytes()
                                pending = json.loads(payload)["fetch_ledger"]
                                self.assertFalse(pending["verified"])
                                self.assertFalse(pending["report_persisted"])
                                self.assertTrue(pending["companion_required"])
                                self.assertEqual(pending["outcome"], "companion_pending")
                                self.assertEqual(pending["report_path"], str(companion))
                                self.assertEqual(evidence["artifact_path"], str(artifacts[0]))
                                self.assertEqual(evidence["artifact_sha256"], probe.hashlib.sha256(payload).hexdigest())
                                self.assertEqual(evidence["artifact_state"], "written")
                                self.assertIn(created[-1].operation_id, artifacts[0].name)
                            else:
                                self.assertEqual(evidence["artifact_state"],
                                                 "unconfirmed" if point == "artifact" else "not_written")
                            self.assertEqual(list(companion.parent.glob(".operation-*.tmp")), [])
                            self.assertEqual(len(transport.calls), 0 if point in {"setup", "terminal"} else 1)
                            self.assertEqual(probe.bank_tree_metadata(bank), before)
                            self.assertTrue(all(lease.released for lease in self.fixture_leases))
                            self.assertTrue(fetcher._adapter is None)
                            self.assertEqual(op._OPERATIONS, {})
                            self.assertEqual(op._CHILDREN, {})

    def test_probe_failed_file_close_retires_handle(self):
        self.root_fixture()
        create, write_report = FetchRunContext.create, reporting.write_report
        from fetch_ibkr_integration_selftest import ib_contract
        with patch.dict("sys.modules", {"ib_async": SimpleNamespace(Contract=ib_contract)}):
            for token in ("1m", "1d", "1d-iv", "1d-hvol"):
                bank, raw = self.probe_bank_fixture(token,
                    [date(2026, 6, 29), date(2026, 6, 30), date(2026, 7, 1)])
                for fail_report in (False, True):
                    with self.subTest(token=token, fail_report=fail_report):
                        registry, adapter, _ = self.metadata_fixture()
                        adapter.ib.rows = raw
                        failure = OSError("file close witness")
                        fired, streams, contexts = [], [], []
                        class CloseFault:
                            def __init__(self, stream):
                                self.stream = stream
                            def __getattr__(self, name):
                                return getattr(self.stream, name)
                            def close(self):
                                self.stream.close()
                                if not fired:
                                    fired.append(True)
                                    raise failure
                        def factory(directory, **kwargs):
                            ctx = create(directory, **kwargs)
                            contexts.append(ctx)
                            streams.append(ctx.ledger._file)
                            ctx.ledger._file = CloseFault(ctx.ledger._file)
                            return ctx
                        def fault(event, phase):
                            if fail_report and phase == "fsync":
                                raise OSError("close companion witness")
                        cls = probe.IBKRMinuteDayFetcher if token == "1m" else probe.IBKRDailySpanFetcher
                        fetcher = cls(adapter_factory=lambda: adapter)
                        reports = self.root / f"close-fault-{token}-{fail_report}"
                        with patch.object(governors, "_REGISTRY", registry), patch.object(
                                FetchRunContext, "create", side_effect=factory), patch.object(
                                reporting, "write_report", side_effect=lambda value, directory=None:
                                write_report(value, directory, fault=fault)):
                            with self.assertRaises(reporting.OperationReportError if fail_report else OSError) as caught:
                                probe.run_live_probe(bank, ticker="TEST", day="2026-07-01", interval=token,
                                    live_fetcher=fetcher, run_logs_root=reports, _test_capability=self.capability)
                        # Register any regression-created leak for test cleanup;
                        # it must still fail the actual lifetime assertion.
                        self.runs.extend(handle for handle in op._OPERATIONS if handle not in self.runs)
                        self.assertEqual(fired, [True])
                        self.assertTrue(all(stream.closed for stream in streams))
                        self.assertEqual(len(op._OPERATIONS), 0, "failed close retained authority handle")
                        self.assertEqual(op._CHILDREN, {})
                        with self.assertRaises(AuthorityError):
                            contexts[-1].worker("late-after-close-failure")
                        self.assertFalse(reports.exists())
                        evidence = caught.exception.fetch_ledger
                        self.assertFalse(evidence["verified"])
                        self.assertEqual(evidence["artifact_state"], "not_written")
                        self.assertEqual(evidence["report_persisted"], not fail_report)
                        if fail_report:
                            self.assertIs(caught.exception.__cause__, failure)
                        else:
                            self.assertIs(caught.exception, failure)

    def test_probe_atomic_artifact_faults_never_credit_delivery(self):
        import builtins
        self.root_fixture()
        atomic, write_report, path_open = probe.storage._atomic_write_bytes, reporting.write_report, Path.open
        real_open = builtins.open
        from fetch_ibkr_integration_selftest import ib_contract
        with patch.dict("sys.modules", {"ib_async": SimpleNamespace(Contract=ib_contract)}):
            for token in ("1m", "1d", "1d-iv", "1d-hvol"):
                bank, raw = self.probe_bank_fixture(token,
                    [date(2026, 6, 29), date(2026, 6, 30), date(2026, 7, 1)])
                before = probe.bank_tree_metadata(bank)
                for stage in ("create", "write", "flush", "fsync", "replace", "readback"):
                    for fail_report in (False, True):
                        with self.subTest(token=token, stage=stage, fail_report=fail_report):
                            registry, adapter, _ = self.metadata_fixture()
                            adapter.ib.rows = raw
                            failure = OSError("artifact " + stage + " witness")
                            fired = []
                            def fail(*args, **kwargs):
                                fired.append(stage)
                                raise failure
                            class WriteFault:
                                def __init__(self, stream):
                                    self.stream = stream
                                def __getattr__(self, name):
                                    return getattr(self.stream, name)
                                def __enter__(self):
                                    return self
                                def __exit__(self, *args):
                                    return self.stream.__exit__(*args)
                                def write(self, payload):
                                    return fail() if stage == "write" else self.stream.write(payload)
                                def flush(self):
                                    return fail() if stage == "flush" else self.stream.flush()
                            def open_temp(*args, **kwargs):
                                if stage == "create":
                                    fail()
                                return WriteFault(real_open(*args, **kwargs))
                            def write_atomic(target, payload):
                                with patch.object(builtins, "open", side_effect=open_temp), \
                                        (patch.object(probe.storage.os, "fsync", side_effect=fail)
                                         if stage == "fsync" else nullcontext()), \
                                        (patch.object(probe.storage.os, "replace", side_effect=fail)
                                         if stage == "replace" else nullcontext()):
                                    return atomic(target, payload)
                            def read_artifact(path, mode="r", *args, **kwargs):
                                if stage == "readback" and mode == "rb" and path.name.startswith("live-spot-probe-"):
                                    fail()
                                return path_open(path, mode, *args, **kwargs)
                            def report_fault(event, phase):
                                if fail_report and phase == "fsync":
                                    raise OSError("artifact companion witness")
                            cls = probe.IBKRMinuteDayFetcher if token == "1m" else probe.IBKRDailySpanFetcher
                            fetcher = cls(adapter_factory=lambda: adapter)
                            reports = self.root / f"atomic-{token}-{stage}-{fail_report}"
                            with patch.object(governors, "_REGISTRY", registry), patch.object(
                                    probe.storage, "_atomic_write_bytes", side_effect=write_atomic), patch.object(
                                    Path, "open", new=read_artifact), patch.object(reporting, "write_report",
                                    side_effect=lambda value, directory=None: write_report(value, directory, fault=report_fault)):
                                with self.assertRaises(reporting.OperationReportError if fail_report else OSError) as caught:
                                    probe.run_live_probe(bank, ticker="TEST", day="2026-07-01", interval=token,
                                        live_fetcher=fetcher, run_logs_root=reports, _test_capability=self.capability)
                            self.assertEqual(fired, [stage])
                            self.assertIs(caught.exception.__cause__ if fail_report else caught.exception, failure)
                            evidence = caught.exception.fetch_ledger
                            self.assertFalse(evidence["verified"])
                            self.assertEqual(evidence["artifact_state"], "unconfirmed")
                            self.assertEqual(evidence["report_persisted"], not fail_report)
                            self.assertNotIn("artifact_sha256", evidence)
                            self.assertEqual(list(reports.glob("*.tmp")), [])
                            artifacts = list(reports.glob("*.json"))
                            self.assertEqual(len(artifacts), int(stage == "readback"))
                            if artifacts:
                                pending = json.loads(artifacts[0].read_text())["fetch_ledger"]
                                self.assertFalse(pending["verified"])
                                self.assertEqual(pending["outcome"], "companion_pending")
                            companion = Path(evidence["report_path"])
                            self.assertEqual(companion.exists(), not fail_report)
                            if companion.exists():
                                self.assertEqual(json.loads(companion.read_text()), evidence)
                            self.assertEqual(probe.bank_tree_metadata(bank), before)
                            self.assertEqual(op._OPERATIONS, {})
                            self.assertEqual(op._CHILDREN, {})

    def test_probe_same_owner_artifacts_are_invocation_specific(self):
        self.root_fixture()
        from fetch_ibkr_integration_selftest import ib_contract
        with patch.dict("sys.modules", {"ib_async": SimpleNamespace(Contract=ib_contract)}):
            for token in ("1m", "1d", "1d-iv", "1d-hvol"):
                bank, raw = self.probe_bank_fixture(token,
                    [date(2026, 6, 29), date(2026, 6, 30), date(2026, 7, 1)])
                before = probe.bank_tree_metadata(bank)
                artifacts = {}
                for partial in (False, False, True):
                    registry, adapter, _ = self.metadata_fixture()
                    adapter.ib.rows = raw
                    def factory():
                        if partial:
                            raise OSError("later partial invocation")
                        return adapter
                    cls = probe.IBKRMinuteDayFetcher if token == "1m" else probe.IBKRDailySpanFetcher
                    fetcher = cls(adapter_factory=factory)
                    with patch.object(governors, "_REGISTRY", registry):
                        result = probe.run_live_probe(bank, ticker="TEST", day="2026-07-01", interval=token,
                            owner="same-owner", live_fetcher=fetcher, run_logs_root=self.root / ("shared-" + token),
                            _test_capability=self.capability)
                    evidence = result["fetch_ledger"]
