    def test_probe_exception_hooks_are_observers_and_preserve_failure(self):
        self.root_fixture()
        from fetch_ibkr_integration_selftest import ib_contract
        owner = self
        with patch.dict("sys.modules", {"ib_async": SimpleNamespace(Contract=ib_contract)}):
            for token in ("1m", "1d", "1d-iv", "1d-hvol"):
                bank, raw = self.probe_bank_fixture(token,
                    [date(2026, 6, 29), date(2026, 6, 30), date(2026, 7, 1)])
                before = probe.bank_tree_metadata(bank)
                for stage, reject_attribute in (("setup", False), ("close", False),
                        ("terminal", False), ("artifact", False),
                        ("terminal", True), ("artifact", True),
                        ("companion", False), ("companion", True)):
                    with self.subTest(token=token, stage=stage, reject_attribute=reject_attribute):
                        registry, adapter, _ = self.metadata_fixture()
                        transport = adapter.ib
                        transport.rows = raw
                        observed = []
                        leaks = []
                        def witness(hook):
                            observed.append(hook)
                            if bridge.current_worker() is not None:
                                leaks.append((hook, "worker"))
                            if bridge._SEND.get() is not None:
                                leaks.append((hook, "send"))
                            for label, action in (
                                    ("root", lambda: owner.open("diagnostic")),
                                    ("bars", lambda: adapter.fetch(contract(),
                                        datetime(2026, 7, 1, 16), "1 D", "1 day")),
                                    ("head", lambda: adapter.head_timestamp(contract()))):
                                try:
                                    result = action()
                                except AuthorityError:
                                    continue
                                leaks.append((hook, label))
                                if label == "root":
                                    result.close()
                        base = (ib.Cancelled if stage == "terminal" else
                                reporting.OperationReportError if stage == "companion" else OSError)
                        class ObserverFailure(base):
                            def __str__(self):
                                witness("format")
                                return "probe exception observer witness"
                            def __setattr__(self, name, value):
                                if name == "fetch_ledger":
                                    witness("attribute")
                                    if reject_attribute:
                                        raise RuntimeError("attachment hook must not replace original failure")
                                object.__setattr__(self, name, value)
                        failure = ObserverFailure()
                        def fail(*args, **kwargs):
                            raise failure
                        if stage == "close":
                            adapter.disconnect = fail
                        cls = probe.IBKRMinuteDayFetcher if token == "1m" else probe.IBKRDailySpanFetcher
                        fetcher = cls(adapter_factory=fail if stage in {"setup", "terminal"} else lambda: adapter)
                        reports = self.root / f"observer-{token}-{stage}-{reject_attribute}"
                        artifact_patch = (patch.object(probe, "write_artifact", side_effect=fail)
                                          if stage == "artifact" else nullcontext())
                        report_patch = (patch.object(reporting, "write_report", side_effect=fail)
                                        if stage == "companion" else nullcontext())
                        with patch.object(governors, "_REGISTRY", registry), artifact_patch, report_patch:
                            if stage in {"terminal", "artifact", "companion"}:
                                with self.assertRaises(ObserverFailure) as caught:
                                    probe.run_live_probe(bank, ticker="TEST", day="2026-07-01", interval=token,
                                        live_fetcher=fetcher, run_logs_root=reports, _test_capability=self.capability)
                                self.assertIs(caught.exception, failure)
                                self.assertIn("attribute", observed)
                                if not reject_attribute:
                                    self.assertFalse(failure.fetch_ledger["verified"])
                                    companion = Path(failure.fetch_ledger["report_path"])
                                    if stage == "companion":
                                        self.assertFalse(companion.exists())
                                        self.assertFalse(failure.fetch_ledger["report_persisted"])
                                    else:
                                        self.assertEqual(json.loads(companion.read_text())["state"], "UNVERIFIED")
                                self.assertEqual(reports.exists(), stage == "companion")
                            else:
                                result = probe.run_live_probe(bank, ticker="TEST", day="2026-07-01", interval=token,
                                    live_fetcher=fetcher, run_logs_root=reports, _test_capability=self.capability)
                                self.assertEqual(result["status"], "partial")
                                self.assertFalse(result["fetch_ledger"]["verified"])
                                error = result["close_error"] if stage == "close" else result["probes"][0]["error"]
                                self.assertEqual(error["message"], "probe exception observer witness")
                                self.assertEqual(result["probe_error_count"], int(stage == "setup"))
                        # Check outside the hook: formatting/attachment callers
                        # can catch exceptions raised by an assertion inside it.
                        self.assertEqual(leaks, [], "exception observer authority leaked")
                        self.assertIn("format", observed)
                        self.assertEqual(len(transport.calls), 0 if stage in {"setup", "terminal"} else 1)
                        self.assertEqual(probe.bank_tree_metadata(bank), before)
                        self.assertTrue(fetcher._adapter is None)
                        self.assertTrue(all(lease.released for lease in self.fixture_leases))
                        self.assertEqual(op._OPERATIONS, {})
                        self.assertEqual(op._CHILDREN, {})

