    def legacy_ratio_hard_exit_contracts(self):
        import vol_value_reconcile_selftest as legacy
        import vol_value_reconcile as reconcile
        self.assertIsNone(tp._ACTIVE)
        original = reconcile.reconcile_one
        def retry(*args, **kwargs):
            self.assertIsNone(tp._ACTIVE)
            case = Operations("legacy_ratio_retry")
            case.retry_args, case.retry_kwargs = args, kwargs
            case._legacy_ratio_shipped = original
            result = unittest.TestResult()
            unittest.TestSuite([case]).run(result)
            self.assertTrue(result.wasSuccessful(), repr(result.errors + result.failures))
            self.assertIsNone(tp._ACTIVE)
            return case.retry_result
        self.patch(reconcile, "reconcile_one", new=retry)
        saved_fails, saved_checks = legacy.FAILS[:], legacy.CHECKS
        legacy.FAILS.clear(); legacy.CHECKS = 0
        try:
            legacy.run_hard_exit_recovery_checks(self.root)
            self.assertEqual(legacy.FAILS, [])
            self.assertEqual(legacy.CHECKS, 12)
            # Each real hard exit follows a durable decision/result pair. This
            # is evidence of the request path, not merely an expected exit code.
            ledgers = list(self.root.glob("*/fetch-evidence/**/*.jsonl"))
            self.assertEqual(len(ledgers), 11)
            for ledger in ledgers:
                events = inspect_ledger(ledger, require_seal=False)["events"]
                self.assertEqual([event["event"] for event in events], ["decision", "result"])
                self.assertEqual(events[0]["producer_id"], "ibkr.vol_value_bank.ratio_day")
            print(f"legacy ratio hard exits: {legacy.CHECKS}/{legacy.CHECKS}, 11 physical request ledgers")
        finally:
            legacy.FAILS[:] = saved_fails
            legacy.CHECKS = saved_checks

    def legacy_ratio_fixture(self, legacy, *, bank_scope=None):
        """Legacy assertions with explicit children and raw-only fake sources."""
        import platform
        import vol_value_reconcile as reconcile
        import fix_data_pipeline as pipeline
        from fetch_ibkr_integration_selftest import ib_contract
        self.root_fixture()
        self.patch(platform, "machine", return_value="AMD64")
        modules = patch.dict("sys.modules", {"ib_async": SimpleNamespace(Contract=ib_contract)})
        modules.start(); self.addCleanup(modules.stop)
        registry, _, _ = self.metadata_fixture()
        self.patch(governors, "_REGISTRY", new=registry)
        sources, adapters = {}, []
        contract_for = ib.LiveIB.contract_for
        def pinned(adapter, conid):
            source = sources.get(adapter)
            if source is not None:
                source.contract_calls.append(int(conid))
            return contract_for(adapter, conid)
        self.patch(ib.LiveIB, "contract_for", new=pinned)
        def wrap(source):
            self.assertIsInstance(source, legacy.FakeAdapter)
            adapter = ib.LiveIB()
            adapter.port = 2000
            adapter.use_rth = source.use_rth
            raw = RawIB()
            raw.managedAccounts = lambda: [source.account()]
            raw.disconnect = source.disconnect
            def history(contract, **fields):
                raw.calls.append(("bars", contract.conId, fields))
                previous = source.use_rth
                source.use_rth = fields["useRTH"]
                try:
                    return bridge.without_authority(source.fetch)(
                        contract, fields["endDateTime"], fields["durationStr"],
                        fields["barSizeSetting"], fields["whatToShow"])
                finally:
                    source.use_rth = previous
            raw.reqHistoricalDataAsync = history
            adapter.ib = raw
            adapter._await = lambda value, timeout, description: value
            sources[adapter] = source
            adapters.append(adapter)
            return adapter
        shipped = getattr(self, "_legacy_ratio_shipped", reconcile.reconcile_one)
        def run(source, pacer, root, row, *args, **kwargs):
            self.assertTrue(Path(root).resolve().is_relative_to(bank_scope or self.root))
            if "_fetch_child" in kwargs:
                self.assertIs(type(source), ib.LiveIB)
                return shipped(source, pacer, root, row, *args, **kwargs)
            adapter = wrap(source)
            run = self.open("repair", governors=registry)
            governor = registry.ibkr([source.account()])
            original_turn = governor.wait_turn
            def turn(*a, **k):
                pacer.canonical_calls.append((a, k))
                return original_turn(*a, **k)
            try:
                with patch.object(governor, "wait_turn", new=turn):
                    return shipped(adapter, pacer, root, row, *args, **kwargs,
                        _fetch_child=self.child(run, "legacy-ratio-" + str(len(self.children))))
            finally:
                run.close()
                adapter.disconnect()
        self.patch(reconcile, "reconcile_one", new=run)
        pipeline_run = pipeline.run
        def composed(**kwargs):
            factory = kwargs["adapter_factory"]
            kwargs["adapter_factory"] = lambda port: wrap(factory(port))
            kwargs.pop("fill_fn", None)
            kwargs.pop("reconcile_fn", None)
            kwargs.update(engine_tasks=True, _test_capability=self.capability,
                          evidence_dir=self.root / "legacy-ratio-composition-ledgers")
            return pipeline_run(**kwargs)
        self.patch(pipeline, "run", new=composed)
        return adapters

