        self.assertEqual(seen, [True])
        self.assertEqual(len(pacer.canonical_calls), 1)
        self.assertEqual(pacer.calls, [])
        with self.assertRaises(AssertionError):
            self.legacy_crash_custody(bank)
        with self.assertRaises(AssertionError):
            self.legacy_crash_custody(Path(__file__).resolve().parents[1] / ib.ss.STORAGE_DIR_NAME)
        self.assertTrue(all(adapter.ib is None for adapter in adapters))
