    def ratio_fixture(self, token="1m-iv", *, fresh=0.8,
                      day=date(2024, 6, 18), minute=15 * 60 + 59,
                      queue_required=True):
        import platform
        self.patch(platform, "machine", return_value="AMD64")
        import vol_value_reconcile_selftest as legacy
        import vol_value_reconcile as reconcile
        self.ratio_sequence = getattr(self, "ratio_sequence", 0) + 1
        bank = legacy.fresh_root(self.root, f"ratio-{self.ratio_sequence}")
        prior = day - timedelta(days=1)
        while prior.weekday() >= 5:
            prior -= timedelta(days=1)
        original_bar = legacy.day_bar
        def fixture_bar(bar_day, value, **options):
            return original_bar(bar_day, value,
                minute=0 if token.startswith("1d") else minute)
        with patch.object(legacy, "day_bar", fixture_bar):
            paths = legacy.write_values(bank, "TEST", token,
                [(prior, 0.1), (day, 0.8)], conid=91001)
        legacy.audit.audit(bank, write_queue=True)
        planned = reconcile.plan(bank)
        if queue_required:
            row, = planned
        else:
            self.assertEqual(planned, [])
            row = None
        registry, adapter, _ = self.metadata_fixture()
        adapter.use_rth = False
        adapter.ib.rows = [legacy.vendor_bar(day, fresh,
            daily=token.startswith("1d"), minute=minute)]
        snapshot = reconcile.bank.snapshot_ratio_day(bank, "TEST", token, day,
            today=day + timedelta(days=1))
        manifest = bank / "TEST" / legacy.storage.MANIFEST_NAME
        protected = list(paths.values()) + [manifest]
        return SimpleNamespace(bank=bank, row=row, snapshot=snapshot, adapter=adapter, prior=prior,
            registry=registry, protected=protected, before={path: path.read_bytes() for path in protected})

    def ratio_supported_tokens(self, day):
        from fetch_authority import TOKENS, parse_token
        import vol_value_bank as bank
        supported = []
        expected_bases = {"30s", "1m", "2m", "5m", "15m", "30m", "1h", "1d"}
        expected = {base + "-" + kind for base in expected_bases for kind in ("iv", "hvol")}
        self.assertEqual(len(TOKENS), 132)
        for token in TOKENS:
            base, kind, session = parse_token(token)
            if token in expected:
                self.assertEqual(bank._kind_token(token, for_day=day), token)
                self.assertEqual(len(ib.day_requests(token, day)), 1)
                supported.append(token)
            else:
                reason = ("more than one request" if kind in {"iv", "hvol"}
                          and session == "rth" else "exact RTH IV/HVOL")
                with self.assertRaisesRegex(bank.RatioDayError, reason):
                    bank._kind_token(token, for_day=day)
                if kind in {"iv", "hvol"} and session == "rth":
                    self.assertIn(base, {"1s", "5s", "10s"})
                    self.assertGreater(len(ib.day_requests(token, day)), 1)
        self.assertEqual(set(supported), expected)
        return tuple(supported)

