    def test_c2_ratio_all_tokens_calendar_publication(self):
        from fetch_authority import BAR_SIZES, parse_token
        import vol_value_reconcile as reconcile
        import vol_value_reconcile_selftest as legacy
        from fetch_ibkr_integration_selftest import ib_contract
        self.root_fixture()
        days = (date(1980, 1, 2), date(1980, 2, 1), date(2024, 2, 29),
                date(2024, 3, 8), date(2024, 3, 11), date(2024, 11, 1),
                date(2024, 11, 4), date(2024, 11, 29))
        cases = 0
        with patch.dict("sys.modules", {"ib_async": SimpleNamespace(Contract=ib_contract)}):
            for day in days:
                for token in self.ratio_supported_tokens(day):
                    opening, closing = self.authority.window(token, day)
                    seconds = BAR_SIZES[parse_token(token)[0]][1]
                    last_label = opening + timedelta(seconds=
                        int(((closing - opening).total_seconds() - 1) // seconds) * seconds)
                    minute = last_label.hour * 60 + last_label.minute
                    for fresh in (0.8, 0.1):
                        purpose = "repair" if fresh == 0.8 else "add_stocks"
                        with self.subTest(day=day, token=token, fresh=fresh, purpose=purpose):
                            f = self.ratio_fixture(token, fresh=fresh, day=day, minute=minute)
                            # Independent cases retain real ledger I/O without
                            # retrying every prior case's allocated filename.
                            evidence_dir = self.root / f"ratio-calendar-{cases:04d}"
                            run = self.open(purpose, governors=f.registry, evidence_dir=evidence_dir)
                            self.assertEqual(run.context.ledger.path.parent, evidence_dir)
                            pacer = InstantPacer()
                            result = reconcile.reconcile_one(f.adapter, pacer, f.bank, f.row,
                                "ratio-calendar", _fetch_child=self.child(run))
                            self.assertEqual(result["status"], "settled" if fresh == 0.8 else "corrected", result)
                            self.assertTrue(result["queue_resolved"], result)
                            self.assertEqual(reconcile.audit.queue_snapshot(f.bank), [])
                            self.assertEqual(legacy.month_values(f.bank, "TEST", token),
                                             {f.prior: 0.1, day: fresh})
                            self.assertEqual(len(f.adapter.ib.calls), 1)
                            self.assertEqual(pacer.turns, 0)
                            self.assertFalse(f.adapter.use_rth)
                            run.seal()
                            events = inspect_ledger(run.context.ledger.path)["events"]
                            decision, response = events[:2]
                            self.assertEqual(decision["producer_id"], "ibkr.vol_value_bank.ratio_day")
                            requested = decision["payload"]["requested"]
                            effective = decision["payload"]["effective"]
                            self.assertEqual(requested["token"], token)
                            self.assertEqual(datetime.fromisoformat(requested["intended_start"]), opening)
                            self.assertEqual(datetime.fromisoformat(requested["intended_end"]), closing)
                            self.assertEqual(requested["intended_end"], effective["intended_end"])
                            self.assertEqual(response["payload"]["accepted"]["count"], 1)
                            after = {path: path.read_bytes() for path in f.protected}
                            if fresh == 0.8:
                                self.assertEqual(after, f.before)
                            else:
                                self.assertNotEqual(after, f.before)
                            run.close()
                            self.assertEqual(op._CHILDREN, {})
                            self.assertEqual(op._OPERATIONS, {})
                            cases += 1
        self.assertEqual(cases, 256)
        self.assertTrue(all(lease.released for lease in self.fixture_leases))

    def test_c2_ratio_calendar_refusals_preserve_bank_and_queue(self):
        import vol_value_reconcile as reconcile
        import vol_value_reconcile_selftest as legacy
        from fetch_ibkr_integration_selftest import ib_contract
        self.root_fixture()
        cases = 0
        with patch.dict("sys.modules", {"ib_async": SimpleNamespace(Contract=ib_contract)}):
            for label, day, clock, reason in (
                    ("unsupported", date(1979, 12, 31), datetime(2026, 8, 4, 17, tzinfo=NY),
                     "outside schedule coverage"),
                    ("closed", date(2024, 7, 4), datetime(2026, 8, 4, 17, tzinfo=NY),
                     "closed session"),
                    ("same-day", date(2024, 6, 18), datetime(2024, 6, 18, 13, 20, tzinfo=NY),
                     "completed past RTH day")):
                for token in self.ratio_supported_tokens(day):
                    with self.subTest(category=label, token=token):
                        f = self.ratio_fixture(token, day=day, queue_required=label != "closed")
                        queue_before = legacy.queue_bytes(f.bank)
                        run = self.open("repair", governors=f.registry, clock=lambda: clock)
                        if label == "same-day":
                            result = reconcile.reconcile_one(f.adapter, InstantPacer(), f.bank,
                                f.row, "ratio-calendar-refusal", _fetch_child=self.child(run))
                            self.assertEqual(result["status"], "unresolved", result)
                            self.assertFalse(result["queue_resolved"])
                            self.assertIn(reason, result["error"])
                        elif label == "closed":
                            # The real audit excludes holiday findings. No row
                            # can reach reconcile_one; probe its child consumer
                            # separately without inventing a queue authorization.
                            self.assertEqual(reconcile.plan(f.bank), [])
                            with self.assertRaisesRegex(AuthorityError, reason):
                                reconcile.bank.fetch_ratio_day(f.adapter, InstantPacer(), f.snapshot,
                                    _fetch_child=self.child(run))
                        else:
                            with self.assertRaisesRegex(AuthorityError, reason):
                                reconcile.reconcile_one(f.adapter, InstantPacer(), f.bank,
                                    f.row, "ratio-calendar-refusal", _fetch_child=self.child(run))
                        self.assertEqual(f.adapter.ib.calls, [])
                        self.assertEqual(self.virtual_time, 0)
                        self.assertEqual({path: path.read_bytes() for path in f.protected}, f.before)
                        queue_after = json.loads(legacy.queue_bytes(f.bank))
                        self.assertEqual(queue_after["rows"], json.loads(queue_before)["rows"])
                        if label == "closed":
                            self.assertEqual(legacy.queue_bytes(f.bank), queue_before)
                            self.assertEqual(reconcile.audit.queue_snapshot(f.bank), [])
                        else:
                            self.assertTrue(queue_after["partial"])
                            self.assertEqual(queue_after["scope_tickers"], ["TEST"])
                            self.assertEqual(reconcile.audit.queue_snapshot(f.bank), [f.row])
                        self.assertFalse(f.adapter.use_rth)
                        self.assertEqual(inspect_ledger(run.context.ledger.path,
                                                       require_seal=False)["events"], [])
                        run.seal()
                        run.close()
                        self.assertEqual(op._CHILDREN, {})
                        self.assertEqual(op._OPERATIONS, {})
                        cases += 1
        self.assertEqual(cases, 48)
        self.assertTrue(all(lease.released for lease in self.fixture_leases))

