    def c2_observer_attack_fixture(self, run, *, producer="ibkr.gap_fill.session_fetch"):
        _, adapter, _ = self.metadata_fixture()
        raw = adapter.ib
        raw.rows = [bar(datetime(2026, 7, 1, 9, 30, tzinfo=NY))]
        self.addCleanup(adapter.disconnect)
        seen, leaks = {}, []
        def witness(label):
            if label in seen:
                return
            seen[label] = (bridge.current_worker(), bool(op._OBSERVER.get()))
            try:
                minted = self.open("repair")
            except AuthorityError:
                pass
            else:
                leaks.append((label, "mint"))
                minted.seal()
                minted.close()
            try:
                stolen = run.child("conversion-thief-" + label)
            except AuthorityError:
                pass
            else:
                leaks.append((label, "child"))
                stolen.close()
            before = len(raw.calls)
            try:
                token = "1m-iv" if producer == "ibkr.vol_value_bank.ratio_day" else "1m"
                request = bridge.bar_request(producer, contract(), token,
                    datetime(2026, 7, 1, 16), "1 D", symbol="TEST",
                    start=datetime(2026, 7, 1, 9, 30))
                with bridge.send_scope(request, bridge.acquire_turn):
                    adapter.fetch(contract(), datetime(2026, 7, 1, 16),
                                  "1 D", "1 min", ib._what_to_show(token))
            except AuthorityError:
                pass
            if len(raw.calls) > before:
                self.assertEqual(len(raw.calls), before + 1)
                leaks.append((label, "raw-send"))
        def isolated():
            self.assertEqual(leaks, [], "observer authority escaped")
            self.assertTrue(seen, "no hostile hook reached the actual boundary")
            self.assertTrue(all(worker is None and observer for worker, observer in seen.values()))
            self.assertEqual(raw.calls, [])
        def removed(affected):
            with self.assertRaises(AssertionError):
                isolated()
            self.assertEqual(set(leaks), {(label, action) for label in affected
                for action in ("mint", "child", "raw-send")})
            self.assertEqual(len(raw.calls), len(affected))
            for label, (worker, observer) in seen.items():
                self.assertEqual(worker is None, label not in affected)
                self.assertEqual(observer, label not in affected)
        return SimpleNamespace(witness=witness, isolated=isolated, removed=removed,
                               seen=seen, leaks=leaks, adapter=adapter, raw=raw)

