    def test_c2_reconcile_conversion_and_row_guard_removal_inverses(self):
        import inspect
        import addstock_fetch_tasks as tasks
        import vol_value_reconcile as reconcile
        cases = (
            (tasks, "_run_addstock_task",
             'run_id = fib.without_authority(lambda: str(options["run_id"]))()',
             'run_id = str(options["run_id"])',
             self.test_c2_reconcile_run_id_conversion_is_observer),
            (reconcile, "reconcile_one",
             "run_id = fib.without_authority(_run_id)(run_id)",
             "run_id = _run_id(run_id)",
             self.test_c2_reconcile_run_id_conversion_is_observer),
            (reconcile, "reconcile_one",
             "return fib.without_authority(_base)(row, error=_error(exc))",
             "return _base(row, error=_error(exc))",
             self.test_c2_reconcile_invalid_run_id_row_is_observer),
            (reconcile, "reconcile_one",
             'return fib.without_authority(_base)(\n            row, status="stale", error="queue row changed before refetch")',
             'return _base(row, status="stale", error="queue row changed before refetch")',
             self.test_c2_reconcile_stale_row_is_observer),
        )
        for module, name, needle, replacement, oracle in cases:
            source = inspect.getsource(getattr(module, name))
            self.assertEqual(source.count(needle), 1)
            namespace = dict(vars(module))
            exec(compile(source.replace(needle, replacement), module.__file__, "exec"), namespace)
            with self.subTest(guard=needle), patch.object(module, name, namespace[name]):
                with self.assertRaisesRegex(AssertionError, "observer authority escaped"):
                    oracle()
            self.assertEqual(op._CHILDREN, {})
            self.assertEqual(op._OPERATIONS, {})

