    def test_c2_ratio_concurrent_poison_precedes_evidence_publication(self):
        import vol_value_reconcile as reconcile
        from fetch_ibkr_integration_selftest import ib_contract
        self.root_fixture()
        f = self.ratio_fixture()
        run = self.open("repair", governors=f.registry)
        original = reconcile.bank._ratio_request_evidence
        acquisitions = []
        def race(request, raw, token):
            ledger = request.worker.context.ledger
            real_lock = ledger._lock
            class InterleavedLock:
                def __enter__(lock):
                    real_lock.acquire()
                    acquisitions.append(1)
                    if len(acquisitions) == 2:
                        ledger._failed = "concurrent writer fault witness"
                    return lock
                def __exit__(lock, *args):
                    real_lock.release()
            ledger._lock = InterleavedLock()
            try:
                return original(request, raw, token)
            finally:
                ledger._lock = real_lock
        with patch.dict("sys.modules", {"ib_async": SimpleNamespace(Contract=ib_contract)}), \
                patch.object(reconcile.bank, "_ratio_request_evidence", race):
            with self.assertRaisesRegex(LedgerError, "ledger failed"):
                reconcile.reconcile_one(f.adapter, InstantPacer(), f.bank, f.row,
                    "ratio-concurrent-fault", _fetch_child=self.child(run))
        self.assertGreaterEqual(len(acquisitions), 2)
        self.assertEqual(reconcile.audit.queue_snapshot(f.bank), [f.row])
        self.assertEqual({p: p.read_bytes() for p in f.protected}, f.before)
