                            self.assertEqual(classify.call_count, int(not unsettled))
                            self.assertEqual(row["pass_equivalent"], not unsettled, row)
                            self.assertEqual(row["request_count"], 1)
                            self.assertEqual(row["span_start"], snapshot["span_start"])
                            self.assertEqual(row["span_end"], snapshot["span_end"])
                            proof = row["fetch_provenance"]
