    def test_c2_dispatch_argument_and_child_lifetime_matrix(self):
        from contextlib import contextmanager
        import addstock_fetch_tasks as tasks
        import vol_value_reconcile as reconcile
        pipeline = self.fixdata_fixture()
        targets = (
            ("fixed-fill", pipeline._fixed_fill, {}, "repair"),
            ("fixed-probe", pipeline._fixed_probe, {}, "repair"),
            ("fixed-reconcile", pipeline._fixed_reconcile, {}, "repair"),
            ("addstock-task", tasks._run_addstock_task, {}, "add_stocks"),
            ("ratio-fetch", reconcile.bank.fetch_ratio_day, {}, "repair"),
            ("ratio-reconcile", reconcile.reconcile_one, {}, "repair"),
            ("embedded-probe", probe.run_embedded_probe, {"adapter": object()}, "repair"),
        )
        original_scope = op.scoped_worker
        removed_calls = []
        @contextmanager
        def no_join(child, *, close=False):
            removed_calls.append(close)
            with original_scope(child, close=False) as worker:
                yield worker
        count = 0
        for label, dispatch, options, purpose in targets:
            for removed in (False, True):
                with self.subTest(entry=label, cleanup_removed=removed):
                    run = self.open(purpose, evidence_dir=self.root / f"c06-{label}-{removed}")
                    child, sibling = self.child(run, "transfer"), self.child(run, "sibling")
                    scope = patch.object(op, "scoped_worker", no_join) if removed else nullcontext()
                    with scope, self.assertRaises(TypeError):
                        dispatch(_fetch_child=child, **options)
                    def joined_only_transferred():
                        self.assertNotIn(child, op._CHILDREN, "transferred child was not joined")
                        self.assertIn(sibling, op._CHILDREN, "unrelated sibling was stolen")
                    if removed:
                        with self.assertRaisesRegex(AssertionError, "transferred child was not joined"):
                            joined_only_transferred()
                        self.assertIn(sibling, op._CHILDREN)
                        child.close()  # Rescue only after the inverse is observed.
                    else:
                        joined_only_transferred()
                    self.assertEqual(run.context.ledger.path.read_bytes(), b"")
                    for boundary in (run.seal, run.close):
                        with self.assertRaisesRegex(AuthorityError, "outstanding"):
                            boundary()
                    with sibling.scope():
                        self.assertIs(sibling.worker().context, run.context)
                    sibling.close()
                    run.seal()
                    run.close()
                    count += 1
            for other_thread in (False, True):
                with self.subTest(entry=label, other_thread=other_thread):
                    run = self.open(purpose, evidence_dir=self.root / f"c06-{label}-active-{other_thread}")
                    child = self.child(run, "active")
                    entered, release = threading.Event(), threading.Event()
                    errors = []
                    def hold():
                        try:
                            with child.scope():
                                entered.set()
                                if not release.wait(5):
                                    raise AssertionError("C06 active child was not released")
                                self.assertIs(child.worker().context, run.context)
                        except BaseException as error:
                            errors.append(error)
                    thread = threading.Thread(target=hold)
                    try:
                        if other_thread:
                            thread.start()
                            self.assertTrue(entered.wait(5))
                        with nullcontext() if other_thread else child.scope():
                            with self.assertRaisesRegex(AuthorityError, "already active"):
                                dispatch(_fetch_child=child, **options)
                            self.assertIn(child, op._CHILDREN)
                            for boundary in (run.seal, run.close):
                                with self.assertRaisesRegex(AuthorityError, "outstanding"):
                                    boundary()
                    finally:
                        release.set()
                        if thread.ident is not None:
                            thread.join(5)
                    self.assertFalse(thread.is_alive())
                    self.assertEqual(errors, [])
                    self.assertIn(child, op._CHILDREN)
                    self.assertEqual(run.context.ledger.path.read_bytes(), b"")
                    child.close()
                    run.seal()
                    run.close()
                    count += 1
            closed = []
            forged = SimpleNamespace(close=lambda: closed.append(True))
            with self.subTest(entry=label, forged=True), self.assertRaises(AuthorityError):
                dispatch(_fetch_child=forged, **options)
            self.assertEqual(closed, [])
            self.assertEqual(op._CHILDREN, {})
            self.assertEqual(op._OPERATIONS, {})
            count += 1
        self.assertEqual(count, 35)
        self.assertEqual(removed_calls, [True] * 7)

