    def test_c2_embedded_concurrent_poison_stops_classifier(self):
        import inspect
        from fetch_ibkr_integration_selftest import ib_contract
        self.root_fixture()
        shipped = probe._probe_request_evidence
        source = inspect.getsource(shipped)
        before = ('    with context.ledger._lock:\n'
                  '        if context.ledger.failure:\n'
                  '            raise LedgerError("probe ledger failed before result publication")\n')
        after = ('    if context.ledger.failure:\n'
                 '        raise LedgerError("probe ledger failed before result publication")\n'
                 '    with context.ledger._lock:\n')
        self.assertEqual(source.count(before), 1)
        namespace = dict(probe.__dict__)
        exec(compile(source.replace(before, after), "<probe-lock-removal-inverse>", "exec"), namespace)
        with patch.dict("sys.modules", {"ib_async": SimpleNamespace(Contract=ib_contract)}):
            for token in ("1m", "1d"):
                for removed in (False, True):
                    registry, adapter, _ = self.metadata_fixture()
                    adapter.port = 2000
                    bank, raw = self.probe_bank_fixture(token,
                        [date(2026, 6, 29), date(2026, 6, 30), date(2026, 7, 1)])
                    adapter.ib.rows = raw
                    run = self.open("repair", governors=registry)
                    acquisitions = []
                    target = namespace[shipped.__name__] if removed else shipped
                    def race(request, bars, kind):
                        ledger = request.worker.context.ledger
                        real_lock = ledger._lock
                        class InterleavedLock:
                            def __enter__(lock):
                                real_lock.acquire()
                                acquisitions.append(True)
                                if len(acquisitions) == 2:
                                    ledger._failed = "concurrent probe writer fault"
                            def __exit__(lock, *args):
                                real_lock.release()
                        ledger._lock = InterleavedLock()
                        try:
                            return target(request, bars, kind)
                        finally:
                            ledger._lock = real_lock
                    classify_name = "classify_snapshot_live" if token == "1m" else "classify_daily_span_live"
                    with patch.object(probe, "_probe_request_evidence", race), patch.object(
                            probe, classify_name, wraps=getattr(probe, classify_name)) as classify:
                        options = dict(ticker="TEST", day="2026-07-01", interval=token,
                            adapter=adapter, _fetch_child=self.child(run))
                        if removed:
                            row = probe.run_embedded_probe(bank, **options)
                            self.assertTrue(row["pass_equivalent"], "inverse did not expose false clean probe")
                            classify.assert_called_once()
                        else:
                            with self.assertRaisesRegex(LedgerError, "probe ledger failed"):
                                probe.run_embedded_probe(bank, **options)
                            classify.assert_not_called()
                    self.assertEqual(len(adapter.ib.calls), 1)
                    self.assertGreaterEqual(len(acquisitions), 2)
                    self.assertEqual(len(op._CHILDREN), 0)
                    run.close()

