    def test_c2_fixdata_root_admission_removal_inverse(self):
        import inspect
        pipeline = self.fixdata_fixture()
        source = inspect.getsource(op.require_root_admission)
        needle = 'if run.purpose != "nightly" and run.capability is None:'
        self.assertEqual(source.count(needle), 1)
        namespace = dict(vars(op))
        exec(compile(source.replace(needle, "if False:"), op.__file__, "exec"), namespace)
        original = op.require_root_admission
        for removed in (False, True):
            with self.subTest(removed=removed), patch.object(op, "require_root_admission",
                    namespace["require_root_admission"] if removed else original):
                called = []
                lease_start = len(self.fixture_leases)
                def scan(*args, **kwargs):
                    called.append("scan")
                    return {"summary": {}}
                options = dict(root=self.root / ("admission-bank-" + str(removed)), ports=[2000],
                    adapter_factory=lambda port: self.fail("empty admission control opened an adapter"),
                    scan_fn=scan, series_fn=lambda *a: [], audit_fn=lambda *a: {},
                    refresh_fn=lambda *a, **k: {}, engine_tasks=True,
                    evidence_dir=self.root / ("admission-evidence-" + str(removed)))
                if removed:
                    result = pipeline.run(**options)
                    self.assertIsNone(result["error"], result)
                else:
                    with self.assertRaisesRegex(AuthorityError, "not activated") as caught:
                        pipeline.run(**options)
                    self.assertFalse(caught.exception.fetch_ledger["verified"])
                def refused_before_entry():
                    self.assertEqual(called, [])
                    self.assertEqual(len(self.fixture_leases), lease_start)
                if removed:
                    with self.assertRaises(AssertionError):
                        refused_before_entry()
                    self.assertEqual(called, ["scan"])
                    self.assertGreater(len(self.fixture_leases), lease_start)
                else:
                    refused_before_entry()
                self.assertTrue(all(lease.released for lease in self.fixture_leases))
                self.assertFalse(options["root"].exists())
                self.assertEqual(op._CHILDREN, {})
                self.assertEqual(op._OPERATIONS, {})

