    def fixdata_multiport_recovery_identity(self, *, reset_recovered_fill=False):
        import vol_value_reconcile as reconcile
        from fetch_ibkr_integration_selftest import ib_contract
        pipeline = self.fixdata_fixture()
        mutex, virtual = threading.Lock(), [0.0]
        def clock():
            with mutex:
                return virtual[0]
        def sleep(seconds, cancel=None):
            if cancel is not None and cancel.is_set():
                raise ib.Cancelled()
            with mutex:
                virtual[0] += seconds
        registry = governors.GovernorRegistry(time_fn=clock, sleep_fn=sleep)
        adapters, transports = {}, {}
        records, turns, created, recoveries, observations = [], [], [], [], []
        original_create, original_turn = FetchRunContext.create, governors.Governor.wait_turn
        original_fixed_fill = pipeline._fixed_fill
        def fixed_fill(adapter, root, ticker, interval, days, **kwargs):
            if not reset_recovered_fill or adapter.port != 2001:
                return original_fixed_fill(adapter, root, ticker, interval, days, **kwargs)
            # Model losing parent forwarding after the failed port is recovered.
            # Use an existing registered root, never alter registry/guard policy.
            with op.scoped_worker(kwargs.pop("_fetch_child"), close=True):
                result = ib.fill_missing_days(adapter, root, ticker, interval, days,
                    cancel=kwargs["cancel"], progress=kwargs["progress"],
                    manifest_lock=kwargs["manifest_lock"], run_id=kwargs["run_id"],
                    evidence_dir=self.root / f"recovery-reset-{len(created)}",
                    _test_capability=self.capability)
                # Keep the engine receipt so the sole intended fault is parent
                # custody, not an unrelated loss of completion accounting.
                kwargs["completion"].update(result["fetch_ledger"]["targeted_fill"])
                return result
        def create(*args, **kwargs):
            context = original_create(*args, **kwargs)
            created.append(context)
            return context
        def turn(governor, *args, **kwargs):
            with mutex:
                turns.append(governor)
            return original_turn(governor, *args, **kwargs)
        class Transport(RawIB):
            def __init__(raw, port):
                super().__init__([bar(date(2026, 7, 1))])
                raw.port = port
                raw.barrier = None
                raw.first = True
                raw.disconnected = False
            def witness(raw, kind):
                worker = bridge.current_worker()
                with mutex:
                    records.append((raw.port, kind, worker.context, worker.worker_id))
            def qualifyContractsAsync(raw, pinned):
                raw.witness("qualify")
                return super().qualifyContractsAsync(pinned)
            def reqHeadTimeStampAsync(raw, pinned, **kwargs):
                raw.witness("head")
                return super().reqHeadTimeStampAsync(pinned, **kwargs)
            def reqHistoricalDataAsync(raw, pinned, **kwargs):
                raw.witness("bars")
                if raw.first:
                    raw.first = False
                    # Both distinct port workers must own actual in-flight sends.
                    raw.barrier.wait(timeout=10)
                raw.rows = (raw.ratio_rows if kwargs["whatToShow"] != "TRADES"
                            else raw.probe_rows)
                return super().reqHistoricalDataAsync(pinned, **kwargs)
            def disconnect(raw):
                raw.disconnected = True
            def managedAccounts(raw):
                return [raw.account]
        for port in (2000, 2001):
            adapter = ib.LiveIB()
            adapter.port = port
            adapter._await = lambda value, timeout, description: value
            adapters[port], transports[port] = adapter, Transport(port)
        with patch.dict("sys.modules", {"ib_async": SimpleNamespace(Contract=ib_contract,
                Stock=lambda symbol, *a, **k: contract(symbol))}), \
                patch.object(governors, "_REGISTRY", registry), \
                patch.object(governors.Governor, "wait_turn", turn), \
                patch.object(pipeline, "_fixed_fill", new=fixed_fill), \
                patch.object(FetchRunContext, "create", side_effect=create):
            for iteration in range(4):
                scope = nullcontext() if reset_recovered_fill else self.subTest(iteration=iteration)
                with scope:
                    fixture = self.ratio_fixture()
                    _, probe_rows = self.probe_bank_fixture("1m", [date(2026, 7, 1)],
                        name=f"multiport-probe-source-{iteration}")
                    for ticker in ("AAA", "BBB"):
                        folder = fixture.bank / ticker
                        folder.mkdir()
                        manifest = ib.ss.new_manifest(ticker, ticker)
                        manifest["conid"] = 123
                        ib.ss.save_manifest(folder, manifest)
                    start, turn_start = len(records), len(turns)
                    attempts, events = {2000: 0, 2001: 0}, []
                    gate = threading.Barrier(2)
                    self.fixture_now = datetime(2026, 8, 4 + iteration, 17, tzinfo=NY)
                    expected_now = self.fixture_now
                    for raw in transports.values():
                        raw.barrier, raw.first, raw.disconnected = gate, True, False
                        raw.ratio_rows, raw.probe_rows = fixture.adapter.ib.rows, probe_rows
                        raw.account = "SECOND-ACCOUNT" if iteration >= 2 and raw.port == 2001 else "TEST-ACCOUNT"
                    def factory(port):
                        observations.append((bridge.current_worker(), op._OBSERVER.get()))
                        attempts[port] += 1
                        if port == 2001 and attempts[port] <= pipeline.CONNECT_ATTEMPTS:
                            raise ConnectionError("offline recovery witness")
                        # Later wall-clock movement must not change this parent's horizon.
                        self.fixture_now = datetime(2026, 8, 10, 17, tzinfo=NY)
                        adapters[port].ib = transports[port]
                        return adapters[port]
                    def recover(port, reason):
                        observations.append((bridge.current_worker(), op._OBSERVER.get()))
                        recoveries.append((iteration, port, reason))
                        with self.assertRaisesRegex(AuthorityError, "observer"):
                            self.open("repair")
                        return True
                    def progress(event):
                        if event["type"] == "done":
                            self.assertEqual(len(op._CHILDREN), 0)
                            self.assertEqual(len(op._OPERATIONS), 0)
                            self.assertTrue(all(lease.released for lease in self.fixture_leases))
                            self.assertTrue(all(raw.disconnected for raw in transports.values()))
                        events.append(event)
                    def plan(root, *, ticker=None, kinds=None):
                        return [row for row in reconcile.plan(root)
                                if ticker is None or row["ticker"] == ticker]
                    result = pipeline.run(root=fixture.bank,
                        ports=[2000, 2001], adapter_factory=factory, port_recover_fn=recover,
                        sleep_fn=sleep, scan_fn=lambda *a, **k: {"summary": {
                            f"{ticker} 1m": {"missing_day_list": ["2026-07-01"]}
                            for ticker in ("AAA", "BBB")}},
                        series_fn=lambda root: [(ticker, "1m") for ticker in ("AAA", "BBB")],
                        audit_fn=lambda *a: {"status": "ok", "_verification_current": True},
                        refresh_fn=lambda *a, **k: {}, reconcile_plan_fn=plan,
                        probe_plan_fn=lambda *a: {"seed": 1, "items": {
                            ticker: {"day": "2026-07-01"} for ticker in ("AAA", "BBB")}},
                        engine_tasks=True, progress=progress,
                        evidence_dir=self.root / f"multiport-evidence-{iteration}",
                        _test_capability=self.capability)
                    self.assertIsNone(result["error"], result)
                    self.assertEqual(result["port_errors"], [])
                    self.assertEqual(result["added"], 24, result)
                    self.assertEqual(result["probe_completed"], 2, result)
                    self.assertTrue(all(row["pass_equivalent"] for row in result["probe_rows"]),
                                    result["probe_rows"])
                    self.assertEqual(result["reconcile_settled"], 1, result)
                    self.assertEqual(reconcile.audit.queue_snapshot(fixture.bank), [])
                    self.assertTrue(result["fetch_ledger"]["verified"])
                    if reset_recovered_fill:
                        self.c04_recovery_reset_evidence = {
                            "contexts": list(created), "sends": records[start:],
                            "attempts": dict(attempts), "recoveries": len(recoveries)}
                    self.assertEqual(len(created), iteration + 1, "recovery minted a parent")
                    context = created[-1]
                    self.assertEqual(context.captured_now, expected_now)
                    current = records[start:]
                    self.assertEqual({row[0] for row in current if row[1] == "bars"}, {2000, 2001})
                    self.assertTrue(all(row[2] is context for row in current))
                    workers = {port: {r[3] for r in current if r[0] == port} for port in adapters}
                    self.assertTrue(workers[2000].isdisjoint(workers[2001]))
                    self.assertEqual(set(context._account_bindings), {r[3] for r in current})
                    expected_accounts = {("ibkr", raw.account) for raw in transports.values()}
                    self.assertEqual(set(context._account_bindings.values()), expected_accounts)
                    for port, names in workers.items():
                        self.assertTrue(all(context._account_bindings[name] ==
                            ("ibkr", transports[port].account) for name in names))
                    self.assertEqual(len(turns) - turn_start, len(current))
                    self.assertEqual({governor.identity for governor in turns[turn_start:]}, expected_accounts)
                    evidence = inspect_ledger(context.ledger.path)
                    self.assertTrue(evidence["verified"])
                    decisions = [row for row in evidence["events"] if row["event"] == "decision"]
                    self.assertEqual(len(decisions), len(current))
                    self.assertTrue({"ibkr.gap_fill.month_intraday", "ibkr.live_spot_probe.minute",
                        "ibkr.vol_value_bank.ratio_day"}.issubset({row["producer_id"] for row in decisions}))
                    task_workers = [{row["worker_id"] for row in decisions if row["producer_id"] == producer}
                        for producer in ("ibkr.gap_fill.month_intraday", "ibkr.live_spot_probe.minute",
                                         "ibkr.vol_value_bank.ratio_day")]
                    self.assertEqual([len(workers) for workers in task_workers], [2, 2, 1])
                    self.assertEqual(len(set.union(*task_workers)), 5, "nested phases reused a child")
                    self.assertEqual({row["payload"]["captured_now"] for row in decisions},
                                     {expected_now.isoformat()})
                    self.assertEqual({row["operation_id"] for row in evidence["events"]},
                                     {context.operation_id})
                    self.assertEqual(attempts, {2000: 1, 2001: pipeline.CONNECT_ATTEMPTS + 1})
                    self.assertEqual(sum(event["type"] == "done" for event in events), 1)
        self.assertEqual(len(recoveries), 4)
        self.assertEqual(len(turns), len(records), "missing or duplicate canonical turn")
        self.assertEqual(len({id(governor) for governor in turns}), 2)
        self.assertTrue(all(governor is registry.ibkr([governor.identity[1]]) for governor in turns))
        self.assertEqual(len({context.operation_id for context in created}), 4)
        self.assertEqual(len({id(context.ledger) for context in created}), 4)
        self.assertEqual(len({context.captured_now for context in created}), 4)
        self.assertTrue(all(worker is None and observed for worker, observed in observations))
        self.assertEqual(len(op._CHILDREN), 0)
        self.assertEqual(len(op._OPERATIONS), 0)
        self.assertFalse(any(t.name.startswith("fixdata-scheduler-") for t in threading.enumerate()))

    def test_c2_fixdata_saturation_survives_root_and_port_change(self):
        from fetch_ibkr_integration_selftest import ib_contract
        pipeline = self.fixdata_fixture()
        original_saturate = governors.Governor.saturate
        for removed in (False, True):
            for cancel_wait in ("none", "user", "terminal"):
                with self.subTest(removed=removed, cancel_wait=cancel_wait):
                    virtual, waits, saturations, events = [0.0], [], [], []
                    cancelled = threading.Event()
                    paused = threading.Event()
                    armed = [False]
                    def sleep(seconds, cancel=None):
                        waits.append(seconds)
                        if armed[0] and cancel_wait != "none" and seconds > 1:
                            cancelled.set()
                            if cancel_wait == "terminal":
                                raise ib.Cancelled("terminal pacing cancellation")
                            paused.set()  # The existing UI requests Pause before Cancel.
                        virtual[0] += seconds
                    registry = governors.GovernorRegistry(
                        time_fn=lambda: virtual[0], sleep_fn=sleep)
                    def saturate(governor):
                        saturations.append(governor)
                        if not removed:
                            return original_saturate(governor)
                    bank, bars = self.probe_bank_fixture("1m", [date(2026, 7, 1)],
                        name=f"saturation-bank-{removed}-{cancel_wait}")
                    transports, adapters = [], []
                    for port in (2000, 2001):
                        adapter = ib.LiveIB()
                        adapter.port = port
                        adapter.ib = RawIB(bars)
                        adapter.ib.disconnect = lambda: None
                        adapter._await = lambda value, timeout, description: value
                        transports.append(adapter.ib)
                        adapters.append(adapter)
                    transports[0].failures = [ib.PacingViolation("offline account saturation")]
                    def run(index):
                        return pipeline.run(root=bank, ports=[2000 + index],
                            adapter_factory=lambda port: adapters[index],
                            scan_fn=lambda *a, **k: {"summary": {}},
                            series_fn=lambda root: [("TEST", "1m")],
                            audit_fn=lambda *a: {"status": "ok", "_verification_current": True},
                            refresh_fn=lambda *a, **k: {}, engine_tasks=True,
                            probe_plan_fn=lambda *a: {"seed": 1, "items": {
                                "TEST": {"day": "2026-07-01"}}},
                            pause_event=paused, cancel_event=cancelled, progress=events.append,
                            evidence_dir=self.root / f"saturation-{removed}-{cancel_wait}-{index}",
                            _test_capability=self.capability)
                    with patch.dict("sys.modules", {"ib_async": SimpleNamespace(Contract=ib_contract)}), \
                            patch.object(governors, "_REGISTRY", registry), \
                            patch.object(governors.Governor, "saturate", saturate):
                        first = run(0)
                        self.assertEqual(len(transports[0].calls), 1)
                        self.assertEqual(first["probe_completed"], 1)
                        self.assertFalse(first["probe_rows"][0]["pass_equivalent"])
                        self.assertEqual(len(saturations), 1)
                        armed[0] = True
                        if cancel_wait == "terminal" and not removed:
                            with self.assertRaises(ib.Cancelled) as caught:
                                run(1)
                            second = caught.exception.fetch_ledger
                            self.assertFalse(second["verified"])
                            self.assertTrue(second["fix_data"]["unprocessed"])
                            self.assertEqual(second["fix_data"]["probe_completed"], 0)
                            self.assertEqual(len(transports[1].calls), 0)
                            self.assertEqual(inspect_ledger(second["path"],
                                require_seal=False)["events"], [])
                        else:
                            result = run(1)
                            second = result["fetch_ledger"]
                            user_cancelled = cancel_wait == "user" and not removed
                            self.assertEqual(result["cancelled"], user_cancelled)
                            self.assertEqual(second["verified"], not user_cancelled)
                            self.assertTrue(result["probe_rows"][0]["pass_equivalent"])
                            self.assertEqual(len(transports[1].calls), 1)
                            decision = inspect_ledger(second["path"])["events"][0]
                            self.assertEqual(decision["payload"]["governor_identity"],
                                             ["ibkr", "TEST-ACCOUNT"])
                            self.assertAlmostEqual(decision["payload"]["pacer_wait_seconds"], sum(waits))
                    slot = governors.IBKR_POLICY.window_s / governors.IBKR_POLICY.max_requests
                    self.assertEqual(sum(waits) >= slot, not removed,
                        "no-op saturation must remove the inherited window constraint")
                    self.assertEqual(cancelled.is_set(), cancel_wait != "none" and not removed)
                    self.assertNotEqual(first["fetch_ledger"]["operation_id"], second["operation_id"])
                    self.assertIs(saturations[0], registry.ibkr(["TEST-ACCOUNT"]))
                    done = [event for event in events if event["type"] == "done"]
                    self.assertEqual(len(done), 2)
                    self.assertEqual(len(op._CHILDREN), 0)
                    self.assertEqual(len(op._OPERATIONS), 0)
                    self.assertTrue(all(lease.released for lease in self.fixture_leases))
                    self.assertTrue(all(adapter.ib is None for adapter in adapters))

