    def test_c2_fixdata_audit_currentness_debt_and_credit(self):
        pipeline = self.fixdata_fixture()
        for status in ("ok", "error", "inconclusive", "blocked", "pending"):
            for current in (True, False):
                with self.subTest(status=status, current=current):
                    credits, audits, disconnected = [], [], []
                    def audit(adapter, root, ticker, interval, cache_root):
                        audits.append((ticker, interval))
