    def test_c2_fixdata_callback_families_and_removal_inverses(self):
        import ast
        import inspect
        import textwrap
        import vol_value_reconcile as reconcile
        from fetch_ibkr_integration_selftest import ib_contract
        pipeline = self.fixdata_fixture()
        data_names = {"scan_fn", "health_fn", "audit_fn", "series_fn", "refresh_fn",
                      "probe_plan_fn", "probe_report_fn", "reconcile_plan_fn", "reconcile_report_fn"}
        plain_names = {"adapter_factory", "progress", "verification_fn", "sleep_fn",
                       "reconcile_pacer_factory", "port_recover_fn"}
        event_names = {"pause_event", "cancel_event"}
        source = inspect.getsource(pipeline._prepare_options)
        loops = [node for node in ast.parse(source).body[0].body if isinstance(node, ast.For)]
        self.assertEqual([set(ast.literal_eval(node.iter)) for node in loops],
                         [data_names | {"fill_fn", "probe_fn", "reconcile_fn"},
                          plain_names | {"_reference_opener"}, event_names])
        # The outer opener wrap is defense in depth: _audit_ticker wraps again.
        # Pin its membership here; do not claim a behavioral removal inverse.
        replacements = {
            "data": ("options[name] = fib.without_authority(observe)", "options[name] = observe"),
            "plain": ("options[name] = fib.without_authority(options[name])", "options[name] = options[name]"),
            "events": ("options[name] = fib.observer_object(options[name])", "options[name] = options[name]"),
        }
        mutants = {}
        for label, (needle, replacement) in replacements.items():
            self.assertEqual(source.count(needle), 1)
            namespace = dict(vars(pipeline))
            exec(compile(source.replace(needle, replacement), pipeline.__file__, "exec"), namespace)
            mutants[label] = namespace["_prepare_options"]
        next_source = textwrap.dedent(inspect.getsource(pipeline._ObservedIterator.__next__))
        needle = "return fib.without_authority(lambda: _plain_data(next(self.source)))()"
        self.assertEqual(next_source.count(needle), 1)
        namespace = dict(vars(pipeline))
        exec(compile(next_source.replace(needle, "return _plain_data(next(self.source))"),
                     pipeline.__file__, "exec"), namespace)
        expected = ({(name, "call") for name in data_names | plain_names}
                    | {(name, "items") for name in data_names - {"series_fn"}}
                    | {(name, stage) for name in event_names for stage in ("descriptor", "call")}
                    | {("series_fn", "next"), ("series_fn", "yield-iterate")})
        self.assertEqual(len(expected), 29)
        for removed in ("none", "data", "plain", "events", "iterator"):
            with self.subTest(removed=removed), tempfile.TemporaryDirectory(dir=self.root) as tmp:
                outer_root = self.root
                self.root = Path(tmp)
                attack_adapter = None
                try:
                    f = self.ratio_fixture()
                    _, price_rows = self.probe_bank_fixture("1m", [date(2026, 7, 1)])
                    folder = f.bank / "AAA"
                    folder.mkdir()
                    manifest = ib.ss.new_manifest("AAA", "AAA")
                    manifest["conid"] = 123
                    ib.ss.save_manifest(folder, manifest)
                    adapter, raw = f.adapter, f.adapter.ib
                    adapter.port = 2000
                    ratio_rows = list(raw.rows)
                    original_send = raw.reqHistoricalDataAsync
                    def send(*args, **kwargs):
                        raw.rows = ratio_rows if kwargs["whatToShow"] != "TRADES" else price_rows
                        return original_send(*args, **kwargs)
                    raw.reqHistoricalDataAsync = send
                    _, attack_adapter, _ = self.metadata_fixture()
                    attack_adapter.port = 2000
                    attack_raw = attack_adapter.ib
                    attack_raw.rows = price_rows
                    observed, leaks, parent = {}, [], []
                    mutex = threading.RLock()
                    def witness(name, stage):
                        key = (name, stage)
                        with mutex:
                            if key in observed:
                                return
                            observed[key] = (bridge.current_worker() is not None, bool(op._OBSERVER.get()))
                            if not parent:
                                handle, = op._OPERATIONS
                                parent.append(handle)
                            try:
                                minted = self.open("repair")
                            except AuthorityError:
                                pass
                            else:
                                leaks.append((key, "root"))
                                minted.seal()
                                minted.close()
                            try:
                                child = parent[0].child("callback-thief-" + name + "-" + stage)
                            except AuthorityError:
                                pass
                            else:
                                leaks.append((key, "child"))
                                child.close()
                            prior_calls = len(attack_raw.calls)
                            try:
                                pinned = contract("AAA", 123)
                                end = datetime(2026, 7, 1, 16)
                                request = bridge.bar_request("ibkr.gap_fill.month_intraday",
                                    pinned, "1m", end, "1 D", symbol="AAA",
                                    start=datetime(2026, 7, 1, 9, 30))
                                with bridge.send_scope(request, bridge.acquire_turn):
                                    attack_adapter.fetch(pinned, end, "1 D", "1 min", "TRADES")
                            except AuthorityError:
                                pass
                            if len(attack_raw.calls) > prior_calls:
                                self.assertEqual(len(attack_raw.calls), prior_calls + 1)
                                leaks.append((key, "raw-send"))
                    class Result(dict):
                        def __init__(value, name, data):
                            super().__init__(data)
                            value.name = name
                        def items(value):
                            witness(value.name, "items")
                            return super().items()
                    class Series(tuple):
                        def __iter__(value):
                            witness("series_fn", "yield-iterate")
                            return super().__iter__()
                    def series(root):
                        witness("series_fn", "call")
                        def rows():
                            witness("series_fn", "next")
                            yield Series(("AAA", "1m"))
                        return rows()
                    def data_callback(name, value):
                        def callback(*args, **kwargs):
                            witness(name, "call")
                            return Result(name, value)
                        return callback
                    def ratio_plan(root, *, ticker=None, kinds=None):
                        witness("reconcile_plan_fn", "call")
                        return [Result("reconcile_plan_fn", row) for row in reconcile.plan(root)
                                if ticker is None or row["ticker"] == ticker]
                    attempts = []
                    def factory(port):
                        witness("adapter_factory", "call")
                        attempts.append(port)
                        if len(attempts) <= pipeline.CONNECT_ATTEMPTS:
                            raise ConnectionError("callback proof connection recovery")
                        return adapter
                    def plain(name, value=None):
                        def callback(*args, **kwargs):
                            witness(name, "call")
                            return value
                        return callback
                    class Event:
                        def __init__(value, name):
                            value.name = name
                        @property
                        def is_set(value):
                            witness(value.name, "descriptor")
                            def check():
                                witness(value.name, "call")
                                return False
                            return check
                    options = dict(root=f.bank, ports=[2000], adapter_factory=factory,
                        scan_fn=data_callback("scan_fn", {"summary": {"AAA 1m": {"missing_day_list": ["2026-07-01"]}}}),
                        health_fn=data_callback("health_fn", {}), series_fn=series,
                        audit_fn=data_callback("audit_fn", {"status": "ok", "_verification_current": True}),
                        refresh_fn=data_callback("refresh_fn", {}), reconcile_plan_fn=ratio_plan,
                        probe_plan_fn=data_callback("probe_plan_fn", {"seed": 1, "items": {"AAA": {"day": "2026-07-01"}}}),
                        probe_report_fn=data_callback("probe_report_fn", {}),
                        reconcile_report_fn=data_callback("reconcile_report_fn", {}),
                        progress=plain("progress"), verification_fn=plain("verification_fn"),
                        sleep_fn=plain("sleep_fn"), reconcile_pacer_factory=plain("reconcile_pacer_factory", InstantPacer()),
                        port_recover_fn=plain("port_recover_fn", True),
                        pause_event=Event("pause_event"), cancel_event=Event("cancel_event"),
                        engine_tasks=True, evidence_dir=self.root / "evidence", _test_capability=self.capability)
                    with patch.dict("sys.modules", {"ib_async": SimpleNamespace(Contract=ib_contract,
                            Stock=lambda symbol, *a, **k: contract(symbol))}), \
                            patch.object(governors, "_REGISTRY", f.registry), \
                            patch.object(pipeline, "_prepare_options", mutants.get(removed, pipeline._prepare_options)), \
                            patch.object(pipeline._ObservedIterator, "__next__",
                                namespace["__next__"] if removed == "iterator" else pipeline._ObservedIterator.__next__):
                        result = pipeline.run(**options)
                    self.assertEqual(set(observed), expected, result)
                    def no_authority_leaked():
                        self.assertEqual(leaks, [])
                        self.assertTrue(all(not worker and observer for worker, observer in observed.values()))
                        self.assertEqual(attack_raw.calls, [])
                    if removed == "none":
                        no_authority_leaked()
                    else:
                        with self.assertRaises(AssertionError):
                            no_authority_leaked()
                        self.assertEqual({kind for key, kind in leaks}, {"root", "child", "raw-send"})
                    affected = {
                        "none": set(),
                        "data": ({(name, "call") for name in data_names}
                                 | {(name, "items") for name in data_names - {"series_fn"}}),
                        # worker_scope independently re-wraps these two names.
                        "plain": {(name, "call") for name in plain_names - {"adapter_factory", "progress"}},
                        "events": {(name, stage) for name in event_names for stage in ("descriptor", "call")},
                        "iterator": {("series_fn", "next"), ("series_fn", "yield-iterate")},
                    }[removed]
                    self.assertEqual({key for key, kind in leaks}, affected)
                    for key, (worker, observer) in observed.items():
                        kinds = {kind for seen_key, kind in leaks if seen_key == key}
                        if key in affected:
                            self.assertFalse(observer, key)
                            self.assertEqual(kinds, {"root", "child", "raw-send"}
                                             if worker else {"root", "child"}, key)
                        else:
                            self.assertEqual((worker, observer, kinds), (False, True, set()), key)
                    self.assertIsNone(result["error"], result)
                    self.assertEqual(result["added"], 12)
                    self.assertEqual(result["probe_completed"], 1)
                    self.assertTrue(result["probe_rows"][0]["pass_equivalent"])
                    self.assertEqual(result["reconcile_settled"], 1)
                    self.assertEqual(reconcile.audit.queue_snapshot(f.bank), [])
                    self.assertTrue(result["fetch_ledger"]["verified"])
                    self.assertEqual(len(attempts), pipeline.CONNECT_ATTEMPTS + 1)
                    self.assertIsNone(adapter.ib)
                    self.assertTrue(all(lease.released for lease in self.fixture_leases))
                    self.assertEqual(op._CHILDREN, {})
                    self.assertEqual(op._OPERATIONS, {})
                    self.assertFalse(any(t.name.startswith("fixdata-scheduler-") for t in threading.enumerate()))
                finally:
                    if attack_adapter is not None:
                        attack_adapter.disconnect()
                    self.root = outer_root

    def test_c2_fixdata_ledger_fault_is_terminal_and_reported_once(self):
        from fetch_ibkr_integration_selftest import ib_contract
        pipeline = self.fixdata_fixture()
        original = FetchRunContext.create
        with patch.dict("sys.modules", {"ib_async": SimpleNamespace(Contract=ib_contract)}):
            for event in ("decision", "result"):
                registry, adapter, _ = self.metadata_fixture()
                adapter.port = 2000
                bank, raw = self.probe_bank_fixture("1m", [date(2026, 7, 1)])
                transport = adapter.ib
                transport.rows = raw
                events = []
                def fault(kind, stage):
                    if (kind, stage) == (event, "fsync"):
                        raise OSError("fixdata ledger witness")
                with patch.object(FetchRunContext, "create", side_effect=lambda *a, **k:
                        original(*a, **dict(k, fault=fault))), patch.object(governors, "_REGISTRY", registry):
                    with self.assertRaises(LedgerError) as caught:
                        pipeline.run(root=bank, ports=[2000], adapter_factory=lambda p: adapter,
                            scan_fn=lambda *a, **k: {"summary": {}}, series_fn=lambda r: [("TEST", "1m")],
                            audit_fn=lambda *a: {"status": "ok"}, refresh_fn=lambda *a, **k: {},
                            probe_plan_fn=lambda *a: {"seed": 1, "items": {"TEST": {"day": "2026-07-01"}}},
                            engine_tasks=True, progress=events.append, evidence_dir=self.root / ("fault-" + event),
                            _test_capability=self.capability)
                evidence = caught.exception.fetch_ledger
                self.assertFalse(evidence["verified"])
                self.assertEqual(evidence["fix_data"]["probe_completed"], 0)
                self.assertTrue(evidence["fix_data"]["unprocessed"])
                done = [item for item in events if item["type"] == "done"]
                self.assertEqual(len(done), 1)
                self.assertFalse(done[0]["result"]["fetch_ledger"]["verified"])
                self.assertEqual(len(transport.calls), 0 if event == "decision" else 1)
                self.assertEqual(len(op._CHILDREN), 0)
                self.assertEqual(len(op._OPERATIONS), 0)

    def test_c2_fixdata_observer_terminal_boundaries(self):
        pipeline = self.fixdata_fixture()
        for stage in ("health", "reconcile-plan", "probe-plan", "verification",
                      "progress", "recovery", "disconnect", "refresh", "retention"):
            with self.subTest(stage=stage):
                failure = LedgerError("terminal-" + stage)
                events, factories, observers = [], [], []
                def fail(*args, **kwargs):
                    observers.append((bridge.current_worker(), op._OBSERVER.get()))
                    raise failure
                def factory(port):
                    factories.append(port)
                    if stage == "recovery":
                        raise ConnectionError("ordinary connection failure")
                    return SimpleNamespace(disconnect=fail if stage == "disconnect" else lambda: None)
                def progress(event):
                    events.append(event)
                    if stage == "progress" and event["type"] == "stage":
                        fail()
                options = dict(root=self.root / ("terminal-bank-" + stage), ports=[2000],
                    adapter_factory=factory, scan_fn=lambda *a, **k: {"summary": {}},
                    series_fn=lambda r: [("TEST", "1m")], audit_fn=lambda *a: {"status": "ok"},
                    fill_fn=lambda *a, **k: {}, refresh_fn=lambda *a, **k: {},
                    progress=progress, evidence_dir=self.root / ("terminal-evidence-" + stage),
                    _test_capability=self.capability)
                if stage == "health":
                    options["health_fn"] = fail
                elif stage == "reconcile-plan":
                    options.update(reconcile_plan_fn=fail, reconcile_fn=lambda *a, **k: {})
                elif stage == "probe-plan":
                    options.update(probe_plan_fn=fail, probe_fn=lambda *a, **k: {})
                elif stage == "verification":
                    options["verification_fn"] = fail
                elif stage == "recovery":
                    options["port_recover_fn"] = fail
                elif stage == "refresh":
                    options["refresh_fn"] = fail
                    options["scan_fn"] = lambda *a, **k: {"summary": {
                        "TEST 1m": {"missing_day_list": ["2026-07-01"]}}}
                with patch.object(pipeline.run_log_retention, "prune_run_logs",
                        side_effect=fail if stage == "retention" else lambda *a: {}):
                    with self.assertRaises(LedgerError) as caught:
                        pipeline.run(**options)
                self.assertIs(caught.exception, failure)
                self.assertFalse(failure.fetch_ledger["verified"])
                self.assertTrue(observers)
                self.assertTrue(all(worker is None and observer for worker, observer in observers))
                self.assertEqual(len([e for e in events if e["type"] == "done"]), 1)
                if stage in {"health", "reconcile-plan", "probe-plan", "progress"}:
                    self.assertEqual(factories, [])
                self.assertEqual(len(op._CHILDREN), 0)
                self.assertEqual(len(op._OPERATIONS), 0)
                self.assertTrue(all(lease.released for lease in self.fixture_leases))

    def test_c2_fixdata_first_failure_survives_cleanup_and_report_fault(self):
        pipeline = self.fixdata_fixture()
