    def test_d_fixdata_completion_detachment_preserves_delivery(self):
        pipeline = self.fixdata_fixture()
        original_body = pipeline._run_fix_data_body
        for mode in ("clean", "nested", "iterator", "bytes", "cycle", "shape",
                     "mapping", "format", "name", "event"):
            for prior in (False, True):
                for report_fault in (False, True):
                    with self.subTest(mode=mode, prior=prior, report_fault=report_fault):
                        events, hooks = [], []
                        first = LedgerError("earlier operation failure")
                        def witness():
                            hooks.append((bridge.current_worker(), op._OBSERVER.get()))
                            with self.assertRaisesRegex(AuthorityError, "observer"):
                                self.open("repair")
                        class ErrorMeta(type):
                            def __getattribute__(cls, name):
                                if mode == "name" and name == "__name__":
                                    witness()
                                    return object()
                                return super().__getattribute__(name)
                        class DetachError(ValueError, metaclass=ErrorMeta):
                            def __str__(error):
                                witness()
                                if mode == "mapping":
                                    return "bounded diagnostic " + "x" * 900
                                raise LedgerError("secondary diagnostic hook failure")
                        detach_error = DetachError("completion witness")
                        class Hostile(dict):
                            def items(value):
                                witness()
                                raise detach_error
                            def __bool__(value):
                                witness()
                                raise AssertionError("completion truthiness must not run")
                        def body(**options):
                            try:
                                return original_body(**options)
                            finally:
                                completion = options["_completion"]
                                if mode == "nested":
                                    completion["result"]["bad"] = object()
                                elif mode == "iterator":
                                    completion["result"]["bad"] = iter([object()])
                                elif mode == "bytes":
                                    completion["result"]["bad"] = b"not JSON evidence"
                                elif mode == "cycle":
                                    completion["result"]["bad"] = completion["result"]
                                elif mode == "shape":
                                    completion["result"] = ["not a result dictionary"]
                                elif mode in {"mapping", "format", "name"}:
                                    completion["result"] = Hostile()
                                elif mode == "event":
                                    completion["done_event"] = Hostile()
                        def health(*args):
                            if prior:
                                raise first
                            return {}
                        evidence_dir = self.root / f"detach-{mode}-{prior}-{report_fault}"
                        result, caught = None, None
                        with patch.object(pipeline, "_run_fix_data_body", side_effect=body), \
                                patch.object(reporting, "write_report",
                                    side_effect=reporting.OperationReportError("report fault")
                                    if report_fault else None,
                                    wraps=None if report_fault else reporting.write_report):
                            try:
                                result = pipeline.run(root=self.root / "empty-bank", ports=[2000],
                                    adapter_factory=lambda p: self.fail("empty run connected"),
                                    scan_fn=lambda *a, **k: {"summary": {}},
                                    series_fn=lambda *a: [], health_fn=health,
                                    audit_fn=lambda *a: {}, fill_fn=lambda *a, **k: {},
                                    refresh_fn=lambda *a, **k: {}, progress=events.append,
                                    run_id="completion-test", evidence_dir=evidence_dir,
                                    _test_capability=self.capability)
                            except BaseException as exc:
                                caught = exc
                        if prior:
                            self.assertIs(caught, first)
                        elif mode in {"mapping", "format", "name", "event"}:
                            self.assertIs(caught, detach_error)
                        elif mode in {"nested", "iterator", "bytes", "shape"}:
                            self.assertIsInstance(caught, TypeError)
                        elif mode == "cycle":
                            self.assertIsInstance(caught, RecursionError)
                        elif report_fault:
                            self.assertIsInstance(caught, reporting.OperationReportError)
                        else:
                            self.assertIsNone(caught)
                        done = [event for event in events if event["type"] == "done"]
                        self.assertEqual(len(done), 1)
                        ledger = done[0]["result"]["fetch_ledger"]
                        self.assertEqual(done[0]["run_id"], "completion-test")
                        self.assertEqual(ledger["ledger_verified"], not prior)
                        if mode != "clean":
                            self.assertFalse(ledger["verified"])
                            self.assertEqual(ledger["state"], "UNVERIFIED")
                            self.assertLessEqual(len(ledger["completion_failure"]), 500)
                            self.assertIsNone(ledger["fix_data"])
                            self.assertNotIn("bad", done[0]["result"])
                        if mode in {"mapping", "format", "name", "event"}:
                            self.assertTrue(hooks)
                            self.assertTrue(all(worker is None and observer for worker, observer in hooks))
                        if report_fault:
                            self.assertFalse(ledger["report_persisted"])
                        reports = list(evidence_dir.glob("*.operation.json"))
                        self.assertEqual(len(reports), 0 if report_fault else 1)
                        if reports:
                            saved = json.loads(reports[0].read_text(encoding="utf-8"))
                            self.assertEqual(saved["fix_data"], ledger["fix_data"])
                            self.assertEqual(saved["verified"], ledger["verified"])
                        self.assertEqual(op._CHILDREN, {})
                        self.assertEqual(op._OPERATIONS, {})
                        self.assertTrue(all(lease.released for lease in self.fixture_leases))

    def test_c2_fixdata_fixed_probe_selection_is_observer(self):
        pipeline = self.fixdata_fixture()
        witnessed = []
        class Selection(dict):
            def __getitem__(value, key):
                witnessed.append((bridge.current_worker(), op._OBSERVER.get()))
                raise ValueError("selection witness")
