    def test_c2_legacy_fixdata_scheduler_contracts(self):
        import contextlib
        import io
        import operation_gate
        pipeline = self.fixdata_fixture()
        original_run = pipeline.run
        leases, held, mutex = [], {}, threading.RLock()
        class Lease:
            def __init__(self, key, mode):
                self.key, self.mode, self.released = key, mode, False
            def __enter__(self):
                return self
            def release(self):
                with mutex:
                    if not self.released:
                        self.released = True
                        held[self.key][1] -= 1
                        if not held[self.key][1]:
                            del held[self.key]
            def __exit__(self, *args):
                self.release()
                return False
        def acquire(mode, *, owner=None, path=None):
            key = str(Path(path or operation_gate.LOCK_PATH).resolve())
            with mutex:
                if key in held and held[key][0] != mode:
                    raise operation_gate.OperationBusy("offline conflicting operation")
                held.setdefault(key, [mode, 0])[1] += 1
                lease = Lease(key, mode)
                leases.append(lease)
                return lease
        sequence = [0]
        def run(**kwargs):
            sequence[0] += 1
            kwargs.update(root=self.root / "legacy-bank", _test_capability=self.capability,
                evidence_dir=self.root / "legacy-fixdata" / str(sequence[0]))
            return original_run(**kwargs)
        source = Path(__file__).with_name("fix_data_pipeline_selftest.py")
        namespace = {"__file__": str(source), "__name__": "confined_fixdata_legacy"}
        output = io.StringIO()
        with patch.object(pipeline, "run", run), patch.object(operation_gate, "acquire", acquire), \
                contextlib.redirect_stdout(output):
            try:
                exec(compile(source.read_text(encoding="utf-8"), str(source), "exec"), namespace)
            except SystemExit as exc:
                exit_code = exc.code
            else:
                self.fail("legacy scheduler entry did not report a terminal result")
        print(output.getvalue(), end="")
        self.assertEqual(exit_code, 0, output.getvalue())
        self.assertEqual(len(namespace["checks"]), 79)
        self.assertTrue(all(namespace["checks"]))
        self.assertTrue(all(lease.released for lease in leases))
        self.assertEqual(held, {})
        self.assertEqual(len(op._CHILDREN), 0)
        self.assertEqual(len(op._OPERATIONS), 0)
        self.assertFalse(any(t.name.startswith("fixdata-scheduler-") for t in threading.enumerate()))

