    def test_c2_shared_planners_keep_non_nightly_purpose_and_inverse(self):
        from fetch_ibkr_integration_selftest import ib_contract
        from contextlib import ExitStack
        modes = (("serial", (2000,)), ("fleet", (2000,)), ("fleet", (2000, 2001)),
                 ("targeted", (2000,)))
        for mode, ports in modes:
            for inverse in (False, True):
                with self.subTest(mode=mode, ports=ports, inverse=inverse), \
                        tempfile.TemporaryDirectory(dir=self.root) as tmp, ExitStack() as scope:
                    outer_root = self.root
                    self.root = Path(tmp)
                    scope.callback(setattr, self, "root", outer_root)
                    f = self.addstock_root_fixture()
                    original_make, physical = f.make, []
                    expected_purpose = "repair" if mode == "targeted" else "add_stocks"
                    def make(port):
                        adapter = original_make(port)
                        for method in ("reqHistoricalDataAsync", "reqHeadTimeStampAsync",
                                       "qualifyContractsAsync"):
                            original_send = getattr(adapter.ib, method)
                            def send(*args, _send=original_send, **kwargs):
                                worker = bridge.current_worker()
                                physical.append((worker.context, worker.worker_id,
                                                 op.operation_purpose(worker.context)))
                                return _send(*args, **kwargs)
                            setattr(adapter.ib, method, send)
                        return adapter
                    scope.enter_context(patch.dict("sys.modules", {
                        "ib_async": SimpleNamespace(Contract=ib_contract)}))
                    if inverse:
                        scope.enter_context(patch.object(op, "operation_purpose",
                                                       lambda context: "nightly"))
                    options = dict(evidence_dir=self.root / "purpose-evidence",
                                   _test_capability=self.capability)
                    if mode == "targeted":
                        result = ib.fill_missing_days(make(2000), f.bank, "TEST", "1m",
                            ["2026-07-01"], contract=contract(), **options)
                        added = result["added"]
                        expected_producer = "ibkr.gap_fill.month_intraday"
                    else:
                        options.update(today=date(2026, 7, 2), since=date(2026, 7, 1),
                                       resolved={"TEST": 123})
                        if mode == "serial":
                            result = ib.add_stocks_gap_fill(f.bank, [("TEST", "1m")],
                                adapter_factory=lambda: make(2000), **options)
                        else:
                            result = ib.add_stocks_gap_fill_parallel_resilient(f.bank,
                                [("TEST", "1m")], ports,
                                adapter_factory=lambda host, ports: lambda: make(ports[0]),
                                port_up=lambda port: True,
                                restart_port=lambda port: self.fail("healthy purpose proof recovered"),
                                **options)
                        added = result["totals"]["added"]
                        expected_producer = "ibkr.gap_fill.session_fetch"
                    self.assertEqual(added, 12, result)
                    self.assertTrue(result["fetch_ledger"]["verified"], result)
                    self.assertEqual(result["fetch_ledger"]["purpose"], expected_purpose)
                    self.assertEqual(len(f.created), 1)
                    self.assertTrue(physical)
                    self.assertTrue(all(context is f.created[0] for context, _, _ in physical))
                    def correct_purpose():
                        self.assertEqual({purpose for _, _, purpose in physical}, {expected_purpose})
                    if inverse:
                        self.assertEqual({purpose for _, _, purpose in physical}, {"nightly"})
                        with self.assertRaises(AssertionError):
                            correct_purpose()
                    else:
                        correct_purpose()
                    evidence = inspect_ledger(result["fetch_ledger"]["path"])
                    self.assertTrue(evidence["verified"])
                    decisions = [row for row in evidence["events"] if row["event"] == "decision"]
                    results = [row for row in evidence["events"] if row["event"] == "result"]
                    expected_producers = ({expected_producer} if mode == "targeted" else
                        {expected_producer, "ibkr.gap_fill.head_timestamp",
                         "ibkr.gap_fill.head_daily_probe"})
                    self.assertEqual({row["producer_id"] for row in decisions}, expected_producers)
                    self.assertEqual(len(decisions), len(results))
                    self.assertEqual(len(decisions), len(physical))
                    self.assertEqual({row["operation_id"] for row in decisions},
                                     {f.created[0].operation_id})
                    month = ib.ss.month_file_path(f.bank, "TEST", 2026, 7, "1m")
                    stored, _ = ib.ss.read_month_file(month)
                    self.assertEqual(len(stored), 12)
                    self.assertEqual(op._CHILDREN, {})
                    self.assertEqual(op._OPERATIONS, {})
                    self.assertTrue(all(lease.released for lease in self.fixture_leases))
                    self.assertFalse(any(t.name.startswith("ibkr-fetch-")
                                         for t in threading.enumerate()))

    def test_c2_addstock_root_observer_authority_and_removal_inverse(self):
        import inspect
        from fetch_ibkr_integration_selftest import ib_contract
        source = inspect.getsource(bridge.guard_callbacks)
        needle = '("cancel", "pause", "post_pipeline")'
        self.assertEqual(source.count(needle), 1)
        namespace = dict(vars(bridge))
        exec(compile(source.replace(needle, '("cancel", "pause")'), bridge.__file__, "exec"), namespace)
        original = bridge.guard_callbacks
        seams = {"claim", "has_pending", "record_series", "request_options", "complete_request"}
        expected = {(name, stage) for name in seams for stage in ("descriptor", "call")}
        for mode in ("serial", "fleet"):
            for removed in (False, True):
                with self.subTest(mode=mode, removed=removed), tempfile.TemporaryDirectory(dir=self.root) as tmp:
                    outer_root = self.root
                    self.root = Path(tmp)
                    attack_adapter = None
                    try:
                        f = self.addstock_root_fixture()
                        # This test attacks the five facade hooks below. Keep
                        # check_fn a passive fixture so its older assertion
                        # cannot stop the inverse before later hooks execute.
                        def check(*args):
                            f.callbacks.append("check")
                            return {"selection": {"day": "2026-07-01"}}
                        f.coordinator = probe.AddStockProbeCoordinator(
                            [("TEST", "1m")], check_fn=check, engine_requests=True, seed=32)
                        _, attack_adapter, _ = self.metadata_fixture()
                        attack_adapter.port = 2000
                        attack_raw = attack_adapter.ib
                        attack_raw.rows = [bar(datetime(2026, 7, 1, 9, 30, tzinfo=NY))]
                        observed, leaks = {}, []
                        lock = threading.RLock()
                        def witness(name, stage):
                            key = (name, stage)
                            with lock:
                                if key in observed:
                                    return
                                observed[key] = (bridge.current_worker() is not None, bool(op._OBSERVER.get()))
                                parent, = [handle for handle, record in op._OPERATIONS.items()
                                           if record.context is f.created[0]]
                                try:
                                    minted = self.open("add_stocks")
                                except AuthorityError:
                                    pass
                                else:
                                    leaks.append((key, "root"))
                                    minted.seal()
                                    minted.close()
                                try:
                                    child = parent.child("observer-thief-" + name + "-" + stage)
                                except AuthorityError:
                                    pass
                                else:
                                    leaks.append((key, "child"))
                                    child.close()
                                prior_calls = len(attack_raw.calls)
                                try:
                                    pinned = contract("TEST", 123)
                                    end = datetime(2026, 7, 1, 16)
                                    request = bridge.bar_request("ibkr.gap_fill.month_intraday",
                                        pinned, "1m", end, "1 D", symbol="TEST",
                                        start=datetime(2026, 7, 1, 9, 30))
                                    with bridge.send_scope(request, bridge.acquire_turn):
                                        attack_adapter.fetch(pinned, end, "1 D", "1 min", "TRADES")
                                except AuthorityError:
                                    pass
                                if len(attack_raw.calls) > prior_calls:
                                    self.assertEqual(len(attack_raw.calls), prior_calls + 1)
                                    leaks.append((key, "raw-send"))
                        class Coordinator:
                            def __getattr__(value, name):
                                target = getattr(f.coordinator, name)
                                if name not in seams:
                                    return target
                                witness(name, "descriptor")
                                def invoke(*args, **kwargs):
                                    witness(name, "call")
                                    return target(*args, **kwargs)
                                return invoke
                        options = dict(today=date(2026, 7, 2), since=date(2026, 7, 1),
                            resolved={"TEST": 123}, post_pipeline=Coordinator(), engine_post_tasks=True,
                            evidence_dir=self.root / "evidence", _test_capability=self.capability)
                        with patch.dict("sys.modules", {"ib_async": SimpleNamespace(Contract=ib_contract)}), \
                                patch.object(bridge, "guard_callbacks",
                                    namespace["guard_callbacks"] if removed else original):
                            if mode == "serial":
                                result = ib.add_stocks_gap_fill(f.bank, [("TEST", "1m")],
                                    adapter_factory=lambda: f.make(2000), **options)
                            else:
                                result = ib.add_stocks_gap_fill_parallel_resilient(f.bank,
                                    [("TEST", "1m")], [2000, 2001],
                                    adapter_factory=lambda host, ports: lambda: f.make(ports[0]),
                                    port_up=lambda port: True,
                                    restart_port=lambda port: self.fail("observer proof tried recovery"), **options)
                        self.assertEqual(set(observed), expected)
                        def no_authority_leaked():
                            self.assertEqual(leaks, [])
                            self.assertTrue(all(worker is False and observer is True
                                                for worker, observer in observed.values()))
                            self.assertEqual(attack_raw.calls, [])
                        if removed:
                            with self.assertRaises(AssertionError):
                                no_authority_leaked()
                            self.assertEqual({kind for key, kind in leaks}, {"root", "child", "raw-send"})
                            for key, (worker, observer) in observed.items():
                                kinds = {kind for seen_key, kind in leaks if seen_key == key}
                                if key[0] == "request_options":
                                    self.assertEqual((worker, observer, kinds), (False, True, set()))
                                else:
                                    self.assertFalse(observer, key)
                                    self.assertEqual(kinds, {"root", "child", "raw-send"}
                                                     if worker else {"root", "child"}, key)
                            # The fixed task's explicit options guard remains
                            # independently effective after facade removal.
                            self.assertFalse(any(key[0] == "request_options" for key, kind in leaks))
                        else:
                            no_authority_leaked()
                        self.assertTrue(result["fetch_ledger"]["verified"], result)
                        self.assertEqual(result["totals"]["added"], 12)
                        self.assertEqual(f.coordinator.result()["issue_count"], 0)
                        self.assertEqual(f.callbacks, ["check"])
                        self.assertTrue(all(adapter.ib is None for adapter in f.adapters))
                        self.assertTrue(all(lease.released for lease in self.fixture_leases))
                        self.assertEqual(op._CHILDREN, {})
                        self.assertEqual(op._OPERATIONS, {})
                        self.assertFalse(any(t.name.startswith("ibkr-fetch-")
                                             or t.name == "ibkr-adaptive" for t in threading.enumerate()))
                    finally:
                        if attack_adapter is not None:
                            attack_adapter.disconnect()
                        self.root = outer_root

