    def test_c2_addstock_observer_failure_settles_active_phase(self):
        for phase in ("check", "reconcile-plan"):
            for seam in ("callback", "progress", "formatter", "result"):
                with self.subTest(phase=phase, seam=seam):
                    primary = LedgerError("observer terminal witness")
                    class HostileError(LedgerError):
                        def __str__(self):
                            raise KeyboardInterrupt("secondary formatter")
                    if seam == "formatter":
                        primary = HostileError("original terminal")
                    def fail():
                        self.assertIsNone(bridge.current_worker())
                        raise primary
                    class HostileResult(dict):
                        def get(self, *args):
                            fail()
                    class HostilePlan:
                        def __iter__(self):
                            fail()
                    def callback(*args):
                        if seam == "result":
                            return HostileResult() if phase == "check" else HostilePlan()
                        fail()
                    coordinator = probe.AddStockProbeCoordinator(
                        [("TEST", "1m")], check_fn=callback, engine_requests=True, seed=32,
                        reconcile_plan_fn=callback if phase == "reconcile-plan" else None,
                        progress=(lambda message: fail()) if seam == "progress" else None)
                    coordinator.record_series([{"ticker": "TEST", "interval": "1m"}])
                    task = coordinator.claim()
                    self.assertEqual(task, (phase, "TEST"))
                    escaped = None
                    try:
                        bridge.without_authority(coordinator.execute)(task, None, None)
                    except BaseException as exc:
                        escaped = exc
                    self.assertIs(escaped, primary)
                    self.assertEqual(coordinator._active_checks, 0)
                    self.assertEqual(coordinator._active_reconcile_plans, 0)
                    self.assertFalse(coordinator._reconcile_active_plan_tickers)
                    self.assertIsNone(coordinator.claim(), "terminal observer queued successor work")
                    self.assertEqual(coordinator.result()["issue_count"], 1)

