    def test_c2_addstock_completion_evidence_faults_actual_roots(self):
        from fetch_ibkr_integration_selftest import ib_contract
        points = [(None, None)] + [(kind, stage) for kind, stages in (
            ("seal", ("append", "flush", "fsync")),
            ("receipt", ("append", "flush", "fsync", "publish")),
            ("report", ("create", "flush", "fsync", "replace"))) for stage in stages]
        for mode in ("serial", "fleet"):
            for point, stage in points:
                with self.subTest(mode=mode, point=point, stage=stage), \
                        tempfile.TemporaryDirectory(dir=self.root) as tmp:
                    outer_root = self.root
                    self.root = Path(tmp)
                    try:
                        f = self.addstock_root_fixture()
                        create, write_report = FetchRunContext.create, reporting.write_report
                        faults, sends_at_fault, committed = [], [], []
                        def send_count():
                            return sum(len(raw.calls) for raw in f.raws)
                        def fault(kind, phase):
                            if (kind, phase) != (point, stage):
                                return
                            faults.append((kind, phase))
                            sends_at_fault.append(send_count())
                            self.assertEqual(op._CHILDREN, {})
                            month = ib.ss.find_month_file(f.bank, "TEST", 2026, 7, "1m")
                            self.assertIsNotNone(month)
                            committed.append((Path(month), Path(month).read_bytes(),
                                              ib.ss.load_manifest(f.bank / "TEST")))
                            raise OSError("C2 completion evidence witness")
                        writer = (patch.object(reporting, "write_report",
                            side_effect=lambda value, directory=None:
                                write_report(value, directory, fault=fault))
                            if point == "report" else nullcontext())
                        options = dict(today=date(2026, 7, 2), since=date(2026, 7, 1),
                            resolved={"TEST": 123}, post_pipeline=f.coordinator, engine_post_tasks=True,
                            evidence_dir=self.root / "evidence", _test_capability=self.capability)
                        escaped, result = None, None
                        with writer, patch.object(FetchRunContext, "create", side_effect=lambda *a, **k:
                                create(*a, **dict(k, fault=fault))), \
                                patch.dict("sys.modules", {"ib_async": SimpleNamespace(Contract=ib_contract)}):
                            try:
                                if mode == "serial":
                                    result = ib.add_stocks_gap_fill(f.bank, [("TEST", "1m")],
                                        adapter_factory=lambda: f.make(2000), **options)
                                else:
                                    result = ib.add_stocks_gap_fill_parallel_resilient(f.bank,
                                        [("TEST", "1m")], (2000, 2001),
                                        adapter_factory=lambda host, ports: lambda: f.make(ports[0]),
                                        port_up=lambda port: True,
                                        restart_port=lambda port: self.fail("completion fault started recovery"),
                                        **options)
                            except BaseException as exc:
                                escaped = exc
                        self.assertTrue(all(adapter.ib is None for adapter in f.adapters))
                        self.assertTrue(all(lease.released for lease in self.fixture_leases))
                        self.assertEqual(op._CHILDREN, {})
                        self.assertEqual(op._OPERATIONS, {})
                        self.assertFalse(any(t.name.startswith("ibkr-") for t in threading.enumerate()))
                        if point is not None:
                            self.assertEqual(faults, [(point, stage)])
                            self.assertEqual(sends_at_fault, [send_count()])
                            for path, content, manifest in committed:
                                self.assertEqual(path.read_bytes(), content)
                                self.assertEqual(ib.ss.load_manifest(f.bank / "TEST"), manifest)
                            self.assertIsInstance(escaped, LedgerError,
                                "completion evidence failure returned normally instead of surfacing")
                            result = escaped.fetch_report
                        else:
                            self.assertIsNone(escaped)
                            self.assertEqual(faults, [])
                        self.assertEqual(result["totals"]["added"], 12)
                        self.assertEqual(result["spot_probe"]["completed_count"], 1)
                        self.assertEqual(result["spot_probe"]["issue_count"], 0)
                        evidence = result["fetch_ledger"]
                        self.assertEqual(evidence["verified"], point is None)
                        self.assertEqual(evidence["state"], "VERIFIED" if point is None else "UNVERIFIED")
                        self.assertEqual(evidence["ledger_verified"], point in (None, "report"))
                        companion = self.root / "evidence" / (evidence["operation_id"] + ".operation.json")
                        if point == "report":
                            self.assertFalse(companion.exists())
                            self.assertEqual(list(companion.parent.glob(".operation-*.tmp")), [])
                            self.assertIn("C2 completion evidence witness", evidence["report_failure"])
                        else:
                            saved = json.loads(companion.read_text(encoding="utf-8"))
                            self.assertEqual(saved["verified"], point is None)
                            self.assertEqual(saved["operation_id"], evidence["operation_id"])
                        if point in ("seal", "receipt"):
                            with self.assertRaises(LedgerError):
                                inspect_ledger(evidence["path"])
                        else:
                            self.assertTrue(inspect_ledger(evidence["path"])["verified"])
                    finally:
                        self.root = outer_root

