                        options = dict(today=date(2026, 7, 2), since=date(2026, 7, 1),
                            resolved={"TEST": 123}, post_pipeline=f.coordinator, engine_post_tasks=True,
                            evidence_dir=self.root / "evidence", _test_capability=self.capability)
                        with patch.object(ib.ss, "_atomic_write_bytes", side_effect=write), \
                                patch.dict("sys.modules", {"ib_async": SimpleNamespace(Contract=ib_contract)}):
                            if mode == "serial":
                                result = ib.add_stocks_gap_fill(f.bank, [("TEST", "1m")],
                                    adapter_factory=lambda: f.make(2000), **options)
