    def test_c2_addstock_fixed_request_failure_observer(self):
        import addstock_fetch_tasks as tasks
        import addstock_watchdog as watchdog
        from fetch_ibkr_integration_selftest import ib_contract
        self.root_fixture()
        with patch.dict("sys.modules", {"ib_async": SimpleNamespace(Contract=ib_contract)}):
            for phase in ("probe", "reconcile"):
                for kind in (ConnectionResetError, TimeoutError, LedgerError):
                    with self.subTest(phase=phase, kind=kind.__name__):
                        f = self.addstock_task_fixture(phase)
                        primary = kind("raw request failure")
                        f.adapter.ib.failures.append(primary)
                        notifications = []
                        def notify(error):
                            self.assertIsNone(bridge.current_worker())
                            with self.assertRaises(AuthorityError):
                                f.run.child("observer-must-not-mint")
                            with self.assertRaises(AuthorityError):
                                self.open("add_stocks")
                            notifications.append(watchdog.hard_signal_kind(error))
                            bridge.notify_request_error(error)  # no recursive hook
                            return lambda: self.fail("observer result became an executor")
                        escaped = None
                        try:
                            tasks._run_addstock_task(f.bank, f.coordinator, f.task,
                                f.adapter, f.pacer, on_request_error=notify,
                                _fetch_child=self.child(f.run, "notify-" + str(len(self.children))))
                        except BaseException as exc:
                            escaped = exc
                        if kind is LedgerError:
                            self.assertIs(escaped, primary)
                            self.assertEqual(notifications, [])
                        else:
                            self.assertIsNone(escaped)
                            self.assertEqual(notifications,
                                ["connection_lost"] if kind is ConnectionResetError else [None])
                        bridge.notify_request_error(primary)
                        self.assertEqual(len(notifications), 0 if kind is LedgerError else 1)
                        self.assertEqual(len(f.adapter.ib.calls), 1)
                        self.assertEqual(len(op._CHILDREN), 0)
                        self.assertEqual(f.coordinator.status_snapshot()[
                            "active_probes" if phase == "probe" else "active_reconciles"], 0)
                        f.run.close()
                        f.adapter.disconnect()

    def test_c2_addstock_request_error_observer_precedence(self):
        original = LedgerError("original terminal")
        secondary = KeyboardInterrupt("observer terminal")
        def fail(error):
            raise secondary
        with bridge.request_error_observer(fail):
            for error, expected in ((original, original), (RuntimeError("request"), secondary)):
                escaped = None
                try:
                    bridge.notify_request_error(error)
                except BaseException as exc:
                    escaped = exc
                self.assertIs(escaped, expected)
        bridge.notify_request_error(original)
        with bridge.request_error_observer(lambda error: (_ for _ in ()).throw(ValueError("reporting"))):
            bridge.notify_request_error(RuntimeError("ordinary request failure"))

