                    raw = f.adapter.ib
                    original_send = raw.reqHistoricalDataAsync
                    witnesses = []
                    def send(*args, **kwargs):
                        worker = bridge.current_worker()
                        witnesses.append((worker.context, worker.worker_id))
                        return original_send(*args, **kwargs)
                    governor = f.registry.ibkr(["TEST-ACCOUNT"])
