    def test_c2_addstock_fixed_terminal_is_not_observer_replaceable(self):
        from fetch_ibkr_integration_selftest import ib_contract
        import vol_value_reconcile as reconcile
        self.root_fixture()
        with patch.dict("sys.modules", {"ib_async": SimpleNamespace(Contract=ib_contract)}):
            for phase in ("probe", "reconcile"):
                for kind in (AuthorityError, LedgerError, ib.Cancelled, KeyboardInterrupt):
                    for reporting in ("normal", "swallow", "replace"):
                        with self.subTest(phase=phase, error=kind.__name__, reporting=reporting):
                            f = self.addstock_task_fixture(phase)
                            primary = kind("fixed-request terminal witness")
                            f.adapter.ib.failures.append(primary)
                            original_complete = f.coordinator.complete_request
                            def complete(*args, **kwargs):
                                self.assertIsNone(bridge.current_worker())
                                if reporting == "normal":
                                    return original_complete(*args, **kwargs)
                                try:
                                    original_complete(*args, **kwargs)
                                except BaseException:
                                    if reporting == "replace":
                                        raise RuntimeError("observer replacement")
                            with patch.object(f.coordinator, "complete_request", side_effect=complete), \
                                    self.assertRaises(kind) as caught:
                                f.dispatch(f.task)
                            self.assertIs(caught.exception, primary)
                            self.assertEqual(len(f.adapter.ib.calls), 1)
                            self.assertEqual(len(op._CHILDREN), 0)
                            self.assertEqual(f.coordinator.status_snapshot()[
                                "active_probes" if phase == "probe" else "active_reconciles"], 0)
                            self.assertEqual(f.coordinator.result()["issue_count"], 1)
                            if phase == "reconcile":
                                debt = f.coordinator.reconcile_result()
                                self.assertEqual(debt["queue_resolved_count"], 0)
                                self.assertEqual(debt["request_count_unknown"], 1)
                                self.assertEqual(reconcile.audit.queue_snapshot(f.bank), [f.row])
                                self.assertEqual({p: p.read_bytes() for p in f.protected}, f.before)
                            else:
                                row = f.coordinator.result()["rows"][0]
                                self.assertFalse(row["pass_equivalent"])
                                self.assertTrue(row["request_count_unknown"])
                            events = inspect_ledger(f.run.context.ledger.path, require_seal=False)["events"]
                            self.assertEqual(len(events), 1 if kind is KeyboardInterrupt else 2)
                            f.run.close()
                            f.adapter.disconnect()
        self.assertEqual(len(op._OPERATIONS), 0)

    def test_c2_addstock_fixed_descriptors_and_task_data_are_observers(self):
        import inspect
        import addstock_fetch_tasks as tasks
        from fetch_ibkr_integration_selftest import ib_contract
        self.root_fixture()
        source = inspect.getsource(tasks._run_addstock_task)
        mutations = {
            "task-data": ("root, task = fib.without_authority(_task_data)(root, task)",
                          "root, task = _task_data(root, task)"),
            "options-data": (
                "options = fib.without_authority(lambda: dict(post_pipeline.request_options(task)))()",
                "options = dict(post_pipeline.request_options(task))"),
        }
        mutants = {}
        for label, (needle, replacement) in mutations.items():
            self.assertEqual(source.count(needle), 1)
            namespace = dict(vars(tasks))
            exec(compile(source.replace(needle, replacement), tasks.__file__, "exec"), namespace)
            mutants[label] = namespace["_run_addstock_task"]
        with patch.dict("sys.modules", {"ib_async": SimpleNamespace(Contract=ib_contract)}):
            for removed in ("none", "task-data", "options-data"):
                with self.subTest(removed=removed), tempfile.TemporaryDirectory(dir=self.root) as tmp:
                    outer_root = self.root
                    self.root = Path(tmp)
                    try:
                        f = self.addstock_task_fixture("probe")
                        _, attack, _ = self.metadata_fixture()
                        attack.ib.rows = [bar(datetime(2026, 7, 1, 9, 30, tzinfo=NY))]
                        seen, leaks = {}, []
                        def witness(label):
                            if label in seen:
                                return
                            seen[label] = (bridge.current_worker(), bool(op._OBSERVER.get()))
                            try:
                                minted = self.open("add_stocks")
                            except AuthorityError:
                                pass
                            else:
                                leaks.append((label, "mint"))
                                minted.seal()
                                minted.close()
                            try:
                                stolen = f.run.child("observer-stolen-" + label)
                            except AuthorityError:
                                pass
                            else:
                                leaks.append((label, "child"))
                                stolen.close()
                            before = len(attack.ib.calls)
                            try:
                                result = {"requests": 0, "counters": {
                                    "invalid": 0, "outside_day": 0, "non_rth": 0}}
                                list(ib._fetch_sessions([date(2026, 7, 1)], "1m", attack,
                                    contract(), InstantPacer(), None, lambda _: None,
                                    lambda: None, "TEST", result))
                            except AuthorityError:
                                pass
                            if len(attack.ib.calls) > before:
                                self.assertEqual(len(attack.ib.calls), before + 1)
                                leaks.append((label, "helper-send"))
                        class Root:
                            def __fspath__(value):
                                witness("path")
                                return str(f.bank)
                        class Selection(dict):
                            def get(value, *args):
                                witness("selection")
                                return super().get(*args)
                        class Options:
                            def keys(value):
                                witness("options-keys")
                                return ["executor"]
                            def __getitem__(value, key):
                                witness("options-getitem")
                                return lambda: witness("forbidden-executor")
                        class Coordinator:
                            @property
                            def request_options(value):
                                witness("options-descriptor")
                                def options(task):
                                    witness("options-call")
                                    f.coordinator.request_options(task)
                                    return Options()
                                return options
                            @property
                            def complete_request(value):
                                witness("complete-descriptor")
                                def complete(task, result, **kwargs):
                                    witness("complete-call")
                                    self_task = task[2]
                                    if type(self_task) is not dict or type(self_task["day"]) is not str:
                                        raise AssertionError("request data was not detached")
                                    return f.coordinator.complete_request(task, result, **kwargs)
                                return complete
                        dispatch = mutants.get(removed, tasks._run_addstock_task)
                        dispatch(Root(), Coordinator(),
                            ("probe", "TEST", Selection(day="2026-07-01")), f.adapter,
                            _fetch_child=self.child(f.run, "hostile-observers"))
                        self.assertEqual(set(seen), {"path", "selection", "options-descriptor",
                            "options-call", "options-keys", "options-getitem",
                            "complete-descriptor", "complete-call"})
                        def no_authority():
                            self.assertEqual(leaks, [])
                            self.assertTrue(all(worker is None and observer
                                                for worker, observer in seen.values()))
                            self.assertEqual(attack.ib.calls, [])
                        if removed == "none":
                            no_authority()
                        else:
                            with self.assertRaises(AssertionError):
                                no_authority()
                            affected = ({"path", "selection"} if removed == "task-data"
                                        else {"options-keys", "options-getitem"})
                            self.assertEqual(set(leaks), {(label, action) for label in affected
                                for action in ("mint", "child", "helper-send")})
                            self.assertEqual(len(attack.ib.calls), len(affected))
                            for label, (worker, observer) in seen.items():
                                self.assertEqual(worker is None, label not in affected)
                                self.assertEqual(observer, label not in affected)
                        self.assertEqual(f.coordinator.result()["issue_count"], 0)
                        self.assertEqual(len(f.adapter.ib.calls), 1)
                        self.assertEqual(len(op._CHILDREN), 0)
                        f.run.seal()
                        f.run.close()
                        f.adapter.disconnect()
                        attack.disconnect()
                        self.assertEqual(len(op._OPERATIONS), 0)
                    finally:
                        self.root = outer_root

