    def test_c2_addstock_fixed_missing_child_and_legacy_coordinator(self):
        import addstock_fetch_tasks as tasks
        import live_spot_probe_selftest as legacy
        import contextlib
        import io
        with self.assertRaisesRegex(AuthorityError, "explicit operation child"):
            tasks._run_addstock_task(self.root, None, ("probe", "TEST", {"day": "2026-07-01"}), None)
        self.assertEqual(len(op._CHILDREN), 0)
        run = self.open("add_stocks")
        owned = self.child(run)
        args = (self.root, None, ("probe", "TEST", {"day": "2026-07-01"}), None)
        with self.assertRaises(AuthorityError):
            tasks._run_addstock_task(*args, _fetch_child=object())
        self.assertIn(owned, op._CHILDREN)
        with op.scoped_worker(owned), self.assertRaises(AuthorityError):
            tasks._run_addstock_task(*args, _fetch_child=owned)
        self.assertIn(owned, op._CHILDREN)
        owned.close()
        for payload in ({"day": "bad-date"}, {"day": "20260701"}):
            with self.assertRaisesRegex(AuthorityError, "ISO day"):
                tasks._run_addstock_task(self.root, None, ("probe", "TEST", payload), None,
                    _fetch_child=self.child(run, "invalid-" + str(len(self.children))))
