    def test_d11_held_diagnostic_cli_exit_matrix(self):
        import contextlib
        import importlib
        import io

        cases = (
            ("live_internal_revalidate", "run_internal_revalidate", []),
            ("live_combined_flags", "run_combined_flags", []),
            ("live_internal_daily_check", "run_internal_daily_check", []),
            ("live_kind_smoke", "run_kind_smoke", []),
            ("two_account_pacing_probe", "run_pacing_probe", None),
            ("live_feature_check", "run_feature_check", None),
            ("live_pipeline_check", "run_pipeline_check", None),
            ("live_run_all", "run_all", []),
            ("live_validate_catchup", "run_catchup", []),
        )
        for name, root_name, argv in cases:
            module = importlib.import_module(name)
            invoke = lambda: module.main() if argv is None else module.main(argv)
            for error_type in (AuthorityError, LedgerError, RequestCancelled):
                with self.subTest(module=name, error=error_type.__name__), \
                        patch.object(module, root_name,
                            side_effect=error_type("terminal witness")), \
                        contextlib.redirect_stderr(io.StringIO()) as stderr:
                    self.assertEqual(invoke(), 3)
                    self.assertEqual(stderr.getvalue().strip(),
                        f"DIAGNOSTIC TERMINAL: {error_type.__name__}: terminal witness")
            with self.subTest(module=name, result="pass-through"), \
                    patch.object(module, root_name, return_value={"exit_code": 7}), \
                    contextlib.redirect_stderr(io.StringIO()) as stderr:
                self.assertEqual(invoke(), 7)
                self.assertEqual(stderr.getvalue(), "")
            with self.subTest(module=name, error="unexpected"), \
                    patch.object(module, root_name,
                        side_effect=RuntimeError("unexpected witness")), \
                    self.assertRaisesRegex(RuntimeError, "unexpected witness"):
                invoke()

