    def test_d2_kind_unfiltered_iv_preserves_prefilter_evidence(self):
        import live_kind_smoke as diagnostic
        from fetch_envelopes import parse_envelope, decide, EnvelopeError
        registry, adapter, _hits = self.metadata_fixture()
        adapter.port = 2000
        adapter.use_rth = True
        self.patch(governors, "_REGISTRY", new=registry)
        inside = bar(datetime(2026, 7, 2, 10, tzinfo=NY))
        outside = bar(datetime(2026, 7, 2, 8, tzinfo=NY))
        for label, rows, expected_failed, expected_outside in (
                ("rth", [inside], 0, 0),
                ("outside", [outside, inside], 1, 1),
                ("empty", [], 1, 0)):
            with self.subTest(label=label):
                adapter.ib.rows = rows
                run = self.open("diagnostic", clock=lambda:
                    datetime(2026, 7, 6, 17, tzinfo=NY))
                tally = diagnostic._Tally()
                diagnostic.test_iv_rth_only(SimpleNamespace(fetch=adapter.fetch),
                    contract("TEST", 123), tally,
                    None, _fetch_child=self.child(run, "iv-" + label,
                        rights={diagnostic._IV_RTH}))
                self.assertTrue(adapter.use_rth, "unfiltered request cannot toggle shared adapter")
                sent = [call for call in adapter.ib.calls if call[0] == "bars"][-1]
                self.assertIs(sent[2]["useRTH"], False,
                    "transport must take useRTH from the guarded envelope")
                self.assertEqual(tally.failed, expected_failed)
                events = inspect_ledger(run.context.ledger.path,
                    require_seal=False)["events"]
                decision, = (event["payload"] for event in events
                             if event["event"] == "decision")
                for field in ("requested", "effective"):
                    self.assertEqual(decision[field]["variant"], "ibkr-bars-unfiltered")
                    self.assertEqual(decision[field]["intended_start"],
                        "2026-07-02T09:30:00-04:00")
                    self.assertEqual(decision[field]["intended_end"],
                        "2026-07-02T16:00:00-04:00")
                result, = (event["payload"] for event in events
                           if event["event"] == "result")
                self.assertEqual(result["rows_received"], len(rows))
                self.assertEqual(result["rows_outside_rth"], expected_outside)
                self.assertEqual(result["rows_accepted"], int(bool(rows)))
                self.assertEqual(len(result["first_outside_timestamps"]),
                    expected_outside)
                run.seal()
                run.close()
        envelope = {"variant": "ibkr-bars", "symbol": "TEST", "con_id": 123,
            "token": "1m-iv", "what_to_show": "OPTION_IMPLIED_VOLATILITY",
            "use_rth": False, "bar_size": "1 min",
            "raw_end": "2026-07-02T16:00:00-04:00", "duration": "1 D",
            "intended_start": "2026-07-01T16:00:00-04:00",
            "intended_end": "2026-07-02T16:00:00-04:00"}
        with self.assertRaises(EnvelopeError):
            parse_envelope(envelope)
        with self.assertRaises(EnvelopeError):
            parse_envelope({**envelope, "variant": "ibkr-bars-unfiltered",
                            "use_rth": True})
        valid = {**envelope, "variant": "ibkr-bars-unfiltered",
                 "intended_start": "2026-07-02T09:30:00-04:00"}
        horizon = {"1m-iv": datetime(2026, 7, 2, 16, tzinfo=NY)}
        self.assertEqual(decide(parse_envelope(valid), self.authority,
                                horizon, captured_now=datetime(
                                    2026, 7, 6, 17, tzinfo=NY)).state, "allowed")
        self.assertEqual(decide(parse_envelope({**valid, "duration": "2 D"}),
                                self.authority, horizon, captured_now=datetime(
                                    2026, 7, 6, 17, tzinfo=NY)).state, "allowed")
        future = {**valid, "raw_end": "2026-07-06T16:00:00-04:00",
                  "duration": "5 D"}
        clamped = decide(parse_envelope(future), self.authority, horizon,
                         captured_now=datetime(2026, 7, 6, 12, tzinfo=NY))
        self.assertEqual(clamped.state, "clamped")
        self.assertEqual(clamped.effective.intended_start,
                         datetime(2026, 7, 2, 9, 30, tzinfo=NY))
        self.assertEqual(clamped.effective.intended_end, horizon["1m-iv"])
        self.assertEqual(clamped.effective.raw_end, horizon["1m-iv"])
        self.assertEqual(clamped.effective.variant, "ibkr-bars-unfiltered")
        with self.assertRaisesRegex(EnvelopeError, "raw carrier"):
            parse_envelope({**future, "duration": "1 D"})
        for changed, clock_horizon, now in (
                ({"intended_start": "2026-07-01T16:00:00-04:00"}, horizon,
                 datetime(2026, 7, 6, 17, tzinfo=NY)),
                ({"raw_end": "2026-07-02T15:00:00-04:00",
                  "intended_end": "2026-07-02T15:00:00-04:00"}, horizon,
                 datetime(2026, 7, 6, 17, tzinfo=NY)),
                ({}, {"1m-iv": datetime(2026, 7, 2, 15, tzinfo=NY)},
                 datetime(2026, 7, 6, 17, tzinfo=NY)),
                ({}, horizon, datetime(2026, 7, 2, 17, tzinfo=NY))):
            with self.subTest(changed=changed, horizon=clock_horizon, now=now):
                self.assertEqual(decide(parse_envelope({**valid, **changed}),
                                        self.authority, clock_horizon,
                                        captured_now=now).state, "refused")
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})

