    def test_d2_pacing_root_hold_duplicate_and_covered_calendar(self):
        import two_account_pacing_probe as pacing
        from fetch_ibkr_integration_selftest import ib_contract
        created = self.root_fixture()
        touched = []
        with self.assertRaisesRegex(AuthorityError, "not activated") as held:
            pacing.run_pacing_probe(ports=(2000, 2001),
                adapter_factory=lambda *args: touched.append(args),
                evidence_dir=self.root / "pacing-held")
        self.assertEqual(touched, [])
        self.assertEqual(self.fixture_leases, [])
        self.assertFalse(held.exception.fetch_ledger["verified"])
        self.assertEqual(len(created), 1)
        with patch.dict("sys.modules", {"ib_async": SimpleNamespace(
                Stock=lambda symbol, *a: contract(symbol, 0),
                Contract=ib_contract)}):
            adapters, raws = {}, {}
            for port in (2000, 2001):
                adapter = ib.LiveIB()
                adapter.port = port
                adapter.ib = RawIB()
                adapter.ib.disconnect = lambda: None
                adapter._await = lambda value, timeout, description: value
                adapters[port] = adapter
                raws[port] = adapter.ib
            with self.assertRaisesRegex(AuthorityError, "same account") as duplicate:
                pacing.run_pacing_probe(ports=(2000, 2001),
                    adapter_factory=lambda port, _cid: adapters[port],
                    evidence_dir=self.root / "pacing-duplicate",
                    _test_capability=self.capability)
        self.assertFalse(duplicate.exception.fetch_ledger["verified"])
        self.assertTrue(all(not raw.calls for raw in raws.values()))
        for label, accounts in (("unknown", ["unknown"]),
                                ("ambiguous", ["ACCOUNT-A", "ACCOUNT-B"])):
            with self.subTest(label=label):
                for port, adapter in adapters.items():
                    adapter.ib = raws[port]
                raws[2000].managedAccounts = lambda accounts=accounts: accounts
                with self.assertRaises(AuthorityError) as unresolved:
                    pacing.run_pacing_probe(ports=(2000, 2001),
                        adapter_factory=lambda port, _cid: adapters[port],
                        evidence_dir=self.root / ("pacing-" + label),
                        _test_capability=self.capability)
                self.assertFalse(unresolved.exception.fetch_ledger["verified"])
                self.assertTrue(all(not raw.calls for raw in raws.values()))
        self.assertTrue(all(lease.released for lease in self.fixture_leases))
        context = created[-1]
        ends = pacing.settled_session_ends(context)
        self.assertGreaterEqual(len(ends), 80)
        self.assertEqual(len(ends), len(set(ends)))
        for end in ends:
            window = context.authority.window("1s", end.date())
            self.assertIsNotNone(window)
            self.assertGreaterEqual(end - timedelta(minutes=30), window[0])
            self.assertLessEqual(end, min(window[1], context.horizons["1s"]))
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})

