    def test_d2_runall_parallel_groups_and_isolated_retry_share_parent(self):
        import live_run_all as all_groups
        created = self.root_fixture()
        calls, lock = [], threading.Lock()
        names = ("raw", "store", "update", "span")
        def group(name):
            def run(port, ticker, tally, *args, **kwargs):
                child = kwargs.pop("_fetch_child")
                self.assertEqual(kwargs.get("adapter_factory"), None)
                with op.scoped_worker(child, close=True) as worker:
                    with lock:
                        calls.append((name, port, ticker, worker.context,
                                      worker.worker_id))
                        first_raw = name == "raw" and sum(
                            row[0] == "raw" for row in calls) == 1
                    tally.check(not first_raw, name + " offline group")
            return run
        with patch.object(all_groups.L, "run_raw_group", side_effect=group(names[0])), \
                patch.object(all_groups.L, "test_end_to_end_store",
                             side_effect=group(names[1])), \
                patch.object(all_groups.L, "test_daily_update_twice",
                             side_effect=group(names[2])), \
                patch.object(all_groups.L, "run_span_group", side_effect=group(names[3])):
            result = all_groups.run_all(ports=(2000, 3000), ticker="TEST",
                evidence_dir=self.root / "runall-parallel",
                _test_capability=self.capability)
        self.assertEqual(result["status"], "complete")
        self.assertEqual(result["exit_code"], 0)
        self.assertTrue(result["fetch_ledger"]["verified"])
        self.assertEqual(len(created), 1)
        self.assertEqual(len(calls), 5)
        self.assertEqual(set(row[0] for row in calls), set(names))
        self.assertEqual(len({row[4] for row in calls}), 5)
        self.assertTrue(all(row[3] is created[0] for row in calls))
        self.assertEqual([row[1] for row in calls if row[0] == "raw"], [2000, 2000])
        self.assertTrue(result["results"][all_groups.GROUPS[0]]["iso"])
        self.assertEqual(len(self.fixture_leases), 1)
        self.assertTrue(all(lease.released for lease in self.fixture_leases))
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})

