    def test_d2_runall_cross_thread_terminal_stops_remaining_group(self):
        import live_run_all as all_groups
        self.root_fixture()
        rendezvous = threading.Barrier(2, timeout=5)
        after_terminal = threading.Event()
        later = []
        def terminal(port, ticker, tally, *args, **kwargs):
            with op.scoped_worker(kwargs.pop("_fetch_child"), close=True):
                rendezvous.wait()
                raise RequestRefused("cross-thread run-all stop")
        def alongside(port, ticker, tally, *args, **kwargs):
            with op.scoped_worker(kwargs.pop("_fetch_child"), close=True):
                rendezvous.wait()
                if kwargs["cancel"].is_set() or after_terminal.wait(2):
                    return
        def never(*args, **kwargs):
            later.append(True)
            with op.scoped_worker(kwargs.pop("_fetch_child"), close=True):
                pass
        with patch.object(all_groups.L, "run_raw_group", side_effect=terminal), \
                patch.object(all_groups.L, "test_end_to_end_store", side_effect=alongside), \
                patch.object(all_groups.L, "test_daily_update_twice", side_effect=never), \
                patch.object(all_groups.L, "run_span_group", side_effect=never), \
                self.assertRaisesRegex(RequestRefused,
                    "cross-thread run-all stop") as refused:
            all_groups.run_all(ports=(2000, 3000), ticker="TEST",
                evidence_dir=self.root / "runall-cross-stop",
                _test_capability=self.capability)
        self.assertEqual(later, [])
        self.assertEqual(refused.exception.fetch_ledger["state"], "UNVERIFIED")
        self.assertEqual(len(self.fixture_leases), 1)
        self.assertTrue(self.fixture_leases[0].released)
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})

