    def test_d2_pacing_two_accounts_governed_and_inconclusive(self):
        import two_account_pacing_probe as pacing
        from fetch_ibkr_integration_selftest import ib_contract
        created = self.root_fixture()
        virtual = [0.0]
        registry = governors.GovernorRegistry(time_fn=lambda: virtual[0],
            sleep_fn=lambda seconds, cancel=None: virtual.__setitem__(0, virtual[0] + seconds))
        self.patch(governors, "_REGISTRY", new=registry)
        self.patch(pacing, "MAX_FIRE", new=2)
        adapters, raws, observers = {}, {}, []
        for port, account in ((2000, "ACCOUNT-A"), (2001, "ACCOUNT-B")):
            adapter = ib.LiveIB()
            adapter.port = port
            adapter.ib = RawIB([bar(datetime(2026, 8, 4, 15, 59, 59, tzinfo=NY))])
            adapter.ib.managedAccounts = lambda account=account: [account]
            adapter.ib.disconnect = lambda: None
            adapter._await = lambda value, timeout, description: value
            adapters[port] = adapter
            raws[port] = adapter.ib
        def factory(port, _cid):
            observers.append((bridge.current_worker(), op._OBSERVER.get()))
            return adapters[port]
        with patch.dict("sys.modules", {"ib_async": SimpleNamespace(
                Stock=lambda symbol, *a: contract(symbol, 0),
                Contract=ib_contract)}):
            result = pacing.run_pacing_probe(ports=(2000, 2001),
                adapter_factory=factory, evidence_dir=self.root / "pacing-two",
                _test_capability=self.capability)
        self.assertEqual(result["status"], "inconclusive")
        self.assertIn("cannot prove", result["reason"])
        self.assertEqual({result["accounts"][key]["account"] for key in ("A", "B")},
                         {"ACCOUNT-A", "ACCOUNT-B"})
        self.assertEqual([result["accounts"][key]["fired"] for key in ("A", "B")], [2, 2])
        self.assertTrue(result["fetch_ledger"]["verified"])
        saved = json.loads(Path(result["fetch_ledger"]["report_path"]).read_text(
            encoding="utf-8"))
        self.assertEqual(saved["pacing"]["accounts"], result["accounts"])
        self.assertEqual(saved["pacing"]["status"], "inconclusive")
        files = [path for path in (self.root / "pacing-two").rglob("*") if path.is_file()]
        self.assertEqual(len(files), 3)
        self.assertTrue({Path(result["fetch_ledger"]["path"]).name,
                         Path(result["fetch_ledger"]["report_path"]).name}.issubset(
                             {path.name for path in files}))
        self.assertEqual(sum(path.name.endswith(".seal.json") for path in files), 1,
            "D09 must produce ledger, seal and report only, never a bank store")
        self.assertEqual(len(created), 1)
        context = created[0]
        self.assertEqual(set(context._account_bindings.values()),
                         {("ibkr", "ACCOUNT-A"), ("ibkr", "ACCOUNT-B")})
        for raw in raws.values():
            bars = [call for call in raw.calls if call[0] == "bars"]
            self.assertEqual(len(bars), 2)
            for _kind, _con_id, kwargs in bars:
                self.assertEqual((kwargs["barSizeSetting"], kwargs["durationStr"],
                                  kwargs["whatToShow"], kwargs["useRTH"]),
                                 ("1 secs", "1800 S", "TRADES", True))
        events = inspect_ledger(context.ledger.path)["events"]
        decisions = [event for event in events if event["event"] == "decision"]
        self.assertEqual(len(decisions), 6)  # two qualifications, four bars
        self.assertEqual(sum(row["producer_id"] == pacing._HAMMER for row in decisions), 4)
        self.assertTrue(all(worker is None and observed for worker, observed in observers))
        first_elapsed = virtual[0]
        self.assertGreaterEqual(first_elapsed, .15,
            "D09 physical sends must honor the canonical governor floor")
        for port, adapter in adapters.items():
            adapter.ib = raws[port]
        # A caller-supplied no-op turn cannot bypass the real account governor,
        # and the next parent inherits its process-lifetime budgets.
        with patch.dict("sys.modules", {"ib_async": SimpleNamespace(
                Stock=lambda symbol, *a: contract(symbol, 0),
                Contract=ib_contract)}), patch.object(bridge, "acquire_turn", return_value=0):
            again = pacing.run_pacing_probe(ports=(2000, 2001),
                adapter_factory=factory, evidence_dir=self.root / "pacing-repeat",
                _test_capability=self.capability)
        self.assertEqual(again["status"], "inconclusive")
        self.assertGreater(virtual[0], first_elapsed)
        self.assertEqual(len(created), 2)
        self.assertIs(created[0].governors, created[1].governors)
        self.assertTrue(all(lease.released for lease in self.fixture_leases))
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})

