    def test_d2_pacing_exact_token_shape_and_child_only(self):
        import two_account_pacing_probe as pacing
        from fetch_envelopes import parse_envelope
        with self.assertRaisesRegex(AuthorityError, "explicit operation child"):
            pacing.hammer("A", None, "TEST", [])
        run = self.open("diagnostic")
        child = self.child(run, "pacing-token", rights={pacing._HAMMER})
        base = {"variant": "ibkr-bars", "symbol": "TEST", "con_id": 123,
            "token": "1s", "what_to_show": "TRADES", "use_rth": True,
            "bar_size": "1 secs", "raw_end": "2026-08-03T16:00:00-04:00",
            "duration": "1800 S", "intended_start": "2026-08-03T15:30:00-04:00",
            "intended_end": "2026-08-03T16:00:00-04:00"}
        with op.scoped_worker(child, close=True):
            self.assertTrue(run.context.permits(pacing._HAMMER, parse_envelope(base)))
            for changed in ({"token": "5s", "bar_size": "5 secs"},
                            {"duration": "900 S",
                             "intended_start": "2026-08-03T15:45:00-04:00"},
                            {"token": "1m", "bar_size": "1 min"}):
                with self.subTest(changed=changed):
                    self.assertFalse(run.context.permits(
                        pacing._HAMMER, parse_envelope({**base, **changed})))
        other = "ibkr.stock_ibkr.span_probe"
        with op.scoped_worker(self.child(run, "pacing-other",
                                   rights={other}), close=True):
            for token, size in (("1s", "1 secs"), ("5s", "5 secs"),
                                ("10s", "10 secs"), ("30s", "30 secs")):
                self.assertTrue(run.context.permits(other,
                    parse_envelope({**base, "token": token, "bar_size": size})),
                    "approved pre-D09 all-token diagnostic paths remain unchanged")
        run.close()
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})

