    def test_d2_kind_disconnect_descriptor_and_formatter_are_observers(self):
        import contextlib
        import io
        import live_kind_smoke as diagnostic
        run = self.open("diagnostic")
        seen = []
        case = self
        class TerminalAdapter:
            def qualify(self, _ticker):
                raise ib.RequestRefused("primary kind stop")
            @property
            def disconnect(self):
                seen.append(("descriptor", bridge.current_worker()))
                with case.assertRaises(AuthorityError):
                    case.open("diagnostic")
                def cleanup():
                    raise ib.RequestRefused("cleanup kind stop")
                return cleanup
        with contextlib.redirect_stdout(io.StringIO()), \
                self.assertRaisesRegex(ib.RequestRefused, "primary kind stop") as caught:
            diagnostic.run_raw_group(2000, "TEST", diagnostic._Tally(),
                adapter_factory=TerminalAdapter,
                _fetch_child=self.child(run, "kind-hostile-disconnect",
                    rights=diagnostic._RAW_RIGHTS))
        self.assertEqual(seen, [("descriptor", None)])
        self.assertIsInstance(caught.exception.__cause__, ib.RequestRefused)
        self.assertIn("cleanup kind stop", str(caught.exception.__cause__))

        class HostileError(Exception):
            def __str__(self):
                seen.append(("formatter", bridge.current_worker()))
                with case.assertRaises(AuthorityError):
                    case.open("diagnostic")
                return "ordinary cleanup noise"
        class OrdinaryAdapter:
            @property
            def disconnect(self):
                seen.append(("ordinary descriptor", bridge.current_worker()))
                def cleanup():
                    raise HostileError()
                return cleanup
        with op.scoped_worker(self.child(run, "kind-hostile-formatter"), close=True), \
                contextlib.redirect_stdout(io.StringIO()):
            diagnostic._disconnect_observer(OrdinaryAdapter())
        self.assertEqual(seen[1:], [("ordinary descriptor", None),
                                     ("formatter", None)])
        run.close()
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})

