    def test_d2_kind_full_root_fake_transport_and_temporary_store(self):
        import contextlib
        import io
        import live_kind_smoke as diagnostic
        self.internal_fixture()
        registry, _unused, _hits = self.metadata_fixture()
        self.patch(governors, "_REGISTRY", new=registry)
        daily_rows = []
        minute_rows = []
        for offset in range(22):
            day = date(2026, 7, 2) - timedelta(days=offset)
            if self.authority.window("1m-iv", day) is None:
                continue
            daily_rows.append(SimpleNamespace(date=day, open=.2, high=.3,
                low=.1, close=.25, volume=-1))
            minute_rows.append(SimpleNamespace(
                date=datetime.combine(day, time(10), tzinfo=NY),
                open=.2, high=.3, low=.1, close=.25, volume=-1))
        adapters = []
        factory_observations = []
        def factory():
            factory_observations.append(bridge.current_worker())
            with self.assertRaises(AuthorityError):
                self.open("diagnostic")
            adapter = ib.LiveIB()
            adapter.ib = RawIB()
            adapter.ib.head = datetime(2026, 6, 1, 9, 30, tzinfo=NY)
            adapter._await = lambda value, _timeout, _description: value
            adapter.port = 2000
            def bars(_contract, **kwargs):
                adapter.ib.calls.append(("bars", kwargs))
                return daily_rows if kwargs["barSizeSetting"] == "1 day" else minute_rows
            adapter.ib.reqHistoricalDataAsync = bars
            adapter.ib.disconnect = lambda: None
            adapters.append(adapter)
            return adapter
        output = io.StringIO()
        with contextlib.redirect_stdout(output):
            result = diagnostic.run_kind_smoke(port=2000, ticker="TEST",
                adapter_factory=factory, evidence_dir=self.root / "kind-evidence",
                _test_capability=self.capability)
