        self.assertEqual(result["failed"], 0, output.getvalue())
        self.assertTrue(result["fetch_ledger"]["verified"])
        events = inspect_ledger(result["fetch_ledger"]["path"])["events"]
        decisions = [event for event in events if event["event"] == "decision"]
        self.assertTrue({diagnostic._IV_DAILY, diagnostic._IV_INTRADAY,
            diagnostic._HVOL_DAILY, diagnostic._HVOL_INTRADAY,
            diagnostic._IV_RTH, diagnostic._SPAN}.issubset(
                {event["producer_id"] for event in decisions}))
        update_workers = {event["worker_id"] for event in decisions
                          if "kind-update-" in event["worker_id"]}
        self.assertEqual(len(update_workers), 2)
        self.assertGreaterEqual(len(adapters), 4)
        self.assertEqual(factory_observations, [None] * len(adapters))
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})
        self.assertTrue(all(lease.released for lease in self.fixture_leases))

