    def test_d2_combined_send_sites_exact_and_drift_inverses(self):
        import fetch_send_inventory as sends
        from collections import Counter
        expected = Counter({
            ("ibkr.live_combined_flags.daily_refetch",
             "engine.live_combined_flags:_fetch_month_1d:adapter_fetch:1",
             "_fetch_month_1d", "a2_refused", "ibkr-bars"): 1,
            ("ibkr.live_combined_flags.minute_month",
             "engine.live_combined_flags:_fetch_month_1m:adapter_fetch:1",
             "_fetch_month_1m", "a2_refused", "ibkr-bars"): 1,
        })
        rows = [row for row in sends.build_inventory()["sites"]
                if row["producer_id"].startswith("ibkr.live_combined_flags.")]
        def observed(entries):
            return Counter((row["producer_id"], row["site_key"],
                            row["qualname"], row["disposition"], row["transport"])
                           for row in entries)
        self.assertEqual(observed(rows), expected)
        for changed in (rows[:-1], rows + rows[:1],
                        [{**rows[0], "producer_id": rows[1]["producer_id"]}, rows[1]],
                        [{**rows[0], "disposition": "a1_context_required"}, rows[1]]):
            with self.assertRaises(AssertionError):
                self.assertEqual(observed(changed), expected)

