    def a41_barrier(self, admit=True, capability=False, engine_tasks=True):
        from contextlib import ExitStack
        import fix_data_pipeline as repair
        c = self
        created = c.root_fixture()
        effects = []
        def forbidden(label):
            def effect(*args, **kwargs):
                effects.append(label)
                raise AssertionError('effect before admission: '+label)
            return effect
        kwargs = self.a41_kwargs(c.root/'never-bank', forbidden('opener'))
        kwargs.update(adapter_factory=forbidden('adapter'), scan_fn=forbidden('scan'),
                      series_fn=forbidden('series'), refresh_fn=forbidden('refresh'),
                      engine_tasks=engine_tasks)
        if capability:
            kwargs['_test_capability'] = c.capability
        with ExitStack() as stack:
            stack.enter_context(patch.object(repair, 'Path', side_effect=forbidden('root')))
            stack.enter_context(patch.object(repair.operation_gate, 'acquire', side_effect=forbidden('lease')))
            stack.enter_context(patch.object(repair, '_run_fix_data_body', side_effect=forbidden('body')))
            if admit:
                stack.enter_context(patch.object(op, 'require_root_admission', return_value=None))
            expected = RequestRefused if admit else AuthorityError
            with self.assertRaises(expected) as caught:
                repair.run(**kwargs)
        self.assertIs(type(caught.exception), expected)
        message = ('raw reference transport requires fixed engine tasks' if capability else
                   'injected repair reference transport is offline-only')
        if admit:
            self.assertEqual(str(caught.exception), message)
        else:
            self.assertIn('not activated', str(caught.exception))
        self.assertEqual(effects, [])
        self.assertEqual(c.fixture_leases, [])
        self.assertEqual(len(created), 1)
        self.assertIs(created[0].test_capability, c.capability if capability else None)
        self.assertFalse(caught.exception.fetch_ledger['verified'])
        evidence = caught.exception.fetch_ledger
        report = Path(evidence['report_path']).resolve()
        self.assertTrue(report.is_relative_to(c.root))
        durable = json.loads(report.read_text(encoding='utf-8'))
        self.assertEqual(durable['operation_id'], evidence['operation_id'])
        self.assertFalse(durable['verified'])
        self.assertEqual(durable['state'], 'UNVERIFIED')
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})

    def a41_run_repair(self):
        import platform
        import fix_data_pipeline as repair
        c = self
        combined, bank, adapter, opener, calls, contexts, children = c.a23_embedded_fixture()
        adapter.port = 2000
        c.patch(platform, 'machine', return_value='offline')
        c.patch(repair.run_log_retention, 'prune_run_logs', return_value={})
        kwargs = self.a41_kwargs(bank, opener)
        credits = []
        kwargs.update(adapter_factory=lambda _: adapter, series_fn=lambda _: [('TEST','1m')],
                      verification_fn=lambda *args: credits.append(args),
                      progress=lambda _: None, _test_capability=c.capability)
        reached = set(); old_main = sys.getprofile(); old_thread = threading.getprofile()
        def profile(frame, event, arg):
            if event == 'call' and Path(frame.f_code.co_filename).stem in {
                    'fix_data_pipeline','live_combined_flags','stock_validate','fetch_http_labels'}:
                reached.add((Path(frame.f_code.co_filename).stem, frame.f_code.co_qualname))
        try:
            sys.setprofile(profile); threading.setprofile(profile)
            result = repair.run(**kwargs)
        finally:
            sys.setprofile(old_main); threading.setprofile(old_thread)
        self.assertIsNone(result['error'], result)
        self.assertEqual(result['checked'], 1, result)
        self.assertEqual(len(contexts), 1)
        self.assertEqual(contexts[0].captured_now, c.fixture_now)
        rows = c.rows_from_context_path(result['fetch_ledger']['path'])
        http = [r for r in rows if r.get('producer_id') == 'http.stockanalysis.validation']
        self.assertEqual(result['unprocessed'], [], result)
        self.assertEqual(credits, [('xval','TEST','1m')])
        self.assertEqual(len(calls), 1)
        self.assertNotEqual(calls[0][1], threading.get_ident())
        self.assertEqual([r['event'] for r in http], ['decision','result'])
        self.assertEqual({r['operation_id'] for r in http}, {contexts[0].operation_id})
        self.assertTrue(result['fetch_ledger']['verified'])
        self.assertEqual([r for name,r,_ in children if 'http-reference' in name],
                         [frozenset({'http.stockanalysis.validation'})])
        expected = {('fix_data_pipeline', name) for name in (
            'run','_run_fix_data_body','_run_fix_data_body.<locals>.run_scheduler',
            '_run_fix_data_body.<locals>.run_scheduler.<locals>.worker','_fixed_audit')}
        expected |= {('live_combined_flags','_audit_ticker'),
                     ('stock_validate','fetch_daily_reference'),
                     ('fetch_http_labels','guarded_stockanalysis_attempt')}
        self.assertTrue(expected <= reached, expected - reached)
        self.assertEqual(sv._REF_CACHE, {})
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})
        self.assertTrue(all(lease.released for lease in c.fixture_leases))
        print('A41_SHIPPED_REPAIR', 'HTTP-positive',
              'offline source acceptance; live remains held')


