    def a41_fill_no_http(self, *, pin_rights=False):
        self.root_fixture()
        observed, calls = [], []
        original = ib._fill_missing_days_body
        @bridge.worker_scope
        def observed_body(*args, **kwargs):
            worker = bridge.current_worker()
            if pin_rights:
                expected = frozenset({
                    "ibkr.gap_fill.month_daily", "ibkr.gap_fill.month_intraday",
                    "ibkr.gap_fill.session_fetch", "ibkr.gap_fill.head_daily_probe",
                    "ibkr.gap_fill.head_timestamp", "ibkr.earliest_available.head_timestamp",
                    "ibkr.choke.qualify", "ibkr.choke.qualify_many",
                    "ibkr.vol_value_bank.ratio_day", "ibkr.live_spot_probe.daily",
                    "ibkr.live_spot_probe.minute", "ibkr.live_combined_flags.minute_month",
                    "ibkr.live_combined_flags.daily_refetch",
                })
                with op._LOCK:
                    _run, child_state = op._active_child(worker.context, worker.worker_id)
                    actual = child_state.rights
                self.assertEqual(actual, expected, "standalone repair child rights drift")
            # Real guarded HTTP admission must refuse before receiver/decision,
            # even though the operation's repair purpose now has this right.
            with self.assertRaisesRegex(AuthorityError,
                    "^producer is outside this operation purpose or child rights$"):
                sv.fetch_daily_reference("TEST", _fetch_worker=worker,
                    _opener=lambda *_: (calls.append("HTTP") or b'{"data":[]}'))
            observed.append(worker.context.operation_id)
            child = op.narrow_worker_child(worker, "targeted-original",
                rights=op._SHARED)
            return original(*args, **kwargs, _fetch_child=child)
        with patch.object(ib, "_fill_missing_days_body", new=observed_body):
            result = ib.fill_missing_days(None, self.root/"empty-bank", "TEST",
                "1d", [], evidence_dir=self.root/"evidence",
                _test_capability=self.capability)
        self.assertEqual(len(observed), 1)
        self.assertEqual(calls, [])
        self.assertTrue(result["fetch_ledger"]["verified"])
        rows = self.rows_from_context_path(result["fetch_ledger"]["path"])
        self.assertFalse(any(row.get("producer_id", "").startswith("http.") for row in rows))
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})

