    def a23_embedded_fixture(self):
        combined, bank, adapter, transport, reference = self.combined_fixture()
        sv.clear_reference_cache()
        self.addCleanup(sv.clear_reference_cache)
        raw = json.dumps({"data": [dict(t=day, **dict(zip(
            ("o", "h", "l", "c", "v"), values)))
            for day, values in reference.items()]}).encode()
        calls, contexts, children = [], [], []
        original_create, original_child = FetchRunContext.create, op.narrow_worker_child
        def create(*args, **kwargs):
            context = original_create(*args, **kwargs)
            contexts.append(context)
            return context
        def narrow(worker, name, **kwargs):
            child = original_child(worker, name, **kwargs)
            children.append((name, frozenset(kwargs.get("rights", ())), child))
            return child
        self.patch(FetchRunContext, "create", side_effect=create)
        self.patch(op, "narrow_worker_child", side_effect=narrow)
        def opener(url):
            self.assertIsNone(bridge.current_worker(), "raw receiver borrowed worker")
            with self.assertRaises(AuthorityError):
                self.open("diagnostic")
            calls.append((url, threading.get_ident()))
            return raw
        return combined, bank, adapter, opener, calls, contexts, children

    def a23_run_embedded(self, kind, bank, adapter, opener, **kwargs):
        import live_combined_flags as combined
        import live_validate_catchup as catchup
        root = combined.run_combined_flags if kind == "combined" else catchup.run_catchup
        if kind == "catchup":
            kwargs.setdefault("all_tickers", True)
        return root(bank, ports=[2000], adapter_factory=lambda _: adapter,
            progress=lambda _: None, _reference_opener=opener,
            _test_capability=self.capability, **kwargs)

    def a23_assert_embedded(self, kind):
        combined, bank, adapter, opener, calls, contexts, children = self.a23_embedded_fixture()
        main_thread = threading.get_ident()
        reached = set()
        module = "live_combined_flags" if kind == "combined" else "live_validate_catchup"
        def profile(frame, event, arg):
            if event == "call" and Path(frame.f_code.co_filename).stem in {
                    module, "live_combined_flags", "stock_validate", "fetch_http_labels"}:
                reached.add((Path(frame.f_code.co_filename).stem, frame.f_code.co_qualname))
        old_main, old_thread = sys.getprofile(), threading.getprofile()
        sys.setprofile(profile)
        threading.setprofile(profile)
        try:
            result = self.a23_run_embedded(kind, bank, adapter, opener)
        finally:
            sys.setprofile(old_main)
            threading.setprofile(old_thread)
        self.assertEqual(result["status"], "complete", result)
        self.assertTrue(result["fetch_ledger"]["verified"], result)
        self.assertEqual(len(contexts), 1)
        self.assertEqual(contexts[0].captured_now, self.fixture_now)
        self.assertEqual(len(calls), 1, "guarded HTTP path was not reached exactly once")
        self.assertNotEqual(calls[0][1], main_thread)
        self.assertEqual(calls[0][0],
            "https://stockanalysis.com/api/symbol/s/TEST/history?range=Max&period=Daily")
        events = self.rows_from_context_path(result["fetch_ledger"]["path"])
        http = [row for row in events if row.get("producer_id") == combined._HTTP]
        self.assertEqual([row["event"] for row in http], ["decision", "result"])
        self.assertEqual(http[0]["operation_id"], contexts[0].operation_id)
        self.assertEqual(http[0]["payload"]["captured_now"], self.fixture_now.isoformat())
        self.assertEqual(http[0]["payload"]["requested"]["endpoint"], "stockanalysis.history")
        self.assertEqual(http[1]["payload"]["accepted"]["count"], 1)
        http_children = [rights for name, rights, _child in children if "http-reference" in name]
        self.assertEqual(http_children, [frozenset({combined._HTTP})])
        expected = {(module, "run_combined_flags" if kind == "combined" else "run_catchup"),
            (module, "_combined_body" if kind == "combined" else "_catchup_body"),
            (module, "_combined_body.<locals>.worker" if kind == "combined" else "_catchup_body.<locals>.worker"),
            (module, "_combined_port" if kind == "combined" else "_catchup_port"),
            ("live_combined_flags", "_audit_ticker"),
            ("live_combined_flags", "_audit_ticker.<locals>._external"),
            ("stock_validate", "fetch_daily_reference"),
            ("fetch_http_labels", "guarded_stockanalysis_attempt")}
        if kind == "catchup":
            expected.add((module, "_catchup"))
        self.assertTrue(expected <= reached, ("missing runtime edges", expected - reached))
        self.assertEqual(sv._REF_CACHE, {}, "embedded path published a pre-seal cache")
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})
        self.assertTrue(all(lease.released for lease in self.fixture_leases))
        print("A23_EMBEDDED_REACHED", kind, "thread->port->audit->http-child->guarded-attempt")

