    def test_a23_embedded_cancel_during_http_turn_is_terminal(self):
        combined, bank, adapter, opener, calls, contexts, _ = self.a23_embedded_fixture()
        cancelled = threading.Event()
        original = governors.Governor.wait_turn
        def turn(governor, cancel=None, **kwargs):
            if governor.identity[0] == "http":
                self.assertIsNotNone(cancel, "HTTP cancellation was not forwarded")
                cancelled.set()
            return original(governor, cancel, **kwargs)
        with patch.object(governors.Governor, "wait_turn", turn), self.assertRaises(RequestCancelled):
            self.a23_run_embedded("catchup", bank, adapter, opener, cancel=cancelled)
