    def test_a23_embedded_decision_and_result_faults_do_not_publish(self):
        combined, bank, adapter, opener, calls, contexts, _ = self.a23_embedded_fixture()
        transport = adapter.ib
        original = combined.sv.fetch_daily_reference
        for event in ("decision", "result"):
            def armed(*args, **kwargs):
                worker = kwargs["_fetch_worker"]
                def fault(kind, stage):
                    if (kind, stage) == (event, "fsync"):
                        raise OSError("HTTP durability witness")
                worker.context.ledger._fault = fault
                return original(*args, **kwargs)
            adapter.ib = transport
            calls.clear()
            with self.subTest(event=event), patch.object(combined.sv,
                    "fetch_daily_reference", side_effect=armed), self.assertRaises(LedgerError):
                self.a23_run_embedded("combined", bank, adapter, opener)
            self.assertEqual(len(calls), 0 if event == "decision" else 1)
            self.assertFalse((bank / "_combined_flags.json").exists())
            self.assertEqual(sv._REF_CACHE, {})
            self.assertEqual(op._CHILDREN, {})

