    def test_a23_embedded_forwarding_and_rights_inverses_are_red(self):
        import live_combined_flags as combined
        import live_validate_catchup as catchup
        import urllib.request
        for module, name, old, new in (
                (combined, "_combined_body", "_reference_opener=_reference_opener,",
                 "_reference_opener=None,"),
                (combined, "_combined_port", "_reference_opener=_reference_opener,",
                 "_reference_opener=None,"),
                (catchup, "_catchup_body", "_reference_opener=_reference_opener,",
                 "_reference_opener=None,"),
                (catchup, "_catchup_port", "_reference_opener=_reference_opener,",
                 "_reference_opener=None,"),
                (catchup, "_catchup", "_reference_opener=_reference_opener,",
                 "_reference_opener=None,")):
            source = inspect.getsource(getattr(module, name))
            self.assertEqual(source.count(old), 1)
            namespace = dict(vars(module))
            exec(compile(source.replace(old, new, 1), module.__file__, "exec"), namespace)
            mutant = namespace[name]
            with (self.subTest(pin=name), patch.object(module, name, mutant),
                  patch.object(urllib.request.OpenerDirector, 'open',
                    side_effect=AuthorityError('forwarding inverse reached default receiver')) as opened):
                with self.assertRaisesRegex(AuthorityError, '^forwarding inverse reached default receiver$'):
                    self.a23_assert_embedded("combined" if module is combined else "catchup")
                opened.assert_called_once()
            print("A23_EMBEDDED_INVERSE_RED", name)
        rights = dict(op.PURPOSE_PRODUCERS)
        rights["diagnostic"] = rights["diagnostic"] - {combined._HTTP}
        with patch.object(op, "PURPOSE_PRODUCERS", rights), self.assertRaisesRegex(
                AuthorityError, "rights"):
            self.a23_assert_embedded("combined")
        print("A23_EMBEDDED_INVERSE_RED", "diagnostic-http-right")

