    def a23_month_reference_fixture(self, bank, transport):
        days = [date(2026, 6, number) for number in range(1, 31)
                if self.authority.window("1m", date(2026, 6, number)) is not None]
        anomaly = days[len(days) // 2]
        minute_rows = [(datetime.combine(day, time(9, 30)), 10, 11, 9, 10, 100)
                       for day in days]
        stored_daily = [(datetime.combine(day, time()), 10,
                         21 if day == anomaly else 11, 9,
                         20 if day == anomaly else 10, 100) for day in days]
        manifest = ib.ss.load_manifest(bank / "TEST")
        for token, rows in (("1m", minute_rows), ("1d", stored_daily)):
            path = ib.ss.month_file_path(bank, "TEST", 2026, 6, token)
            ib.ss.manifest_months(manifest, token)["2026-06"] = dict(
                ib.ss.write_month_file(path, rows), status="present")
        ib.ss.save_manifest(bank / "TEST", manifest)
        derived = sv.derive_daily(sv.read_series(bank, "TEST", "1m"))
        clean = {day.isoformat(): values for day, values in derived.items()}
        initial = dict(clean)
        initial[anomaly.isoformat()] = (10, 21, 9, 20, 100)
        raw_minute = [bar(stamp.replace(tzinfo=NY)) for stamp, *_ in minute_rows]
        raw_daily = [SimpleNamespace(date=day, open=10, high=11, low=9,
                                     close=10, volume=100) for day in days]
        def ib_request(contract, **kwargs):
            return raw_minute if kwargs["barSizeSetting"] == "1 min" else raw_daily
        self.patch(transport, "reqHistoricalDataAsync", side_effect=ib_request)
        return anomaly, initial, clean

    def a42_multi_month_fixture(self, bank, transport, months):
        """Two anomalies per selected month; full settled fixture months only."""
        import calendar
        anomalies, minute_rows, raw_daily = [], [], []
        manifest = ib.ss.load_manifest(bank / "TEST")
        for month in months:
            days = [date(2026, month, number)
                    for number in range(1, calendar.monthrange(2026, month)[1] + 1)
                    if self.authority.window("1m", date(2026, month, number)) is not None]
            bad = {days[len(days) // 3], days[2 * len(days) // 3]}
            anomalies.extend(sorted(bad))
            minutes = [(datetime.combine(day, time(9, 30)), 10, 11, 9, 10, 100)
                       for day in days]
            daily = [(datetime.combine(day, time()), 10, 21 if day in bad else 11,
                      9, 20 if day in bad else 10, 100) for day in days]
            for token, rows in (("1m", minutes), ("1d", daily)):
                path = ib.ss.month_file_path(bank, "TEST", 2026, month, token)
                ib.ss.manifest_months(manifest, token)[f"2026-{month:02d}"] = dict(
                    ib.ss.write_month_file(path, rows), status="present")
            minute_rows.extend(minutes)
            raw_daily.extend(SimpleNamespace(date=day, open=10, high=11, low=9,
                                             close=10, volume=100) for day in days)
        ib.ss.save_manifest(bank / "TEST", manifest)
        derived = sv.derive_daily(sv.read_series(bank, "TEST", "1m"))
        clean = {day.isoformat(): values for day, values in derived.items()}
        initial = dict(clean)
        for day in anomalies:
            initial[day.isoformat()] = (10, 21, 9, 20, 100)
        raw_minute = [bar(stamp.replace(tzinfo=NY)) for stamp, *_ in minute_rows]
        # A broad raw response deliberately includes the neighboring month;
        # the shipped request/response guard and month filter must separate it.
        self.patch(transport, "reqHistoricalDataAsync", side_effect=lambda contract, **kw:
                   raw_minute if kw["barSizeSetting"] == "1 min" else raw_daily)
        return anomalies, initial, clean

    def a42_month_refetch_route(self, kind, *, months=None, use_default=False):
        combined, bank, adapter, transport, _ = self.combined_fixture()
        sv.clear_reference_cache()
        self.addCleanup(sv.clear_reference_cache)
        if months is None:
            anomaly, initial, clean = self.a23_month_reference_fixture(bank, transport)
            anomalies, month_count = [anomaly], 1
        else:
            anomalies, initial, clean = self.a42_multi_month_fixture(bank, transport, months)
            month_count = len(set(months))
        expected_http = 1 + month_count
        calls = []
        def opener(url):
            if not use_default:
                self.assertIsNone(bridge.current_worker())
            calls.append(url)
            values = initial if len(calls) == 1 else clean
            return json.dumps({"data": [dict(t=day, **dict(zip(
                ("o", "h", "l", "c", "v"), row))) for day, row in values.items()]}).encode()
        responses = []
        if use_default:
            import urllib.request
            def physical_open(_opener, wire, *, timeout):
                self.assertEqual(inspect.currentframe().f_back.f_code.co_qualname,
                                 "guarded_stockanalysis_attempt.<locals>.one_send")
                self.assertEqual(wire.get_method(), "GET")
                self.assertGreater(timeout, 0)
                self.assertLessEqual(timeout, 20)
                response = io.BytesIO(opener(wire.full_url))
                responses.append(response)
                return response
            self.enterContext(patch.object(urllib.request.OpenerDirector, "open", physical_open))
        contexts, children = [], []
        original_create, original_child = FetchRunContext.create, op.narrow_worker_child
        def create(*args, **kwargs):
            context = original_create(*args, **kwargs)
            contexts.append(context)
            return context
        def narrow(worker, name, **kwargs):
            child = original_child(worker, name, **kwargs)
            children.append((name, frozenset(kwargs.get("rights", ())), child))
            return child
        self.patch(FetchRunContext, "create", side_effect=create)
        self.patch(op, "narrow_worker_child", side_effect=narrow)
        if kind == "repair":
            import platform
            import fix_data_pipeline as repair
            adapter.port = 2000
            self.patch(platform, "machine", return_value="offline")
            self.patch(repair.run_log_retention, "prune_run_logs", return_value={})
            kwargs = self.a41_kwargs(bank, None if use_default else opener)
            credits = []
            kwargs.update(adapter_factory=lambda _: adapter,
                          series_fn=lambda _: [("TEST", "1m")],
                          verification_fn=lambda *args: credits.append(args),
                          progress=lambda _: None, _test_capability=self.capability)
            result = repair.run(**kwargs)
            self.assertIsNone(result["error"], result)
            self.assertEqual(result["checked"], 1)
            self.assertEqual(result["unprocessed"], [], result)
            self.assertEqual(credits, [("xval", "TEST", "1m")])
        else:
            self.assertIn(kind, {"combined", "catchup"})
            result = self.a23_run_embedded(kind, bank, adapter, None if use_default else opener)
            if kind == "catchup":
                # The deliberate stored-daily anomaly also makes the earlier
                # internal comparison disagree. Fresh combined refetch evidence
                # does not rewrite that stored file or erase the partial result.
                self.assertEqual(result["status"], "partial", result)
                self.assertEqual(result["results"], [{"ticker": "TEST", "store1d": "had",
                                                     "internal": "disagree", "combined": "ok"}])
                self.assertEqual(result["fetch_ledger"]["outcome"], "partial")
            else:
                self.assertEqual(result["status"], "complete", result)
        self.assertEqual(len(calls), expected_http, "month-local HTTP request denominator")
        if use_default:
            self.assertEqual(len(responses), expected_http)
            self.assertTrue(all(response.closed for response in responses))
        self.assertEqual(transport.reqHistoricalDataAsync.call_count, 2 * month_count,
                         "month-local IBKR request denominator")
        saved = sv.combined_entries_for_ticker(sv.load_combined_flags(bank), "TEST")
        self.assertEqual(len(saved), 1)
        row = saved[0]
        self.assertEqual(row["candidates"], [day.isoformat() for day in anomalies])
        self.assertEqual(row["cleared"], [day.isoformat() for day in anomalies])
        self.assertEqual(row["persistent"], [])
        self.assertEqual([item["month"] for item in row["refetch_coverage"]],
                         sorted({day.strftime("%Y-%m") for day in anomalies}))
        events = self.rows_from_context_path(result["fetch_ledger"]["path"])
        http = [event for event in events if event.get("producer_id") == combined._HTTP]
        self.assertEqual([event["event"] for event in http], ["decision", "result"] * expected_http)
        self.assertEqual(len({event["worker_id"] for event in http}), expected_http)
        self.assertEqual(len({event["attempt_id"] for event in http}), expected_http)
        self.assertEqual(len({event["operation_id"] for event in http}), 1)
        self.assertEqual(len({event["logical_id"] for event in http}), expected_http)
        self.assertEqual(len(contexts), 1)
        self.assertEqual(contexts[0].captured_now, self.fixture_now)
        self.assertEqual({event["operation_id"] for event in events}, {contexts[0].operation_id})
        self.assertEqual([rights for name, rights, child in children if "http-reference" in name],
                         [frozenset({combined._HTTP})] * expected_http)
        decisions = Counter(event["producer_id"] for event in events if event["event"] == "decision")
        self.assertEqual(decisions, Counter({
            "ibkr.choke.qualify": 1,
            "http.stockanalysis.validation": 1 + month_count,
            "ibkr.live_combined_flags.minute_month": month_count,
            "ibkr.live_combined_flags.daily_refetch": month_count,
        }), "whole month-refetch decision budget")
        self.assertEqual([event["event"] for event in events
                          if event.get("producer_id") == "ibkr.choke.qualify"],
                         ["decision", "result"])
        for producer in (combined._MINUTE, combined._DAILY):
            self.assertEqual(decisions[producer], month_count)
            self.assertEqual([event["event"] for event in events
                              if event.get("producer_id") == producer],
                             ["decision", "result"] * month_count)
        self.assertEqual(decisions[combined._HTTP], len(calls))
        self.assertNotEqual(http[1]["payload"]["accepted"]["digest"],
                            http[3]["payload"]["accepted"]["digest"])
        self.assertEqual(sv._REF_CACHE, {})
        self.assertTrue(result["fetch_ledger"]["ledger_verified"])
        self.assertEqual(result["fetch_ledger"]["verified"], kind != "catchup")
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})
        self.assertTrue(all(lease.released for lease in self.fixture_leases))
        print("A42_MONTH_REFETCH", kind, "anomalies", len(anomalies),
              "months", month_count, json.dumps(dict(decisions), sort_keys=True))

