    def a40_root_dependency_witness(self, kind, dependency="adapter", *,
                                   explicit_bank=False, admit=True):
        from contextlib import ExitStack
        import live_validate_catchup as catchup
        import live_run_all as all_groups
        diagnostic = catchup if kind == "catchup" else all_groups
        created = self.root_fixture()
        effects = []
        def forbidden(label):
            def effect(*args, **kwargs):
                effects.append(label)
                raise AssertionError("effect before dependency refusal: " + label)
            return effect
        kwargs = {"evidence_dir": self.root / ("a40-" + kind)}
        keyword = {"adapter": "adapter_factory", "reference": "reference_fn",
                   "opener": "_reference_opener"}[dependency]
        kwargs[keyword] = forbidden(dependency)
        if explicit_bank:
            kwargs["root"] = self.root / "bank-not-to-resolve"
        expected = RequestRefused if admit else AuthorityError
        message = ("injected catch-up dependencies are offline-only" if kind == "catchup"
                   else "injected kind/daily adapter factory is offline-only")
        with ExitStack() as stack:
            for owner, name, label in (
                    (diagnostic.operation_gate, "acquire", "lease"),
                    (diagnostic, "_free_ports", "ports"),
                    (sv, "discover_series", "bank-scan"),
                    (sv, "record_combined_flags", "publication")):
                stack.enter_context(patch.object(owner, name, side_effect=forbidden(label)))
            if kind == "catchup":
                stack.enter_context(patch.object(catchup, "_bank_root",
                                   side_effect=forbidden("bank-root")))
                stack.enter_context(patch.object(catchup, "Path",
                                   side_effect=forbidden("bank-path")))
                stack.enter_context(patch.object(catchup, "_catchup_port",
                                   side_effect=forbidden("dispatch")))
                stack.enter_context(patch.object(catchup.combined, "_combined_qualify",
                                   side_effect=forbidden("qualify")))
            else:
                stack.enter_context(patch.object(all_groups, "_run_group",
                                   side_effect=forbidden("dispatch")))
            if admit:
                # Only simulate the currently held root admission. The context
                # really has no test capability; every effect tripwire stays live.
                stack.enter_context(patch.object(op, "require_root_admission", return_value=None))
            with self.assertRaises(expected) as caught:
                (catchup.run_catchup if kind == "catchup" else all_groups.run_all)(**kwargs)
        self.assertIs(type(caught.exception), expected)
        if admit:
            self.assertEqual(str(caught.exception), message)
        else:
            self.assertIn("not activated", str(caught.exception))
        self.assertFalse(caught.exception.fetch_ledger["verified"])
        self.assertTrue(caught.exception.fetch_ledger["report_persisted"])
        self.assertEqual(len(created), 1)
        self.assertIsNone(created[0].test_capability)
        self.assertEqual(effects, [])
        self.assertEqual(self.fixture_leases, [])
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})

