    def a39_refusal_witness(self, kind="combined", *, refetch=False):
        combined, bank, adapter, transport, reference = self.combined_fixture()
        if refetch:
            _, reference, _ = self.a23_month_reference_fixture(bank, transport)
        raw_bars = self.patch(transport, "reqHistoricalDataAsync",
                              wraps=transport.reqHistoricalDataAsync)
        sv.clear_reference_cache()
        self.addCleanup(sv.clear_reference_cache)
        # Retain real bytes, not merely absence or an in-memory verdict.
        sv.record_combined_flags(bank, {"ticker": "TEST", "interval": "1m",
            "status": "flagged", "persistent": ["2026-06-10"],
            "note": "pre-existing evidence must survive terminal refusal"})
        sidecar = bank / "_combined_flags.json"
        before = sidecar.read_bytes()
        comparisons, sends, audited = [], [], []
        permits = FetchRunContext.permits
        audit = combined._audit_ticker
        def permitted(context, producer, envelope):
            allowed = permits(context, producer, envelope)
            if producer == combined._HTTP:
                # Count consumer admission, not later attempt rechecks.
                caller = inspect.currentframe().f_back.f_code.co_name
                if caller == "fetch_daily_reference":
                    comparisons.append(envelope)
                    if len(comparisons) == (2 if refetch else 1):
                        return False
            return allowed
        def opener(url):
            self.assertIsNone(bridge.current_worker())
            sends.append(url)
            return json.dumps({"data": [dict(t=day, **dict(zip(
                ("o", "h", "l", "c", "v"), row)))
                for day, row in reference.items()]}).encode()
        def seen_audit(adapter, root, ticker, interval, **kwargs):
            audited.append(ticker)
            return audit(adapter, root, ticker, interval, **kwargs)
        import live_validate_catchup as catchup
        self.patch(combined, "_bank_series", return_value=[("TEST", "1m"), ("ZZZ", "1m")])
        self.patch(catchup.sv, "discover_series", return_value=[("TEST", "1m"), ("ZZZ", "1m")])
        with patch.object(FetchRunContext, "permits", new=permitted), \
                patch.object(combined, "_audit_ticker", new=seen_audit), \
                self.assertRaises(RequestRefused) as caught:
            self.a23_run_embedded(kind, bank, adapter, opener)
        self.assertIs(type(caught.exception), RequestRefused)
        self.assertEqual(str(caught.exception), "validation cache lacks operation rights")
        self.assertEqual(sidecar.read_bytes(), before)
        self.assertEqual(audited, ["TEST"])
        self.assertEqual(len(comparisons), 2 if refetch else 1)
        self.assertEqual(len(sends), 1 if refetch else 0)
        self.assertFalse(caught.exception.fetch_ledger["verified"])
        events = self.rows_from_context_path(caught.exception.fetch_ledger["path"])
        expected = {"ibkr.choke.qualify": 1}
        if refetch:
            expected.update({"http.stockanalysis.validation": 1,
                             "ibkr.live_combined_flags.minute_month": 1,
                             "ibkr.live_combined_flags.daily_refetch": 1})
        self.assertEqual(Counter(event["producer_id"] for event in events
                                 if event["event"] == "decision"), Counter(expected),
                         "whole terminal-refusal decision budget")
        for producer, count in expected.items():
            self.assertEqual([event["event"] for event in events
                              if event.get("producer_id") == producer],
                             ["decision", "result"] * count)
        self.assertEqual(raw_bars.call_count, 2 if refetch else 0)
        self.assertEqual(sum(call[0] == "qualify" for call in transport.calls), 1)
        self.assertEqual(sv._REF_CACHE, {})
        self.assertTrue(all(lease.released for lease in self.fixture_leases))
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})

        print("A44_REFUSAL_BUDGET", kind, "month" if refetch else "initial",
              json.dumps(expected, sort_keys=True))

