    def a47_embedded_error_matrix(self, kind, position, *, durability=False,
                                  errors=None, use_default=False, http_status=None):
        """Real registered roots; inject only raw HTTP or selected journal fsync."""
        from contextlib import ExitStack
        import platform
        import fix_data_pipeline as repair
        import live_validate_catchup as catchup
        combined, bank, adapter, transport, reference = self.combined_fixture()
        if position == "month":
            _, reference, _ = self.a23_month_reference_fixture(bank, transport)
        self.assertIn(position, {"initial", "month"})
        self.assertIn(kind, {"combined", "catchup", "repair"})
        selected = 2 if position == "month" else 1
        sv.clear_reference_cache()
        self.addCleanup(sv.clear_reference_cache)
        sv.record_combined_flags(bank, {"ticker": "TEST", "interval": "1m",
            "status": "flagged", "persistent": ["2026-06-10"],
            "note": "A47 pre-existing evidence"})
        sidecar = bank / "_combined_flags.json"
        before = sidecar.read_bytes()
        raw = json.dumps({"data": [dict(t=day, **dict(zip(
            ("o", "h", "l", "c", "v"), row)))
            for day, row in reference.items()]}).encode()
        inverse = errors is not None
        errors = errors or (("decision", "result") if durability else
            (AuthorityError, LedgerError, RequestCancelled, RequestRefused))
        original_reference, original_audit = sv.fetch_daily_reference, combined._audit_ticker
        for error in errors:
            with (nullcontext() if inverse else self.subTest(
                    root=kind, position=position, error=error)):
                adapter.ib = transport
                adapter.port = 2000
                transport.calls.clear()
                sends, comparisons, audited, credits, faults = [], [], [], [], []
                if http_status is not None:
                    from urllib.error import HTTPError
                    terminal = HTTPError('https://stockanalysis.com/', http_status,
                                         'A62 provider block', {}, None)
                    self.addCleanup(terminal.close)
                else:
                    terminal = None if durability else error("A47 raw terminal witness")
                def opener(url):
                    if not use_default:
                        self.assertIsNone(bridge.current_worker())
                    sends.append(url)
                    if len(sends) == selected and not durability:
                        raise terminal
                    return raw
                def reference_call(*args, **kwargs):
                    comparisons.append(args[0])
                    if len(comparisons) == selected and durability:
                        def fail(event, stage):
                            if (event, stage) == (error, "fsync"):
                                faults.append((event, stage))
                                raise OSError("A47 selected HTTP fsync")
                        kwargs["_fetch_worker"].context.ledger._fault = fail
                    return original_reference(*args, **kwargs)
                def audit_call(adapter, root, ticker, interval, **kwargs):
                    audited.append(ticker)
                    return original_audit(adapter, root, ticker, interval, **kwargs)
                caught = None
                with ExitStack() as stack:
                    if use_default:
                        import urllib.request
                        def default_open(_opener, wire, *, timeout):
                            self.assertEqual(wire.get_method(), 'GET')
                            self.assertTrue(0 < timeout <= 20)
                            return io.BytesIO(opener(wire.full_url))
                        stack.enter_context(patch.object(urllib.request.OpenerDirector, 'open', default_open))
                    bars = stack.enter_context(patch.object(transport,
                        "reqHistoricalDataAsync", wraps=transport.reqHistoricalDataAsync))
                    publication = stack.enter_context(patch.object(sv,
                        "record_combined_flags", wraps=sv.record_combined_flags))
                    stack.enter_context(patch.object(sv, "fetch_daily_reference",
                                                     side_effect=reference_call))
                    stack.enter_context(patch.object(combined, "_audit_ticker",
                                                     side_effect=audit_call))
                    stack.enter_context(patch.object(combined, "_bank_series",
                        return_value=[("TEST", "1m"), ("ZZZ", "1m")]))
                    stack.enter_context(patch.object(catchup.sv, "discover_series",
                        return_value=[("TEST", "1m"), ("ZZZ", "1m")]))
                    stack.enter_context(patch.object(platform, "machine", return_value="offline"))
                    stack.enter_context(patch.object(repair.run_log_retention,
                                                     "prune_run_logs", return_value={}))
                    try:
                        if kind == "repair":
                            kwargs = self.a41_kwargs(bank, None if use_default else opener)
                            kwargs.update(adapter_factory=lambda _: adapter,
                                series_fn=lambda _: [("TEST", "1m"), ("ZZZ", "1m")],
                                verification_fn=lambda *args: credits.append(args),
                                progress=lambda _: None, _test_capability=self.capability)
                            repair.run(**kwargs)
                        else:
                            self.a23_run_embedded(kind, bank, adapter, None if use_default else opener)
                    except BaseException as exc:
                        caught = exc
                if durability:
                    self.assertIs(type(caught), LedgerError, "selected durability fault must escape")
                    self.assertIn(error + " durability failure", str(caught))
                    self.assertEqual(faults, [(error, "fsync")])
                elif http_status is not None:
                    self.assertIsInstance(caught, RequestRefused, '403 must stop embedded root')
                    self.assertIs(caught.__cause__, terminal)
                else:
                    self.assertIs(caught, terminal, "embedded terminal must escape unchanged")
                self.assertEqual(audited, ["TEST"], "terminal must stop the next ticker")
                self.assertEqual(comparisons, ["TEST"] * selected)
                self.assertEqual(len(sends), selected - int(durability and error == "decision"))
                self.assertEqual(bars.call_count, 2 if position == "month" else 0)
                self.assertEqual(sum(call[0] == "qualify" for call in transport.calls), 1)
                self.assertEqual(publication.call_count, 0, "failed reference cannot publish combined verdict")
                self.assertEqual(sidecar.read_bytes(), before)
                self.assertEqual(credits, [])
                self.assertEqual(sv._REF_CACHE, {})
                evidence = caught.fetch_ledger
                self.assertFalse(evidence["verified"])
                events = self.rows_from_context_path(evidence["path"])
                expected = {QUALIFY: 1, combined._HTTP: selected}
                if position == "month":
                    expected.update({combined._MINUTE: 1, combined._DAILY: 1})
                self.assertEqual(Counter(row["producer_id"] for row in events
                    if row["event"] == "decision"), Counter(expected), "A47 whole decision budget")
                http = [row for row in events if row.get("producer_id") == combined._HTTP]
                expected_events = ["decision", "result"] * selected
                if durability and error == "decision":
                    expected_events.pop()
                # A failed fsync can leave a visible line, never durable credit.
                self.assertEqual([row["event"] for row in http], expected_events)
                if not durability:
                    self.assertEqual(http[-1]["payload"]["outcome"], "error")
                    self.assertEqual(http[-1]["payload"]["error_type"], type(terminal).__name__)
                self.assertEqual(len({row["logical_id"] for row in http}), selected)
                self.assertFalse(any(row["event"] == "seal" for row in events))
                self.assertFalse(Path(evidence["path"]).with_suffix(".seal.json").exists())
                self.assertEqual(op._OPERATIONS, {})
                self.assertEqual(op._CHILDREN, {})
                self.assertTrue(all(lease.released for lease in self.fixture_leases))
                print("A47_EMBEDDED_ERROR", kind, position,
                      error if durability else error.__name__, "sends", len(sends),
                      "decisions", json.dumps(expected, sort_keys=True))

