    def a49_embedded_provider_matrix(self, kind, position):
        """Ordinary unavailable/quarantined HTTP is paired, never a clean audit."""
        from contextlib import ExitStack
        import platform
        import fix_data_pipeline as repair
        import live_validate_catchup as catchup
        combined, bank, adapter, transport, reference = self.combined_fixture()
        if position == "month":
            _, reference, _ = self.a23_month_reference_fixture(bank, transport)
        selected = 2 if position == "month" else 1
        sv.clear_reference_cache()
        self.addCleanup(sv.clear_reference_cache)
        raw = json.dumps({"data": [dict(t=day, **dict(zip(
            ("o", "h", "l", "c", "v"), row))) for day, row in reference.items()]}).encode()
        # HTTP403 is terminal under F-A47-2; A62 witnesses every root/position.
        for mode in ("timeout", "quarantine"):
            with self.subTest(root=kind, position=position, mode=mode):
                adapter.ib, adapter.port = transport, 2000
                transport.calls.clear()
                sends, credits = [], []
                malformed = b'{"data":[{"t":"bad-date"}]}'
                def opener(url):
                    self.assertIsNone(bridge.current_worker())
                    sends.append(url)
                    if len(sends) != selected:
                        return raw
                    if mode == "timeout":
                        raise TimeoutError("A49 provider timeout")
                    return malformed
                with ExitStack() as stack:
                    bars = stack.enter_context(patch.object(transport,
                        "reqHistoricalDataAsync", wraps=transport.reqHistoricalDataAsync))
                    stack.enter_context(patch.object(combined, "_bank_series",
                                                     return_value=[("TEST", "1m")]))
                    stack.enter_context(patch.object(catchup.sv, "discover_series",
                                                     return_value=[("TEST", "1m")]))
                    stack.enter_context(patch.object(platform, "machine", return_value="offline"))
                    stack.enter_context(patch.object(repair.run_log_retention,
                                                     "prune_run_logs", return_value={}))
                    if kind == "repair":
                        kwargs = self.a41_kwargs(bank, opener)
                        kwargs.update(adapter_factory=lambda _: adapter,
                            series_fn=lambda _: [("TEST", "1m")],
                            verification_fn=lambda *args: credits.append(args),
                            progress=lambda _: None, _test_capability=self.capability)
                        result = repair.run(**kwargs)
                    else:
                        result = self.a23_run_embedded(kind, bank, adapter, opener)
                self.assertEqual(len(sends), selected, "ordinary validation must not retry")
                self.assertEqual(bars.call_count, 2 if position == "month" else 0)
                self.assertEqual(sum(call[0] == "qualify" for call in transport.calls), 1)
                self.assertEqual(credits, [])
                self.assertEqual(sv._REF_CACHE, {})
                saved, = sv.combined_entries_for_ticker(sv.load_combined_flags(bank), "TEST")
                self.assertIs(saved["_verification_current"], False,
                              "unavailable reference must not earn current credit")
                self.assertFalse(saved["coverage_complete"])
                evidence = result["fetch_ledger"]
                self.assertFalse(evidence["verified"])
                self.assertTrue(evidence["ledger_verified"],
                                "ordinary provider result must have a paired sealed journal")
                events = self.rows_from_context_path(evidence["path"])
                expected = {QUALIFY: 1, combined._HTTP: selected}
                if position == "month":
                    expected.update({combined._MINUTE: 1, combined._DAILY: 1})
                self.assertEqual(Counter(row["producer_id"] for row in events
                    if row["event"] == "decision"), Counter(expected))
                for producer, count in expected.items():
                    self.assertEqual([row["event"] for row in events
                        if row.get("producer_id") == producer], ["decision", "result"] * count)
                http = [row for row in events if row.get("producer_id") == combined._HTTP]
                payload = http[-1]["payload"]
                self.assertEqual(payload["outcome"], "timeout" if mode == "timeout" else "error")
                self.assertEqual(payload["error_type"], {
                    "timeout": "TimeoutError",
                    "quarantine": "ResponseQuarantined"}[mode])
                if mode == "quarantine":
                    import base64
                    quarantined = Path(evidence["path"]).with_suffix(
                        "." + http[-1]["attempt_id"] + ".quarantine.json")
                    receipt = json.loads(quarantined.read_text())
                    self.assertEqual(base64.b64decode(receipt["response"]["raw_response_base64"]), malformed)
                self.assertEqual(op._OPERATIONS, {})
                self.assertEqual(op._CHILDREN, {})
                self.assertTrue(all(lease.released for lease in self.fixture_leases))
                print("A49_PROVIDER_OUTCOME", kind, position, mode, "sends", len(sends))

