    def a49_durability_inverse(self, kind, position):
        # Model a journal that incorrectly reports success after fsync failed.
        # Retain real append/flush and the injected fault; remove only the poison
        # and terminal raise, so the original matrix must reject publication.
        import textwrap
        original = FetchLedger._append
        source = textwrap.dedent(inspect.getsource(original))
        old = ('        self._failed = f"{kind} durability failure: {type(exc).__name__}: {exc}"\n'
               '        raise LedgerError(self._failed) from exc\n')
        self.assertEqual(source.count(old), 1)
        namespace = {}
        exec(compile(source.replace(old, '        pass  # inverse: falsely durable\n', 1),
                     original.__code__.co_filename, 'exec'), original.__globals__, namespace)
        with patch.object(FetchLedger, "_append", new=namespace["_append"]), \
                self.assertRaisesRegex(AssertionError, "selected durability fault must escape"):
            self.a47_embedded_error_matrix(kind, position, durability=True, errors=("result",))
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})
        self.assertTrue(all(lease.released for lease in self.fixture_leases))
        print("A49_DURABILITY_INVERSE_RED", kind, position, "fsync-failure-reported-success")

