    def a39_mutant(self, module, name, old, new):
        import textwrap
        original = getattr(module, name)
        source = textwrap.dedent(inspect.getsource(original))
        self.assertEqual(source.count(old), 1, "mutant anchor is not unique")
        # Definition locals avoid replacing the original at construction; live
        # globals preserve tripwires patched after the mutant is compiled.
        namespace = {}
        exec(compile(source.replace(old, new, 1), module.__file__, "exec"),
             module.__dict__, namespace)
        self.assertIs(getattr(module, name), original)
        return namespace[name]

