    def a39_no_capability_witness(self, route, dependency="opener"):
        import live_combined_flags as combined
        import live_validate_catchup as catchup
        effects = []
        def forbidden(label):
            def effect(*args, **kwargs):
                effects.append(label)
                child = kwargs.get("_fetch_child")
                if label == "qualify" and child is not None:
                    child.close()
                raise AssertionError("effect before dependency refusal: " + label)
            return effect
        callback = forbidden(dependency)
        adapter_fn = callback if dependency == "adapter" else None
        reference_fn = callback if dependency == "reference" else None
        opener = callback if dependency == "opener" else None
        self.patch(combined, "_bank_root", side_effect=forbidden("bank-root"))
        self.patch(combined, "_bank_series", side_effect=forbidden("bank-scan"))
        self.patch(combined, "_free_ports", side_effect=forbidden("ports"))
        self.patch(combined, "_combined_qualify", side_effect=forbidden("qualify"))
        self.patch(sv, "record_combined_flags", side_effect=forbidden("publication"))
        self.patch(combined.operation_gate, "acquire", side_effect=forbidden("lease"))
        root = SimpleNamespace(exists=forbidden("bank-exists"))
        if route == "root":
            created = self.root_fixture()
            self.patch(combined.operation_gate, "acquire", side_effect=forbidden("lease"))
            # Simulate admission only, under intact offline tripwires. The
            # registered root still mints a context without capability.
            with patch.object(op, "require_root_admission", return_value=None), \
                    self.assertRaises(RequestRefused) as caught:
                combined.run_combined_flags(adapter_factory=adapter_fn,
                    reference_fn=reference_fn, _reference_opener=opener,
                    evidence_dir=self.root / "no-cap-root")
            self.assertEqual(self.fixture_leases, [])
            self.assertEqual(len(created), 1)
            self.assertIsNone(created[0].test_capability)
            message = "injected combined dependencies are offline-only"
        else:
            run = self.open("diagnostic")
            # Retain confined mint custody; remove capability only from the
            # context consumed by the barrier (the existing A1 test idiom).
            object.__setattr__(run.context, "test_capability", None)
            self.assertIsNone(run.context.test_capability)
            try:
                with self.assertRaises(RequestRefused) as caught:
                    if route == "audit":
                        combined._audit_ticker(None, root, "TEST", "1m",
                            _reference_opener=opener,
                            _fetch_child=self.child(run, rights=combined._RIGHTS))
                    elif route == "catchup":
                        catchup._catchup_body(run, root, True, None, adapter_fn,
                            None, reference_fn, None, opener)
                    else:
                        combined._combined_body(run, root, None, None, adapter_fn,
                            None, reference_fn, None, opener)
            finally:
                run.close()
            message = ("injected external reference is offline-only" if route == "audit"
                else "injected catch-up dependencies are offline-only" if route == "catchup"
                else "injected combined dependencies are offline-only")
        self.assertIs(type(caught.exception), RequestRefused)
        self.assertEqual(str(caught.exception), message)
        self.assertEqual(effects, [])
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})

