    def a39_verified_cache_witness(self, *, refetch=False):
        combined, bank, adapter, transport, fresh = self.combined_fixture()
        if refetch:
            anomaly, fresh, clean = self.a23_month_reference_fixture(bank, transport)
        sv.clear_reference_cache()
        self.addCleanup(sv.clear_reference_cache)
        cached = {day: (10, 31, 9, 30, 100) for day in fresh}
        def raw(rows):
            return json.dumps({"data": [dict(t=day, **dict(zip(
                ("o", "h", "l", "c", "v"), row))) for day, row in rows.items()]}).encode()
        common = dict(_test_capability=self.capability, _authority=self.authority,
            _clock=lambda: self.fixture_now, _governors=governors._REGISTRY)
        with patch.object(sv._time, "time", return_value=1234567890):
            first = sv.fetch_daily_reference_single_request("TEST", "Max",
                _evidence_dir=self.root / "warm-cache", _opener=lambda _: raw(cached), **common)
            self.assertEqual(first, cached)
            before = deepcopy(sv._REF_CACHE)
            entry = before[("TEST", "Max")]
            self.assertTrue(inspect_ledger(Path(entry["ledger_path"]))["verified"])
            replay = sv.fetch_daily_reference_single_request("TEST", "Max",
                _evidence_dir=self.root / "prove-hit",
                _opener=lambda _: self.fail("verified warm cache was not a real hit"), **common)
            self.assertEqual(replay, cached)
            replay_path = next((self.root / "prove-hit").glob("*.jsonl"))
            self.assertEqual([row["event"] for row in self.rows_from_context_path(replay_path)], ["seal"])
            calls = []
            def opener(url):
                self.assertIsNone(bridge.current_worker())
                calls.append(url)
                return raw(clean if refetch and len(calls) > 1 else fresh)
            with patch.object(sv, "combined_crosscheck", wraps=sv.combined_crosscheck) as compare:
                result = self.a23_run_embedded("combined", bank, adapter, opener)
            self.assertEqual(len(calls), 2 if refetch else 1)
            self.assertEqual(compare.call_count, 1)
            self.assertEqual(compare.call_args.kwargs["ext_ref"], fresh)
            self.assertNotEqual(compare.call_args.kwargs["ext_ref"], cached)
            self.assertEqual(sv._REF_CACHE, before)
            self.assertEqual(result["status"], "complete")
            if refetch:
                self.assertEqual(result["results"][0]["cleared"], [anomaly.isoformat()])
                self.assertEqual(result["results"][0]["persistent"], [])
            self.assertTrue(result["fetch_ledger"]["verified"])
            events = self.rows_from_context_path(result["fetch_ledger"]["path"])
            self.assertEqual([row["event"] for row in events
                if row.get("producer_id") == combined._HTTP],
                ["decision", "result"] * (2 if refetch else 1))

