    def test_a23_offline_reference_routes_do_not_mint_http_authority(self):
        import health
        import triage_classifier as triage
        import deep_seam_scan as seam
        import phantom_fix
        import wbd_truncate
        import split_cache
        class StaticProvider:
            def fetch_history(self, ticker, provider_symbol=None, cik=None):
                return {"ticker": ticker, "provider_symbol": provider_symbol or ticker,
                    "cik": cik or 123456, "fetched_at": "2026-07-02T21:00:00+00:00",
                    "provider": "offline-fixture", "provider_status": "ok",
                    "coverage": {"from": "1980-01-01", "through": "2026-07-02",
                        "evidence_level": "provisional", "complete": False,
                        "complete_basis": None, "source_ids": ["fixture"]},
                    "events": [], "sources": {"fixture": {
                        "kind": "fixture", "payload_sha256": "f" * 64}}}
        combined, bank, _adapter, _transport, reference = self.combined_fixture()
        # The existing offline health path refreshes this local derived cache;
        # seed it before snapshotting correction/source safety.
        sv.consensus_calendar(bank)
        before = {str(path.relative_to(bank)): path.read_bytes()
                  for path in bank.rglob("*") if path.is_file()}
        reached = set()
        watched = {"health", "triage_classifier", "deep_seam_scan", "phantom_fix",
                   "wbd_truncate", "stock_validate", "split_cache"}
        def profile(frame, event, arg):
            if event == "call" and Path(frame.f_code.co_filename).stem in watched:
                reached.add((Path(frame.f_code.co_filename).stem,
                             frame.f_code.co_qualname))
        previous = sys.getprofile()
        def run(invoke, expected):
            reached.clear()
            sys.setprofile(profile)
            try:
                value = invoke()
            finally:
                sys.setprofile(previous)
            self.assertTrue(set(expected) <= reached, (set(expected) - reached, reached))
            return value
        flag = {"ticker": "TEST", "boundary": "2026-07-01"}
        report = run(lambda: health.audit(bank, write=False, triage_flags=[flag]), {
            ("health", "audit"), ("health", "_offline_triage_reference"),
            ("triage_classifier", "audit"), ("triage_classifier", "classify_flags"),
            ("triage_classifier", "classify_flag")})
        self.assertEqual(report["triage"]["classified"][0]["verdict"], "UNVERIFIABLE")
        self.assertNotIn(("stock_validate", "fetch_daily_reference"), reached)
        report = run(lambda: triage.audit(bank, flags=[flag]), {
            ("triage_classifier", "audit"), ("triage_classifier", "classify_flags"),
            ("triage_classifier", "classify_flag"), ("stock_validate", "fetch_daily_reference")})
        self.assertEqual(report["classified"][0]["verdict"], "UNVERIFIABLE")
        for name, invoke in (
                ("phantom_fix", lambda: phantom_fix.apply_correction(bank,
                    ticker="TEST", ex_date="2026-07-01", dry_run=False)),
                ("wbd_truncate", lambda: wbd_truncate.apply_truncation(bank,
                    ticker="TEST", boundary="2026-07-01", cutover="2026-07-02",
                    intervals=("1d",), dry_run=False))):
            def refused():
                with self.assertRaisesRegex(RuntimeError, "triage verdict is UNVERIFIABLE"):
                    invoke()
            run(refused, {(name, "apply_correction" if name == "phantom_fix" else "apply_truncation"),
                ("triage_classifier", "classify_flag"), ("stock_validate", "fetch_daily_reference")})
        result = run(lambda: seam.scan_bank(bank, tickers=["TEST"]), {
            ("deep_seam_scan", "scan_bank"), ("deep_seam_scan", "scan_ticker"),
            ("deep_seam_scan", "scan_ticker_steps"), ("stock_validate", "fetch_daily_reference")})
        self.assertEqual(result["other"][0]["verdict"], "UNVERIFIABLE")
        run(lambda: seam.scan_ticker(bank, "TEST", ref=reference), {
            ("deep_seam_scan", "scan_ticker"), ("deep_seam_scan", "scan_ticker_steps"),
            ("deep_seam_scan", "detect_steps")})
        self.assertNotIn(("stock_validate", "fetch_daily_reference"), reached)
        run(lambda: sv.internal_crosscheck(bank, "TEST", daily_ref=reference), {
            ("stock_validate", "internal_crosscheck"), ("stock_validate", "_validate_series_body")})
        self.assertNotIn(("stock_validate", "fetch_daily_reference"), reached)
        result = run(lambda: split_cache.refresh_ticker(bank, "TEST", StaticProvider()), {
            ("split_cache", "refresh_ticker"), ("stock_validate", "fetch_daily_reference")})
        self.assertEqual(result["status"], "error")
        self.assertNotIn(("split_cache", "write_cache"), reached)
        self.assertEqual(before, {str(path.relative_to(bank)): path.read_bytes()
                         for path in bank.rglob("*") if path.is_file()})
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})
        print("A23_OFFLINE_ROUTES_REACHED health triage phantom wbd deep-seam split-reference internal-only")

    def a48_offline_callback_witness(self, kind, error_type=None):
        from contextlib import ExitStack
        import health
        import triage_classifier as triage
        import phantom_fix
        import wbd_truncate
        import fetch_http_labels as labels
        _, bank, _, _, reference = self.combined_fixture()
        sv.clear_reference_cache()
        self.addCleanup(sv.clear_reference_cache)
        sv.consensus_calendar(bank)
        before = {str(path.relative_to(bank)): path.read_bytes()
                  for path in bank.rglob("*") if path.is_file()}
        calls, classified = [], []
        error = error_type("A48 detached callback failure") if error_type else None
        original = triage.classify_series
        def callback(ticker, rng):
            self.assertIsNone(bridge.current_worker())
            calls.append((ticker, rng))
            if error is not None:
                raise error
            return reference
        def classify(ticker, boundary, stored, ref):
            classified.append(ref)
            return original(ticker, boundary, stored, ref)
        flag = {"ticker": "TEST", "boundary": "2026-07-01"}
        with ExitStack() as stack:
            default = stack.enter_context(patch.object(sv, "fetch_daily_reference",
                side_effect=AssertionError("offline callback fell back to HTTP helper")))
            physical = stack.enter_context(patch.object(labels, "guarded_stockanalysis_attempt",
                side_effect=AssertionError("offline callback attempted physical HTTP")))
            mint = stack.enter_context(patch.object(op, "begin_operation",
                side_effect=AssertionError("offline callback minted operation")))
            stack.enter_context(patch.object(triage, "classify_series", side_effect=classify))
            if kind == "health":
                value = health.audit(bank, write=False, triage_flags=[flag], triage_ref_fn=callback)
                verdict = value["triage"]["classified"][0]
            elif kind == "triage":
                value = triage.audit(bank, flags=[flag], ref_fn=callback)
                verdict = value["classified"][0]
            else:
                self.assertIn(kind, {"phantom", "truncate"})
                with self.assertRaisesRegex(RuntimeError,
                        "triage verdict is UNVERIFIABLE" if error else "triage verdict is"):
                    if kind == "phantom":
                        phantom_fix.apply_correction(bank, ticker="TEST", ex_date="2026-07-01",
                            dry_run=False, ref_fn=callback, snapshot_root=self.root / "never-snapshot")
                    else:
                        wbd_truncate.apply_truncation(bank, ticker="TEST", boundary="2026-07-01",
                            cutover="2026-07-02", intervals=("1d",), dry_run=False,
                            ref_fn=callback, snapshot_root=self.root / "never-snapshot")
                verdict = None
        self.assertEqual(calls, [("TEST", "Max")], "offline callback forwarding")
        if error is None:
            self.assertEqual(len(classified), 1)
            self.assertIs(classified[0], reference, "detached reference identity")
        else:
            self.assertEqual(classified, [])
            if verdict is not None:
                self.assertEqual(verdict["verdict"], "UNVERIFIABLE")
                self.assertEqual(verdict["evidence"]["error"], str(error))
        self.assertEqual(default.call_count, 0, "provided reference must not invoke default HTTP")
        self.assertEqual(physical.call_count, 0)
        self.assertEqual(mint.call_count, 0)
        self.assertEqual(before, {str(path.relative_to(bank)): path.read_bytes()
                         for path in bank.rglob("*") if path.is_file()})
        self.assertFalse((self.root / "never-snapshot").exists())
        self.assertEqual(sv._REF_CACHE, {})
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})
        print("A48_OFFLINE_CALLBACK", kind, error_type.__name__ if error_type else "rows")

