    def a44_split_callback_witness(self, *, batch=False, failure=None, default_scan=False):
        import split_cache as cache
        import deep_seam_scan as seam
        _combined, bank, _adapter, _transport, reference = self.combined_fixture()
        before = {str(path.relative_to(bank)): path.read_bytes()
                  for path in bank.rglob("*") if path.is_file()}
        calls = []
        def unbound(stage):
            self.assertIsNone(bridge.current_worker())
            self.assertEqual(op._OPERATIONS, {})
            self.assertEqual(op._CHILDREN, {})
            calls.append(stage)
        owner = self
        class Provider:
            def fetch_history(self, ticker, symbol, cik=None):
                unbound("provider")
                owner.assertEqual((ticker, symbol, cik), ("TEST", "TEST-ALIAS", 123456))
                return {"ticker": ticker, "provider_symbol": symbol, "cik": cik,
                    "fetched_at": "2026-07-02T21:00:00+00:00", "provider": "fixture",
                    "provider_status": "ok", "events": [],
                    "coverage": {"from": "1980-01-01", "through": "2026-07-02",
                        "evidence_level": "provisional", "complete": False,
                        "complete_basis": None, "source_ids": ["fixture"]},
                    "sources": {"fixture": {"kind": "fixture", "payload_sha256": "f" * 64}}}
        def fetch(symbol, *, rng):
            unbound("reference")
            self.assertEqual((symbol, rng), ("TEST-ALIAS", "Max"))
            if failure == "reference":
                raise LedgerError("fixture reference terminal")
            return reference
        actual_scan = seam.scan_ticker_steps
        def scan(root, ticker, *, ref):
            unbound("scan")
            self.assertEqual((root, ticker), (bank, "TEST"))
            self.assertIs(ref, reference)
            if failure == "scan":
                raise LedgerError("fixture scan terminal")
            if default_scan:
                return actual_scan(root, ticker, ref=ref)
            # Explicit injected result, not claimed evidence of real split detection.
            return {"ticker": ticker, "verdict": "CLEAN", "candidates": [],
                    "series_fingerprint": seam._stored_1d_snapshot(root, ticker)[1]}
        self.patch(op, "begin_operation", side_effect=AssertionError("split callback minted operation"))
        extra_reference = self.patch(sv, "fetch_daily_reference",
                                     side_effect=AssertionError("unexpected second/default reference"))
        if default_scan:
            self.patch(seam, "scan_ticker_steps", side_effect=scan)
        if batch:
            result = cache.refresh_many(bank, ["TEST"], Provider(),
                provider_symbols={"TEST": "TEST-ALIAS"}, cik_bindings={"TEST": 123456},
                pace_seconds=0, reference_fetcher=fetch, scan_fn=scan)
            self.assertEqual(result["processed"], 1)
            row = result["rows"][0]
        else:
            row = cache.refresh_ticker(bank, "TEST", Provider(),
                provider_symbol="TEST-ALIAS", cik=123456,
                reference_fetcher=fetch, scan_fn=None if default_scan else scan)
        expected_calls = ["provider", "reference"] + ([] if failure == "reference" else ["scan"])
        self.assertEqual(calls, expected_calls, "split callback forwarding/order")
        extra_reference.assert_not_called()
        if failure:
            self.assertEqual(row["status"], "error")
            self.assertIn("LedgerError: fixture " + failure + " terminal", row["error"])
            self.assertEqual(before, {str(path.relative_to(bank)): path.read_bytes()
                                      for path in bank.rglob("*") if path.is_file()})
        elif default_scan:
            # A one-session fixture is deliberately insufficient split evidence.
            self.assertEqual(row["status"], "error")
            self.assertIn("candidate detection is not usable", row["error"])
            self.assertEqual(before, {str(path.relative_to(bank)): path.read_bytes()
                                      for path in bank.rglob("*") if path.is_file()})
        else:
            self.assertEqual(row["status"], "refreshed")
            identity = cache.manifest_identity(bank, "TEST", provider_symbol="TEST-ALIAS")
            self.assertEqual(cache.load_cache(bank, identity)["status"], "ok")
            # Only the split-cache namespace may be added by this fixture path.
            after = {str(path.relative_to(bank)): path.read_bytes()
                     for path in bank.rglob("*") if path.is_file()}
            self.assertEqual({k: v for k, v in after.items() if k in before}, before)
            self.assertTrue(all(Path(k).parts[0] == "_split_history" for k in set(after) - set(before)))
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})
        print("A44_SPLIT_CALLBACKS", "batch" if batch else "single",
              failure or ("default-scan" if default_scan else "injected-success"), calls)

