    def test_d2_combined_month_refetch_uses_both_guarded_producers(self):
        combined, bank, adapter, transport, reference = self.combined_fixture()
        days = [date(2026, 6, number) for number in range(1, 31)
                if self.authority.window("1m", date(2026, 6, number)) is not None]
        self.assertGreaterEqual(len(days), 20)
        minute_rows = [(datetime.combine(day, time(9, 30)), 10, 11, 9, 10, 100)
                       for day in days]
        daily_rows = [(datetime.combine(day, time()), 10, 11, 9, 10, 100)
                      for day in days]
        anomaly = days[len(days) // 2]
        stored_daily = [(stamp, 10, 21, 9, 20, 100) if stamp.date() == anomaly
                        else (stamp, 10, 11, 9, 10, 100)
                        for stamp, *_ in daily_rows]
        manifest = ib.ss.load_manifest(bank / "TEST")
        for token, rows in (("1m", minute_rows), ("1d", stored_daily)):
            path = ib.ss.month_file_path(bank, "TEST", 2026, 6, token)
            ib.ss.manifest_months(manifest, token)["2026-06"] = dict(
                ib.ss.write_month_file(path, rows), status="present")
        ib.ss.save_manifest(bank / "TEST", manifest)
        derived = combined.sv.derive_daily(combined.sv.read_series(bank, "TEST", "1m"))
        clean = {day.isoformat(): values for day, values in derived.items()}
        initial = dict(clean)
        initial[anomaly.isoformat()] = (10, 21, 9, 20, 100)
        internal = combined.sv.parse_ibkr_daily_reference(
            combined.sv.read_series(bank, "TEST", "1d"))
        self.assertIn(anomaly.isoformat(), combined.sv.combined_double_flag(
            derived, initial, internal))
        raw_minute = [bar(stamp.replace(tzinfo=NY)) for stamp, *_ in minute_rows]
        raw_daily = [SimpleNamespace(date=day, open=10, high=11, low=9,
                                     close=10, volume=100) for day in days]
        def request(contract, **kwargs):
            transport.calls.append(("bars", contract.conId, kwargs))
            return raw_minute if kwargs["barSizeSetting"] == "1 min" else raw_daily
        self.patch(transport, "reqHistoricalDataAsync", side_effect=request)
        calls = []
        def external(_ticker, _rng):
            calls.append(1)
            return initial if len(calls) == 1 else clean
        result = combined.run_combined_flags(bank, ports=[2000],
            adapter_factory=lambda _: adapter, reference_fn=external,
            progress=lambda _: None, _test_capability=self.capability)
        row = result["results"][0]
        self.assertEqual(row["candidates"], [anomaly.isoformat()], row)
        self.assertEqual(row["cleared"], [anomaly.isoformat()], row)
        self.assertEqual(row["persistent"], [])
        self.assertEqual(row["status"], "ok")
        self.assertEqual(len(row["refetch_coverage"]), 1)
        self.assertTrue(row["refetch_coverage"][0]["full_month"])
        events = self.rows_from_context_path(result["fetch_ledger"]["path"])
        self.assertEqual({event["producer_id"] for event in events
                          if event["event"] == "decision"},
                         {QUALIFY, combined._MINUTE, combined._DAILY})
        self.assertTrue(result["fetch_ledger"]["verified"])
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})

        saved = (bank / "_combined_flags.json").read_bytes()
        adapter.ib = transport
        self.fixture_now = datetime(2026, 6, 15, 13, 20, tzinfo=NY)
        calls.clear()
        partial = combined.run_combined_flags(bank, ports=[2000],
            adapter_factory=lambda _: adapter, reference_fn=external,
            progress=lambda _: None, _test_capability=self.capability)
        self.assertEqual(partial["status"], "partial")
        self.assertEqual(partial["results"][0]["status"], "inconclusive")
        self.assertFalse(partial["results"][0]["_verification_current"])
        self.assertFalse(partial["fetch_ledger"]["verified"])
        partial_saved = (bank / "_combined_flags.json").read_bytes()
        self.assertNotEqual(partial_saved, saved)

        self.fixture_now = datetime(2026, 7, 2, 17, tzinfo=NY)
        adapter.ib = transport
        terminal = LedgerError("terminal combined minute response")
        calls.clear()
        def failed_request(pinned, **kwargs):
            if kwargs["barSizeSetting"] == "1 min":
                raise terminal
            return request(pinned, **kwargs)
        with patch.object(transport, "reqHistoricalDataAsync", side_effect=failed_request), \
                self.assertRaises(LedgerError) as caught:
            combined.run_combined_flags(bank, ports=[2000],
                adapter_factory=lambda _: adapter, reference_fn=external,
                progress=lambda _: None, _test_capability=self.capability)
        self.assertIs(caught.exception, terminal)
        self.assertFalse(caught.exception.fetch_ledger["verified"])
        self.assertEqual((bank / "_combined_flags.json").read_bytes(), partial_saved)
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})

