    def temporary_diagnostic_fixture(self, rows_by_size):
        """Raw-only IBKR fixture; shipped diagnostic bodies do all bank work."""
        from fetch_ibkr_integration_selftest import ib_contract
        import platform
        import sys
        created = self.root_fixture()
        self.patch(platform, "machine", return_value="AMD64")
