    def test_d2_pipeline_tree_inverse_is_partial_with_original_scrub(self):
        import contextlib
        import io
        import live_pipeline_check as pipeline
        self.fixture_now = datetime(2026, 6, 15, 17, tzinfo=NY)
        minute = [bar(datetime(2026, 5, 1, 9, 30, tzinfo=NY) + timedelta(minutes=n))
                  for n in range(60)]
