    def test_d2_temporary_fill_refusal_stops_comparison_and_second_fill(self):
        import contextlib
        import io
        import live_internal_daily_check as daily
        import live_pipeline_check as pipeline
        for module, clock in ((daily, datetime(2026, 7, 2, 17, tzinfo=NY)),
                              (pipeline, datetime(2026, 6, 15, 17, tzinfo=NY))):
            with self.subTest(module=module.__name__):
                self.fixture_now = clock
                _, adapters, transports, base_factory = self.temporary_diagnostic_fixture(
                    {"1 day": [bar(date(2026, 5, 1))]})
                refused = []
                def factory():
                    adapter = base_factory()
                    raw = adapter.ib
                    original = raw.reqHistoricalDataAsync
                    def request(c, **kwargs):
                        if kwargs["barSizeSetting"] == "1 min":
                            refused.append(kwargs)
                            raise ib.RequestRefused("minute send refused")
                        return original(c, **kwargs)
                    raw.reqHistoricalDataAsync = request
                    return adapter
                output = io.StringIO()
                root = (daily.run_internal_daily_check if module is daily
                        else pipeline.run_pipeline_check)
                with patch.object(daily.sv, "internal_crosscheck",
                        side_effect=AssertionError("classifier after terminal halt")), \
                        contextlib.redirect_stdout(output), \
                        self.assertRaisesRegex(ib.RequestRefused, "fill halted") as caught:
                    root(adapter_factory=factory, _test_capability=self.capability)
                self.assertTrue(refused)
                self.assertEqual(len(adapters), 2, output.getvalue())
                self.assertFalse(caught.exception.fetch_ledger["verified"])
                if module is pipeline:
                    self.assertNotIn("[2/2]", output.getvalue())
                self.assertEqual(op._OPERATIONS, {})
                self.assertEqual(op._CHILDREN, {})

