    def test_d2_internal_request_durability_matrix(self):
        diagnostic, bank, adapter, transport = self.internal_fixture(mismatch=True)
        create = FetchRunContext.create
        for attempt in (1, 2, 3):
            for event in ("decision", "result"):
                for stage in ("append", "flush", "fsync"):
                    with self.subTest(attempt=attempt, event=event, stage=stage):
                        adapter.ib = transport
                        transport.calls.clear()
                        seen = []
                        def fault(kind, phase):
                            if (kind, phase) == (event, stage):
                                seen.append(1)
                                if len(seen) == attempt:
                                    raise OSError("internal diagnostic durability witness")
                        with patch.object(FetchRunContext, "create", side_effect=lambda directory, **kw:
                                create(directory, fault=fault, **kw)), self.assertRaises(LedgerError) as caught:
                            diagnostic.run_internal_revalidate(bank, ports=[2000],
                                adapter_factory=lambda _: adapter, progress=lambda _: None,
                                _test_capability=self.capability)
                        self.assertEqual(len(seen), attempt)
                        self.assertEqual(len(transport.calls), attempt - (event == "decision"))
                        self.assertFalse((bank / "_internal_validation.json").exists())
                        self.assertFalse(caught.exception.fetch_ledger["verified"])
                        self.assertEqual(op._CHILDREN, {})
                        self.assertEqual(op._OPERATIONS, {})
        self.assertTrue(all(lease.released for lease in self.fixture_leases))

