    def test_d2_internal_multiport_one_parent_and_clock(self):
        diagnostic, bank, adapter, transport = self.internal_fixture()
        manifest = ib.ss.new_manifest("OTHER", "OTHER")
        manifest["conid"] = 123
        bars = diagnostic.sv.read_series(bank, "TEST", "1m")
        values = bars
        path = ib.ss.month_file_path(bank, "OTHER", 2026, 7, "1m")
        info = ib.ss.write_month_file(path, values)
        info["status"] = "present"
        ib.ss.manifest_months(manifest, "1m")["2026-07"] = info
        ib.ss.save_manifest(bank / "OTHER", manifest)
        # Distinct connected sessions, same verified account and governor.
        other = ib.LiveIB()
        other.ib = RawIB()
        other.ib.reqHistoricalDataAsync = transport.reqHistoricalDataAsync
        other.ib.disconnect = lambda: None
        other._await = adapter._await
        barrier = threading.Barrier(2)
        def factory(port):
            barrier.wait(timeout=5)
            return adapter if port == 2000 else other
        result = diagnostic.run_internal_revalidate(bank, ports=[2000, 3000], days=3,
            adapter_factory=factory, progress=lambda _: None, _test_capability=self.capability)
        self.assertEqual({r["ticker"] for r in result["results"]}, {"TEST", "OTHER"})
        self.assertTrue(result["fetch_ledger"]["verified"], result)
        self.assertEqual({r["operation_id"] for r in result["results"]},
                         {result["fetch_ledger"]["operation_id"]})
        self.assertEqual({r["asof"] for r in result["results"]}, {"2026-07-02T17:00:00-04:00"})
        events = self.rows_from_context_path(result["fetch_ledger"]["path"])
        self.assertEqual(len([r for r in events if r["event"] == "decision"]), 4)
        self.assertEqual(events[-1]["event"], "seal")
        self.assertEqual(op._CHILDREN, {})

    def test_d2_internal_daily_settlement_and_unsupported(self):
        diagnostic, bank, adapter, transport = self.internal_fixture()
        rows = dict(self.authority.rows)
        rows[date(2026, 7, 2)] = replace(rows[date(2026, 7, 2)], status="open_early_close", close=time(13))
        self.authority = replace(self.authority, rows=rows)
        for clock, days, day, permitted in [
                (datetime(2026, 7, 2, 13, 20, tzinfo=NY), 1, date(2026, 7, 2), False),
                (datetime(2026, 7, 2, 16, 20, tzinfo=NY), 1, date(2026, 7, 2), True),
                (datetime(2026, 7, 2, 17, tzinfo=NY), 1, date(1979, 12, 30), False)]:
            run = self.open("diagnostic", clock=lambda: clock)
            child = self.child(run, "daily", rights={diagnostic._DAILY})
            transport.calls.clear()
            adapter.ib = transport
            with self.subTest(clock=clock, day=day):
                if permitted:
                    _, coverage = diagnostic._internal_daily(adapter, contract(),
                        datetime.combine(day, time(16), NY), days, _fetch_child=child)
                    self.assertEqual(coverage["decision"], "clamped")
                    self.assertTrue(coverage["effective"]["intended_end"].startswith("2026-07-02"))
                    self.assertEqual(len(transport.calls), 1)
                else:
                    with self.assertRaises(AuthorityError):
                        diagnostic._internal_daily(adapter, contract(),
                            datetime.combine(day, time(16), NY), days, _fetch_child=child)
                    self.assertEqual(transport.calls, [])
            run.close()

