    def open(self, purpose="nightly", **options):
        capability = options.pop("test_capability", self.capability)
        value = op.begin_operation(purpose, options.pop("evidence_dir", self.root / "ledgers"),
            authority=self.authority,
            clock=options.pop("clock", lambda: datetime(2026, 8, 4, 17, tzinfo=NY)),
            test_capability=capability, **options)
        self.runs.append(value)
        return value

    def child(self, run, name="worker", **kwargs):
        child = run.child(name, **kwargs)
        self.children.append(child)
        return child

    def request(self, worker, producer=QUALIFY):
        return worker.request(producer, {"variant": "ibkr-metadata",
            "symbol": "TEST", "con_id": 0,
            "method": "symbol_search" if producer == SEARCH else "qualification"})

    def metadata_fixture(self):
        self.virtual_time = 0.0
        def sleep(seconds, cancel=None):
            if cancel is not None and cancel.is_set():
                raise ib.Cancelled()
            self.virtual_time += seconds
        registry = governors.GovernorRegistry(time_fn=lambda: self.virtual_time, sleep_fn=sleep)
        adapter = ib.LiveIB()
        adapter.ib = RawIB()
        adapter._await = lambda value, timeout, description: value
        hits = [SimpleNamespace(contract=contract("ZED", 456), companyName="Zed Inc.")]
        def search(text):
            adapter.ib.calls.append(("search", text, self.virtual_time))
            return hits
        def details(pinned):
            adapter.ib.calls.append(("details", pinned.conId))
            return [SimpleNamespace(longName=" Test Company ", contract=pinned)]
        adapter.ib.reqMatchingSymbols = search
        adapter.ib.reqContractDetailsAsync = details
        adapter.ib.disconnect = lambda: None
        return registry, adapter, hits

    def legacy_probe_fixture(self, legacy):
        """Keep legacy scenarios; only raw transport and fake leases are injected.

        No policy is minted here: the existing Operations.setUp/open owner is
        used. Fixed shipped fetch methods, their children and all ledger/result
        consumers execute unchanged, including when a legacy callback fails.
        """
        import operation_gate
        import platform
        from fetch_ibkr_integration_selftest import ib_contract
        self.root_fixture()
        self.patch(platform, "machine", return_value="offline")
        modules = patch.dict("sys.modules", {"ib_async": SimpleNamespace(Contract=ib_contract)})
        modules.start(); self.addCleanup(modules.stop)
        held, leases = {}, []
        def acquire(mode, *, owner=None, path=None, **kwargs):
            self.assertIsNotNone(path, "legacy test attempted the production lease path")
            key = Path(path).resolve()
            self.assertTrue(key.is_relative_to(self.root), "legacy lease escaped temporary custody")
            if key in held:
                raise operation_gate.OperationBusy("offline conflicting lease")
            class Lease(nullcontext):
                released = False
                def release(lease):
                    held.pop(key, None)
                    lease.released = True
                def __exit__(lease, *args):
                    lease.release()
                    return False
            lease = Lease()
            held[key] = lease
            leases.append(lease)
            return lease
        self.patch(operation_gate, "acquire", side_effect=acquire)
        self.patch(operation_gate, "status", side_effect=lambda *, path:
                   {"available": Path(path).resolve() not in held})
        def raw_bars(rows, *, daily):
            return [SimpleNamespace(date=(row[0].date() if daily and isinstance(row[0], datetime)
                                    else row[0].replace(tzinfo=NY)
                                    if isinstance(row[0], datetime) and row[0].tzinfo is None else row[0]),
                                    open=row[1], high=row[2], low=row[3],
                                    close=row[4], volume=row[5]) for row in rows]
        original_root = probe.run_live_probe
        last_live = []
        def run(root, **kwargs):
            last_live.clear()
            self.assertTrue(Path(root).resolve().is_relative_to(self.root),
                            "legacy request escaped temporary bank custody")
            self.fixture_now = kwargs.get("now") or legacy.FIXED_NOW
            fake = kwargs.pop("live_fetcher", None)
            daily = kwargs.get("interval", "1m") != "1m"
            if fake is None:
                fake = legacy.FakeDailySpanFetcher() if daily else legacy.FakeLiveFetcher()
            self.assertIsInstance(fake, (legacy.FakeLiveFetcher, legacy.FakeDailySpanFetcher))
            registry, adapter, _ = self.metadata_fixture()
            raw = adapter.ib
            adapter.port, adapter.client_id = 2000, 7315
            current = {}
            def history(pinned, **fields):
                raw.calls.append(("bars", pinned.conId, fields))
                callback = fake.fetch_span if daily else fake.fetch_day
                result = bridge.without_authority(callback)(current["snapshot"])
                rows = []
                for index, (stamp, close) in enumerate(result["closes"].items()):
                    timestamp = (datetime.combine(date.fromisoformat(stamp), time.min) if daily
                                 else datetime.combine(date.fromisoformat(current["snapshot"]["day"]),
                                                       time.fromisoformat(stamp)))
                    rows.append((timestamp, close, close, close, close,
                                 result.get("volume", 0) if index == 0 else 0))
                return raw_bars(rows, daily=daily)
            raw.reqHistoricalDataAsync = history
            raw.disconnect = fake.close
            def factory():
                try:
                    fake.start()
                except BaseException:
                    fake.close()
                    raise
                return adapter
            cls = probe.IBKRDailySpanFetcher if daily else probe.IBKRMinuteDayFetcher
            method_name = "fetch_span" if daily else "fetch_day"
            shipped = getattr(cls, method_name)
            def capture(fetcher, snapshot, **child):
                current["snapshot"] = snapshot
                value = shipped(fetcher, snapshot, **child)
                last_live.append(value)
                return value
            fetcher = cls(adapter_factory=factory, ibkr_module=ib, pacer=legacy._FakePacer())
            with patch.object(governors, "_REGISTRY", registry), patch.object(cls, method_name, capture):
                return original_root(root, live_fetcher=fetcher,
                    evidence_dir=self.root / "legacy-ledgers", _test_capability=self.capability, **kwargs)
        self.patch(probe, "run_live_probe", side_effect=run)

        # The embedded cases have an already-open parent, exactly as the
        # production scheduler must. Their no-open/no-bank-write traps remain
        # installed: only the existing ledger stream may append/fsync, and no
        # embedded call starts/closes a connection or acquires a Bank lease.
        embedded_registry, _, _ = self.metadata_fixture()
        embedded_parent = self.open("repair", governors=embedded_registry,
            clock=lambda: legacy.FIXED_NOW)
        original_embedded = probe.run_embedded_probe
        embedded_calls = []
        def embedded(root, **kwargs):
            fake = kwargs.get("live_fetcher")
            if fake is None or kwargs.get("live_evidence") is not None:
                return original_embedded(root, **kwargs)
            self.assertTrue(Path(root).resolve().is_relative_to(self.root),
                            "legacy embedded request escaped temporary custody")
            self.assertIsInstance(fake, (legacy.FakeLiveFetcher, legacy.FakeDailySpanFetcher))
            kwargs = dict(kwargs)
            kwargs.pop("live_fetcher")
            daily = kwargs.get("interval", "1m") != "1m"
            _, adapter, _ = self.metadata_fixture()
            adapter.port, adapter.client_id = 2000, 7315
            current = {}
            def history(pinned, **fields):
                adapter.ib.calls.append(("bars", pinned.conId, fields))
                callback = fake.fetch_span if daily else fake.fetch_day
                value = bridge.without_authority(callback)(current["snapshot"])
                rows = []
                for index, (stamp, close) in enumerate(value["closes"].items()):
                    timestamp = (datetime.combine(date.fromisoformat(stamp), time.min) if daily
                        else datetime.combine(date.fromisoformat(current["snapshot"]["day"]),
                                              time.fromisoformat(stamp)))
                    rows.append((timestamp, close, close, close, close,
                                 value.get("volume", 0) if index == 0 else 0))
                return raw_bars(rows, daily=daily)
            adapter.ib.reqHistoricalDataAsync = history
            cls = probe.IBKRDailySpanFetcher if daily else probe.IBKRMinuteDayFetcher
            name = "fetch_span" if daily else "fetch_day"
            shipped = getattr(cls, name)
            def capture(fetcher, snapshot, **options):
                current["snapshot"] = snapshot
                return shipped(fetcher, snapshot, **options)
            embedded_calls.append(True)
            with patch.object(cls, name, capture):
                return original_embedded(root, adapter=adapter, pacer=legacy._FakePacer(),
                    _fetch_child=self.child(embedded_parent, f"legacy-embedded-{len(embedded_calls)}"),
                    **kwargs)
        self.patch(probe, "run_embedded_probe", side_effect=embedded)

        def reusable(root, snapshot):
            source = run(root, ticker=snapshot["ticker"], day=snapshot["day"],
                interval=snapshot.get("interval", "1m"),
                run_logs_root=self.root / "legacy-reuse-artifacts",
                gate_path=self.root / "legacy-reuse.lock")
            self.assertTrue(source["fetch_ledger"]["verified"])
            self.assertEqual(len(last_live), 1)
            return dict(probe._public_snapshot(snapshot), read_only=True, used_for_commit=False,
                fetched_after_boundary=True, live_result=last_live[0])
        self.patch(legacy, "_reusable_evidence", new=reusable)

        def physical(snapshot, rows, *, error=None):
            registry, adapter, _ = self.metadata_fixture()
            raw = adapter.ib
            daily = snapshot.get("interval", "1m") != "1m"
            raw.rows = raw_bars(rows, daily=daily)
            if error is not None:
                raw.failures.append(error)
            closed = []
            raw.disconnect = lambda: closed.append(True)
            adapter.port, adapter.client_id, adapter.use_rth = 2000, 7315, False
            private = legacy._FakePacer()
            cls = probe.IBKRDailySpanFetcher if daily else probe.IBKRMinuteDayFetcher
            fetcher = cls(adapter_factory=lambda: adapter, ibkr_module=ib, pacer=private)
            run = self.open("diagnostic", governors=registry, clock=lambda: legacy.FIXED_NOW)
            outcome = SimpleNamespace(result=None, error=None)
            original_turn = governors.Governor.wait_turn
            with patch.object(governors.Governor, "wait_turn", autospec=True,
                              side_effect=original_turn) as turns, \
                    patch.object(ib, "split_session_bars", wraps=ib.split_session_bars) as parser:
                fetcher.start()
                try:
                    method = fetcher.fetch_span if daily else fetcher.fetch_day
                    outcome.result = method(snapshot, _fetch_child=self.child(run))
                except Exception as exc:
                    outcome.error = exc
                finally:
                    fetcher.close()
                run.seal()
                outcome.turns = turns.call_args_list
                outcome.parser_tokens = [call.args[3] for call in parser.call_args_list]
            outcome.sends = [call for call in raw.calls if call[0] == "bars"]
            outcome.private_turns = private.calls
            outcome.restored = adapter.use_rth is False
            outcome.disconnected = closed == [True] and adapter.ib is None
            outcome.events = inspect_ledger(run.context.ledger.path)["events"]
            run.close()
            return outcome
        self.patch(legacy, "_physical_fetch", new=physical)
        return held, leases, embedded_parent

