    def assert_legacy_minute_surface(self, filename):
        import contextlib
        import io
        import live_spot_probe_selftest as legacy
        path = Path(probe.__file__).with_name(filename)
        source = path.read_text(encoding="utf-8")
        original_read = Path.read_text
        label = "surface: automatic Fix/Add callers remain explicitly minute-only"
        variants = (
            ("control", source, False),
            ("missing", source.replace("live_spot_probe.run_embedded_probe(",
                                        "live_spot_probe.not_automatic(", 1), True),
            ("daily", source.replace('interval="1m"', 'interval="1d"', 1), True),
            ("duplicate", source + '\nlive_spot_probe.run_embedded_probe(interval="1m")\n', True))
        saved_fails, saved_total = legacy.FAILS[:], legacy.TOTAL[0]
        try:
            for name, candidate, refused in variants:
                if refused:
                    self.assertNotEqual(candidate, source)
                def read(target, *args, **kwargs):
                    return candidate if target == path else original_read(target, *args, **kwargs)
                legacy.FAILS.clear()
                legacy.TOTAL[0] = 0
                with self.subTest(case=name), patch.object(Path, "read_text", read), \
                        contextlib.redirect_stdout(io.StringIO()):
                    legacy.source_boundary()
                    self.assertEqual(legacy.FAILS, [label] if refused else [])
        finally:
            legacy.FAILS[:] = saved_fails
            legacy.TOTAL[0] = saved_total

