    def auxiliary_case(self, name, folder, adapter, factory=None):
        """Drive shipped roots, never substitute their worker orchestration."""
        kwargs = dict(adapter_factory=factory if factory is not None else ib.ReusableAdapter(lambda: adapter),
                      evidence_dir=folder, _test_capability=self.capability)
        if name == "doctor":
            adapter.ib.rows = [bar(datetime(2026, 8, 4, 15, 59, tzinfo=NY))]
            return ib.doctor(probe_fn=lambda *a: True, import_fn=lambda: "offline", **kwargs)
        if name == "find_symbol":
            return ib.find_symbol("Test Company", **kwargs)
        if name == "company_lookup":
            return ib.company_lookup("TEST", **kwargs)
        if name == "validate_symbols":
            return ib.validate_symbols(["TEST"], **kwargs)
        if name == "estimate_backfill":
            adapter.ib.rows = [bar(date(2026, 7, 8))]
            return ib.estimate_backfill("TEST", "1d", **kwargs)
        if name == "probe_max_span":
            adapter.ib.rows = [bar(datetime(2026, 8, 4, 15, 59, tzinfo=NY))]
            return ib.probe_max_span("1m", **kwargs)
        raise AssertionError(name)

