    def test_concurrent_metadata_search_shares_one_account_budget_across_ports(self):
        registry, adapter, _ = self.metadata_fixture()
        another = ib.LiveIB()
        another.ib, another.port = adapter.ib, 1002
        first = self.open("identity", governors=registry)
        second = self.open("identity", governors=registry)
        barrier = threading.Barrier(2)
        failures, outputs = [], []
        def work(child, target):
            try:
                barrier.wait(5)
                outputs.append(self.metadata_search(child, target))
            except BaseException as exc:
                failures.append(exc)
        threads = [threading.Thread(target=copy_context().run, args=(work, self.child(run), target))
                   for run, target in ((first, adapter), (second, another))]
        for thread in threads:
            thread.start()
        for thread in threads:
            thread.join(5)
        self.assertFalse(any(thread.is_alive() for thread in threads))
        self.assertEqual(failures, [])
        self.assertEqual(len(outputs), 2)
        self.assertEqual(sorted(call[2] for call in adapter.ib.calls), [0.0, 1.0])
        self.assertEqual(len(registry.ibkr(["TEST-ACCOUNT"])._pacer._burst), 2)
        for run in (first, second):
            run.seal()
            events = inspect_ledger(run.context.ledger.path)["events"]
            self.assertEqual(sum(event["event"] == "decision" for event in events), 1)
            self.assertEqual(sum(event["event"] == "result" for event in events), 1)

