    def test_search_dispatch_lock_cancellation_does_not_reserve(self):
        registry, adapter, _ = self.metadata_fixture()
        run = self.open("identity", governors=registry)
        child = self.child(run)
        governor = registry.ibkr(["TEST-ACCOUNT"])
        cancel, inspected = threading.Event(), threading.Event()
        failures = []
        class Cancel:
            def is_set(self):
                inspected.set()
                return cancel.is_set()
        def work():
            try:
                self.metadata_search(child, adapter, cancel=Cancel())
            except BaseException as exc:
                failures.append(exc)
        with governor.search_dispatch_window():
            thread = threading.Thread(target=copy_context().run, args=(work,))
            thread.start()
            self.assertTrue(inspected.wait(5))
            cancel.set()
            thread.join(5)
            self.assertFalse(thread.is_alive())
        self.assertEqual(len(failures), 1)
        self.assertIsInstance(failures[0], ib.Cancelled)
        self.assertEqual(adapter.ib.calls, [])
        self.assertEqual(len(governor._pacer._burst), 0)
        run.seal()

