    def test_d06_older_head_thirty_year_floor_and_expanded_max_send(self):
        from fetch_envelopes import carrier_start
        registry, adapter, _ = self.metadata_fixture()
        adapter.ib.head = datetime(1980, 1, 2, 9, 30, tzinfo=NY)
        adapter.ib.rows = [bar(date(1996, 8, 5))]
        today = date(2026, 8, 4)
        run = self.open("diagnostic", governors=registry,
                        clock=lambda: datetime(2026, 8, 4, 17, tzinfo=NY))

        @bridge.worker_scope
        def head_body():
            return ib._head_start_evidence(adapter, contract(), None, today)

        start, note, served = head_body(_fetch_child=self.child(run, "head"))
        self.assertEqual((start, note, served),
                         (date(1980, 1, 2), None, date(1996, 8, 5)))
        head_sends = [call[2] for call in adapter.ib.calls if call[0] == "bars"]
        self.assertEqual(len(head_sends), 1)
        self.assertEqual(head_sends[0]["durationStr"], ib.HEAD_PROBE_DURATION)
        self.assertGreaterEqual(carrier_start(head_sends[0]["endDateTime"],
                                            head_sends[0]["durationStr"]).date(),
                                self.authority.first_date)

        # "Max" is not a wire duration: an old-head caller expands it to a
        # bounded year carrier, which the real choke point narrows further.
        adapter.ib.rows = [bar(date(1980, 12, 2))]
        raw_end = datetime(2026, 8, 4, 23, 59)
        old_start = datetime(1980, 12, 2)

        @bridge.worker_scope
        def max_body():
            request = bridge.bar_request("ibkr.gap_fill.head_daily_probe",
                contract(), "1d", raw_end, "60 Y", start=old_start)
            with bridge.send_scope(request, bridge.acquire_turn):
                return adapter.fetch(contract(), raw_end, "60 Y", "1 day")

        self.assertEqual(len(max_body(_fetch_child=self.child(run, "max"))), 1)
        run.seal()
        sends = [call[2] for call in adapter.ib.calls if call[0] == "bars"]
        self.assertEqual(len(sends), 2)
        self.assertGreaterEqual(carrier_start(sends[1]["endDateTime"],
                                            sends[1]["durationStr"]).date(),
                                self.authority.first_date)
        self.assertNotEqual(sends[1]["durationStr"], "60 Y")
        events = inspect_ledger(run.context.ledger.path)["events"]
        decisions = [row for row in events if row["event"] == "decision"
                     and row["producer_id"] == "ibkr.gap_fill.head_daily_probe"]
        results = [row for row in events if row["event"] == "result"
                   and row["producer_id"] == "ibkr.gap_fill.head_daily_probe"]
        self.assertEqual((len(decisions), len(results)), (2, 2))
        self.assertEqual(decisions[-1]["payload"]["requested"]["intended_start"],
                         old_start.replace(tzinfo=NY).isoformat())
        self.assertEqual(results[-1]["payload"]["accepted"]["count"], 1)
        print("D06_CALENDAR_EDGE", json.dumps({"head": start.isoformat(),
            "probe_floor": ib._head_probe_floor(today).isoformat(),
            "served": served.isoformat(), "max_transport": sends[1]["durationStr"],
            "max_start": old_start.date().isoformat()}, sort_keys=True))

