    def test_auxiliary_disconnect_callback_and_descriptor_are_observers(self):
        self.root_fixture()
        run = self.open("identity")
        child = self.child(run)
        checked = []
        def witness(label):
            self.assertIsNone(bridge.current_worker())
            with self.assertRaises(AuthorityError):
                child.worker()
            with self.assertRaises(AuthorityError):
                self.open()
            checked.append(label)
        class Adapter:
            @property
            def disconnect(self):
                witness("descriptor")
                return lambda: witness("callback")
        with child.scope():
            ib._auxiliary_disconnect(Adapter())
        self.assertEqual(checked, ["descriptor", "callback"])
        child.close(); run.seal()
        class Broken:
            def disconnect(self):
                raise LedgerError("cleanup guard remains terminal")
        with self.assertRaises(LedgerError):
            ib._auxiliary_disconnect(Broken())

