    def test_estimate_calendar_and_first_month_carriers_all_applicable_tokens(self):
        from fetch_authority import TOKENS, parse_token
        from fetch_envelopes import carrier_start, decide
        dates = [date(1980, 1, 2), date(1980, 1, 3), date(1980, 1, 31),
                 date(2024, 2, 29), date(2024, 3, 8), date(2024, 3, 11),
                 date(2025, 12, 23), date(2025, 12, 24), date(2025, 12, 25), date(2025, 12, 26)]
        run = self.open("diagnostic", clock=lambda: datetime(2026, 8, 4, 17, tzinfo=NY))
        @bridge.worker_scope
        def body(token):
            notes = {}
            days = ib._settled_plan_days(token, dates, notes)
            spans = ib._estimate_covered_spans(token, days, run.context)
            for first, last, duration in spans:
                request = bridge.bar_request("ibkr.stock_ibkr.span_probe", contract(), token,
                                             last, duration, start=first)
                decision = decide(request.envelope, run.context.authority, run.context.horizons,
                                  captured_now=run.context.captured_now)
                self.assertEqual(decision.state, "allowed", (token, first, last, duration, decision.reason))
            return days, notes, spans
        for index, token in enumerate(TOKENS):
            base, _, session = parse_token(token)
            if base.endswith("s") or (base == "1d" and session != "rth"):
                continue
            with self.subTest(token=token):
                days, notes, spans = body(token, _fetch_child=self.child(run, str(index)))
                self.assertNotIn(date(2025, 12, 25), days)
                self.assertIn("2025-12-25", notes["calendar_closed_days"])
                if session != "rth":
                    self.assertIn("2025-12-24", notes["calendar_unsupported_days"])
                for first, last, duration in spans:
                    self.assertGreaterEqual(carrier_start(last, duration).date(), date(1980, 1, 2))
                    self.assertLessEqual(carrier_start(last, duration), first)
        run.seal()

