        first = self.open("identity", governors=registry)
        second = self.open("identity", governors=registry)
        output = self.metadata_search(self.child(first), adapter, "  Test Company  ")
        another = ib.LiveIB()
        another.ib, another.port = adapter.ib, 1002
        self.metadata_search(self.child(second), another)
        self.assertEqual(adapter.ib.calls, [("search", "Test Company", 0.0),
                                            ("search", "Test Company", 1.0)])
        governor = registry.ibkr(["TEST-ACCOUNT"])
        self.assertEqual(len(governor._pacer._burst), 2)
        self.assertEqual(len(governor._pacer._stamps), 0)
        hits[0].contract.symbol = "MUTATED"
        self.assertEqual(output[0]["symbol"], "ZED")
        for run, waited in ((first, 0.0), (second, 1.0)):
            run.seal()
            events = inspect_ledger(run.context.ledger.path)["events"]
            decisions = [row for row in events if row["event"] == "decision"]
            results = [row for row in events if row["event"] == "result"]
            self.assertEqual(len(decisions), 1)
            self.assertEqual(len(results), 1)
            self.assertEqual(decisions[0]["payload"]["pacer_wait_seconds"], waited)

