            with self.subTest(scenario=scenario):
                registry, adapter, _ = self.metadata_fixture()
                def fault(event, stage):
                    if scenario == "result-fault" and event == "result" and stage == "fsync":
                        raise OSError("company result fault")
                run = self.open("identity", governors=registry, fault=fault)
                if scenario == "wrong-identity":
                    adapter.ib.reqContractDetailsAsync = lambda _: [
                        SimpleNamespace(longName="Wrong company", contract=contract("OTHER", 999))]
                elif scenario == "wrong-tail":
                    adapter.ib.reqContractDetailsAsync = lambda _: [
                        SimpleNamespace(longName="Valid first", contract=contract()),
                        SimpleNamespace(longName="Wrong later identity", contract=contract("OTHER", 999))]
                elif scenario == "ordinary-unavailable":
                    def unavailable(_):
                        raise ConnectionError("ordinary metadata unavailable")
                    adapter.ib.reqContractDetailsAsync = unavailable
                @bridge.worker_scope
                def body():
                    request = bridge.metadata_request("company_name", "TEST", 123)
                    with bridge.send_scope(request, bridge.acquire_turn):
                        return adapter.company_name("TEST", contract=contract())
                if scenario == "ordinary-unavailable":
                    self.assertEqual(body(_fetch_child=self.child(run)), "")
                    run.seal()
                else:
                    with self.assertRaises(LedgerError if scenario == "result-fault" else AuthorityError):
                        body(_fetch_child=self.child(run))

