    def test_new_and_a1_ledgers_use_same_schema_and_parser(self):
        fixture = json.loads((Path(__file__).parent / "fixtures" /
            "fetch_ledger_a1_schema1.json").read_text(encoding="utf-8"))
        fixture_path = self.root / "a1-era.jsonl"
        fixture_path.write_bytes(("\n".join(fixture["ledger_lines"]) + "\n").encode("utf-8"))
        fixture_path.with_suffix(".seal.json").write_text(json.dumps(fixture["receipt"]), encoding="utf-8")
        self.assertEqual(fixture["source_commit"], "8cb3cd2")
        self.assertTrue(inspect_ledger(fixture_path, require_seal=True)["verified"])
        run = self.open()
        context = run.context
        child = self.child(run)
        with child.scope():
            self.assertEqual(self.execute(self.request(child.worker())), {"con_id": 123})
        child.close(); run.seal()
        new = inspect_ledger(context.ledger.path, require_seal=True)
        old = FetchRunContext.create(self.root / "old", authority=self.authority,
            clock=lambda: datetime(2026, 8, 4, 17, tzinfo=NY))
        self.addCleanup(old.ledger.close)
        self.execute(self.request(old.worker("worker"))); old.seal()
        previous = inspect_ledger(old.ledger.path, require_seal=True)
        self.assertEqual(set(new), set(previous))
        for path in (old.ledger.path, context.ledger.path):
            events = [json.loads(line) for line in path.read_text().splitlines()]
            self.assertEqual([e["event"] for e in events], ["decision", "result", "seal"])
            self.assertEqual({e["schema_version"] for e in events}, {1})

