    def test_a1_consumer_requires_nightly_purpose_without_request_test_policy(self):
        # Independent consumer proof: retain the authentic guarded mint's
        # custody while removing activation from the context being consumed.
        # This prevents the root hold alone from masking the old purpose bug.
        for purpose in ("nightly", "add_stocks", "repair", "diagnostic"):
            run = self.open(purpose)
            object.__setattr__(run.context, "test_capability", None)
            child = self.child(run, purpose)
            sent = []
            with child.scope():
                if purpose == "nightly":
                    self.execute(self.request(child.worker()), lambda e: sent.append(1) or {})
                else:
                    with self.assertRaises(AuthorityError):
                        self.execute(self.request(child.worker()), lambda e: sent.append(1) or {})
                    # Dedicated inverse: wrong purpose returned by the actual
                    # consumer seam restores the forbidden A1 authorization.
                    with patch.object(op, "operation_purpose", lambda context: "nightly"):
                        self.execute(self.request(child.worker()), lambda e: sent.append(1) or {})
            self.assertEqual(sent, [1])

    def test_every_shared_id_intersects_purpose_with_valid_envelopes(self):
        self.assertEqual(set(tp.TEST_SHARED_PRODUCERS), set(op.PURPOSE_PRODUCERS["nightly"]))
        self.assertFalse(set(tp.TEST_SHARED_PRODUCERS) & set(tp.TEST_PRODUCERS))
        for purpose in ("nightly", "add_stocks", "repair", "diagnostic"):
            run = self.open(purpose)
            object.__setattr__(run.context, "test_capability", None)
            child = self.child(run, purpose)
            with child.scope():
                for producer, (variant, endpoint) in tp.TEST_SHARED_PRODUCERS.items():
                    raw = {"variant": variant, "symbol": "TEST", "con_id": 123}
                    if variant == "ibkr-metadata":
                        raw["method"] = "qualification"
                    else:
                        raw.update(what_to_show="TRADES", use_rth=True)
                    if variant == "ibkr-bars":
                        raw.update(token="1d", bar_size="1 day", duration="1 D",
                            raw_end=datetime(2026, 8, 3, 16, tzinfo=NY),
                            intended_start=datetime(2026, 8, 3, tzinfo=NY),
                            intended_end=datetime(2026, 8, 3, 16, tzinfo=NY))
                    sent = []
                    def send():
                        request = child.worker().request(producer, raw)
                        return self.execute(request, lambda e: sent.append(1) or
                            ([] if variant == "ibkr-bars" else {}))
                    with self.subTest(purpose=purpose, producer=producer):
                        if purpose == "nightly":
                            send()
                        else:
                            with self.assertRaises(AuthorityError):
                                send()
                            self.assertEqual(sent, [])
                            with patch.object(op, "operation_purpose", lambda context: "nightly"):
                                send()
                        self.assertEqual(sent, [1])

