    def test_concurrent_held_child_blocks_seal_and_close(self):
        run = self.open(); child = self.child(run)
        entered, release = threading.Event(), threading.Event()
        results = []
        def work():
            try:
                with child.scope():
                    entered.set()
                    if not release.wait(5):
                        raise AssertionError("worker release timed out")
                    results.append(self.execute(self.request(child.worker())))
            except BaseException as exc:
                results.append(exc)
        thread = threading.Thread(target=work); thread.start()
        try:
            self.assertTrue(entered.wait(5))
            for callback in (run.seal, run.close, child.close, run.context.ledger.seal):
                with self.assertRaises(AuthorityError):
                    callback()
        finally:
            release.set(); thread.join(5)
        self.assertFalse(thread.is_alive()); self.assertEqual(results, [{"con_id": 123}])
        child.close(); run.seal()

    def test_sibling_creation_never_takes_ledger_lock(self):
        run = self.open(); ledger = run.context.ledger; results = []
        # Real ledger lock held elsewhere: child registration must still finish.
        # This covers the lock-order inverse without leaving a deadlocked worker.
        def make_sibling():
            try:
                results.append(self.child(run, "sibling"))
            except BaseException as exc:
                results.append(exc)
        with ledger._lock:
            thread = threading.Thread(target=make_sibling); thread.start(); thread.join(1)
            completed_without_ledger = not thread.is_alive()
        thread.join(5)
        self.assertTrue(completed_without_ledger)
        self.assertFalse(thread.is_alive()); self.assertEqual(len(results), 1)
        self.assertIs(type(results[0]), op._ChildHandle)

    def test_seal_io_does_not_lock_unrelated_operations(self):
        entered, release, progressed = threading.Event(), threading.Event(), threading.Event()
        errors = []
        def fault(event, stage):
            if event == "seal" and stage == "fsync":
                entered.set()
                if not release.wait(5):
                    raise AssertionError("seal release timed out")
        held = self.open(fault=fault)
        other = self.open(); child = self.child(other, "unrelated")
        def seal():
            try:
                held.seal()
            except BaseException as exc:
                errors.append(exc)
        def use_other():
            try:
                with child.scope():
                    self.execute(self.request(child.worker()))
                # Check every race barrier without blocking the test's release.
                for callback in (held.close, held.seal, lambda: held.child("late")):
                    with self.assertRaises(AuthorityError):
                        callback()
                progressed.set()
            except BaseException as exc:
                errors.append(exc)
        sealing = threading.Thread(target=seal)
        worker = threading.Thread(target=use_other)
        sealing.start()
        try:
            self.assertTrue(entered.wait(5))
            worker.start()
            self.assertTrue(progressed.wait(2), "unrelated operation blocked behind seal I/O")
        finally:
            release.set(); sealing.join(5)
            if worker.ident is not None:
                worker.join(5)
        self.assertFalse(sealing.is_alive()); self.assertFalse(worker.is_alive())
        self.assertEqual(errors, [])

