    def test_inventory_and_injected_mint_references(self):
        with patch.object(inventory.ast, "parse", wraps=inventory.ast.parse) as parsed:
            actual = inventory.check()  # Always scan the real complete source tree.
        self.assertEqual(parsed.call_count, len(inventory.source_catalog()))
        self.assertEqual(len(actual["production_roots"]), 30)
        good = Path(__file__).read_text(encoding="utf-8")
        catalog = inventory.source_catalog()
        fixture_paths = {inventory.TEST_OWNER, "engine/stock_ibkr.py", "display_data.py",
                         "engine/fetch_operations.py", "engine/fetch_send_inventory.py",
                         "engine/live_spot_probe.py", "engine/stock_validate.py",
                         "engine/external_sweep.py"} | {row[0] for row in inventory.ENGINE_DISPATCHES}
        sources = {path: catalog[path] for path in fixture_paths}
        baseline = inventory.build_inventory(sources)
        for field in ("production_roots", "production_dispatches", "test_mint_sites"):
            self.assertEqual(baseline[field], actual[field])
        core_only = {"engine/fetch_operations.py": sources["engine/fetch_operations.py"]}
        for source, reason in (
                ("from fetch_operations import begin_operation as escape", "unregistered operation mint reference"),
                ("value = module._OperationHandle", "unregistered operation mint reference"),
                ("value = '_ChildHandle'", "unregistered operation mint reference"),
                ("module.nightly_update()", "unregistered or indirect root dispatch"),
                ("value = module.nightly_update", "unregistered or indirect root dispatch"),
                ("value = 'nightly_update'", "unregistered or indirect root dispatch")):
            with self.subTest(source=source), self.assertRaisesRegex(ValueError, reason):
                inventory.build_inventory({**core_only, "engine/foreign.py": source})
        # If the subject no longer triggers its early guard, the incomplete
        # fixture reaches this distinct denominator, never a matching refusal.
        with self.assertRaisesRegex(ValueError, "operation mint site denominator changed"):
            inventory.build_inventory({**core_only, "engine/foreign.py": "value = 'ordinary'"})
        with self.assertRaises(ValueError):
            inventory.build_inventory({**sources,
                inventory.TEST_OWNER: good.replace("op.begin_operation(", "op.not_a_root(")})
        with self.assertRaisesRegex(ValueError, "unregistered root dispatch owner"):
            inventory.build_inventory({**core_only,
                "engine/foreign_selftest.py": "stock_ibkr.nightly_update()"})
        for path, before, after in (
            ("engine/stock_ibkr.py", 'fops.begin_operation("nightly",', 'fops.begin_operation("add_stocks",'),
            ("engine/stock_ibkr.py", "def nightly_update(", "def unknown_root("),
            ("engine/stock_ibkr.py", "import inspect", "import inspect\nescape = fops.begin_operation"),
            ("display_data.py", "stock_ibkr.nightly_update(", "stock_ibkr.add_stocks_gap_fill("),
            ("display_data.py", "stock_ibkr.nightly_update(", "other.nightly_update(")):
            with self.subTest(after=after), self.assertRaises(ValueError):
                changed = sources[path].replace(before, after, 1)
                self.assertNotEqual(changed, sources[path])
                inventory.build_inventory({**sources, path: changed})

    def test_inventory_index_is_fresh_and_preserves_refusal_order(self):
        import ast
        source = "class Owner:\n    def method(self):\n        return value + value\n"
        with patch.object(inventory.ast, "parse", wraps=inventory.ast.parse) as parsed:
            first = inventory._source_index(source)
            second = inventory._source_index(source)
            changed = inventory._source_index(source.replace("value + value", "value - value"))
        self.assertEqual(parsed.call_count, 3)
        self.assertIsNot(first[0], second[0])
        self.assertNotEqual(ast.dump(first[0]), ast.dump(changed[0]))
        for tree, nodes, parents, children, references in (first, second, changed):
            self.assertEqual(nodes, list(ast.walk(tree)))
            self.assertEqual(parents, {child: parent for parent in ast.walk(tree)
                                      for child in ast.iter_child_nodes(parent)})
            self.assertTrue(all(children[node] == tuple(ast.iter_child_nodes(node)) for node in nodes))
            self.assertEqual(references, {node: node.id for node in nodes
                                         if isinstance(node, ast.Name)})
        reference_source = ("from module import imported as alias\n"
                            "obj.member(keyword='literal')\n"
                            "values = [None, True, 3, b'bytes', f'{value}']\n")
        tree, nodes, parents, children, references = inventory._source_index(reference_source)
        # Independent original-category oracle includes aliases, attributes,
        # executable names and strings, but never non-string constants.
        spellings = {"imported", "obj", "member", "literal", "values", "value", "missing"}
        for spelling in spellings:
            expected = [node for node in nodes if
                (isinstance(node, ast.Name) and node.id == spelling)
                or (isinstance(node, ast.Attribute) and node.attr == spelling)
                or (isinstance(node, ast.alias) and node.name == spelling)
                or (isinstance(node, ast.Constant) and isinstance(node.value, str)
                    and node.value == spelling)]
            self.assertEqual([node for node in nodes if references.get(node) == spelling], expected)
        self.assertTrue(all(isinstance(value, str) for value in references.values()))
        preorder = []
        def collect(node):
            if node in references:
                preorder.append(node)
            for child in ast.iter_child_nodes(node):
                collect(child)
        collect(tree)
        self.assertEqual(sorted(references, key=lambda node:
            inventory._source_order(node, parents, children)), preorder)
        for builder in (inventory._context_inventory, inventory.build_inventory):
            with self.assertRaisesRegex(ValueError, "context reference"):
                builder({"a.py": "factory = module.FetchRunContext", "z.py": "def broken("})
            with self.assertRaises(SyntaxError):
                builder({"a.py": "def broken(", "z.py": "factory = module.FetchRunContext"})

    def test_inventory_sparse_context_preserves_nested_owner_and_first_refusal(self):
        core = ("def begin_operation():\n"
                "    from fetch_run_context import FetchRunContext\n"
                "    return FetchRunContext.create(path)\n")
        nested = ("class Outer:\n"
                  "    async def inner(self):\n"
                  "        factory = module.FetchRunContext\n"
                  "later = module.FetchRunContext\n")
        # Breadth-first order would refuse the global 'later' assignment
        # first. The sparse scan must retain recursive preorder and owner.
        with self.assertRaisesRegex(ValueError, "context reference: a.py:Outer.inner$"):
            inventory._context_inventory({"a.py": nested,
                                          "engine/fetch_operations.py": core})
        sources = {"engine/fetch_operations.py": core, inventory.TEST_OWNER: nested}
        actual = inventory._context_inventory(sources)
        rows = [row for row in actual["references"] if row["path"] == inventory.TEST_OWNER]
        self.assertEqual(rows, [
            {"path": inventory.TEST_OWNER, "owner": "", "kind": "read"},
            {"path": inventory.TEST_OWNER, "owner": "Outer.inner", "kind": "read"}])
        literal = "def owner():\n    text = 'prefix FetchRunContext suffix'\n"
        with self.assertRaisesRegex(ValueError, "context reference: a.py:owner$"):
            inventory._context_inventory({"a.py": literal,
                                          "engine/fetch_operations.py": core})
        for text in ("prefixFetchRunContext", "FetchRunContextSuffix", "éFetchRunContext"):
            self.assertEqual(inventory._context_inventory({
                "a.py": "text = " + repr(text), "engine/fetch_operations.py": core}),
                inventory._context_inventory({"engine/fetch_operations.py": core}))

    def test_inventory_compaction_preserves_mint_custody_and_operation_preorder(self):
        import ast
        core = ("def begin_operation():\n"
                "    from fetch_run_context import FetchRunContext\n"
                "    return FetchRunContext.create(path)\n")
        path = "engine/fetch_pickup_selftest.py"  # Registered, but never a mint owner.
        unregistered = "engine/pacer_selftest.py"  # Test-looking is not registration.
        sources = {"engine/fetch_operations.py": core, path: "value = 'ordinary'",
                   "docs/ordinary.py": "value = 3", unregistered: "value = 4"}
        retained = {}
        with patch.object(inventory.ast, "parse", wraps=inventory.ast.parse) as parsed:
            yielded = list(inventory._indexed_sources(sources, retained))
        self.assertEqual(parsed.call_count, len(sources))
        self.assertEqual([p for p, index in yielded], sorted(sources))
        self.assertTrue(all(isinstance(index[0], ast.Module) for p, index in yielded))
        self.assertEqual(set(retained), {path, unregistered})
        self.assertIs(retained[path], False)
        self.assertIsInstance(retained[unregistered][0], ast.Module)
        changed = {**sources, path: "value = '_OperationHandle'"}
        retained_again = {}
        list(inventory._indexed_sources(changed, retained_again))
        self.assertIs(retained_again[path], True)
        with self.assertRaisesRegex(ValueError, "operation mint reference: engine/fetch_pickup_selftest.py$"):
            inventory.build_inventory(changed)
        with self.assertRaisesRegex(ValueError, "context reference: z.py"):
            inventory.build_inventory({**changed, "z.py": "factory = module.FetchRunContext"})
        # The first deep call must refuse as a root owner before a later
        # shallow transitive alias; breadth-first candidate order is wrong.
        foreign = ("class Outer:\n    def inner(self):\n        sk.doctor()\n"
                   "saved = sk.preflight\n")
        with self.assertRaisesRegex(ValueError, r"unregistered root dispatch owner: \('engine/foreign.py', 'Outer.inner', 'doctor', 'sk'\)$"):
            inventory.build_inventory({"engine/fetch_operations.py": core, "engine/foreign.py": foreign})

    def test_inventory_root_dispatch_owner_has_its_own_refusal_pin(self):
        sources = inventory.source_catalog()
        path = "engine/live_feature_check.py"
        changed = sources[path] + "\ndef unregistered_probe_owner():\n    sk.doctor()\n"
        with self.assertRaisesRegex(ValueError, "unregistered root dispatch owner"):
            inventory.build_inventory({
                "engine/fetch_operations.py": sources["engine/fetch_operations.py"], path: changed})
        # Remove only this early owner check in an in-memory scanner copy.
        # The later denominator still refuses, but no longer satisfies the
        # named owner oracle above; neither redundant fence masks its loss.
        import inspect
        source = inspect.getsource(inventory.build_inventory)
        old = 'if (path, ".".join(names), name, receiver) not in allowed:'
        self.assertEqual(source.count(old), 1)
        namespace = dict(vars(inventory))
        exec(compile(source.replace(old, "if False:"), inventory.__file__, "exec"), namespace)
        with self.assertRaisesRegex(ValueError, "production root dispatch denominator changed"):
            namespace["build_inventory"]({**sources, path: changed})

    def test_inventory_targeted_and_transitive_custody_negatives(self):
        catalog = inventory.source_catalog()
        paths = {inventory.TEST_OWNER, "engine/stock_ibkr.py", "display_data.py",
                 "engine/fetch_operations.py", "engine/fetch_send_inventory.py",
                 "engine/live_spot_probe.py", "engine/stock_validate.py",
                 "engine/external_sweep.py"}
        paths |= {row[0] for row in inventory.ENGINE_DISPATCHES}
        sources = {path: catalog[path] for path in paths}
        actual = inventory.build_inventory(sources)
        self.assertEqual(len(actual["production_dispatches"]), 36)
        inherited = {(row["owner"], row["api"]) for row in actual["production_dispatches"]
                     if row["purpose"] == "inherited"}
        self.assertEqual(inherited, {("_backfill_seal_interior", "fill_missing_days"),
                                     ("_nightly_update_body", "validate_symbols"),
                                     ("_feature_body", "validate_symbols"),
                                     ("_daily_body", "validate_symbols"),
                                     ("_pipeline_body", "validate_symbols"),
                                     ("test_end_to_end_store", "validate_symbols"),
                                     ("_fixed_fill", "fill_missing_days")})
        self.assertEqual(actual["forwarded_references"], [])
        core_only = {"engine/fetch_operations.py": sources["engine/fetch_operations.py"]}
        for path, before, after, reason in (
            ("display_data.py", "stock_ibkr.preflight(ports=ports, cancel=ev)",
             "other.preflight(ports=ports, cancel=ev)", "unregistered root dispatch owner"),
            ("display_data.py", "stock_ibkr.preflight(ports=ports, cancel=ev)",
             "True, []", "dispatch denominator"),
            ("engine/fix_data_pipeline.py", "return sk.fill_missing_days(",
             "saved = sk.fill_missing_days\n    return saved(", "indirect root dispatch"),
            ("display_data.py", "fix_data_pipeline.run(",
             "other.run(", "dispatch denominator"),
            ("engine/stock_ibkr.py", "_fetch_child=fops.narrow_worker_child(",
             "other_child=fops.narrow_worker_child(", "child mode changed")):
            changed = sources[path].replace(before, after, 1)
            self.assertNotEqual(changed, sources[path])
            with self.subTest(after=after), self.assertRaisesRegex(ValueError, reason):
                fixture = sources if reason == "dispatch denominator" else core_only
                inventory.build_inventory({**fixture, path: changed})
        for extra in ("saved = stock_ibkr.preflight", "from stock_ibkr import preflight as saved"):
            with self.subTest(extra=extra), self.assertRaisesRegex(ValueError, "indirect transitive"):
                inventory.build_inventory({**core_only, "engine/unregistered.py": extra})
        with self.assertRaisesRegex(ValueError, "unregistered root dispatch owner"):
            inventory.build_inventory({**core_only, "engine/unregistered.py": "stock_ibkr.preflight()"})

    def test_c2_fixdata_inventory_qualified_run_and_indirection(self):
        sources = inventory.source_catalog()
        baseline = inventory.build_inventory(sources)
        unrelated = "def run(): return None\nclass Other:\n    def run(self): return None\nOther().run()\n"
        self.assertEqual(inventory.build_inventory({**sources, "engine/unrelated.py": unrelated}), baseline)
        readonly = "import fix_data_pipeline as alias\nvalue = alias.PROBE_WAIT_HEARTBEAT_S\n"
        self.assertEqual(inventory.build_inventory({**sources, "engine/readonly.py": readonly}), baseline)
        # Refusal happens before the global root denominator. Keep the actual
        # core constructor plus the injected source for each refusal pin;
        # unrelated files add no reachability to this branch. The positive
        # controls above still validate the complete shipped source catalog.
        refusal_sources = {"engine/fetch_operations.py": sources["engine/fetch_operations.py"]}
        for source, reason in (
                ("fix_data_pipeline.run()", "unregistered root dispatch owner"),
                ("import fix_data_pipeline as alias\nalias.run()", "unregistered root dispatch owner"),
                ("from fix_data_pipeline import run as alias", "indirect Fix Data root import"),
                ("saved = fix_data_pipeline.run", "indirect Fix Data root dispatch"),
                ("getattr(fix_data_pipeline, 'run')()", "indirect Fix Data module reference"),
                ("saved = fix_data_pipeline", "indirect Fix Data module reference")):
            with self.subTest(source=source), self.assertRaisesRegex(ValueError, reason):
                inventory.build_inventory({**refusal_sources, "engine/foreign.py": source})

