    def test_c1_actual_inflight_request_blocks_parent_completion(self):
        from fetch_ibkr_integration_selftest import ib_contract
        with patch.dict("sys.modules", {"ib_async": SimpleNamespace(Contract=ib_contract)}):
            for family in ("1m", "1d", "1d-iv", "1d-hvol", "retired", "targeted"):
                with self.subTest(family=family):
                    token = "1d" if family == "targeted" else "1m" if family == "retired" else family
                    bank, raw = self.probe_bank_fixture(token,
                        [date(2026, 6, 29), date(2026, 6, 30), date(2026, 7, 1)], name="inflight-" + family)
                    registry, adapter, _ = self.metadata_fixture()
                    adapter.port = 2000
                    adapter.ib.rows = raw
                    transport = adapter.ib
                    entered, finish = threading.Event(), threading.Event()
                    results, errors = [], []
                    original = transport.reqHistoricalDataAsync
                    def held(*args, **kwargs):
                        entered.set()
                        if not finish.wait(5):
                            raise AssertionError("actual transport holder timed out")
                        return original(*args, **kwargs)
                    transport.reqHistoricalDataAsync = held
                    run = self.open("repair" if family == "targeted" else "diagnostic", governors=registry)
                    child = self.child(run)
                    def work():
                        try:
                            if family == "targeted":
                                value = ib.fill_missing_days(adapter, bank, "TEST", token, ["2026-07-01"],
                                    contract=contract(), _fetch_child=child)
                            elif family == "retired":
                                stored = ib.convert_bars(raw, date(2026, 7, 1),
                                    {"invalid": 0, "outside_day": 0, "non_rth": 0}, token)
                                value = ib._retired_spot_check_day(adapter, contract(), token, date(2026, 7, 1),
                                    stored, InstantPacer(), None, _fetch_child=child)
                            else:
                                cls = probe.IBKRMinuteDayFetcher if token == "1m" else probe.IBKRDailySpanFetcher
                                fetcher = cls.from_borrowed_adapter(adapter, pacer=InstantPacer())
                                snapshot = (probe.stored_day_snapshot(bank, "TEST", "2026-07-01") if token == "1m"
                                    else probe.stored_daily_span_snapshot(bank, "TEST", day="2026-07-01", interval=token))
                                method = fetcher.fetch_day if token == "1m" else fetcher.fetch_span
                                value = method(snapshot, _fetch_child=child)
                                fetcher.close()
                            results.append(value)
                        except BaseException as exc:
                            errors.append(exc)
                    thread = threading.Thread(target=work)
                    thread.start()
                    try:
                        self.assertTrue(entered.wait(3), str([type(error).__name__ for error in errors]))
                        with self.assertRaisesRegex(AuthorityError, "outstanding"):
                            run.seal()
                        with self.assertRaises(AuthorityError):
                            run.close()
                        self.assertFalse(run.context.ledger.verified)
                    finally:
                        finish.set()
                        thread.join(3)
                    self.assertFalse(thread.is_alive())
                    self.assertEqual(errors, [])
                    self.assertEqual(len(results), 1)
                    self.assertFalse(child in op._CHILDREN, "actual request retained its child")
                    run.seal()
                    self.assertTrue(inspect_ledger(run.context.ledger.path)["verified"])
                    run.close()
                    self.assertEqual(len(transport.calls), 1)
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})

    def test_c1_actual_child_dispatch_argument_and_ownership_barriers(self):
        targets = (("minute", probe.IBKRMinuteDayFetcher().fetch_day, "diagnostic"),
                   ("daily", probe.IBKRDailySpanFetcher().fetch_span, "diagnostic"),
                   ("retired", ib._retired_spot_check_day, "diagnostic"),
                   ("targeted", ib._fill_missing_days_body, "repair"))
        for label, dispatch, purpose in targets:
            for kwargs, error in (({}, TypeError), ({"unknown": True}, TypeError),
                                  ({"_fetch_worker": object()}, AuthorityError)):
                with self.subTest(target=label, refusal=tuple(kwargs)):
                    run = self.open(purpose)
                    child = self.child(run)
                    with self.assertRaises(error):
                        dispatch(_fetch_child=child, **kwargs)
                    self.assertFalse(child in op._CHILDREN, "inactive child retained at actual C1 dispatch")
                    self.assertEqual(run.context.ledger.path.read_bytes(), b"")
                    run.seal()
                    run.close()
            run = self.open(purpose)
            child = self.child(run)
            with child.scope():
                with self.assertRaisesRegex(AuthorityError, "already active"):
                    dispatch(_fetch_child=child)
                self.assertIn(child, op._CHILDREN)
                self.assertTrue(child.worker() is not None)
            entered, finish = threading.Event(), threading.Event()
            errors = []
            def hold():
                try:
                    with child.scope():
                        entered.set()
                        if not finish.wait(5):
                            raise AssertionError("child holder timed out")
                except BaseException as exc:
                    errors.append(exc)
            thread = threading.Thread(target=hold)
            thread.start()
            try:
                self.assertTrue(entered.wait(3))
                with self.assertRaises(AuthorityError):
                    dispatch(_fetch_child=child)
                with self.assertRaises(AuthorityError):
                    run.seal()
                with self.assertRaises(AuthorityError):
                    run.close()
                self.assertIn(child, op._CHILDREN)
            finally:
                finish.set()
                thread.join(3)
            self.assertFalse(thread.is_alive())
            self.assertEqual(errors, [])
            child.close()
            run.seal()
            run.close()
        for option in ("evidence_dir", "_test_capability"):
            run = self.open("repair")
            child = self.child(run)
            with self.assertRaisesRegex(AuthorityError, "root-only options"):
                ib.fill_missing_days(None, self.root, "TEST", "1m", [],
                    _fetch_child=child, **{option: self.root if option == "evidence_dir" else object()})
            self.assertNotIn(child, op._CHILDREN)
            self.assertEqual(run.context.ledger.path.read_bytes(), b"")
            run.seal()
            run.close()
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})

    def test_worker_dispatch_joins_transferred_child_on_argument_refusal(self):
        executed = []
        @bridge.worker_scope
        def helper(required, *, cancel=None):
            executed.append(bridge.current_worker().worker_id)
            return required
        for args, kwargs, error in (
            ((), {}, TypeError), ((1, 2), {}, TypeError),
            ((1,), {"unknown": True}, TypeError),
            ((1,), {"_fetch_worker": object()}, AuthorityError),
        ):
            with self.subTest(args=args, kwargs=kwargs):
                run = self.open(); child = self.child(run)
                with self.assertRaises(error):
                    helper(*args, **kwargs, _fetch_child=child)
                self.assertNotIn(child, op._CHILDREN)
                self.assertEqual(run.context.ledger.path.read_bytes(), b"")
                run.seal(); run.close()
        self.assertEqual(executed, [])
        run = self.open(); child = self.child(run)
        self.assertEqual(helper(123, _fetch_child=child), 123)
        self.assertEqual(executed, ["worker"])
        self.assertNotIn(child, op._CHILDREN)
        run.seal(); run.close()

