    def test_worker_dispatch_refusal_never_closes_forged_or_active_child(self):
        @bridge.worker_scope
        def helper():
            self.fail("refused dispatch entered body")
        closed = []
        forged = SimpleNamespace(close=lambda: closed.append(True))
        with self.assertRaises(AuthorityError):
            helper(_fetch_child=forged)
        self.assertEqual(closed, [])
        run = self.open(); child = self.child(run)
        with child.scope():
            with self.assertRaisesRegex(AuthorityError, "already active"):
                helper(_fetch_child=child)
            self.assertIn(child, op._CHILDREN)
