        missing_embedded[_D02_ROOTS[-1][3]]["embedded"] = []
        with self.assertRaises(AssertionError):
            _d02_verify(roots, dispatches, _D02_ROOTS, missing_embedded, catalog)
        print("D02_INVERSE_RED missing-embedded")
        print("D02_RECONCILED diagnostic_mains=9 embedded_repair=1 roots=10")

