    def test_zz_d04_execution_bound_observer_reconciliation(self):
        import live_run_all as all_groups
        import textwrap
        catalog = set(unittest.TestLoader().getTestCaseNames(type(self)))
        _d04_verify_source_sites()
        companion = "test_c2_fixdata_callback_families_and_removal_inverses"
        self.assertIn(companion, catalog)
        companion_result, companion_output = unittest.TestResult(), io.StringIO()
        with redirect_stdout(companion_output):
            type(self)(companion).run(companion_result)
        self.assertEqual(companion_result.testsRun, 1)
        self.assertTrue(companion_result.wasSuccessful(),
                        companion_result.errors + companion_result.failures)
        self.assertIsNone(tp._ACTIVE)
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})
        print("D04_COMPANION fixdata_callback_families=29 source_removal_mutants=4 pass")
        methods = ({positive for _, _, _, positive, _ in _D02_ROOTS} |
                   set(_D04_HOSTILE))
        receipts = {name: _d04_run_witness(type(self), name)
                    for name in sorted(methods)}
        _d04_verify(_D02_ROOTS, _D04_ROLES, receipts, catalog)
        for name in sorted(receipts):
            print("D04_WITNESS", json.dumps({"method": name,
                "sites": sum(receipts[name]["entries"].values()),
                "unique_sites": len(receipts[name]["entries"]),
                "violations": len(receipts[name]["violations"])}, sort_keys=True))
        for role, method, path, owner, callback in _D04_ROLES:
            count = sum(n for (site_path, site_owner, site_callback), n
                        in receipts[method]["entries"].items()
                        if (site_path, site_owner) == (path, owner)
                        and site_callback.endswith(callback))
            print("D04_ROLE", json.dumps({"role": role, "method": method,
                "path": path, "owner": owner, "callback": callback,
                "observed_calls": count}, sort_keys=True))

        def red(label, *, bindings=_D02_ROOTS, roles=_D04_ROLES, changed=None):
            with self.subTest(inverse=label), self.assertRaises(AssertionError):
                _d04_verify(bindings, roles, changed or receipts, catalog)
            print("D04_INVERSE_RED", label)

        first = _D02_ROOTS[0][3]
        changed = deepcopy(receipts); del changed[first]
        red("missing-root", changed=changed)
        red("extra-root", bindings=(*_D02_ROOTS, _D02_ROOTS[0]))
        red("duplicate-plus-gap", bindings=(*_D02_ROOTS[:-1], _D02_ROOTS[0]))
        red("missing-role", roles=_D04_ROLES[:-1])
        red("extra-role", roles=(*_D04_ROLES, (*_D04_ROLES[0][:4], ".other")))
        changed = deepcopy(receipts)
        sites = changed[_D04_HOSTILE[0]]["entries"]
        site = next(site for site in sites if site[:2] ==
                    ("engine/live_internal_revalidate.py", "_internal_port")
                    and site[2].endswith(".factory"))
        sites[(site[0], "_wrong_port", site[2])] = sites.pop(site)
        red("wrong-callback-owner", changed=changed)
        changed = deepcopy(receipts); changed[first]["violations"].append(("borrowed-worker",))
        red("borrowed-worker", changed=changed)
        changed = deepcopy(receipts); changed[first]["violations"].append(("successful-mint",))
        red("successful-mint", changed=changed)
        changed = deepcopy(receipts); changed[first]["violations"].append(("successful-send",))
        red("successful-send", changed=changed)
        changed = deepcopy(receipts); changed[first]["entries"].clear()
        red("removed-observer-site", changed=changed)

        source = textwrap.dedent(inspect.getsource(all_groups._run_group))
        needle = "tly = fib.observer_object(L._Tally())"
        self.assertEqual(source.count(needle), 1)
        namespace = dict(vars(all_groups))
        exec(compile(source.replace(needle, "tly = L._Tally()"),
                     all_groups.__file__, "exec"), namespace)
        method = "test_d2_runall_real_raw_group_uses_narrowed_parent_child"
        with patch.object(all_groups, "_run_group", new=namespace["_run_group"]):
            mutant = _d04_run_witness(type(self), method)
        self.assertGreater(sum(receipts[method]["entries"].values()),
                           sum(mutant["entries"].values()))
        changed = deepcopy(receipts); changed[method] = mutant
        red("source-removal-tally-boundary", changed=changed)
        print("D04_RECONCILED roots=10 roles=7 hostile=3 inverses=11")

    def test_d05_daily_six_producers_settlement_matrix(self):
        """Run every d daily-token owner across refusal, clamp and settlement."""
        import live_combined_flags as combined
        import live_internal_daily_check as premise
        import live_internal_revalidate as internal
        import live_kind_smoke as kind

        original_authority = self.authority
        ids = [row[0] for row in _D05_DAILY]
        self.assertEqual(len(ids), 6)
        self.assertEqual(len(set(ids)), 6)
        tally = SimpleNamespace(check=lambda okay, label: self.assertTrue(okay, label))
        for producer, _site, token in _D05_DAILY:
            for phase in ("unsettled", "history", "settled"):
                # The combined month must start inside calendar coverage;
                # premise's four-day carrier needs a long holiday gap to be
                # wholly unsettled. Other first-day raw probes have no horizon.
                if phase == "unsettled":
                    day = (date(1980, 2, 1) if producer == combined._DAILY else
                           date(2026, 7, 6) if producer == premise._DAILY else
                           date(2026, 7, 2) if producer == internal._DAILY else
                           date(1980, 1, 2))
                else:
                    day = date(2026, 7, 2)
                prior = day - timedelta(days=1)
                when = datetime.combine(day, time(16, 20) if phase == "settled"
                                        else time(13, 20), NY)
                rows = dict(original_authority.rows)
                rows[day] = replace(rows[day], status="open_early_close", close=time(13))
                self.authority = replace(original_authority, rows=rows)
                try:
                    registry, adapter, _ = self.metadata_fixture()
                    raw = adapter.ib
                    daily_rows = [bar(prior), bar(day)]
                    for value in daily_rows:
                        value.close = 0.2
                        value.volume = -1
                    minute_rows = [bar(datetime.combine(prior, time(9, 30), NY))]
                    original_request = raw.reqHistoricalDataAsync
                    def request(pinned, **kwargs):
                        raw.rows = (daily_rows if kwargs["barSizeSetting"] == "1 day"
                                    else minute_rows)
                        return original_request(pinned, **kwargs)
                    raw.reqHistoricalDataAsync = request
                    accepted = []
                    original_fetch = adapter.fetch
                    def capture(*args, **kwargs):
                        value = original_fetch(*args, **kwargs)
                        if args[3] == "1 day":
                            accepted.append(list(value))
                        return value
                    adapter.fetch = capture
                    run = self.open("diagnostic", governors=registry,
                                    clock=lambda: when)
                    rights = ({producer, kind._HVOL_INTRADAY}
                              if producer == kind._HVOL_DAILY else {producer})
                    child = self.child(run, f"d05-{phase}-{producer}",
                                       rights=rights)
                    end = datetime.combine(day, time(16), NY)
                    def invoke():
                        pinned = contract()
                        if producer == combined._DAILY:
                            return combined._fetch_month_1d(adapter, pinned,
                                day.year, day.month, _fetch_child=child)
                        if producer == premise._DAILY:
                            return premise._premise_request(adapter, pinned, end,
                                1 if phase == "unsettled" else 3,
                                _fetch_child=child)
                        if producer == internal._DAILY:
                            return internal._internal_daily(adapter, pinned, end,
                                1 if phase == "unsettled" else 3,
                                _fetch_child=child)
                        if producer == kind._IV_DAILY:
                            return kind.test_raw_daily_shape(adapter, pinned, tally,
                                end, _fetch_child=child)
                        if producer == kind._HVOL_DAILY:
                            return kind.test_hvol_daily(adapter, pinned, tally,
                                end, _fetch_child=child)
                        if producer == kind._SPAN:
                            return kind.test_span_probe(adapter, pinned, tally,
                                end, _fetch_child=child)
                        self.fail("D05 unbound producer " + producer)

                    with self.subTest(producer=producer, phase=phase), \
                            redirect_stdout(io.StringIO()):
                        if phase == "unsettled":
                            with patch.object(governors.Governor, "wait_turn",
                                              side_effect=AssertionError(
                                                  "unsettled daily took a turn")), \
                                    self.assertRaises(RequestRefused):
                                invoke()
                            self.assertEqual(raw.calls, [])
                            self.assertEqual(accepted, [])
                        else:
                            output = invoke()
                            daily_sends = [row for row in raw.calls
                                           if row[0] == "bars" and
                                           row[2]["barSizeSetting"] == "1 day"]
                            self.assertEqual(len(daily_sends),
                                             4 if producer == kind._SPAN else 1)
                            expected_end = self.authority.window(
                                token, day if phase == "settled" else prior)[1]
                            self.assertTrue(all(row[2]["endDateTime"] == expected_end
                                                for row in daily_sends))
                            self.assertEqual(len(accepted), len(daily_sends))
                            published = {value.date for group in accepted
                                         for value in group}
                            self.assertIn(prior, published)
                            self.assertEqual(day in published, phase == "settled")
                            if producer in {combined._DAILY, premise._DAILY,
                                            internal._DAILY}:
                                reference, coverage = output[:2]
                                self.assertEqual(str(day) in reference,
                                                 phase == "settled")
                                self.assertEqual(coverage["requested"]["intended_start"],
                                                 coverage["effective"]["intended_start"])
                                self.assertEqual(coverage["decision"],
                                                 "allowed" if producer == combined._DAILY
                                                 else "clamped")
                            events = inspect_ledger(run.context.ledger.path,
                                                    require_seal=False)["events"]
                            decisions = [row for row in events
                                         if row["event"] == "decision" and
                                         row["producer_id"] == producer]
                            results = [row for row in events
                                       if row["event"] == "result" and
                                       row["producer_id"] == producer]
                            self.assertEqual(len(decisions), len(daily_sends))
                            self.assertEqual(len(results), len(daily_sends))
                            self.assertTrue(all(
                                row["payload"]["requested"]["intended_start"] ==
                                row["payload"]["effective"]["intended_start"] and
                                row["payload"]["effective"]["intended_end"] ==
                                expected_end.isoformat()
                                for row in decisions))
                    run.close()
                finally:
                    self.authority = original_authority
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})

    def test_zz_d05_execution_bound_daily_reconciliation(self):
        import fetch_send_inventory as sends

        rows = [row for row in sends.build_inventory()["sites"]
                if row["producer_id"] in {binding[0] for binding in _D05_DAILY}]
        method = "test_d05_daily_six_producers_settlement_matrix"
        catalog = set(unittest.TestLoader().getTestCaseNames(type(self)))
        self.assertIn(method, catalog)
        reached = _d01_witness_receipt(type(self), method, rows)
        _d05_verify(rows, _D05_DAILY, reached)
        for producer, site, token in _D05_DAILY:
            print("D05_DAILY_SITE", json.dumps({"producer": producer,
                "site": site, "token": token, "reached": (producer, site) in reached},
                sort_keys=True))

        def red(label, *, sites=rows, bindings=_D05_DAILY, receipt=reached):
            with self.subTest(inverse=label), self.assertRaises(AssertionError):
                _d05_verify(sites, bindings, receipt)
            print("D05_INVERSE_RED", label)

        red("missing-site", sites=rows[1:])
        red("extra-site", sites=[*rows, {**rows[0],
            "producer_id": "ibkr.injected.daily", "site_key":
            "engine.injected:daily:adapter_fetch:1"}])
        red("duplicate-plus-gap", sites=[*rows[1:], rows[1]])
        changed = list(_D05_DAILY)
        changed[0] = (*changed[0][:2], "1m")
        red("wrong-token", bindings=changed)
        changed = [{**rows[0], "module": "engine.wrong_owner"}, *rows[1:]]
        red("wrong-owner", sites=changed)
        red("missing-receipt", receipt=frozenset(set(reached) - {next(iter(reached))}))

        # Execute the real matrix with the daily 16:20 floor removed. The
        # earlier false-13:00 close then becomes sendable at 13:20, and the
        # matrix must fail at its zero-turn/zero-send assertion.
        def premature_settlement(authority, day):
            row = authority.row(day)
            return datetime.combine(day, row.close, NY) + timedelta(minutes=20)
        with patch.object(ScheduleAuthority, "daily_settled_close",
                          new=premature_settlement), \
                self.assertRaisesRegex(AssertionError, "D01 witness"):
            _d01_witness_receipt(type(self), method, rows)
        self.assertIsNone(tp._ACTIVE)
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})
        print("D05_INVERSE_RED removed-16:20-daily-floor")
        print("D05_RECONCILED daily_sites=6 phases=3 inverses=7")

    def test_d06_five_minute_sites_settlement_matrix(self):
        """Exercise shipped minute helpers before open and across partial closes."""
        import live_combined_flags as combined
        import live_internal_revalidate as internal
        import live_kind_smoke as kind

        original_authority = self.authority
        minute_bindings = _D06_SUBDAILY[:-1]
        tally = SimpleNamespace(check=lambda okay, label: self.assertTrue(okay, label))
        for producer, _site, token, _transport in minute_bindings:
            for phase in ("preopen", "mid", "early_close"):
                day = (date(1980, 2, 1) if producer == combined._MINUTE
                       else date(1980, 1, 2)) if phase == "preopen" else date(2026, 7, 2)
                prior = day - timedelta(days=1)
                when = datetime.combine(day, time(9, 20) if phase == "preopen"
                                        else time(10, 20) if phase == "mid"
                                        else time(13, 20), NY)
                rows = dict(original_authority.rows)
                if phase != "preopen":
                    rows[day] = replace(rows[day], status="open_early_close", close=time(13))
                self.authority = replace(original_authority, rows=rows)
                try:
                    registry, adapter, _ = self.metadata_fixture()
                    raw = adapter.ib
                    boundary = datetime.combine(day, time(10, 19) if phase == "mid"
                                                else time(13), NY)
                    minute_rows = [bar(datetime.combine(prior, time(9, 30), NY)),
                                   bar(datetime.combine(day, time(9, 30), NY)),
                                   bar(boundary)]
                    if producer == kind._IV_RTH:
                        # The unfiltered diagnostic's raw carrier is RTH-only;
                        # its out-of-range current row is still inside RTH.
                        minute_rows.pop()
                    daily_rows = [bar(prior), bar(day)]
                    for value in (*minute_rows, *daily_rows):
                        value.close = .2
                        value.volume = -1
                    original_request = raw.reqHistoricalDataAsync
                    def request(pinned, **kwargs):
                        raw.rows = (daily_rows if kwargs["barSizeSetting"] == "1 day"
                                    else minute_rows)
                        return original_request(pinned, **kwargs)
                    raw.reqHistoricalDataAsync = request
                    accepted = []
                    original_fetch = adapter.fetch
                    def capture(*args, **kwargs):
                        value = original_fetch(*args, **kwargs)
                        if args[3] == "1 min":
                            accepted.append(list(value))
                        return value
                    adapter.fetch = capture
                    run = self.open("diagnostic", governors=registry,
                                    clock=lambda: when)
                    rights = ({producer, kind._HVOL_DAILY}
                              if producer == kind._HVOL_INTRADAY else {producer})
                    child = self.child(run, f"d06-{phase}-{producer}", rights=rights)
                    end = datetime.combine(day, time(16), NY)
                    def invoke():
                        pinned = contract()
                        if producer == combined._MINUTE:
                            return combined._fetch_month_1m(adapter, pinned,
                                day.year, day.month, _fetch_child=child)
                        if producer == internal._MINUTE:
                            return internal._internal_minute(adapter, pinned,
                                day, NY, _fetch_child=child)
                        if producer == kind._HVOL_INTRADAY:
                            return kind.test_hvol_daily(adapter, pinned, tally,
                                end, _fetch_child=child)
                        if producer == kind._IV_RTH:
                            return kind.test_iv_rth_only(adapter, pinned, tally,
                                None, _fetch_child=child)
                        if producer == kind._IV_INTRADAY:
                            return kind.test_raw_iv_intraday(adapter, pinned, tally,
                                end, _fetch_child=child)
                        self.fail("D06 unbound minute producer " + producer)

                    with self.subTest(producer=producer, phase=phase), \
                            redirect_stdout(io.StringIO()):
                        if phase == "preopen":
                            with patch.object(governors.Governor, "wait_turn",
                                              side_effect=AssertionError(
                                                  "preopen minute spent a turn")), \
                                    self.assertRaises(RequestRefused):
                                invoke()
                            self.assertEqual(raw.calls, [])
                            self.assertEqual(accepted, [])
                        else:
                            invoke()
                            sends = [row for row in raw.calls if row[0] == "bars"
                                     and row[2]["barSizeSetting"] == "1 min"]
                            self.assertEqual(len(sends), 1)
                            expected_end = (self.authority.window(token, prior)[1]
                                if producer == kind._IV_RTH else
                                datetime.combine(day, time(10, 19) if phase == "mid"
                                                 else time(13), NY))
                            self.assertEqual(sends[0][2]["endDateTime"], expected_end)
                            self.assertEqual(len(accepted), 1)
                            published = {value.date for value in accepted[0]}
                            self.assertNotIn(boundary, published)
                            self.assertEqual(
                                datetime.combine(day, time(9, 30), NY) in published,
                                producer != kind._IV_RTH)
                            events = inspect_ledger(run.context.ledger.path,
                                                    require_seal=False)["events"]
                            decisions = [row for row in events if row["event"] == "decision"
                                         and row["producer_id"] == producer]
                            results = [row for row in events if row["event"] == "result"
                                       and row["producer_id"] == producer]
                            self.assertEqual((len(decisions), len(results)), (1, 1))
                            self.assertEqual(decisions[0]["payload"]["requested"]["token"],
                                             token)
                            self.assertEqual(decisions[0]["payload"]["effective"]
                                             ["intended_end"], expected_end.isoformat())
                    run.close()
                finally:
                    self.authority = original_authority
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})

    def test_d06_second_hammer_uses_captured_settled_half_hour(self):
        """The real 1s helper cannot spend a bar turn before its horizon."""
        import two_account_pacing_probe as pacing

        for phase in ("preopen", "early_close"):
            day = date(1980, 1, 2) if phase == "preopen" else date(2026, 7, 2)
            when = datetime.combine(day, time(9, 20) if phase == "preopen"
                                    else time(13, 20), NY)
            original_authority = self.authority
            rows = dict(original_authority.rows)
            if phase == "early_close":
                rows[day] = replace(rows[day], status="open_early_close", close=time(13))
            self.authority = replace(original_authority, rows=rows)
            try:
                registry, adapter, _ = self.metadata_fixture()
                raw = adapter.ib
                raw.managedAccounts = lambda: ["D06-ACCOUNT"]
                adapter.port = 2000
                adapter.qualify = lambda ticker: (123, contract(ticker))
                raw.rows = [bar(datetime.combine(day, time(12, 30), NY))]
                run = self.open("diagnostic", governors=registry, clock=lambda: when)
                child = self.child(run, f"d06-hammer-{phase}",
                    rights={QUALIFY, pacing._HAMMER})
                with self.subTest(phase=phase), redirect_stdout(io.StringIO()):
                    if phase == "preopen":
                        with self.assertRaises(RequestRefused):
                            pacing.settled_session_ends(run.context, n_sessions=1)
                        with patch.object(governors.Governor, "wait_turn",
                                          side_effect=AssertionError(
                                              "preopen second spent a turn")), \
                                self.assertRaises(RequestRefused):
                            pacing.hammer("D06", adapter, "TEST",
                                [datetime.combine(day, time(10), NY)],
                                _fetch_child=child)
                        self.assertEqual(raw.calls, [])
                    else:
                        ends = pacing.settled_session_ends(run.context, n_sessions=1)
                        self.assertEqual(ends[0], datetime.combine(day, time(13), NY))
                        result = pacing.hammer("D06", adapter, "TEST", ends[:1],
                                               _fetch_child=child)
                        self.assertEqual((result["fired"], result["ok"]), (1, 1))
                        sends = [row for row in raw.calls if row[0] == "bars"]
                        self.assertEqual(len(sends), 1)
                        self.assertEqual(sends[0][2]["endDateTime"], ends[0])
                        events = inspect_ledger(run.context.ledger.path,
                                                require_seal=False)["events"]
                        decisions = [row for row in events if row["event"] == "decision"
                                     and row["producer_id"] == pacing._HAMMER]
                        results = [row for row in events if row["event"] == "result"
                                   and row["producer_id"] == pacing._HAMMER]
                        self.assertEqual((len(decisions), len(results)), (1, 1))
                        self.assertEqual(decisions[0]["payload"]["requested"]["token"], "1s")
                run.close()
            finally:
                self.authority = original_authority
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})

    def test_zz_d06_execution_bound_subdaily_reconciliation(self):
        import fetch_send_inventory as sends

        rows = [row for row in sends.build_inventory()["sites"]
                if row["producer_id"] in {binding[0] for binding in _D06_SUBDAILY}]
        methods = ("test_d06_five_minute_sites_settlement_matrix",
                   "test_d06_second_hammer_uses_captured_settled_half_hour")
        catalog = set(unittest.TestLoader().getTestCaseNames(type(self)))
        self.assertTrue(set(methods) <= catalog)
        reached = set()
        for method in methods:
            reached.update(_d01_witness_receipt(type(self), method, rows))
        _d06_verify(rows, _D06_SUBDAILY, reached)
        for producer, site, token, transport in _D06_SUBDAILY:
            print("D06_SUBDAILY_SITE", json.dumps({"producer": producer,
                "site": site, "token": token, "transport": transport,
                "reached": (producer, site) in reached}, sort_keys=True))

        def red(label, *, sites=rows, bindings=_D06_SUBDAILY, receipt=reached):
            with self.subTest(inverse=label), self.assertRaises(AssertionError):
                _d06_verify(sites, bindings, receipt)
            print("D06_INVERSE_RED", label)

        red("missing-site", sites=rows[1:])
        red("extra-site", sites=[*rows, {**rows[0], "producer_id": "ibkr.injected.minute",
            "site_key": "engine.injected:minute:adapter_fetch:1"}])
        red("duplicate-plus-gap", sites=[*rows[1:], rows[1]])
        changed = list(_D06_SUBDAILY)
        changed[0] = (*changed[0][:2], "1s", changed[0][3])
        red("wrong-token", bindings=changed)
        changed = [{**rows[0], "module": "engine.wrong_owner"}, *rows[1:]]
        red("wrong-owner", sites=changed)
        red("missing-receipt", receipt=frozenset(set(reached) - {next(iter(reached))}))
        original_horizon = ScheduleAuthority.horizon
        def premature_intraday(authority, token, now):
            from fetch_authority import parse_token
            value = original_horizon(authority, token, now)
            base, _, _ = parse_token(token)
            if value is not None and base != "1d" and value.date() == now.date():
                window = authority.window(token, now.date())
                if window is not None and value < window[1]:
                    return value + timedelta(minutes=1)
            return value
        with patch.object(ScheduleAuthority, "horizon", new=premature_intraday), \
                self.assertRaisesRegex(AssertionError, "D01 witness"):
            _d01_witness_receipt(type(self), methods[0], rows)
        self.assertIsNone(tp._ACTIVE)
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})
        print("D06_INVERSE_RED removed-intraday-margin")
        print("D06_RECONCILED subdaily_sites=6 minute_phases=3 second_phases=2 inverses=7")

    def test_zz_d06_calendar_physical_reconciliation(self):
        import fetch_send_inventory as sends

        inventory = sends.build_inventory()["sites"]
        expected = Counter((producer, site) for producer, site, _ in _D06_CALENDAR_SITES)
        self.assertEqual(len(expected), 5)
        rows = [row for row in inventory
                if (row["producer_id"], row["site_key"]) in expected]
        actual = Counter((row["producer_id"], row["site_key"]) for row in rows)
        self.assertEqual(actual, expected)
        for row in rows:
            self.assertEqual(row["module"], "engine.stock_ibkr")
            self.assertEqual(row["primitive"], "adapter_fetch")
            self.assertEqual(row["transport"], "ibkr-bars")
        reached = set()
        for method in dict.fromkeys(binding[2] for binding in _D06_CALENDAR_SITES):
            reached.update(_d01_witness_receipt(type(self), method, rows))
        self.assertEqual(reached, set(expected))
        for producer, site, method in _D06_CALENDAR_SITES:
            print("D06_CALENDAR_SITE", json.dumps({"producer": producer,
                "site": site, "method": method,
                "reached": (producer, site) in reached}, sort_keys=True))
        with self.assertRaises(AssertionError):
            self.assertEqual(set(expected) - {next(iter(expected))}, reached)
        print("D06_CALENDAR_INVERSE_RED missing-physical-receipt")
        original_spans = ib._estimate_covered_spans
        def rounded_before_coverage(token, days, context):
            if token == "1m":
                return [(datetime(1980, 1, 2, 9, 30, tzinfo=NY),
                         datetime(1980, 1, 31, 16, tzinfo=NY), "1 M")]
            return original_spans(token, days, context)
        with patch.object(ib, "_estimate_covered_spans", new=rounded_before_coverage), \
                self.assertRaisesRegex(AssertionError, "D01 witness"):
            _d01_witness_receipt(type(self),
                "test_estimate_calendar_and_first_month_carriers_all_applicable_tokens", [])
        print("D06_CALENDAR_INVERSE_RED first-month-carrier-rounded-precoverage")
        self.assertIsNone(tp._ACTIVE)
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})
        print("D06_CALENDAR_PHYSICAL_RECONCILED sites=5 inverses=2")

