        def false_current_on_error(root, entry):
            if entry.get("status") == "error":
                entry = {**entry, "_verification_current": True}
            return original_save(root, entry)
        with patch.object(combined.sv, "record_combined_flags",
                          new=false_current_on_error), \
                self.assertRaisesRegex(AssertionError, "D07 witness"):
            _d07_audit_witness(type(self),
                "test_d07_fixed_audit_result_fault_has_no_current_credit")
