    def test_zz_d13_regression_reconciliation(self):
        root = Path(__file__).resolve().parent.parent
        baseline_path = root / "engine/_d13_diagnostic_label_baseline.json"
        baseline_bytes = baseline_path.read_bytes()
        self.assertEqual(hashlib.sha256(baseline_bytes).hexdigest(),
                         _D13_LABEL_BASELINE_SHA256)
        catalog = json.loads(baseline_bytes)
        self.assertEqual((catalog["version"], catalog["baseline_commit"]),
                         (1, "4a88a76"))
        baseline = Counter(tuple(row) for row in catalog["rows"])
        sources = {path: (root / path).read_text(encoding="utf-8")
                   for path in catalog["source_sha256"]}
        self.assertEqual(len(sources), 9)
        observed = _d13_label_inventory(sources)
        normalized = _d13_label_verify(baseline, observed)
        self.assertEqual(sum(normalized.values()), 75)
        self.assertNotIn("_retired_spot_check_day(",
                         sources["engine/live_feature_check.py"])
        self.assertNotIn("_retired_spot_check_day(",
                         sources["engine/live_pipeline_check.py"])

        rows = []
        for family, scenario, method, _decisions, _count, _required in _D13_REGRESSION_CASES:
            decisions, labels = _d13_case_witness(type(self), method)
            rows.append({"family": family, "scenario": scenario,
                         "method": method, "decisions": decisions, "labels": labels})
            print("D13_REGRESSION", json.dumps({"family": family,
                "scenario": scenario, "method": method,
                "decisions": dict(sorted(decisions.items())),
                "labels": sum(labels.values())}, sort_keys=True))
        _d13_regression_verify(rows)

        # Pure data inverses fail the exact source-label and execution tables.
        first = next(iter(baseline))
        for name, candidate in (
                ("label-missing", baseline - Counter({first: 1})),
                ("label-extra", baseline + Counter({
                    ("engine/live_feature_check.py", "_feature_body", "'unreviewed'"): 1})),
                ("label-duplicate", baseline + Counter({first: 1}))):
            with self.assertRaises(AssertionError, msg=name):
                _d13_label_verify(candidate, observed)
            print("D13_LABEL_INVERSE_RED", name)
        changed = observed.copy()
        key = next(key for key in changed if key[0] == "engine/live_feature_check.py")
        changed[key] -= 1
        changed[(key[0], "wrong_owner", key[2])] += 1
        with self.assertRaises(AssertionError):
            _d13_label_verify(baseline, changed)
        print("D13_LABEL_INVERSE_RED owner-swap")
        changed = observed.copy()
        key = next(key for key in changed if "legacy spot-check path is retired" in key[2])
        changed[key] -= 1
        changed[(key[0], key[1], "'legacy spot-check path is active'")] += 1
        with self.assertRaises(AssertionError):
            _d13_label_verify(baseline, changed)
        print("D13_LABEL_INVERSE_RED retired-path-revival")
        changed_sources = dict(sources)
        path = "engine/live_feature_check.py"
        changed_sources[path] = sources[path].replace(
            'check("legacy spot-check path is retired",',
            'check("legacy spot-check path is active",', 1)
        self.assertNotEqual(changed_sources[path], sources[path])
        with self.assertRaises(AssertionError):
            _d13_label_verify(baseline, _d13_label_inventory(changed_sources))
        print("D13_LABEL_INVERSE_RED source-retired-path-revival")

        altered = [dict(row) for row in rows]
        inverses = (
            ("missing-case", altered[:-1]),
            ("extra-case", altered + [{**altered[0], "scenario": "unlisted"}]),
            ("duplicate-case", altered + [altered[0]]),
            ("witness-swap", [{**altered[0], "method": altered[1]["method"]},
                              *altered[1:]]),
            ("lost-decision", [{**altered[0], "decisions": Counter()},
                               *altered[1:]]),
            ("retired-path-revival", [{**altered[0], "labels": Counter()},
                                      *altered[1:]]),
        )
        for name, changed_rows in inverses:
            with self.assertRaises(AssertionError, msg=name):
                _d13_regression_verify(changed_rows)
            print("D13_REGRESSION_INVERSE_RED", name)
        self.assertIsNone(tp._ACTIVE)
        self.assertEqual(op._OPERATIONS, {})
        self.assertEqual(op._CHILDREN, {})
        print("D13_REGRESSION_RECONCILED labels=75+2 cases=14 inverses=12")

